  const [profileEditState, setProfileEditState] = useState<ProfileEditState>({ isEditing: false, details: null });
  const [notesViewState, setNotesViewState] = useState<NotesViewState>({ currentNoteId: null, searchTerm: '' });
  const [reportDraft, setReportDraft] = useState<ReportDraft>({ category: 'bug', description: '', attachment: null, contactEmail: '', contactWhatsApp: '' });

  const [showNotifPrompt, setShowNotifPrompt] = useState(false);

  const addToast = useCallback((message: string, type: Toast['type']) => {
    const newToast = { id: Date.now(), message, type };
    setToasts(prev => [...prev, newToast]);
  }, []);

  const persistAllState = useCallback(() => {
    if (!userDetails?.email) return;

    // Use specific user ID if available, otherwise email is a unique enough key for this context if ID is missing.
    // Ideally userDetails.id comes from authService.login/signup
    const userId = userDetails.id || userDetails.email;

    const currentUserData = {
        userDetails,
        smartPlan,
        savedTimetables,
        notes,
        notificationSettings,
        trackedData,
        uploadedMaterials,
        courseCodeMap,
        quizState: {
            quiz: quizState.quiz,
            currentQuestionIndex: quizState.currentQuestionIndex,
            userAnswers: quizState.userAnswers,
        },
        // PERSIST HUB AND DASHBOARD STATE
        learningHubState: {
            ...learningHubState,
            isProcessing: false // Never persist loading state
        },
        dashboardInputs: {
            ...dashboardInputs,
            imageFile: null // Don't persist File objects (non-serializable), rely on imagePreview data URL
        }
    };

    // Save locally
    const allUsersData = storageService.loadItem<any>('usersData') || {};
    allUsersData[userDetails.email] = currentUserData;
    storageService.saveItem('usersData', allUsersData);

    // Sync to Cloud
    storageService.syncUserToCloud(userId, currentUserData);

  }, [userDetails, smartPlan, savedTimetables, notes, notificationSettings, trackedData, quizState, uploadedMaterials, courseCodeMap, learningHubState, dashboardInputs]);

    const loadUserData = useCallback((user: UserDetails) => {
        // Try to load from Local Storage first for speed
        const allUsersData = storageService.loadItem<any>('usersData') || {};
        let userData = allUsersData[user.email!];

        // Legacy cleanup (migration from old single-user structure)
        if (!userData) {
            const legacySmartPlan = storageService.loadItem('smartPlan');
            if (legacySmartPlan) {
                userData = {};
                userData.smartPlan = legacySmartPlan;
                userData.savedTimetables = storageService.loadItem('savedTimetables');
                userData.notes = storageService.loadItem('notes');
                userData.trackedData = storageService.loadItem('trackedData');
                userData.notificationSettings = storageService.loadItem('notificationSettings');
                userData.quizProgress = storageService.loadItem('quizProgress');
                userData.userDetails = storageService.loadItem('userDetails');
                userData.courseCodeMap = {}; 
                // Cleanup old keys
                ['smartPlan', 'savedTimetables', 'notes', 'trackedData', 'notificationSettings', 'quizProgress', 'userDetails'].forEach(key => storageService.removeItem(key));
            }
        }

        // Helper to apply state
        const applyState = (data: any) => {
            const finalUserDetails = { ...user, ...(data.userDetails || {}), usage: (data.userDetails?.usage || user.usage || initializeUsage()) };
            setUserDetails(finalUserDetails);
            setSmartPlan(data.smartPlan || null);
            setSavedTimetables(data.savedTimetables || []);
            setNotes(data.notes || []);
            setTrackedData(data.trackedData || []);
            setUploadedMaterials(data.uploadedMaterials || []);
            setNotificationSettings(data.notificationSettings || defaultNotificationSettings);
            setCourseCodeMap(data.courseCodeMap || {});

            if (data.quizState && data.quizState.quiz?.length > 0) {
                setQuizState({ ...defaultQuizState, ...data.quizState, feedback: null, summary: null });
            } else {
                setQuizState(defaultQuizState);
            }

            // Restore Persistent Hub State
            if (data.learningHubState) {
                setLearningHubState(prev => ({
                    ...prev,
                    ...data.learningHubState,
                    isProcessing: false // Ensure we don't start in a loading state
                }));
            }

            // Restore Persistent Dashboard Inputs
            if (data.dashboardInputs) {
                setDashboardInputs(prev => ({
                    ...prev,
                    ...data.dashboardInputs,
                    imageFile: null // File object cannot be restored, but imagePreview (data URL) should be there
                }));
            }
        };

        if (userData) {
            applyState(userData);
        } else {
            // New login on this device? Check cloud data
            // (Note: The login function in authService usually pre-populates localStorage from cloud, 
            // but we check here just in case)
            applyState({}); 
        }

    }, []);

    // Initialization Effect
    useEffect(() => {
        const init = async () => {
            try {
                const user = getCurrentUser();
                if (user) {
                    loadUserData(user);
                    setIsLoggedIn(true);
                }
            } catch (error) {
                console.error("Initialization error:", error);
            } finally {
                // Ensure the UI has time to update before removing loading screen
                setTimeout(() => setIsInitializing(false), 100);
            }
        };
        init();
    }, [loadUserData]);

  useEffect(() => {
    const handler = setTimeout(() => {
      if (isLoggedIn) {
        persistAllState();
      }
    }, 2000); // Debounce save to 2 seconds to reduce Firestore writes
    return () => clearTimeout(handler);
  }, [isLoggedIn, persistAllState]);

  // Safe check for Notification prompt in useEffect to prevent render crashes
  useEffect(() => {
    try {
        const shouldShow = notificationSettings.status === 'unconfigured' && 
                            typeof Notification !== 'undefined' && 
                            Notification.permission === 'default';
        setShowNotifPrompt(shouldShow);
    } catch (e) {
        setShowNotifPrompt(false);
    }
  }, [notificationSettings.status]);

  const dismissToast = (id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const handleWelcomeComplete = () => {
      setWelcomeComplete(true);
      storageService.saveItem('welcomeComplete', true);
  };

  const checkAndRun = async (
    feature: FeatureName,
    featureTitle: string,
    action: (...args: any[]) => Promise<void> | void,
    ...args: any[]
  ) => {
    if (!userDetails) return;
    try {
        await action(...args);
        setUserDetails(prev => prev ? { ...prev, usage: incrementUsage(prev.usage, feature) } : null);
        return true;
    } catch {
        return false; 
    }
  };


  const handleLogin = (user: UserDetails) => {
    loadUserData(user);
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    persistAllState(); 
    logout();

    setUserDetails(null);
    setIsLoggedIn(false);
    setSmartPlan(null);
    setSavedTimetables([]);
    setNotes([]);
    setActiveSession(null);
    setLearningHubState({ file: null, analysisMode: 'none', analysisResults: { summarize: null, explain: null, read: null }, chatHistory: [], isProcessing: false });
    setNotificationSettings(defaultNotificationSettings);
    setTrackedData([]);
    setUploadedMaterials([]);
    setQuizState(defaultQuizState);
    setCourseCodeMap({});
    setDashboardInputs({ lectures: [], studyGoals: [], agendaItems: [], generalGoals: '', imageFile: null, imagePreview: null, step: 1, isManualPlan: false, isEditing: false });
    setExamPrepState({ mode: 'quiz', topic: '', numQuestions: 5, quizType: QuizType.MCQ, uploadedFiles: [], focusArea: '', isVerifying: false, questionImage: null, questionText: '', solution: null, outputFormat: 'steps', programmingLanguage: 'python', graphInterval: '', graphYInterval: '', graphConfig: null });
    setProfileEditState({ isEditing: false, details: null });
    setNotesViewState({ currentNoteId: null, searchTerm: '' });
    setReportDraft({ category: 'bug', description: '', attachment: null, contactEmail: '', contactWhatsApp: '' });

    addToast(t('auth.logoutSuccess'), 'info');
  };

    const handleNewMaterialUpload = useCallback(async (fileToProcess: File) => {
        if (!userDetails) return;
        setLearningHubState(prev => ({...prev, isProcessing: true, processingMessage: t('uploadslides.verifying')}));

        try {
            const context = intendedStudyContext ? intendedStudyContext.fromSlot.activity : undefined;

            let base64String: string;
            let mimeType = fileToProcess.type;
            let finalSize = fileToProcess.size;

            if (fileToProcess.type.startsWith('image/')) {
                const resized = await processAndResizeImage(fileToProcess);
                base64String = resized.base64;
                mimeType = resized.mimeType;
                finalSize = atob(base64String).length;
            } else {
                base64String = await new Promise<string>((resolve, reject) => {
                    const reader = new FileReader();
                    reader.readAsDataURL(fileToProcess);
                    reader.onload = () => resolve((reader.result as string).split(',')[1]);
                    reader.onerror = error => reject(error);
                });
            }
            const filePart: ImagePart = { inlineData: { data: base64String, mimeType: mimeType } };

            const isMaterial = await isStudyMaterial(filePart, { fast: true });
            if (!isMaterial) {
                throw new Error(t('examprep.error.notStudyMaterial', { fileName: fileToProcess.name }));
            }

            let fileContext = context;
            if (!fileContext) {
                setLearningHubState(prev => ({ ...prev, processingMessage: t('uploadslides.extractingContext') }));
                fileContext = await getDocumentContext(filePart, { fast: true });
            }

            const processedFile: UploadedFile = {
                name: fileToProcess.name,
                type: mimeType,
                size: finalSize,
                base64: base64String,
                context: fileContext,
            };

            setLearningHubState(prev => ({ ...prev, file: processedFile, analysisMode: 'actions', analysisResults: { summarize: null, explain: null, read: null }, chatHistory: [] }));

            const newMaterial: UploadedMaterialInfo = {
                name: processedFile.name,
                type: processedFile.type,
                size: processedFile.size,
                context: processedFile.context,
                uploadedAt: new Date().toISOString()
            };

            setUploadedMaterials(prevMaterials => {
                const isNew = !prevMaterials.some(m => m.name === newMaterial.name && m.size === newMaterial.size);
                if (isNew) {
                    if (userDetails?.id) {
                        globalFeedbackService.trackMaterialUpload(userDetails.id).catch(console.error);
                    }
                    return [...prevMaterials, newMaterial];
                }
                return prevMaterials;
            });

        } catch (error: any) {
            addToast(error.message, 'error');
            throw error;
        } finally {
            setLearningHubState(prev => ({...prev, isProcessing: false, processingMessage: ''}));
        }
    }, [addToast, t, userDetails, intendedStudyContext]);

    const handleSavePlanAttempt = (planName: string) => {
        checkAndRun('timetables', '', () => {
            if (!smartPlan) return;
            const newPlan: StoredPlan = {
                id: Date.now().toString(),
                name: planName,
                createdAt: new Date().toISOString(),
                plan: smartPlan,
                isFavourite: false,
            };
            setSavedTimetables(prev => [...prev, newPlan]);
            addToast(t('toasts.planSaved'), 'success');
        });
    };

    const handleNewMaterialUploadAttempt = (file: File) => {
        checkAndRun('uploads', '', handleNewMaterialUpload, file);
    };

    const handleGenerateQuizAttempt = (apiAction: () => Promise<void>) => {
        checkAndRun('quizzes', '', apiAction);
    };

    const handleSolveProblemAttempt = (apiAction: () => Promise<void>) => {
        checkAndRun('solves', '', apiAction);
    };

    // Collaborative Session Handler
    const handleCollaborativeAction = (action: () => Promise<void>) => {
        checkAndRun('collaboration', 'Collaborative Session', action);
    };

  const handleBreakCompletion = (skipped: boolean) => {
    const breakSession = activeSession;
    if (!breakSession || breakSession.type !== 'break') {
        setActiveSession(null);
        setView('dashboard');
        return;
    }

    if (breakSession.postBreakView) {
        setActiveSession(null);
        setView(breakSession.postBreakView);
        return;
    }

    if (!smartPlan || !breakSession.day) {
        setActiveSession(null);
        setView('dashboard');
        return;
    }

    const dayPlan = smartPlan.find(d => d.day === breakSession.day);
    if (!dayPlan) {
        setActiveSession(null);
        setView('dashboard');
        return;
    }

    const sortedSlots = [...dayPlan.slots].sort((a,b) => timeToMinutes(a.startTime) - timeToMinutes(b.startTime));
    const breakIndex = sortedSlots.findIndex(s => s.startTime === breakSession.fromSlot.startTime && s.activity === breakSession.fromSlot.activity);

    if (breakIndex !== -1 && breakIndex + 1 < sortedSlots.length) {
        const nextSlot = sortedSlots[breakIndex + 1];

        if (nextSlot.type === ActivityType.STUDY) {
            const now = Date.now();
            const duration = timeToMinutes(nextSlot.endTime) - timeToMinutes(nextSlot.startTime);
            const nextNextSlot = breakIndex + 2 < sortedSlots.length ? sortedSlots[breakIndex + 2] : null;

            const newSession: ActiveSession = {
                startTime: now,
                endTime: now + duration * 60 * 1000,
                subject: nextSlot.activity,
                type: ActivityType.STUDY,
                fromSlot: nextSlot,
                nextSlot: nextNextSlot,
                durationMinutes: duration,
                day: breakSession.day,
            };
            setActiveSession(newSession);
            return;
        }
    }

    setActiveSession(null);
    setView('dashboard');
  };

  const isStudyMode = activeSession?.type === 'study';

  const renderView = () => {
    // Safety check for initialization
    if (!userDetails) return null;

    if (view === 'collaborative') {
        return (
            <CollaborativeSession 
                userDetails={userDetails}
                addToast={addToast}
                onActionAttempt={handleCollaborativeAction}
                activeCode={activeCode}
                setActiveCode={setActiveCode}
                notes={notes}
                setNotes={setNotes}
            />
        );
    }

    switch (view) {
      case 'dashboard':
        return <Dashboard 
                  setSmartPlan={setSmartPlan} 
                  smartPlan={smartPlan} 
                  userDetails={userDetails}
                  setUserDetails={setUserDetails}
                  savedTimetables={savedTimetables}
                  setSavedTimetables={setSavedTimetables}
                  addToast={addToast}
                  setActiveSession={setActiveSession}
                  trackedData={trackedData}
                  setTrackedData={setTrackedData}
                  generationState={generationState}
                  setGenerationState={setGenerationState}
                  dashboardInputs={dashboardInputs}
                  setDashboardInputs={setDashboardInputs}
                  setView={setView}
                  setIntendedStudyContext={setIntendedStudyContext}
                  setLearningHubState={setLearningHubState}
                  courseCodeMap={courseCodeMap}
                  setCourseCodeMap={setCourseCodeMap}
                  onSavePlanAttempt={handleSavePlanAttempt}
               />;
      case 'profile':
        return <Profile 
                    userDetails={userDetails} 
                    setUserDetails={setUserDetails} 
                    addToast={addToast} 
                    profileEditState={profileEditState}
                    setProfileEditState={setProfileEditState}
                />;
      case 'mytimetables':
        return <MyTimetables savedTimetables={savedTimetables} setSavedTimetables={setSavedTimetables} onLoadPlan={(plan) => { setSmartPlan(plan); setView('dashboard'); }} addToast={addToast} userDetails={userDetails} />;
      case 'progression':
        return <Progression plan={smartPlan} trackedData={trackedData} userDetails={userDetails} />;
      case 'notes':
        return <Notes 
                    notes={notes} 
                    setNotes={setNotes} 
                    notesViewState={notesViewState}
                    setNotesViewState={setNotesViewState}
                />;
      case 'uploadslides':
        return <UploadSlides
                  smartPlan={smartPlan}
                  setSmartPlan={setSmartPlan}
                  activeSession={activeSession}
                  setActiveSession={setActiveSession}
                  setView={setView}
                  addToast={addToast}
                  learningHubState={learningHubState}
                  setLearningHubState={setLearningHubState}
                  notes={notes}
                  setNotes={setNotes}
                  intendedStudyContext={intendedStudyContext}
                  setIntendedStudyContext={setIntendedStudyContext}
                  onAttemptUpload={handleNewMaterialUploadAttempt}
                />;
      case 'examprep':
        return <ExamPrep 
                    addToast={addToast} 
                    setView={setView}
                    generationState={generationState}
                    setGenerationState={setGenerationState}
                    quizState={quizState}
                    setQuizState={setQuizState}
                    notes={notes}
                    setNotes={setNotes}
                    examPrepState={examPrepState}
                    setExamPrepState={setExamPrepState}
                    onGenerateQuizAttempt={handleGenerateQuizAttempt}
                    onSolveProblemAttempt={handleSolveProblemAttempt}
                />;
      case 'language':
        return <LanguageSettings />;
      case 'theme':
        return <ThemeSettings />;
      case 'notification':
        return <NotificationSettingsComponent settings={notificationSettings} setSettings={setNotificationSettings} />;
      case 'settings':
        return <Settings 
                    addToast={addToast} 
                    handleLogout={handleLogout}
                    userDetails={userDetails}
                    setShowUpgradeModal={() => {}} // No-op as upgrades are gone
                />;
      case 'report':
        return <Reports 
                    userDetails={userDetails} 
                    reportDraft={reportDraft}
                    setReportDraft={setReportDraft}
                    addToast={addToast}
                />;
      case 'feedback':
        return <Feedback 
                    userDetails={userDetails} 
                    addToast={addToast} 
                />;
      case 'help':
        return <Help setView={setView} />;
      case 'about':
        return <About setView={setView} />;
      case 'library':
        return <Library />;
      case 'terms':
        return <Terms />;
      case 'tutorial':
        return <Tutorial
                    addToast={addToast}
                    tutorialVideoUrl={tutorialVideoUrl}
                />;
      default:
        return <div>{t('common.notFound')}</div>;
    }
  };

  // INITIALIZATION STATE: Prevents "Blank Screen"
  if (isInitializing) {
      return (
          <div className="flex flex-col h-screen h-[100dvh] bg-gray-100 dark:bg-gray-900 items-center justify-center">
              <div className="relative">
                  <div className="w-16 h-16 border-4 border-gray-200 dark:border-gray-700 border-t-primary rounded-full animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center">
                      <LogoIcon className="w-8 h-8 text-primary animate-pulse" />
                  </div>
              </div>
              <h1 className="mt-4 text-xl font-bold text-gray-800 dark:text-white tracking-wide">EduBlay</h1>
              <p className="text-sm text-gray-500 dark:text-gray-400 mt-1 animate-pulse">Loading your workspace...</p>
          </div>
      );
  }

  if (!isLoggedIn) {
    if (!welcomeComplete) {
        return <Welcome onProceed={handleWelcomeComplete} />;
    }
    return <SignUp onLogin={handleLogin} />;
  }

  if (isStudyMode) {
     return <FocusedStudyView 
                session={activeSession!} 
                setSession={setActiveSession}
                addToast={addToast}
                trackedData={trackedData}
                setTrackedData={setTrackedData}
                setView={setView}
                learningHubState={learningHubState}
                setLearningHubState={setLearningHubState}
            />;
  }

  return (
    <div className="flex h-screen h-[100dvh] bg-gray-100 dark:bg-gray-900 text-gray-900 dark:text-gray-100 overflow-hidden">
      <NotificationManager plan={smartPlan} settings={notificationSettings} />
      <ToastContainer toasts={toasts} onDismiss={dismissToast} />
      <Sidebar view={view} setView={setView} isOpen={sidebarOpen} setOpen={setSidebarOpen} userDetails={userDetails} />
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        {showNotifPrompt && <NotificationPrompt settings={notificationSettings} setSettings={setNotificationSettings} />}
        <Header 
            toggleSidebar={() => setSidebarOpen(!sidebarOpen)} 
            userDetails={userDetails} 
            setView={setView} 
            addToast={addToast}
            handleLogout={handleLogout}
        />
        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 dark:bg-gray-900 p-4 sm:p-6 lg:p-8">
          {renderView()}
        </main>
      </div>
       {activeSession?.type === 'break' && <BreakView session={activeSession} onEnd={handleBreakCompletion} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import type { NotificationSettings } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { notificationService } from '../services/notificationService';
import { VolumeIcon } from './icons/VolumeIcon';

interface NotificationSettingsProps {
    settings: NotificationSettings;
    setSettings: (settings: NotificationSettings) => void;
}

const NotificationSettingsComponent: React.FC<NotificationSettingsProps> = ({ settings, setSettings }) => {
    const { t } = useLanguage();
    const [isCustomTime, setIsCustomTime] = useState(false);
    const [permissionStatus, setPermissionStatus] = useState<NotificationPermission | 'unsupported'>('default');
    const [isSupported, setIsSupported] = useState(true);

    // Safely check notification support and status
    useEffect(() => {
        const checkSupport = () => {
            try {
                if (typeof window === 'undefined' || !('Notification' in window)) {
                    setIsSupported(false);
                    setPermissionStatus('unsupported');
                    return;
                }
                setPermissionStatus(Notification.permission);
            } catch (e) {
                console.warn("Notification API access failed:", e);
                setIsSupported(false);
                setPermissionStatus('unsupported');
            }
        };

        checkSupport();

        // Poll for changes safely
        const interval = setInterval(() => {
            try {
                if (typeof Notification !== 'undefined' && 'permission' in Notification) {
                     setPermissionStatus(Notification.permission);
                }
            } catch (e) {
                // Ignore errors during polling
            }
        }, 1000);
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        if (settings && ![5, 10, 15].includes(settings.reminderTime)) {
            setIsCustomTime(true);
        } else {
            setIsCustomTime(false);
        }
    }, [settings]);

    const handleRequestPermission = async () => {
        if (!isSupported) {
            alert('Notifications are not supported on this device.');
            return;
        }

        try {
            const permission = await notificationService.requestPermission();
            setPermissionStatus(permission);

            if (permission === 'granted') {
                setSettings({
                    ...settings,
                    enabled: true,
                    status: 'configured',
                    reminders: true,
                    sessionStart: true,
                    breakStartEnd: true
                });
            }
        } catch (error) {
            console.error('Error requesting permission:', error);
        }
    };

    const updateSetting = <K extends keyof NotificationSettings>(key: K, value: NotificationSettings[K]) => {
        setSettings({ ...settings, [key]: value });
    };

    const handleMasterSwitchChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const isEnabled = e.target.checked;

        if (isEnabled) {
            if (!isSupported) {
                setSettings({
                    ...settings,
                    enabled: true,
                    status: 'configured'
                });
                alert('Notifications are not supported by this browser/device.');
                return;
            }

            try {
                if (Notification.permission === 'granted') {
                    setSettings({
                        ...settings,
                        enabled: true,
                        status: 'configured'
                    });
                } else if (Notification.permission === 'denied') {
                    setSettings({
                        ...settings,
                        enabled: true,
                        status: 'configured'
                    });
                } else {
                    setSettings({
                        ...settings,
                        enabled: true,
                        status: 'configured'
                    });
                    await handleRequestPermission();
                }
            } catch (e) {
                 // Fallback if permission check fails
                 setSettings({
                    ...settings,
                    enabled: true,
                    status: 'configured'
                });
            }
        } else {
            updateSetting('enabled', false);
        }
    };

    const handleReminderTimeSelect = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const value = e.target.value;
        if (value === 'custom') {
            setIsCustomTime(true);
        } else {
            setIsCustomTime(false);
            updateSetting('reminderTime', parseInt(value, 10));
        }
    };

    const baseInputClasses = "block w-full px-3 py-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm placeholder-gray-400 text-gray-900 dark:text-gray-200 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm";

    if (!settings) return null;

    if (!isSupported) {
        return (
             <div className="max-w-2xl mx-auto">
                <h2 className="text-3xl font-bold text-gray-800 dark:text-white mb-6">
                    {t('preferences.notifications.title') || 'Notifications'}
                </h2>
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6 border dark:border-gray-700">
                    <div className="p-4 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg text-center">
                        <p className="text-yellow-800 dark:text-yellow-200 font-medium">
                            Notifications are not supported on this browser or device.
                        </p>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="max-w-2xl mx-auto">
            <div>
                <h2 className="text-3xl font-bold text-gray-800 dark:text-white mb-6">
                    {t('preferences.notifications.title') || 'Notifications'}
                </h2>
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6 border dark:border-gray-700 transition-all duration-300">
                <div className="space-y-6">
                    {/* Master Switch */}
                    <div className="flex items-center justify-between pb-4 border-b dark:border-gray-700">
                        <div className="flex-1">
                            <label htmlFor="master-switch" className="font-semibold text-lg cursor-pointer block">
                                {t('notifications.enable') || 'Enable Notifications'}
                            </label>
                            {/* Status Text */}
