            quiz: quizState.quiz,
            currentQuestionIndex: quizState.currentQuestionIndex,
            userAnswers: quizState.userAnswers,
        },
        // PERSIST HUB AND DASHBOARD STATE
        learningHubState: {
            ...learningHubState,
            isProcessing: false // Never persist loading state
        },
        dashboardInputs: {
            ...dashboardInputs,
            imageFile: null // Don't persist File objects (non-serializable), rely on imagePreview data URL
        }
    };

    // Save locally
    const allUsersData = storageService.loadItem<any>('usersData') || {};
    allUsersData[userDetails.email] = currentUserData;
    storageService.saveItem('usersData', allUsersData);

    // Sync to Cloud
    storageService.syncUserToCloud(userId, currentUserData);

  }, [userDetails, smartPlan, savedTimetables, notes, notificationSettings, trackedData, quizState, uploadedMaterials, courseCodeMap, learningHubState, dashboardInputs]);

    const loadUserData = useCallback((user: UserDetails) => {
        // Try to load from Local Storage first for speed
        const allUsersData = storageService.loadItem<any>('usersData') || {};
        let userData = allUsersData[user.email!];

        // Legacy cleanup (migration from old single-user structure)
        if (!userData) {
            const legacySmartPlan = storageService.loadItem('smartPlan');
            if (legacySmartPlan) {
                userData = {};
                userData.smartPlan = legacySmartPlan;
                userData.savedTimetables = storageService.loadItem('savedTimetables');
                userData.notes = storageService.loadItem('notes');
                userData.trackedData = storageService.loadItem('trackedData');
                userData.notificationSettings = storageService.loadItem('notificationSettings');
                userData.quizProgress = storageService.loadItem('quizProgress');
                userData.userDetails = storageService.loadItem('userDetails');
                userData.courseCodeMap = {}; 
                // Cleanup old keys
                ['smartPlan', 'savedTimetables', 'notes', 'trackedData', 'notificationSettings', 'quizProgress', 'userDetails'].forEach(key => storageService.removeItem(key));
            }
        }

        // Helper to apply state
        const applyState = (data: any) => {
            const finalUserDetails = { ...user, ...(data.userDetails || {}), usage: (data.userDetails?.usage || user.usage || initializeUsage()) };
            setUserDetails(finalUserDetails);
            setSmartPlan(data.smartPlan || null);
            setSavedTimetables(data.savedTimetables || []);
            setNotes(data.notes || []);
            setTrackedData(data.trackedData || []);
            setUploadedMaterials(data.uploadedMaterials || []);
            setNotificationSettings(data.notificationSettings || defaultNotificationSettings);
            setCourseCodeMap(data.courseCodeMap || {});

            if (data.quizState && data.quizState.quiz?.length > 0) {
                setQuizState({ ...defaultQuizState, ...data.quizState, feedback: null, summary: null });
            } else {
                setQuizState(defaultQuizState);
            }

            // Restore Persistent Hub State
            if (data.learningHubState) {
                setLearningHubState(prev => ({
                    ...prev,
                    ...data.learningHubState,
                    isProcessing: false // Ensure we don't start in a loading state
                }));
            }

            // Restore Persistent Dashboard Inputs
            if (data.dashboardInputs) {
                setDashboardInputs(prev => ({
                    ...prev,
                    ...data.dashboardInputs,
                    imageFile: null // File object cannot be restored, but imagePreview (data URL) should be there
                }));
            }
        };

        if (userData) {
            applyState(userData);
        } else {
            // New login on this device? Check cloud data
            // (Note: The login function in authService usually pre-populates localStorage from cloud, 
            // but we check here just in case)
            applyState({}); 
        }

    }, []);

    useEffect(() => {
        const user = getCurrentUser();
        if (user) {
            loadUserData(user);
            setIsLoggedIn(true);
        }
    }, [loadUserData]);

  useEffect(() => {
    const handler = setTimeout(() => {
      if (isLoggedIn) {
        persistAllState();
      }
    }, 2000); // Debounce save to 2 seconds to reduce Firestore writes
    return () => clearTimeout(handler);
  }, [isLoggedIn, persistAllState]);

  const dismissToast = (id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id));
