                  savedTimetables={savedTimetables}
                  setSavedTimetables={setSavedTimetables}
                  addToast={addToast}
                  setActiveSession={setActiveSession}
                  trackedData={trackedData}
                  setTrackedData={setTrackedData}
                  generationState={generationState}
                  setGenerationState={setGenerationState}
                  dashboardInputs={dashboardInputs}
                  setDashboardInputs={setDashboardInputs}
                  setView={setView}
                  setIntendedStudyContext={setIntendedStudyContext}
                  setLearningHubState={setLearningHubState}
                  courseCodeMap={courseCodeMap}
                  setCourseCodeMap={setCourseCodeMap}
                  onSavePlanAttempt={handleSavePlanAttempt}
               />;
      case 'profile':
        return <Profile 
                    userDetails={userDetails} 
                    setUserDetails={setUserDetails} 
                    addToast={addToast} 
                    profileEditState={profileEditState}
                    setProfileEditState={setProfileEditState}
                />;
      case 'mytimetables':
        return <MyTimetables savedTimetables={savedTimetables} setSavedTimetables={setSavedTimetables} onLoadPlan={(plan) => { setSmartPlan(plan); setView('dashboard'); }} addToast={addToast} userDetails={userDetails} />;
      case 'progression':
        return <Progression plan={smartPlan} trackedData={trackedData} userDetails={userDetails} />;
      case 'notes':
        return <Notes 
                    notes={notes} 
                    setNotes={setNotes} 
                    notesViewState={notesViewState}
                    setNotesViewState={setNotesViewState}
                />;
      case 'uploadslides':
        return <UploadSlides
                  smartPlan={smartPlan}
                  setSmartPlan={setSmartPlan}
                  activeSession={activeSession}
                  setActiveSession={setActiveSession}
                  setView={setView}
                  addToast={addToast}
                  learningHubState={learningHubState}
                  setLearningHubState={setLearningHubState}
                  notes={notes}
                  setNotes={setNotes}
                  intendedStudyContext={intendedStudyContext}
                  setIntendedStudyContext={setIntendedStudyContext}
                  onAttemptUpload={handleNewMaterialUploadAttempt}
                />;
      case 'examprep':
        return <ExamPrep 
                    addToast={addToast} 
                    setView={setView}
                    generationState={generationState}
                    setGenerationState={setGenerationState}
                    quizState={quizState}
                    setQuizState={setQuizState}
                    notes={notes}
                    setNotes={setNotes}
                    examPrepState={examPrepState}
                    setExamPrepState={setExamPrepState}
                    onGenerateQuizAttempt={handleGenerateQuizAttempt}
                    onSolveProblemAttempt={handleSolveProblemAttempt}
                />;
      case 'language':
        return <LanguageSettings />;
      case 'theme':
        return <ThemeSettings />;
      case 'notification':
        return <NotificationSettingsComponent settings={notificationSettings} setSettings={setNotificationSettings} />;
      case 'settings':
        return <Settings 
                    addToast={addToast} 
                    handleLogout={handleLogout}
                    userDetails={userDetails}
                    setShowUpgradeModal={() => {}} // No-op as upgrades are gone
                />;
      case 'report':
        return <Reports 
                    userDetails={userDetails} 
                    reportDraft={reportDraft}
                    setReportDraft={setReportDraft}
                    addToast={addToast}
                />;
      case 'feedback':
        return <Feedback 
                    userDetails={userDetails} 
                    addToast={addToast} 
                />;
      case 'help':
        return <Help setView={setView} />;
      case 'about':
        return <About setView={setView} />;
      case 'library':
        return <Library />;
      case 'terms':
        return <Terms />;
      case 'tutorial':
        return <Tutorial
                    addToast={addToast}
                    tutorialVideoUrl={tutorialVideoUrl}
                />;
      default:
        return <div>{t('common.notFound')}</div>;
    }
  };

  if (!isLoggedIn) {
    if (!welcomeComplete) {
        return <Welcome onProceed={handleWelcomeComplete} />;
    }
    return <SignUp onLogin={handleLogin} />;
  }

  if (isStudyMode) {
     return <FocusedStudyView 
                session={activeSession!} 
                setSession={setActiveSession}
                addToast={addToast}
                trackedData={trackedData}
                setTrackedData={setTrackedData}
                setView={setView}
                learningHubState={learningHubState}
                setLearningHubState={setLearningHubState}
            />;
  }

  const showNotifPrompt = notificationSettings.status === 'unconfigured' && typeof Notification !== 'undefined' && Notification.permission === 'default';

  return (
    <div className="flex h-screen bg-gray-100 dark:bg-gray-900 text-gray-900 dark:text-gray-100">
      <NotificationManager plan={smartPlan} settings={notificationSettings} />
      <ToastContainer toasts={toasts} onDismiss={dismissToast} />
      <Sidebar view={view} setView={setView} isOpen={sidebarOpen} setOpen={setSidebarOpen} userDetails={userDetails} />
      <div className="flex-1 flex flex-col overflow-hidden">
        {showNotifPrompt && <NotificationPrompt settings={notificationSettings} setSettings={setNotificationSettings} />}
        <Header 
            toggleSidebar={() => setSidebarOpen(!sidebarOpen)} 
            userDetails={userDetails} 
            setView={setView} 
            addToast={addToast}
            handleLogout={handleLogout}
        />
        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 dark:bg-gray-900 p-4 sm:p-6 lg:p-8">
          {renderView()}
        </main>
      </div>
       {activeSession?.type === 'break' && <BreakView session={activeSession} onEnd={handleBreakCompletion} />}
    </div>
  );
};

export default App;

import { GoogleGenAI, HarmCategory, HarmBlockThreshold, GenerateContentResponse, Type } from "@google/genai";
import type { UserDetails, Lecture, StudyGoal, AgendaItem, SmartPlan, ImagePart, QuizQuestion, QuizType, ChatTurn } from '../types';

// ============================================
// CORE CONFIGURATION
// ============================================

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });

const safetySettings = [
    { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
];

// Fast model for all operations
const MODEL = 'gemini-2.5-flash';

// ============================================
// SIMPLIFIED CACHE
// ============================================

class FastCache {
    private cache = new Map<string, any>();
    private readonly MAX_SIZE = 50;

    get(key: string): any | null {
        return this.cache.get(key) ?? null;
    }

    set(key: string, data: any): void {
        if (this.cache.size >= this.MAX_SIZE) {
            const first = this.cache.keys().next().value;
            this.cache.delete(first);
        }
        this.cache.set(key, data);
    }

    clear(): void {
        this.cache.clear();
    }
}

const cache = new FastCache();

// ============================================
// OPTIMIZED SCHEMAS
// ============================================

const planSlotSchema = {
    type: Type.OBJECT,
    properties: {
        activity: { type: Type.STRING },
        startTime: { type: Type.STRING },
        endTime: { type: Type.STRING },
        type: { type: Type.STRING }, // 'lecture', 'break', 'free'
        code: { type: Type.STRING },
        location: { type: Type.STRING },
        durationMinutes: { type: Type.NUMBER },
    },
    required: ['activity', 'startTime', 'endTime', 'type']
};

const smartPlanSchema = {
    type: Type.ARRAY,
    items: {
        type: Type.OBJECT,
        properties: {
            day: { type: Type.STRING },
            slots: { type: Type.ARRAY, items: planSlotSchema }
        },
        required: ['day', 'slots']
    }
};

const quizSchema = {
    type: Type.ARRAY,
    items: {
        type: Type.OBJECT,
        properties: {
            question: { type: Type.STRING },
            options: { type: Type.ARRAY, items: { type: Type.STRING } },
            correctAnswer: { type: Type.STRING },
            explanation: { type: Type.STRING },
            topic: { type: Type.STRING },
            type: { type: Type.STRING },
        },
        required: ['question', 'correctAnswer', 'explanation', 'topic', 'type']
    }
};

const graphSolutionSchema = {
    type: Type.OBJECT,
    properties: {
        explanation: { type: Type.STRING },
        graphFunction: { type: Type.STRING },
        suggestedTitle: { type: Type.STRING },
    },
    required: ['explanation', 'graphFunction']
};

const tableSchema = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING },
        headers: { type: Type.ARRAY, items: { type: Type.STRING } },
        rows: { type: Type.ARRAY, items: { type: Type.ARRAY, items: { type: Type.STRING } } },
        caption: { type: Type.STRING }
    },
    required: ['headers', 'rows']
};

// ============================================
// FAST PARSER
// ============================================

const parseJSON = <T>(response: GenerateContentResponse, fallback?: T): T => {
    try {
        let text = response.text?.trim() || "";

        // Strip markdown if present
        if (text.startsWith('```')) {
            const start = text.indexOf('{') !== -1 ? text.indexOf('{') : text.indexOf('[');
            const end = text.lastIndexOf('}') !== -1 ? text.lastIndexOf('}') : text.lastIndexOf(']');
            if (start !== -1 && end !== -1) {
                text = text.substring(start, end + 1);
            }
        }

        return JSON.parse(text) as T;
    } catch (e) {
        console.error("Parse error:", e);
        if (fallback !== undefined) return fallback;
        throw new Error("Failed to parse AI response");
    }
};

// ============================================
// CLEAN & OPTIMIZE PLAN OUTPUT
// ============================================

const cleanPlan = (plan: SmartPlan): SmartPlan => {
    return plan.map(dayPlan => ({
        ...dayPlan,
        slots: dayPlan.slots.map(slot => {
            let { activity, type, code, location } = slot;

            // Use course codes when available
            if (code && type === 'lecture') {
                activity = code.toUpperCase();
            }

            // Remove redundant words
            activity = activity
                .replace(/\s+(study|session|class|lecture)$/i, '')
                .trim();

            // Lectures can have locations, breaks/free cannot
            if (type !== 'lecture') {
                location = undefined;
            }

            return { ...slot, activity, location };
        })
    }));
};

// ============================================
// SMART PLAN GENERATION (SIMPLIFIED & FAST)
// ============================================

export const generateSmartPlan = async (
    userDetails: UserDetails,
    lectures: Lecture[],
    studyGoals: StudyGoal[], // IGNORED
    agendaItems: AgendaItem[], // IGNORED
    generalGoals: string, // IGNORED
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const cacheKey = `plan_${JSON.stringify(lectures).substring(0, 80)}`;
    const cached = cache.get(cacheKey);
    if (cached) return cached;

    const prompt = `Create a weekly class schedule with breaks and free time in JSON format.

**Input:**
- User: ${userDetails.name} (${userDetails.programmeOfStudy || 'student'})
- Lectures: ${JSON.stringify(lectures)}

**Requirements:**
1. **Add all lectures** from input with exact times and course codes
2. **Add 15-30 min breaks** between consecutive classes
3. **Mark remaining time as 'free'** (mornings, evenings, weekends)
4. **Use course codes** as activity names (e.g., "MATH 101" not "Mathematics Study")
5. **Locations** only for lectures, not for breaks/free time

**Slot Types:**
- 'lecture': Classes from input (WITH location)
- 'break': Short rest periods between classes (NO location)
- 'free': Unscheduled time (NO location)

**Format:**
- 7 days (Monday-Sunday)
- Times in "HH:MM AM/PM" format
- Clean course codes without suffixes

Return ONLY the JSON array.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: {
            responseMimeType: 'application/json',
            responseSchema: smartPlanSchema,
            temperature: 0.2,
            safetySettings,
        },
    });

    const plan = parseJSON<SmartPlan>(response, []);
    const cleaned = cleanPlan(plan);

    cache.set(cacheKey, cleaned);
    return cleaned;
};

// ============================================
// IMAGE-BASED PLAN (SIMPLIFIED & FAST)
// ============================================

export const generatePlanFromImage = async (
    userDetails: UserDetails,
    studyGoals: StudyGoal[], // IGNORED
    agendaItems: AgendaItem[], // IGNORED
    generalGoals: string, // IGNORED
    image: ImagePart,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const prompt = `Extract class schedule from this timetable image and create a weekly plan in JSON.

**Instructions:**
1. **Find all classes/lectures** - extract course codes, times, locations
2. **Add 15-30 min breaks** between back-to-back classes
3. **Mark remaining time as 'free'**
4. **Use exact course codes** from image (e.g., "BIO 304", "STAT 243")
5. **Clean names** - no suffixes like "Study" or "Session"

**Slot Types:**
- 'lecture': Classes from timetable (WITH location)
- 'break': Rest periods (NO location)
- 'free': Unscheduled time (NO location)

**Format:**
- 7 days, "HH:MM AM/PM" times
- Use course codes as-is from image

Return ONLY JSON array.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: prompt }, image] },
        config: {
            responseMimeType: 'application/json',
            responseSchema: smartPlanSchema,
            temperature: 0.2,
            safetySettings,
        },
    });

    const plan = parseJSON<SmartPlan>(response, []);
    return cleanPlan(plan);
};

// ============================================
// FAST IMAGE CLASSIFICATION
// ============================================

export const isImageTimetable = async (image: ImagePart): Promise<boolean> => {
    const cacheKey = `tt_${image.inlineData.data.substring(0, 40)}`;
    const cached = cache.get(cacheKey);
    if (cached !== null) return cached;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: "Is this a class timetable/schedule? Answer: true or false" }, image] },
        config: { safetySettings, maxOutputTokens: 5 },
    });

    const result = response.text?.trim().toLowerCase().includes('true') || false;
    cache.set(cacheKey, result);
    return result;
};

export const isStudyMaterial = async (file: ImagePart, options?: { fast: boolean }): Promise<boolean> => {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: "Is this educational/academic material? true/false" }, file] },
        config: { safetySettings, maxOutputTokens: 5 },
    });
    return response.text?.trim().toLowerCase().includes('true') || false;
};

export const isImageAProblem = async (image: ImagePart): Promise<boolean> => {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: "Is this an academic problem/question? true/false" }, image] },
        config: { safetySettings, maxOutputTokens: 5 },
    });
    return response.text?.trim().toLowerCase().includes('true') || false;
};

// ============================================
// DOCUMENT ANALYSIS (OPTIMIZED)
// ============================================

export const getDocumentContext = async (file: ImagePart, options?: { fast: boolean }): Promise<string> => {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: "What subject/topic? (1-3 words)" }, file] },
        config: { safetySettings, maxOutputTokens: 20 },
    });
    return response.text?.trim() || "Unknown Subject";
};

export const summarizeDocument = async (file: ImagePart, context: string, options?: { fast: boolean }): Promise<string> => {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: `Summarize this ${context} material. Use markdown formatting.` }, file] },
        config: { safetySettings, maxOutputTokens: 800 },
    });
    return response.text?.trim() || "";
};

export const explainDocument = async (file: ImagePart, context: string, options?: { fast: boolean }): Promise<string> => {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: `Explain this ${context} material simply. Use markdown.` }, file] },
        config: { safetySettings, maxOutputTokens: 1000 },
    });
    return response.text?.trim() || "";
};

export const extractTextFromDocument = async (file: ImagePart, options?: { fast: boolean }): Promise<string> => {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: "Extract all text. Preserve formatting with markdown." }, file] },
        config: { safetySettings, maxOutputTokens: 2000 },
    });
    return response.text?.trim() || "";
};

// ============================================
// INTERACTIVE CHAT (STREAMING)
// ============================================

export const chatWithDocumentStream = async (
    file: ImagePart | null,
    userMessage: string,
    history: ChatTurn[],
    context: string,
    smartPlan?: SmartPlan | null
) => {
    const chatHistory = history.map(turn => ([
        { role: 'user', parts: [{ text: turn.user }] },
        { role: 'model', parts: [{ text: turn.blay }] }
    ])).flat();

    const systemInstruction = `You are Blay, a helpful AI tutor. Context: ${context}. Use markdown for formatting.`;

    const contents: any = [...chatHistory];
    const userParts: ({ text: string } | ImagePart)[] = [{ text: userMessage }];
    if (file) userParts.push(file);
    contents.push({ role: 'user', parts: userParts });

    return await ai.models.generateContentStream({
        model: MODEL,
        contents,
        config: { systemInstruction, safetySettings },
    });
};

// ============================================
// QUIZ GENERATION (OPTIMIZED)
// ============================================

export const generateQuiz = async (
    context: string,
    numQuestions: number,
    quizType: QuizType,
    focusArea: string
): Promise<QuizQuestion[]> => {
    const prompt = `Generate ${numQuestions} ${quizType} questions about ${focusArea || context.substring(0, 200)}.

Rules:
- MCQ questions must have 4 options
- Theory questions have no options
- Include explanations
- Return ONLY JSON array

Context: ${context.substring(0, 8000)}`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: { 
            responseMimeType: 'application/json',
            responseSchema: quizSchema,
            temperature: 0.5,
            safetySettings 
        },
    });

    return parseJSON<QuizQuestion[]>(response, []);
};

// ============================================
// PROBLEM SOLVER (OPTIMIZED)
// ============================================

export const solveProblem = async (
    questionText: string,
    imagePart: ImagePart | null,
    outputFormat: string,
    programmingLanguage: string,
    graphInterval?: string,
    graphYInterval?: string,
): Promise<string> => {
    let prompt = `Solve this problem:\n${questionText}\n\n`;

    if (outputFormat === 'code') {
        prompt += `Provide solution as ${programmingLanguage} code in a markdown code block.`;
    } else if (outputFormat === 'latex') {
        prompt += `Return raw LaTeX code in a markdown code block. Do NOT render, just provide the source code.`;
    } else if (outputFormat === 'graph') {
        prompt += `Return JSON with: {explanation, graphFunction (e.g., "x^2 + 2x - 1"), suggestedTitle}`;
        if (graphInterval) prompt += `\nX range: ${graphInterval}`;
    } else {
        prompt += `Explain step-by-step using markdown and LaTeX math notation.`;
    }

    const contents: any = { parts: [{ text: prompt }] };
    if (imagePart) contents.parts.push(imagePart);

    const response = await ai.models.generateContent({
        model: MODEL,
        contents,
        config: {
            ...(outputFormat === 'graph' ? { 
                responseMimeType: 'application/json',
                responseSchema: graphSolutionSchema
            } : {}),
            safetySettings,
        },
    });

    return response.text?.trim() || "";
};

// ============================================
// WEEKLY PROGRESS COACH
// ============================================

export const generateWeeklyProgressComment = async (
    userDetails: UserDetails,
    weeklyData: { subject: string; scheduledHours: number; trackedHours: number }[]
): Promise<string> => {
    const prompt = `As Blay (motivational coach), give ${userDetails.name} brief encouraging feedback (2-3 sentences) on their weekly study progress:\n${JSON.stringify(weeklyData, null, 2)}`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: { temperature: 0.8, safetySettings, maxOutputTokens: 100 },
    });

    return response.text?.trim() || "";
};

// ============================================
// TABLE EXTRACTION & GENERATION
// ============================================

export const extractTablesFromImage = async (image: ImagePart): Promise<any> => {
    const prompt = `Extract table data to JSON format: {title, headers[], rows[][]}.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: prompt }, image] },
        config: {
            responseMimeType: 'application/json',
            responseSchema: tableSchema,
            safetySettings,
        },
    });

    return parseJSON<any>(response, null);
};

export const generateComparisonTable = async (
    topic: string,
    items: string[],
    criteria: string[]
): Promise<any> => {
    const prompt = `Create comparison table for ${topic}. Compare: ${items.join(', ')}. Criteria: ${criteria.join(', ')}. Return JSON.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: {
            responseMimeType: 'application/json',
            responseSchema: tableSchema,
            safetySettings,
        },
    });

    return parseJSON<any>(response, null);
};

export const convertTextToTable = async (text: string, context?: string): Promise<any> => {
    const prompt = `Convert this text to a structured table in JSON format:\n${text.substring(0, 4000)}`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: {
            responseMimeType: 'application/json',
            responseSchema: tableSchema,
            safetySettings,
        },
    });

    return parseJSON<any>(response, null);
};

// ============================================
// UTILITY
// ============================================

export const clearGeminiCache = (): void => {
    cache.clear();
    console.log('🔄 Cache cleared');
};

console.log('⚡ Fast Gemini Service Ready');

