                </div>
                <div>
                    <p className="text-gray-600">Average Rating</p>
                    <p className="text-3xl font-bold">{stats.averageRating}⭐</p>
                </div>
                <div>
                    <p className="text-gray-600">Total Ratings</p>
                    <p className="text-3xl font-bold">{stats.totalRatings}</p>
                </div>
