}

const COMMON_EMOJIS = ["😀", "😂", "🤣", "😊", "😍", "🤔", "😎", "😭", "👍", "👎", "👋", "🙏", "🔥", "✨", "🎉", "💯", "❤️", "💔", "🎓", "📚", "🧠", "💡", "✅", "❌"];

export function CollaborativeSession({ userDetails, addToast, onActionAttempt, activeCode, setActiveCode, notes, setNotes }: CollaborativeSessionProps) {
  // View State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  // Data State
  const [sessionHistory, setSessionHistory] = useState<SessionData[]>([]);
  const [sessionCode, setSessionCode] = useState('');
  const [sessionData, setSessionData] = useState<SessionData | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);

  // Input State
  const [inputCode, setInputCode] = useState('');
  const [newMessage, setNewMessage] = useState('');
  const [isAIThinking, setIsAIThinking] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [showLeaveConfirm, setShowLeaveConfirm] = useState(false);
  const [showJoinModal, setShowJoinModal] = useState(false);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);

  // Dictation State (Speech-to-Text)
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  // Typing Indicator State
  const typingTimeoutRef = useRef<any>(null);
  const [activeTypers, setActiveTypers] = useState<string[]>([]);

  // Editing & Deleting State
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);
  const [editMessageText, setEditMessageText] = useState('');
  const [sessionToDelete, setSessionToDelete] = useState<string | null>(null);
  const [messageToDelete, setMessageToDelete] = useState<Message | null>(null);

  // Invite & Pairing State
  const [createdSessionCode, setCreatedSessionCode] = useState<string | null>(null);
  const [showShareConfirm, setShowShareConfirm] = useState(false);

  // Strict Verification & View Mode State
  const [isVerifyingConnection, setIsVerifyingConnection] = useState(false);
  const [connectionSuccess, setConnectionSuccess] = useState(false);
  const [isViewOnly, setIsViewOnly] = useState(false);
  const [historyActionSession, setHistoryActionSession] = useState<SessionData | null>(null);

  // Refs
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const unsubscribeRef = useRef<(() => void) | null>(null);
  const [shouldAutoScroll, setShouldAutoScroll] = useState(true);

  // --- Scroll Logic ---
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const handleScroll = () => {
      if (scrollContainerRef.current) {
          const { scrollTop, scrollHeight, clientHeight } = scrollContainerRef.current;
          // If within 100px of bottom, enable auto-scroll
          const isNearBottom = scrollHeight - scrollTop - clientHeight < 100;
          setShouldAutoScroll(isNearBottom);
      }
  };

  useEffect(() => {
      if (shouldAutoScroll) {
          scrollToBottom();
      }
  }, [messages, activeTypers, shouldAutoScroll]);

  // --- Initialization & History Fetching ---

  useEffect(() => {
    if (!userDetails?.name) return;

    const q = query(collection(db, 'sessions'), where('participantNames', 'array-contains', userDetails.name));

    const unsubscribeHistory = onSnapshot(q, (snapshot) => {
        const history = snapshot.docs.map(doc => ({ ...doc.data(), code: doc.id } as SessionData));
        // Sort client-side by lastActivity desc
        history.sort((a, b) => (b.lastActivity || 0) - (a.lastActivity || 0));
        setSessionHistory(history);
      }, (error) => {
        console.error("Error fetching history:", error);
      });

    return () => unsubscribeHistory();
  }, [userDetails?.name]);

  useEffect(() => {
    if (activeCode) {
      setSessionCode(activeCode);
      setIsSidebarOpen(false);
      setIsViewOnly(false);
      setIsVerifyingConnection(true);
    }
  }, [activeCode]);

  // --- HEARTBEAT SYSTEM ---
  useEffect(() => {
      if (sessionCode && userDetails && !isViewOnly) {
          const sessionRef = doc(db, 'sessions', sessionCode);

          const sendHeartbeat = () => {
              updateDoc(sessionRef, {
                  [`activeParticipants.${userDetails.name}`]: Date.now()
              }).catch(e => console.warn("Heartbeat failed", e));
          };

          sendHeartbeat();
          const heartbeatInterval = setInterval(sendHeartbeat, 10000);

          const cleanup = () => {
              if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
              clearInterval(heartbeatInterval);
              updateDoc(sessionRef, {
                  [`activeParticipants.${userDetails.name}`]: deleteField(),
                  [`typing.${userDetails.name}`]: deleteField()
              }).catch(e => console.warn("Cleanup failed", e));
          };

          window.addEventListener('beforeunload', cleanup);
          return () => {
              window.removeEventListener('beforeunload', cleanup);
              cleanup();
          };
      }
  }, [sessionCode, userDetails, isViewOnly]);

  // Click outside listener for emoji picker
  useEffect(() => {
      const closePicker = (e: any) => {
          if (showEmojiPicker && !e.target.closest('.emoji-picker-container')) {
              setShowEmojiPicker(false);
          }
      }
      document.addEventListener('mousedown', closePicker);
      return () => document.removeEventListener('mousedown', closePicker);
  }, [showEmojiPicker]);

  // --- SPEECH RECOGNITION ---
  useEffect(() => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (SpeechRecognition) {
        const recognition = new SpeechRecognition();
        recognition.continuous = true;
        recognition.interimResults = true;
        recognition.lang = 'en-US';

        recognition.onresult = (event: any) => {
            let finalTranscript = '';

            for (let i = event.resultIndex; i < event.results.length; ++i) {
                if (event.results[i].isFinal) {
                    finalTranscript += event.results[i][0].transcript;
                }
            }

            if (finalTranscript) {
                setNewMessage(prev => prev + finalTranscript + ' ');
                // Trigger typing indicator
                updateTypingStatus(true);
                if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
                typingTimeoutRef.current = setTimeout(() => { updateTypingStatus(false); }, 2000);
            }
        };

        recognition.onend = () => {
            setIsListening(false);
            updateTypingStatus(false);
        };

        recognition.onerror = (event: any) => {
            console.error("Speech recognition error", event.error);
            setIsListening(false);
            // Optional: Add specific toast for permission denied
            if (event.error === 'not-allowed') {
                addToast('Microphone access denied.', 'error');
            }
        };

        recognitionRef.current = recognition;
    }
  }, [userDetails?.name]);

  const toggleDictation = () => {
      if (isViewOnly) return;
      if (!recognitionRef.current) {
          addToast("Voice input not supported in this browser.", 'error');
          return;
      }

      if (isListening) {
          recognitionRef.current.stop();
      } else {
          recognitionRef.current.start();
          setIsListening(true);
          addToast("Listening...", 'info');
      }
  };


  // --- Helpers ---

  const sendSystemMessage = async (text: string, code: string = sessionCode) => {
      if (!code) return;
      const systemMsg: Message = {
          id: Date.now().toString(),
          sender: 'System',
          text: text,
          timestamp: Date.now(),
          type: 'system'
      };
      try {
          await updateDoc(doc(db, 'sessions', code), {
              messages: arrayUnion(systemMsg),
              lastActivity: Date.now()
          });
      } catch (e) { console.error("Failed to send system message", e); }
  };

  const updateTypingStatus = async (isTyping: boolean) => {
      if (!sessionCode || !userDetails || isViewOnly) return;
      try {
          await updateDoc(doc(db, 'sessions', sessionCode), {
              [`typing.${userDetails.name}`]: isTyping ? true : deleteField()
          });
      } catch (e) { }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setNewMessage(e.target.value);
      if (!sessionCode || isViewOnly) return;
      updateTypingStatus(true);
      if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = setTimeout(() => { updateTypingStatus(false); }, 2000);
  };

  const handleEmojiClick = (emoji: string) => {
      if (isViewOnly) return;
      setNewMessage(prev => prev + emoji);
      updateTypingStatus(true);
      if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = setTimeout(() => { updateTypingStatus(false); }, 2000);
  };

  // --- Session Management Logic ---

  const generateCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 6; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return code;
  };

  const createSession = async () => {
    if (!userDetails?.name) {
      addToast('Please ensure your profile name is set.', 'error');
      return;
    }

    const code = generateCode();
    const participant: Participant = {
        name: userDetails.name,
        photo: userDetails.profilePicture || null
    };

    const newSession: SessionData = {
      code,
      creator: userDetails.name,
      participants: [participant],
      participantNames: [userDetails.name],
      activeParticipants: { [userDetails.name]: Date.now() },
      messages: [],
      typing: {},
      createdAt: Date.now(),
      lastActivity: Date.now()
    };

    try {
        await setDoc(doc(db, 'sessions', code), newSession);
        handleSelectSession(code, false);
        setCreatedSessionCode(code);
        setIsVerifyingConnection(true); 
        setConnectionSuccess(false);
    } catch (error) {
        console.error("Error creating session:", error);
        addToast("Failed to create session. Check your connection.", 'error');
    }
  };

  const joinSession = async () => {
    if (!userDetails?.name) return;
    if (!inputCode.trim()) {
      addToast('Please enter session code', 'warning');
      return;
    }

    if (!navigator.onLine) {
      addToast('You are offline. Please connect to the internet to join a session.', 'error');
      return;
    }

    const code = inputCode.toUpperCase();
    const sessionRef = doc(db, 'sessions', code);

    try {
        const docSnap = await getDoc(sessionRef);
        if (!docSnap.exists()) {
            addToast('Session not found.', 'error');
            return;
        }
        const session = docSnap.data() as SessionData;
        if (!session.participantNames?.includes(userDetails.name)) {
            const newParticipant: Participant = {
                name: userDetails.name,
                photo: userDetails.profilePicture || null
            };
            await updateDoc(sessionRef, {
                participants: arrayUnion(newParticipant),
                participantNames: arrayUnion(userDetails.name),
                [`activeParticipants.${userDetails.name}`]: Date.now(),
                lastActivity: Date.now()
            });
            await sendSystemMessage(`${userDetails.name} joined the session.`, code);
        }
        setShowJoinModal(false);
        setInputCode('');
        handleSelectSession(code, false);
        addToast("Successfully paired!", 'success');
    } catch (error: any) {
        addToast("Failed to join session.", 'error');
    }
  };

  const onHistoryItemClick = (session: SessionData) => {
      if (session.code === activeCode) {
          setIsSidebarOpen(false);
          return;
      }
      setHistoryActionSession(session);
  };

  const handleHistoryAction = (action: 'view' | 'connect') => {
      if (!historyActionSession) return;
      if (action === 'view') {
          handleSelectSession(historyActionSession.code, true);
          addToast("Viewing chat history.", 'info');
      } else {
          handleSelectSession(historyActionSession.code, false);
          setCreatedSessionCode(historyActionSession.code);
          setIsVerifyingConnection(true);
          setConnectionSuccess(false);
      }
      setHistoryActionSession(null);
  };

  const handleSelectSession = (code: string, viewOnly: boolean) => {
      setSessionCode(code);
      setIsViewOnly(viewOnly);
      setIsSidebarOpen(false);
      if (viewOnly) {
          setIsVerifyingConnection(false);
          setConnectionSuccess(true);
          setActiveCode(null);
      } else {
          setActiveCode(code);
          setIsVerifyingConnection(true); 
          setConnectionSuccess(false);
      }
  };

  const shareCode = async (codeOverride?: string) => {
      const explicitCode = typeof codeOverride === 'string' ? codeOverride : undefined;
      const codeToShare = explicitCode || createdSessionCode || sessionCode;
      if (!codeToShare) { addToast("No code available.", 'error'); return; }
      const shareData: ShareData = { title: 'Join my Study Session', text: `My Pairing Code: ${codeToShare}` };
      if (window.location.protocol.startsWith('http')) shareData.url = window.location.href;
      if (navigator.share) { try { await navigator.share(shareData); } catch (err: any) { if (err.name !== 'AbortError') addToast("Unable to share.", 'error'); } } else { copyCode(codeToShare); }
  };

  const copyCode = (codeToCopy: string = sessionCode) => {
    if (!codeToCopy) return;
    navigator.clipboard.writeText(codeToCopy).then(() => addToast("Copied!", 'success')).catch(() => addToast("Failed to copy.", 'error'));
  };

  const handleStartChattingClick = () => setShowShareConfirm(true);
  const confirmShared = () => { setShowShareConfirm(false); setCreatedSessionCode(null); };

  // --- Messaging Logic ---
  const sendMessage = async () => {
    if (!newMessage.trim() || !sessionCode || !userDetails || isViewOnly) return;
    const textToSend = newMessage; 
    setNewMessage(''); 

    // Stop listening if actively dictating
    if (isListening && recognitionRef.current) {
        recognitionRef.current.stop();
        setIsListening(false);
    }

    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current); 
    updateTypingStatus(false);

    setShouldAutoScroll(true);

    const message: Message = { 
        id: Date.now().toString(), 
        sender: userDetails.name, 
        senderProfilePicture: userDetails.profilePicture || null, 
        text: textToSend, 
        timestamp: Date.now(), 
        type: 'text', 
        image: null, 
        fileData: null, 
        fileName: null, 
        fileType: null 
    };
    try { 
        await updateDoc(doc(db, 'sessions', sessionCode), { 
            messages: arrayUnion(message), 
            lastMessage: message, 
            lastActivity: Date.now() 
        }); 
    } catch (error) { addToast("Failed to send message.", 'error'); }
  };

  const handleEditMessage = async (messageId: string, newText: string) => {
      if (!sessionCode || isViewOnly) return;
      try {
          const docRef = doc(db, 'sessions', sessionCode);
          const docSnap = await getDoc(docRef);
          if (docSnap.exists()) {
              const data = docSnap.data() as SessionData;
              const updatedMessages = data.messages.map(m => m.id === messageId ? { ...m, text: newText } : m);
              await updateDoc(docRef, { messages: updatedMessages });
              setEditingMessageId(null); setEditMessageText('');
          }
      } catch (error) { addToast("Failed to edit.", 'error'); }
  };

  const handleDeleteMessage = async (deleteForEveryone: boolean) => {
      if (!sessionCode || !messageToDelete || isViewOnly || !userDetails) return;

      try {
          const docRef = doc(db, 'sessions', sessionCode);
          const docSnap = await getDoc(docRef);

          if (docSnap.exists()) {
              const data = docSnap.data() as SessionData;
              let updatedMessages = [...data.messages];

              if (deleteForEveryone) {
                  updatedMessages = updatedMessages.filter(m => m.id !== messageToDelete.id);
              } else {
                   updatedMessages = updatedMessages.map(m => {
                       if (m.id === messageToDelete.id) {
                           const currentHidden = m.hiddenFor || [];
                           if (!currentHidden.includes(userDetails.name)) {
                               return { ...m, hiddenFor: [...currentHidden, userDetails.name] };
                           }
                       }
                       return m;
                   });
              }

              const newLastMessage = updatedMessages.length > 0 ? updatedMessages[updatedMessages.length - 1] : null;

              await updateDoc(docRef, { 
                  messages: updatedMessages,
                  lastMessage: newLastMessage || deleteField()
              });

              addToast(deleteForEveryone ? "Message deleted for everyone." : "Message deleted for you.", 'success');
          }
      } catch (error) { 
          addToast("Failed to delete message.", 'error'); 
      } finally {
          setMessageToDelete(null);
      }
  };

  const handleDeleteSession = async (codeToDelete: string) => {
      if (!userDetails) return;
      try {
        setSessionHistory(prev => prev.filter(s => s.code !== codeToDelete));
        if (sessionCode === codeToDelete) { setActiveCode(null); setSessionCode(''); setSessionData(null); setMessages([]); setIsSidebarOpen(true); }
        const sessionRef = doc(db, 'sessions', codeToDelete);
        const docSnap = await getDoc(sessionRef);
        if (docSnap.exists()) {
            const data = docSnap.data() as SessionData;
            const participantToRemove = data.participants.find(p => p.name === userDetails.name);
            if (participantToRemove) {
                await updateDoc(sessionRef, {
                    participants: arrayRemove(participantToRemove),
                    participantNames: arrayRemove(userDetails.name)
                });
            }
        }
        setSessionToDelete(null); addToast("Chat deleted.", 'success');
      } catch (error) { addToast("Failed to delete chat.", 'error'); }
  };

  const handleSaveToNotes = (text: string) => {
    const newNote: Note = { id: Date.now().toString(), title: `Chat from Session ${sessionCode}`, content: text, subject: 'Collaborative Session', createdAt: new Date().toISOString(), isFavourite: false };
    setNotes([newNote, ...notes]); addToast('Saved to notes!', 'success');
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !sessionCode || !userDetails || isViewOnly) return;
    if (file.size > 50 * 1024 * 1024) { addToast("File > 50MB.", 'error'); return; }
    setIsUploading(true);
    try {
        const storageRef = ref(storage, `sessions/${sessionCode}/${Date.now()}_${file.name}`);
        await uploadBytes(storageRef, file);
        const downloadURL = await getDownloadURL(storageRef);

        const isImage = file.type.startsWith('image/');
        const message: Message = { 
            id: Date.now().toString(), 
            sender: userDetails.name, 
            senderProfilePicture: userDetails.profilePicture || null, 
            text: isImage ? '📷 Photo' : `📄 ${file.name}`, 
            image: isImage ? downloadURL : null, 
            fileData: !isImage ? downloadURL : null, 
            fileName: file.name || 'unknown', 
            fileType: file.type || 'application/octet-stream', 
            timestamp: Date.now(), 
            type: isImage ? 'image' : 'file' 
        };
        setShouldAutoScroll(true);
        await updateDoc(doc(db, 'sessions', sessionCode), { 
            messages: arrayUnion(message), 
            lastMessage: message, 
            lastActivity: Date.now() 
        });
        await sendSystemMessage(`${userDetails.name} uploaded ${file.name}`);
    } catch (error: any) { 
        console.error(error);
        addToast("Upload failed.", 'error');
    } finally { setIsUploading(false); if (e.target) e.target.value = ''; }
  };

  const askAI = async () => {
    if (messages.length === 0) { addToast('Start a conversation first!', 'info'); return; }
    if (isViewOnly) return;
    setIsAIThinking(true);
    const conversationContext = messages.slice(-20).map(m => `${m.sender}: ${m.text}`).join('\n');
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });
      const prompt = `You are Blay, a study AI. Context:\n${conversationContext}\nResponse:`;
      const response = await ai.models.generateContent({ model: 'gemini-2.5-flash', contents: prompt });
      const aiMessage: Message = { id: Date.now().toString(), sender: 'EduBlay AI', text: response.text, timestamp: Date.now(), type: 'ai', image: null, fileData: null, fileName: null, fileType: null };
      await updateDoc(doc(db, 'sessions', sessionCode), { 
          messages: arrayUnion(aiMessage), 
          lastMessage: aiMessage, 
          lastActivity: Date.now() 
      });
    } catch (error) { addToast('AI failed.', 'error'); } finally { setIsAIThinking(false); }
  };

  // --- Navigation & Cleanup ---
  const handleLeaveRequest = () => setShowLeaveConfirm(true);
  const handleConfirmLeave = async () => {
    setShowLeaveConfirm(false);
    if (unsubscribeRef.current) unsubscribeRef.current();
    if (sessionCode && userDetails && !isViewOnly) {
         try {
            await sendSystemMessage(`${userDetails.name} left the session.`, sessionCode);
            const participantToRemove: Participant = { name: userDetails.name, photo: userDetails.profilePicture || null };
            await updateDoc(doc(db, 'sessions', sessionCode), {
                participants: arrayRemove(participantToRemove),
                participantNames: arrayRemove(userDetails.name),
                [`activeParticipants.${userDetails.name}`]: deleteField(),
                [`typing.${userDetails.name}`]: deleteField()
            });
        } catch (e) { }
    }
    setActiveCode(null); setSessionCode(''); setSessionData(null); setMessages([]); setIsSidebarOpen(true);
  };

  useEffect(() => {
    if (sessionCode) {
      if (!isViewOnly) setIsVerifyingConnection(true);
      const unsubscribe = onSnapshot(doc(db, 'sessions', sessionCode), (docSnap) => {
            if (docSnap.exists()) {
                const data = docSnap.data() as SessionData;
                setSessionData(data);

                const visibleMessages = (data.messages || []).filter(m => !m.hiddenFor?.includes(userDetails?.name || ''));
                setMessages(visibleMessages);

                if (data.typing && userDetails) {
                    const typers = Object.keys(data.typing).filter(name => name !== userDetails.name && data.typing![name]);
                    setActiveTypers(typers);
                } else { setActiveTypers([]); }

                if (!isViewOnly) {
                    const activeMap = data.activeParticipants || {};
                    const now = Date.now();
                    const activeCount = Object.values(activeMap).filter(ts => now - ts < 60000).length;
                    if (activeCount >= 2) {
                        setIsVerifyingConnection(false);
                        setConnectionSuccess(true);
                    } else {
                        setIsVerifyingConnection(true);
                        setConnectionSuccess(false);
                    }
                }
            } else {
                addToast("Session ended.", 'info');
                setActiveCode(null); setSessionCode(''); setIsSidebarOpen(true);
            }
        });
      unsubscribeRef.current = unsubscribe;
      return () => unsubscribe();
    }
  }, [sessionCode, setActiveCode, userDetails, isViewOnly]); 

  const formatTime = (timestamp: number) => new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const getInitials = (name: string) => name ? name.charAt(0).toUpperCase() : '?';
  const getOtherParticipant = (session: SessionData) => {
      if (!userDetails) return null;
      if (session.participants.length > 2) return null; 
      return session.participants.find(p => p.name !== userDetails.name);
  };
  const startEditing = (msg: Message) => { setEditingMessageId(msg.id); setEditMessageText(msg.text); };
  const startDeleting = (msg: Message) => { setMessageToDelete(msg); };

  const filteredHistory = useMemo(() => {
      return sessionHistory.filter(session => {
          const names = session.participants.map(p => p.name).join(' ').toLowerCase();
          return names.includes(searchQuery.toLowerCase()) || session.code.toLowerCase().includes(searchQuery.toLowerCase());
      });
  }, [sessionHistory, searchQuery]);

  return (
    <div className="h-[calc(100vh-90px)] flex bg-white dark:bg-gray-900 rounded-2xl shadow-xl overflow-hidden border dark:border-gray-700 -mx-4 sm:mx-0">
      <div className={`w-full md:w-80 flex-shrink-0 flex flex-col bg-white dark:bg-gray-800 border-r dark:border-gray-700 ${!isSidebarOpen && sessionCode ? 'hidden md:flex' : 'flex'}`}>
        <div className="p-4 bg-gray-50 dark:bg-gray-800/50 border-b dark:border-gray-700 flex justify-between items-center">
            <div className="flex items-center gap-2">
                 {userDetails?.profilePicture ? <img src={userDetails.profilePicture} alt="Me" className="w-10 h-10 rounded-full object-cover" /> : <div className="w-10 h-10 bg-blue-100 dark:bg-blue-900 text-blue-600 rounded-full flex items-center justify-center font-bold">{getInitials(userDetails?.name || '')}</div>}
                <span className="font-bold text-gray-800 dark:text-white truncate max-w-[120px]">{userDetails?.name}</span>
            </div>
            <div className="flex gap-2">
                <button onClick={() => setShowJoinModal(true)} title="Join Session" className="p-2 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full"><Users className="w-5 h-5" /></button>
                <button onClick={() => onActionAttempt(createSession)} title="New Chat" className="p-2 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full"><MessageCircle className="w-5 h-5" /></button>
            </div>
        </div>
        <div className="p-3"><div className="relative"><input type="text" placeholder="Search..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-gray-100 dark:bg-gray-700 border-none rounded-lg text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white" /><Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" /></div></div>
        <div className="flex-1 overflow-y-auto">
            {filteredHistory.length === 0 ? <div className="p-8 text-center text-gray-500 dark:text-gray-400"><p className="text-sm">No conversations yet.</p></div> : filteredHistory.map((session) => {
                const other = getOtherParticipant(session);
                const isGroup = !other;
                const isActive = session.code === sessionCode;
                return (
                    <div key={session.code} onClick={() => onHistoryItemClick(session)} className={`relative group flex items-center gap-3 p-3 cursor-pointer transition-colors border-b dark:border-gray-700/50 hover:bg-gray-50 dark:hover:bg-gray-700 ${isActive ? 'bg-blue-50 dark:bg-blue-900/20' : ''}`}>
                        <div className="relative flex-shrink-0">{isGroup ? <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900 text-indigo-600 rounded-full flex items-center justify-center"><Users className="w-6 h-6" /></div> : other?.photo ? <img src={other.photo} alt={other.name} className="w-12 h-12 rounded-full object-cover" /> : <div className="w-12 h-12 bg-purple-100 dark:bg-purple-900 text-purple-600 rounded-full flex items-center justify-center font-bold text-lg">{getInitials(other?.name || '?')}</div>}</div>
                        <div className="flex-1 min-w-0">
                            <div className="flex justify-between items-baseline"><h4 className="font-semibold text-gray-900 dark:text-gray-100 truncate">{isGroup ? `Group` : other?.name}</h4>{session.lastActivity && <span className="text-[10px] text-gray-500">{new Date(session.lastActivity).toLocaleDateString(undefined, {month: 'short', day: 'numeric'})}</span>}</div>
                            <div className="flex justify-between items-center"><p className="text-sm text-gray-500 dark:text-gray-400 truncate">{session.lastMessage ? (session.lastMessage.type === 'system' ? <span className="italic text-gray-400">{session.lastMessage.text}</span> : session.lastMessage.type === 'image' ? '📷 Photo' : session.lastMessage.type === 'file' ? `📄 ${session.lastMessage.text.replace('📄 ', '')}` : session.lastMessage.text) : <span className="italic">No messages</span>}</p></div>
                        </div>
                        <button onClick={(e) => { e.stopPropagation(); setSessionToDelete(session.code); }} className="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><TrashIcon className="w-4 h-4" /></button>
                    </div>
                );
            })}
        </div>
      </div>

      <div className={`flex-1 flex flex-col bg-[#e5ded8] dark:bg-[#0b141a] ${isSidebarOpen && !activeCode ? 'hidden md:flex' : 'flex'}`}>
        {sessionCode ? (
            <>
                <div className="p-3 bg-white dark:bg-gray-800 border-b dark:border-gray-700 flex items-center justify-between shadow-sm">
                    <div className="flex items-center gap-3">
                        <button onClick={() => setIsSidebarOpen(true)} className="md:hidden p-2 -ml-2 text-gray-600 dark:text-gray-300"><ArrowLeft className="w-5 h-5" /></button>
                        <div className="flex items-center gap-3" onClick={() => copyCode()} title="Copy code">
                             {(() => { const other = sessionData ? getOtherParticipant(sessionData) : null; if(!other) return <div className="w-10 h-10 bg-indigo-100 dark:bg-indigo-900 text-indigo-600 rounded-full flex items-center justify-center"><Users className="w-5 h-5" /></div>; if(other?.photo) return <img src={other.photo} className="w-10 h-10 rounded-full object-cover" alt={other.name} />; return <div className="w-10 h-10 bg-purple-100 dark:bg-purple-900 text-purple-600 rounded-full flex items-center justify-center font-bold">{getInitials(other?.name || '?')}</div>; })()}
                             <div>
                                 <h2 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">{sessionData && (getOtherParticipant(sessionData)?.name || "Group Study")} <span className="text-xs font-normal px-2 py-0.5 bg-gray-200 dark:bg-gray-700 rounded-full text-gray-600 dark:text-gray-300 select-all">{sessionCode}</span> {isViewOnly && <span className="text-[10px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-bold">VIEW ONLY</span>}</h2>
                                 <p className="text-xs text-gray-500 dark:text-gray-400">{sessionData?.participants.map(p => p.name).join(', ')}</p>
                             </div>
                        </div>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="flex flex-col items-center">
                            <button onClick={askAI} disabled={isAIThinking || isViewOnly} className="p-2 text-purple-600 hover:bg-purple-50 dark:hover:bg-gray-700 rounded-full disabled:opacity-50"><Sparkles className={`w-5 h-5 ${isAIThinking ? 'animate-spin' : ''}`} /></button>
                            <span className="text-[9px] text-gray-500 dark:text-gray-400">Ask AI</span>
                        </div>
                         <div className="flex flex-col items-center">
                            <button onClick={handleLeaveRequest} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-gray-700 rounded-full"><LogOut className="w-5 h-5" /></button>
                            <span className="text-[9px] text-gray-500 dark:text-gray-400">Exit</span>
                        </div>
                    </div>
                </div>

                <div 
                    ref={scrollContainerRef}
                    onScroll={handleScroll}
                    className="flex-1 overflow-y-auto p-4 space-y-4 relative bg-[url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')] dark:bg-[url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')] bg-repeat"
                >
                    {isVerifyingConnection && !isViewOnly && (
                        <div className="absolute inset-0 z-10 backdrop-blur-md bg-white/60 dark:bg-black/60 flex flex-col items-center justify-center text-center p-6">
                             <div className="w-24 h-24 bg-white dark:bg-gray-800 rounded-full shadow-2xl flex items-center justify-center mb-6 animate-pulse border-4 border-blue-500"><Users className="w-10 h-10 text-blue-500" /></div>
                             <h3 className="text-2xl font-bold text-gray-800 dark:text-white mb-2">Waiting for Partner...</h3>
                             <p className="text-gray-600 dark:text-gray-300 max-w-sm mb-6">The session is locked until your partner enters the code.</p>
                             <div className="bg-white dark:bg-gray-800 px-4 py-2 rounded-lg border border-blue-200 dark:border-blue-900 shadow-sm flex items-center gap-3">
                                 <span className="font-mono text-xl font-bold tracking-widest text-blue-600 dark:text-blue-400 select-all">{sessionCode}</span>
                                 <button onClick={() => copyCode()} className="p-1.5 text-gray-500 hover:text-blue-500 rounded-md transition-colors"><CopyIcon className="w-4 h-4" /></button>
                             </div>
                             <div className="mt-6 flex gap-3">
                                 <button onClick={() => shareCode()} className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-full font-semibold shadow-lg hover:bg-blue-700 transition-all hover:scale-105"><Share2 className="w-4 h-4" /> Share Code</button>
                             </div>
                        </div>
                    )}

                    {messages.map((msg, index) => {
                        const isMe = msg.sender === userDetails?.name;
                        const isSystem = msg.type === 'system';
                        const showAvatar = !isMe && !isSystem && (index === 0 || messages[index - 1].sender !== msg.sender);
                        const isDeleted = false; 

                        if (isSystem) {
                            return <div key={msg.id} className="flex justify-center my-2"><span className="bg-gray-200 dark:bg-gray-700 text-gray-600 dark:text-gray-300 text-xs px-3 py-1 rounded-full shadow-sm">{msg.text}</span></div>;
                        }

                        return (
                            <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'} group mb-1`}>
                                {!isMe && <div className="w-8 flex-shrink-0 mr-2">{showAvatar ? (msg.senderProfilePicture ? <img src={msg.senderProfilePicture} className="w-8 h-8 rounded-full" /> : <div className="w-8 h-8 bg-purple-500 rounded-full flex items-center justify-center text-white text-xs font-bold">{getInitials(msg.sender)}</div>) : <div className="w-8" />}</div>}

                                <div className={`max-w-[70%] sm:max-w-[60%] relative shadow-sm ${isMe ? 'bg-[#dcf8c6] dark:bg-[#005c4b] rounded-l-lg rounded-tr-lg' : 'bg-white dark:bg-gray-800 rounded-r-lg rounded-tl-lg'} p-2`}>
                                    {!isMe && showAvatar && <p className="text-[10px] font-bold text-orange-600 dark:text-orange-400 mb-1">{msg.sender}</p>}

                                    {msg.type === 'image' && msg.image && (
                                        <div className="mb-1 rounded-lg overflow-hidden cursor-pointer">
                                            <img src={msg.image} alt="Shared" className="max-w-full max-h-60 object-contain" />
                                        </div>
                                    )}

                                    {msg.type === 'file' && msg.fileData && (
                                        <a href={msg.fileData} download={msg.fileName} className="flex items-center gap-3 p-3 bg-black/5 dark:bg-white/10 rounded-lg mb-1 hover:bg-black/10 dark:hover:bg-white/20 transition-colors">
                                            <div className="bg-red-500 text-white p-2 rounded-lg"><FileText className="w-6 h-6" /></div>
                                            <div className="flex-1 min-w-0">
                                                <p className="font-medium text-sm truncate">{msg.fileName}</p>
                                                <p className="text-[10px] opacity-70 uppercase">{msg.fileName?.split('.').pop()} File</p>
                                            </div>
                                            <Download className="w-5 h-5 opacity-50" />
                                        </a>
                                    )}

                                    {editingMessageId === msg.id ? (
                                        <div className="min-w-[200px]">
                                            <input autoFocus type="text" value={editMessageText} onChange={(e) => setEditMessageText(e.target.value)} className="w-full p-1 text-sm border rounded dark:bg-gray-700 dark:border-gray-600" onKeyDown={(e) => { if (e.key === 'Enter') handleEditMessage(msg.id, editMessageText); else if (e.key === 'Escape') setEditingMessageId(null); }} />
                                            <div className="text-[10px] text-gray-500 mt-1">Press Enter to save, Esc to cancel</div>
                                        </div>
                                    ) : (
                                        <p className="text-sm text-gray-900 dark:text-gray-100 whitespace-pre-wrap leading-relaxed">{msg.text}</p>
                                    )}

                                    <div className="flex justify-end items-center gap-1 mt-1">
                                        <span className="text-[10px] text-gray-500 dark:text-gray-400">{formatTime(msg.timestamp)}</span>
                                        {isMe && <Check className="w-3 h-3 text-blue-500" />}
                                    </div>

                                    {!isViewOnly && (
                                        <div className={`absolute top-0 ${isMe ? '-left-8' : '-right-8'} opacity-0 group-hover:opacity-100 flex flex-col gap-1 transition-opacity`}>
                                            {msg.type === 'text' && (
                                                <>
                                                    <button onClick={() => handleSaveToNotes(msg.text)} title="Save to Notes" className="p-1 bg-white dark:bg-gray-700 rounded-full shadow hover:text-blue-500"><SaveIcon className="w-3 h-3" /></button>
                                                    {isMe && <button onClick={() => startEditing(msg)} title="Edit" className="p-1 bg-white dark:bg-gray-700 rounded-full shadow hover:text-green-500"><PencilIcon className="w-3 h-3" /></button>}
                                                </>
                                            )}
                                            <button onClick={() => startDeleting(msg)} title="Delete" className="p-1 bg-white dark:bg-gray-700 rounded-full shadow hover:text-red-500"><TrashIcon className="w-3 h-3" /></button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                    {activeTypers.length > 0 && <div className="text-xs text-gray-500 italic ml-12 animate-pulse">{activeTypers.join(', ')} is typing...</div>}
                    <div ref={messagesEndRef} />
                </div>

                {!isViewOnly && (
                    <div className="p-3 bg-white dark:bg-gray-800 border-t dark:border-gray-700">
                        {isUploading && <div className="text-xs text-blue-500 mb-2 flex items-center gap-2"><Loader2 className="w-3 h-3 animate-spin" /> Uploading file...</div>}
                        <div className="flex items-end gap-2">
                            <div className="flex gap-2 pb-2">
                                <button onClick={() => setShowEmojiPicker(!showEmojiPicker)} className="text-gray-500 hover:text-yellow-500 transition-colors p-1"><Smile className="w-6 h-6" /></button>
                                <button onClick={() => fileInputRef.current?.click()} className="text-gray-500 hover:text-blue-500 transition-colors p-1"><Paperclip className="w-6 h-6" /></button>
                                <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
                            </div>
                            <div className="flex-1 relative">
                                <input type="text" value={newMessage} onChange={handleInputChange} onKeyDown={(e) => e.key === 'Enter' && sendMessage()} placeholder="Type a message..." className="w-full pl-4 pr-10 py-3 bg-gray-100 dark:bg-gray-700 border-none rounded-full focus:ring-1 focus:ring-green-500 text-gray-900 dark:text-white" />
                                {showEmojiPicker && (
                                    <div className="absolute bottom-12 left-0 bg-white dark:bg-gray-800 border dark:border-gray-700 shadow-xl rounded-lg p-2 grid grid-cols-6 gap-1 w-64 z-50 emoji-picker-container">
                                        {COMMON_EMOJIS.map(emoji => <button key={emoji} onClick={() => handleEmojiClick(emoji)} className="text-xl hover:bg-gray-100 dark:hover:bg-gray-700 p-1 rounded">{emoji}</button>)}
                                    </div>
                                )}
                            </div>
                            {newMessage.trim() ? (
                                <button onClick={sendMessage} className="p-3 bg-[#005c4b] hover:bg-[#004a3c] text-white rounded-full shadow-md transition-transform active:scale-95"><Send className="w-5 h-5" /></button>
                            ) : (
                                <button onClick={toggleDictation} className={`p-3 rounded-full shadow-md transition-colors ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-[#005c4b] text-white hover:bg-[#004a3c]'}`}><Mic className="w-5 h-5" /></button>
                            )}
                        </div>
                    </div>
                )}
            </>
        ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-center p-8 bg-gray-50 dark:bg-gray-900">
                <div className="bg-white dark:bg-gray-800 p-8 rounded-full shadow-xl mb-6 animate-bounce"><Users className="w-16 h-16 text-blue-500" /></div>
                <h2 className="text-3xl font-bold text-gray-800 dark:text-white mb-3">Study Together</h2>
                <p className="text-gray-500 dark:text-gray-400 max-w-md mb-8">Collaborate in real-time with friends. Share notes, chat, and use AI tools together to master your subjects.</p>
                <div className="flex flex-col sm:flex-row gap-4">
                    <button onClick={() => onActionAttempt(createSession)} className="px-8 py-3 bg-blue-600 text-white rounded-full font-bold shadow-lg hover:bg-blue-700 transition-transform hover:scale-105 flex items-center justify-center gap-2"><MessageCircle className="w-5 h-5" /> Start New Session</button>
                    <button onClick={() => setShowJoinModal(true)} className="px-8 py-3 bg-white dark:bg-gray-800 text-gray-800 dark:text-white border border-gray-200 dark:border-gray-700 rounded-full font-bold shadow-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-transform hover:scale-105 flex items-center justify-center gap-2"><LinkIcon className="w-5 h-5" /> Join with Code</button>
                </div>
            </div>
        )}
      </div>

      {showJoinModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
            <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl w-full max-w-md p-6 transform transition-all scale-100">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-2xl font-bold text-gray-900 dark:text-white">Join Session</h3>
                    <button onClick={() => setShowJoinModal(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"><X className="w-6 h-6" /></button>
                </div>
                <div className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Session Code</label>
                        <input type="text" value={inputCode} onChange={(e) => setInputCode(e.target.value.toUpperCase())} placeholder="Enter 6-character code" className="w-full px-4 py-3 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-xl text-center text-2xl font-mono tracking-widest uppercase focus:ring-2 focus:ring-blue-500 focus:border-blue-500" maxLength={6} />
                    </div>
                    <button onClick={joinSession} disabled={inputCode.length < 6} className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-md">Join Now</button>
                </div>
            </div>
        </div>
      )}

      <ConfirmationModal isOpen={showLeaveConfirm} onClose={() => setShowLeaveConfirm(false)} onConfirm={handleConfirmLeave} title="Leave Session?" message="Are you sure you want to leave this session? You can rejoin later with the same code." confirmText="Leave" confirmColor="red" />

      <ConfirmationModal isOpen={showShareConfirm} onClose={() => setShowShareConfirm(false)} onConfirm={confirmShared} title="Session Ready!" message={`Your session code is: ${createdSessionCode}. Share this with your friends to start studying together.`} confirmText="Got it" confirmColor="blue" />

      {messageToDelete && (
          <ConfirmationModal 
            isOpen={!!messageToDelete} 
            onClose={() => setMessageToDelete(null)} 
            onConfirm={() => handleDeleteMessage(true)} 
            onCancel={() => handleDeleteMessage(false)} 
            title="Delete Message?" 
            message="Delete for everyone or just for you?" 
            confirmText="Delete for Everyone" 
            cancelText="Delete for Me" 
            confirmColor="red" 
            cancelColor="blue" 
          />
      )}

      {sessionToDelete && (
          <ConfirmationModal
            isOpen={!!sessionToDelete}
            onClose={() => setSessionToDelete(null)}
            onConfirm={() => handleDeleteSession(sessionToDelete)}
            title="Delete Chat?"
            message="Are you sure you want to delete this chat history? This cannot be undone."
            confirmText="Delete"
            confirmColor="red"
          />
      )}

        {historyActionSession && (
            <ConfirmationModal
                isOpen={!!historyActionSession}
                onClose={() => setHistoryActionSession(null)}
                onConfirm={() => handleHistoryAction('connect')}
                title="Session Action"
                message={`What would you like to do with the session "${getOtherParticipant(historyActionSession)?.name || 'Group'}"?`}
                confirmText="Connect / Rejoin"
                confirmColor="green"
                tertiaryAction={{
                    text: "View History",
                    onClick: () => handleHistoryAction('view')
                }}
            />
        )}
    </div>
  );
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { MessageCircle, Send, Bot, Upload, X, Copy, Check, Users, Sparkles, ArrowLeft, FileText, Download, Loader2, Search, MoreVertical, LogOut, Share2, Lock, Mic, Square, Trash2, Smile, EyeIcon, LinkIcon, Paperclip, Image as ImageIcon, FileIcon } from 'lucide-react';
import { TrashIcon } from './icons/TrashIcon';
import { SaveIcon } from './icons/SaveIcon';
import { PencilIcon } from './icons/PencilIcon';
import { CheckIcon } from './icons/CheckIcon';
import { CopyIcon } from './icons/CopyIcon';
import { db, storage } from '../services/firebase';
import { 
  collection, 
  doc, 
  query, 
  where, 
  onSnapshot, 
  updateDoc, 
  setDoc, 
  getDoc, 
  deleteField, 
  arrayUnion, 
  arrayRemove 
} from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { GoogleGenAI } from "@google/genai";
import type { UserDetails, Toast, Note } from '../types';
import ConfirmationModal from './ConfirmationModal';

declare global {
  interface Window {
    SpeechRecognition: any;
    webkitSpeechRecognition: any;
  }
}

interface CollaborativeSessionProps {
  userDetails: UserDetails | null;
  addToast: (message: string, type: Toast['type']) => void;
  onActionAttempt: (action: () => Promise<void>) => void;
  activeCode: string | null;
  setActiveCode: (code: string | null) => void;
  notes: Note[];
  setNotes: (notes: Note[]) => void;
}

interface Message {
  id: string;
  sender: string;
  senderProfilePicture?: string | null;
  text: string;
  image?: string | null;
  fileData?: string | null;
  fileName?: string | null;
  fileType?: string | null;
  timestamp: number;
  type: 'text' | 'image' | 'ai' | 'file' | 'system';
  hiddenFor?: string[]; 
}

interface Participant {
  name: string;
  photo?: string | null;
}

interface SessionData {
  code: string;
  creator: string;
  participants: Participant[];
  participantNames: string[];
  activeParticipants?: Record<string, number>; 
  messages: Message[];
  typing?: Record<string, boolean>;
  createdAt: number;
  lastMessage?: Message;
  lastActivity?: number;
}

const COMMON_EMOJIS = ["😀", "😂", "🤣", "😊", "😍", "🤔", "😎", "😭", "👍", "👎", "👋", "🙏", "🔥", "✨", "🎉", "💯", "❤️", "💔", "🎓", "📚", "🧠", "💡", "✅", "❌"];

export function CollaborativeSession({ userDetails, addToast, onActionAttempt, activeCode, setActiveCode, notes, setNotes }: CollaborativeSessionProps) {
  // View State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  // Data State
  const [sessionHistory, setSessionHistory] = useState<SessionData[]>([]);
  const [sessionCode, setSessionCode] = useState('');
  const [sessionData, setSessionData] = useState<SessionData | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);

  // Input State
  const [inputCode, setInputCode] = useState('');
  const [newMessage, setNewMessage] = useState('');
  const [isAIThinking, setIsAIThinking] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [showLeaveConfirm, setShowLeaveConfirm] = useState(false);
  const [showJoinModal, setShowJoinModal] = useState(false);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);

  // Dictation State (Speech-to-Text)
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  // Typing Indicator State
  const typingTimeoutRef = useRef<any>(null);
  const [activeTypers, setActiveTypers] = useState<string[]>([]);

  // Editing & Deleting State
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);
  const [editMessageText, setEditMessageText] = useState('');
  const [sessionToDelete, setSessionToDelete] = useState<string | null>(null);
  const [messageToDelete, setMessageToDelete] = useState<Message | null>(null);

  // Invite & Pairing State
  const [createdSessionCode, setCreatedSessionCode] = useState<string | null>(null);
  const [showShareConfirm, setShowShareConfirm] = useState(false);

  // Strict Verification & View Mode State
  const [isVerifyingConnection, setIsVerifyingConnection] = useState(false);
  const [connectionSuccess, setConnectionSuccess] = useState(false);
  const [isViewOnly, setIsViewOnly] = useState(false);
  const [historyActionSession, setHistoryActionSession] = useState<SessionData | null>(null);

  // Refs
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const unsubscribeRef = useRef<(() => void) | null>(null);
  const [shouldAutoScroll, setShouldAutoScroll] = useState(true);

  // --- Scroll Logic ---
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const handleScroll = () => {
      if (scrollContainerRef.current) {
          const { scrollTop, scrollHeight, clientHeight } = scrollContainerRef.current;
          // If within 100px of bottom, enable auto-scroll
          const isNearBottom = scrollHeight - scrollTop - clientHeight < 100;
          setShouldAutoScroll(isNearBottom);
      }
  };

  useEffect(() => {
      if (shouldAutoScroll) {
          scrollToBottom();
      }
  }, [messages, activeTypers, shouldAutoScroll]);

  // --- Initialization & History Fetching ---

  useEffect(() => {
    if (!userDetails?.name) return;

    const q = query(collection(db, 'sessions'), where('participantNames', 'array-contains', userDetails.name));

    const unsubscribeHistory = onSnapshot(q, (snapshot) => {
        const history = snapshot.docs.map(doc => ({ ...doc.data(), code: doc.id } as SessionData));
        // Sort client-side by lastActivity desc
        history.sort((a, b) => (b.lastActivity || 0) - (a.lastActivity || 0));
        setSessionHistory(history);
      }, (error) => {
        console.error("Error fetching history:", error);
      });

    return () => unsubscribeHistory();
  }, [userDetails?.name]);

  useEffect(() => {
    if (activeCode) {
      setSessionCode(activeCode);
      setIsSidebarOpen(false);
      setIsViewOnly(false);
      setIsVerifyingConnection(true);
    }
  }, [activeCode]);

  // --- HEARTBEAT SYSTEM ---
  useEffect(() => {
      if (sessionCode && userDetails && !isViewOnly) {
          const sessionRef = doc(db, 'sessions', sessionCode);

          const sendHeartbeat = () => {
              updateDoc(sessionRef, {
                  [`activeParticipants.${userDetails.name}`]: Date.now()
              }).catch(e => console.warn("Heartbeat failed", e));
          };

          sendHeartbeat();
          const heartbeatInterval = setInterval(sendHeartbeat, 10000);

          const cleanup = () => {
              if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
              clearInterval(heartbeatInterval);
              updateDoc(sessionRef, {
                  [`activeParticipants.${userDetails.name}`]: deleteField(),
                  [`typing.${userDetails.name}`]: deleteField()
              }).catch(e => console.warn("Cleanup failed", e));
          };

          window.addEventListener('beforeunload', cleanup);
          return () => {
              window.removeEventListener('beforeunload', cleanup);
              cleanup();
          };
      }
  }, [sessionCode, userDetails, isViewOnly]);

  // Click outside listener for emoji picker
  useEffect(() => {
      const closePicker = (e: any) => {
          if (showEmojiPicker && !e.target.closest('.emoji-picker-container')) {
              setShowEmojiPicker(false);
          }
      }
      document.addEventListener('mousedown', closePicker);
      return () => document.removeEventListener('mousedown', closePicker);
  }, [showEmojiPicker]);

  // --- SPEECH RECOGNITION ---
  useEffect(() => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (SpeechRecognition) {
        const recognition = new SpeechRecognition();
        recognition.continuous = true;
        recognition.interimResults = true;
        recognition.lang = 'en-US';

        recognition.onresult = (event: any) => {
            let finalTranscript = '';

            for (let i = event.resultIndex; i < event.results.length; ++i) {
                if (event.results[i].isFinal) {
                    finalTranscript += event.results[i][0].transcript;
                }
            }

            if (finalTranscript) {
                setNewMessage(prev => prev + finalTranscript + ' ');
                // Trigger typing indicator
                updateTypingStatus(true);
                if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
                typingTimeoutRef.current = setTimeout(() => { updateTypingStatus(false); }, 2000);
            }
        };

        recognition.onend = () => {
            setIsListening(false);
            updateTypingStatus(false);
        };

        recognition.onerror = (event: any) => {
            console.error("Speech recognition error", event.error);
            setIsListening(false);
            // Optional: Add specific toast for permission denied
            if (event.error === 'not-allowed') {
                addToast('Microphone access denied.', 'error');
            }
        };

        recognitionRef.current = recognition;
    }
  }, [userDetails?.name]);

  const toggleDictation = () => {
      if (isViewOnly) return;
      if (!recognitionRef.current) {
          addToast("Voice input not supported in this browser.", 'error');
          return;
      }

      if (isListening) {
          recognitionRef.current.stop();
      } else {
          recognitionRef.current.start();
          setIsListening(true);
          addToast("Listening...", 'info');
      }
  };


  // --- Helpers ---

  const sendSystemMessage = async (text: string, code: string = sessionCode) => {
      if (!code) return;
      const systemMsg: Message = {
          id: Date.now().toString(),
          sender: 'System',
          text: text,
          timestamp: Date.now(),
          type: 'system'
      };
      try {
          await updateDoc(doc(db, 'sessions', code), {
              messages: arrayUnion(systemMsg),
              lastActivity: Date.now()
          });
      } catch (e) { console.error("Failed to send system message", e); }
  };

  const updateTypingStatus = async (isTyping: boolean) => {
      if (!sessionCode || !userDetails || isViewOnly) return;
      try {
          await updateDoc(doc(db, 'sessions', sessionCode), {
              [`typing.${userDetails.name}`]: isTyping ? true : deleteField()
          });
      } catch (e) { }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setNewMessage(e.target.value);
      if (!sessionCode || isViewOnly) return;
      updateTypingStatus(true);
      if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = setTimeout(() => { updateTypingStatus(false); }, 2000);
  };

  const handleEmojiClick = (emoji: string) => {
      if (isViewOnly) return;
      setNewMessage(prev => prev + emoji);
      updateTypingStatus(true);
      if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = setTimeout(() => { updateTypingStatus(false); }, 2000);
  };

  // --- Session Management Logic ---

  const generateCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 6; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return code;
  };

  const createSession = async () => {
    if (!userDetails?.name) {
      addToast('Please ensure your profile name is set.', 'error');
      return;
    }

    const code = generateCode();
    const participant: Participant = {
        name: userDetails.name,
        photo: userDetails.profilePicture || null
    };

    const newSession: SessionData = {
      code,
      creator: userDetails.name,
      participants: [participant],
      participantNames: [userDetails.name],
      activeParticipants: { [userDetails.name]: Date.now() },
      messages: [],
      typing: {},
      createdAt: Date.now(),
      lastActivity: Date.now()
    };

    try {
        await setDoc(doc(db, 'sessions', code), newSession);
        handleSelectSession(code, false);
        setCreatedSessionCode(code);
        setIsVerifyingConnection(true); 
        setConnectionSuccess(false);
    } catch (error) {
        console.error("Error creating session:", error);
        addToast("Failed to create session. Check your connection.", 'error');
    }
  };

  const joinSession = async () => {
    if (!userDetails?.name) return;
    if (!inputCode.trim()) {
      addToast('Please enter session code', 'warning');
      return;
    }

    if (!navigator.onLine) {
      addToast('You are offline. Please connect to the internet to join a session.', 'error');
      return;
    }

    const code = inputCode.toUpperCase();
    const sessionRef = doc(db, 'sessions', code);

    try {
        const docSnap = await getDoc(sessionRef);
        if (!docSnap.exists()) {
            addToast('Session not found.', 'error');
            return;
        }
        const session = docSnap.data() as SessionData;
        if (!session.participantNames?.includes(userDetails.name)) {
            const newParticipant: Participant = {
                name: userDetails.name,
                photo: userDetails.profilePicture || null
            };
            await updateDoc(sessionRef, {
                participants: arrayUnion(newParticipant),
                participantNames: arrayUnion(userDetails.name),
                [`activeParticipants.${userDetails.name}`]: Date.now(),
                lastActivity: Date.now()
            });
            await sendSystemMessage(`${userDetails.name} joined the session.`, code);
        }
        setShowJoinModal(false);
        setInputCode('');
        handleSelectSession(code, false);
        addToast("Successfully paired!", 'success');
    } catch (error: any) {
        addToast("Failed to join session.", 'error');
    }
  };

  const onHistoryItemClick = (session: SessionData) => {
      if (session.code === activeCode) {
          setIsSidebarOpen(false);
          return;
      }
      setHistoryActionSession(session);
  };

  const handleHistoryAction = (action: 'view' | 'connect') => {
      if (!historyActionSession) return;
      if (action === 'view') {
          handleSelectSession(historyActionSession.code, true);
          addToast("Viewing chat history.", 'info');
      } else {
          handleSelectSession(historyActionSession.code, false);
          setCreatedSessionCode(historyActionSession.code);
          setIsVerifyingConnection(true);
          setConnectionSuccess(false);
      }
      setHistoryActionSession(null);
  };

  const handleSelectSession = (code: string, viewOnly: boolean) => {
      setSessionCode(code);
      setIsViewOnly(viewOnly);
      setIsSidebarOpen(false);
      if (viewOnly) {
          setIsVerifyingConnection(false);
          setConnectionSuccess(true);
          setActiveCode(null);
      } else {
          setActiveCode(code);
          setIsVerifyingConnection(true); 
          setConnectionSuccess(false);
      }
  };

  const shareCode = async (codeOverride?: string) => {
      const explicitCode = typeof codeOverride === 'string' ? codeOverride : undefined;
      const codeToShare = explicitCode || createdSessionCode || sessionCode;
      if (!codeToShare) { addToast("No code available.", 'error'); return; }
      const shareData: ShareData = { title: 'Join my Study Session', text: `My Pairing Code: ${codeToShare}` };
      if (window.location.protocol.startsWith('http')) shareData.url = window.location.href;
      if (navigator.share) { try { await navigator.share(shareData); } catch (err: any) { if (err.name !== 'AbortError') addToast("Unable to share.", 'error'); } } else { copyCode(codeToShare); }
  };

  const copyCode = (codeToCopy: string = sessionCode) => {
    if (!codeToCopy) return;
    navigator.clipboard.writeText(codeToCopy).then(() => addToast("Copied!", 'success')).catch(() => addToast("Failed to copy.", 'error'));
  };

  const handleStartChattingClick = () => setShowShareConfirm(true);
  const confirmShared = () => { setShowShareConfirm(false); setCreatedSessionCode(null); };

  // --- Messaging Logic ---
  const sendMessage = async () => {
    if (!newMessage.trim() || !sessionCode || !userDetails || isViewOnly) return;
    const textToSend = newMessage; 
    setNewMessage(''); 

    // Stop listening if actively dictating
    if (isListening && recognitionRef.current) {
        recognitionRef.current.stop();
        setIsListening(false);
    }

    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current); 
    updateTypingStatus(false);

    setShouldAutoScroll(true);

    const message: Message = { 
        id: Date.now().toString(), 
        sender: userDetails.name, 
        senderProfilePicture: userDetails.profilePicture || null, 
        text: textToSend, 
        timestamp: Date.now(), 
        type: 'text', 
        image: null, 
        fileData: null, 
        fileName: null, 
        fileType: null 
    };
    try { 
        await updateDoc(doc(db, 'sessions', sessionCode), { 
            messages: arrayUnion(message), 
            lastMessage: message, 
            lastActivity: Date.now() 
        }); 
    } catch (error) { addToast("Failed to send message.", 'error'); }
  };

  const handleEditMessage = async (messageId: string, newText: string) => {
      if (!sessionCode || isViewOnly) return;
      try {
          const docRef = doc(db, 'sessions', sessionCode);
          const docSnap = await getDoc(docRef);
          if (docSnap.exists()) {
              const data = docSnap.data() as SessionData;
              const updatedMessages = data.messages.map(m => m.id === messageId ? { ...m, text: newText } : m);
              await updateDoc(docRef, { messages: updatedMessages });
              setEditingMessageId(null); setEditMessageText('');
          }
      } catch (error) { addToast("Failed to edit.", 'error'); }
  };

  const handleDeleteMessage = async (deleteForEveryone: boolean) => {
      if (!sessionCode || !messageToDelete || isViewOnly || !userDetails) return;

      try {
          const docRef = doc(db, 'sessions', sessionCode);
          const docSnap = await getDoc(docRef);

          if (docSnap.exists()) {
              const data = docSnap.data() as SessionData;
              let updatedMessages = [...data.messages];

              if (deleteForEveryone) {
                  updatedMessages = updatedMessages.filter(m => m.id !== messageToDelete.id);
              } else {
                   updatedMessages = updatedMessages.map(m => {
                       if (m.id === messageToDelete.id) {
                           const currentHidden = m.hiddenFor || [];
                           if (!currentHidden.includes(userDetails.name)) {
                               return { ...m, hiddenFor: [...currentHidden, userDetails.name] };
                           }
                       }
                       return m;
                   });
              }

              const newLastMessage = updatedMessages.length > 0 ? updatedMessages[updatedMessages.length - 1] : null;

              await updateDoc(docRef, { 
                  messages: updatedMessages,
                  lastMessage: newLastMessage || deleteField()
              });

              addToast(deleteForEveryone ? "Message deleted for everyone." : "Message deleted for you.", 'success');
          }
      } catch (error) { 
          addToast("Failed to delete message.", 'error'); 
      } finally {
          setMessageToDelete(null);
      }
  };

  const handleDeleteSession = async (codeToDelete: string) => {
      if (!userDetails) return;
      try {
        setSessionHistory(prev => prev.filter(s => s.code !== codeToDelete));
        if (sessionCode === codeToDelete) { setActiveCode(null); setSessionCode(''); setSessionData(null); setMessages([]); setIsSidebarOpen(true); }
        const sessionRef = doc(db, 'sessions', codeToDelete);
        const docSnap = await getDoc(sessionRef);
        if (docSnap.exists()) {
            const data = docSnap.data() as SessionData;
            const participantToRemove = data.participants.find(p => p.name === userDetails.name);
            if (participantToRemove) {
                await updateDoc(sessionRef, {
                    participants: arrayRemove(participantToRemove),
                    participantNames: arrayRemove(userDetails.name)
                });
            }
        }
        setSessionToDelete(null); addToast("Chat deleted.", 'success');
      } catch (error) { addToast("Failed to delete chat.", 'error'); }
  };

  const handleSaveToNotes = (text: string) => {
    const newNote: Note = { id: Date.now().toString(), title: `Chat from Session ${sessionCode}`, content: text, subject: 'Collaborative Session', createdAt: new Date().toISOString(), isFavourite: false };
    setNotes([newNote, ...notes]); addToast('Saved to notes!', 'success');
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !sessionCode || !userDetails || isViewOnly) return;
    if (file.size > 50 * 1024 * 1024) { addToast("File > 50MB.", 'error'); return; }
    setIsUploading(true);
    try {
        const storageRef = ref(storage, `sessions/${sessionCode}/${Date.now()}_${file.name}`);
        await uploadBytes(storageRef, file);
        const downloadURL = await getDownloadURL(storageRef);

        const isImage = file.type.startsWith('image/');
        const message: Message = { 
            id: Date.now().toString(), 
            sender: userDetails.name, 
            senderProfilePicture: userDetails.profilePicture || null, 
            text: isImage ? '📷 Photo' : `📄 ${file.name}`, 
            image: isImage ? downloadURL : null, 
            fileData: !isImage ? downloadURL : null, 
            fileName: file.name || 'unknown', 
            fileType: file.type || 'application/octet-stream', 
            timestamp: Date.now(), 
            type: isImage ? 'image' : 'file' 
        };
        setShouldAutoScroll(true);
        await updateDoc(doc(db, 'sessions', sessionCode), { 
            messages: arrayUnion(message), 
            lastMessage: message, 
            lastActivity: Date.now() 
        });
        await sendSystemMessage(`${userDetails.name} uploaded ${file.name}`);
    } catch (error: any) { 
        console.error(error);
        addToast("Upload failed.", 'error');
    } finally { setIsUploading(false); if (e.target) e.target.value = ''; }
  };

  const askAI = async () => {
    if (messages.length === 0) { addToast('Start a conversation first!', 'info'); return; }
    if (isViewOnly) return;
    setIsAIThinking(true);
    const conversationContext = messages.slice(-20).map(m => `${m.sender}: ${m.text}`).join('\n');
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });
      const prompt = `You are Blay, a study AI. Context:\n${conversationContext}\nResponse:`;
      const response = await ai.models.generateContent({ model: 'gemini-2.5-flash', contents: prompt });
      const aiMessage: Message = { id: Date.now().toString(), sender: 'EduBlay AI', text: response.text, timestamp: Date.now(), type: 'ai', image: null, fileData: null, fileName: null, fileType: null };
      await updateDoc(doc(db, 'sessions', sessionCode), { 
          messages: arrayUnion(aiMessage), 
          lastMessage: aiMessage, 
          lastActivity: Date.now() 
      });
    } catch (error) { addToast('AI failed.', 'error'); } finally { setIsAIThinking(false); }
  };

  // --- Navigation & Cleanup ---
  const handleLeaveRequest = () => setShowLeaveConfirm(true);
  const handleConfirmLeave = async () => {
    setShowLeaveConfirm(false);
    if (unsubscribeRef.current) unsubscribeRef.current();
    if (sessionCode && userDetails && !isViewOnly) {
         try {
            await sendSystemMessage(`${userDetails.name} left the session.`, sessionCode);
            const participantToRemove: Participant = { name: userDetails.name, photo: userDetails.profilePicture || null };
            await updateDoc(doc(db, 'sessions', sessionCode), {
                participants: arrayRemove(participantToRemove),
                participantNames: arrayRemove(userDetails.name),
                [`activeParticipants.${userDetails.name}`]: deleteField(),
                [`typing.${userDetails.name}`]: deleteField()
            });
        } catch (e) { }
    }
    setActiveCode(null); setSessionCode(''); setSessionData(null); setMessages([]); setIsSidebarOpen(true);
  };

  useEffect(() => {
    if (sessionCode) {
      if (!isViewOnly) setIsVerifyingConnection(true);
      const unsubscribe = onSnapshot(doc(db, 'sessions', sessionCode), (docSnap) => {
            if (docSnap.exists()) {
                const data = docSnap.data() as SessionData;
                setSessionData(data);

                const visibleMessages = (data.messages || []).filter(m => !m.hiddenFor?.includes(userDetails?.name || ''));
                setMessages(visibleMessages);

                if (data.typing && userDetails) {
                    const typers = Object.keys(data.typing).filter(name => name !== userDetails.name && data.typing![name]);
                    setActiveTypers(typers);
                } else { setActiveTypers([]); }

                if (!isViewOnly) {
                    const activeMap = data.activeParticipants || {};
                    const now = Date.now();
                    const activeCount = Object.values(activeMap).filter(ts => now - ts < 60000).length;
                    if (activeCount >= 2) {
                        setIsVerifyingConnection(false);
                        setConnectionSuccess(true);
                    } else {
                        setIsVerifyingConnection(true);
                        setConnectionSuccess(false);
                    }
                }
            } else {
                addToast("Session ended.", 'info');
                setActiveCode(null); setSessionCode(''); setIsSidebarOpen(true);
            }
        });
      unsubscribeRef.current = unsubscribe;
      return () => unsubscribe();
    }
  }, [sessionCode, setActiveCode, userDetails, isViewOnly]); 

  const formatTime = (timestamp: number) => new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const getInitials = (name: string) => name ? name.charAt(0).toUpperCase() : '?';
  const getOtherParticipant = (session: SessionData) => {
      if (!userDetails) return null;
      if (session.participants.length > 2) return null; 
      return session.participants.find(p => p.name !== userDetails.name);
  };
  const startEditing = (msg: Message) => { setEditingMessageId(msg.id); setEditMessageText(msg.text); };
  const startDeleting = (msg: Message) => { setMessageToDelete(msg); };

  const filteredHistory = useMemo(() => {
      return sessionHistory.filter(session => {
          const names = session.participants.map(p => p.name).join(' ').toLowerCase();
          return names.includes(searchQuery.toLowerCase()) || session.code.toLowerCase().includes(searchQuery.toLowerCase());
      });
  }, [sessionHistory, searchQuery]);

  return (
    <div className="h-[calc(100vh-90px)] flex bg-white dark:bg-gray-900 rounded-2xl shadow-xl overflow-hidden border dark:border-gray-700 -mx-4 sm:mx-0">
      <div className={`w-full md:w-80 flex-shrink-0 flex flex-col bg-white dark:bg-gray-800 border-r dark:border-gray-700 ${!isSidebarOpen && sessionCode ? 'hidden md:flex' : 'flex'}`}>
        <div className="p-4 bg-gray-50 dark:bg-gray-800/50 border-b dark:border-gray-700 flex justify-between items-center">
            <div className="flex items-center gap-2">
                 {userDetails?.profilePicture ? <img src={userDetails.profilePicture} alt="Me" className="w-10 h-10 rounded-full object-cover" /> : <div className="w-10 h-10 bg-blue-100 dark:bg-blue-900 text-blue-600 rounded-full flex items-center justify-center font-bold">{getInitials(userDetails?.name || '')}</div>}
                <span className="font-bold text-gray-800 dark:text-white truncate max-w-[120px]">{userDetails?.name}</span>
            </div>
            <div className="flex gap-2">
                <button onClick={() => setShowJoinModal(true)} title="Join Session" className="p-2 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full"><Users className="w-5 h-5" /></button>
                <button onClick={() => onActionAttempt(createSession)} title="New Chat" className="p-2 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full"><MessageCircle className="w-5 h-5" /></button>
            </div>
        </div>
        <div className="p-3"><div className="relative"><input type="text" placeholder="Search..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-gray-100 dark:bg-gray-700 border-none rounded-lg text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white" /><Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" /></div></div>
        <div className="flex-1 overflow-y-auto">
            {filteredHistory.length === 0 ? <div className="p-8 text-center text-gray-500 dark:text-gray-400"><p className="text-sm">No conversations yet.</p></div> : filteredHistory.map((session) => {
                const other = getOtherParticipant(session);
                const isGroup = !other;
                const isActive = session.code === sessionCode;
                return (
                    <div key={session.code} onClick={() => onHistoryItemClick(session)} className={`relative group flex items-center gap-3 p-3 cursor-pointer transition-colors border-b dark:border-gray-700/50 hover:bg-gray-50 dark:hover:bg-gray-700 ${isActive ? 'bg-blue-50 dark:bg-blue-900/20' : ''}`}>
                        <div className="relative flex-shrink-0">{isGroup ? <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900 text-indigo-600 rounded-full flex items-center justify-center"><Users className="w-6 h-6" /></div> : other?.photo ? <img src={other.photo} alt={other.name} className="w-12 h-12 rounded-full object-cover" /> : <div className="w-12 h-12 bg-purple-100 dark:bg-purple-900 text-purple-600 rounded-full flex items-center justify-center font-bold text-lg">{getInitials(other?.name || '?')}</div>}</div>
                        <div className="flex-1 min-w-0">
                            <div className="flex justify-between items-baseline"><h4 className="font-semibold text-gray-900 dark:text-gray-100 truncate">{isGroup ? `Group` : other?.name}</h4>{session.lastActivity && <span className="text-[10px] text-gray-500">{new Date(session.lastActivity).toLocaleDateString(undefined, {month: 'short', day: 'numeric'})}</span>}</div>
                            <div className="flex justify-between items-center"><p className="text-sm text-gray-500 dark:text-gray-400 truncate">{session.lastMessage ? (session.lastMessage.type === 'system' ? <span className="italic text-gray-400">{session.lastMessage.text}</span> : session.lastMessage.type === 'image' ? '📷 Photo' : session.lastMessage.type === 'file' ? `📄 ${session.lastMessage.text.replace('📄 ', '')}` : session.lastMessage.text) : <span className="italic">No messages</span>}</p></div>
                        </div>
                        <button onClick={(e) => { e.stopPropagation(); setSessionToDelete(session.code); }} className="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><TrashIcon className="w-4 h-4" /></button>
                    </div>
                );
            })}
        </div>
      </div>

      <div className={`flex-1 flex flex-col bg-[#e5ded8] dark:bg-[#0b141a] ${isSidebarOpen && !activeCode ? 'hidden md:flex' : 'flex'}`}>
        {sessionCode ? (
            <>
                <div className="p-3 bg-white dark:bg-gray-800 border-b dark:border-gray-700 flex items-center justify-between shadow-sm">
                    <div className="flex items-center gap-3">
                        <button onClick={() => setIsSidebarOpen(true)} className="md:hidden p-2 -ml-2 text-gray-600 dark:text-gray-300"><ArrowLeft className="w-5 h-5" /></button>
                        <div className="flex items-center gap-3" onClick={() => copyCode()} title="Copy code">
                             {(() => { const other = sessionData ? getOtherParticipant(sessionData) : null; if(!other) return <div className="w-10 h-10 bg-indigo-100 dark:bg-indigo-900 text-indigo-600 rounded-full flex items-center justify-center"><Users className="w-5 h-5" /></div>; if(other?.photo) return <img src={other.photo} className="w-10 h-10 rounded-full object-cover" alt={other.name} />; return <div className="w-10 h-10 bg-purple-100 dark:bg-purple-900 text-purple-600 rounded-full flex items-center justify-center font-bold">{getInitials(other?.name || '?')}</div>; })()}
                             <div>
                                 <h2 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">{sessionData && (getOtherParticipant(sessionData)?.name || "Group Study")} <span className="text-xs font-normal px-2 py-0.5 bg-gray-200 dark:bg-gray-700 rounded-full text-gray-600 dark:text-gray-300 select-all">{sessionCode}</span> {isViewOnly && <span className="text-[10px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-bold">VIEW ONLY</span>}</h2>
                                 <p className="text-xs text-gray-500 dark:text-gray-400">{sessionData?.participants.map(p => p.name).join(', ')}</p>
                             </div>
                        </div>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="flex flex-col items-center">
                            <button onClick={askAI} disabled={isAIThinking || isViewOnly} className="p-2 text-purple-600 hover:bg-purple-50 dark:hover:bg-gray-700 rounded-full disabled:opacity-50"><Sparkles className={`w-5 h-5 ${isAIThinking ? 'animate-spin' : ''}`} /></button>
                            <span className="text-[9px] text-gray-500 dark:text-gray-400">Ask AI</span>
                        </div>
                         <div className="flex flex-col items-center">
                            <button onClick={handleLeaveRequest} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-gray-700 rounded-full"><LogOut className="w-5 h-5" /></button>
                            <span className="text-[9px] text-gray-500 dark:text-gray-400">Exit</span>
                        </div>
                    </div>
                </div>

                <div 
                    ref={scrollContainerRef}
                    onScroll={handleScroll}
                    className="flex-1 overflow-y-auto p-4 space-y-4 relative bg-[url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')] dark:bg-[url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')] bg-repeat"
                >
                    {isVerifyingConnection && !isViewOnly && (
                        <div className="absolute inset-0 z-10 backdrop-blur-md bg-white/60 dark:bg-black/60 flex flex-col items-center justify-center text-center p-6">
                             <div className="w-24 h-24 bg-white dark:bg-gray-800 rounded-full shadow-2xl flex items-center justify-center mb-6 animate-pulse border-4 border-blue-500"><Users className="w-10 h-10 text-blue-500" /></div>
                             <h3 className="text-2xl font-bold text-gray-800 dark:text-white mb-2">Waiting for Partner...</h3>
                             <p className="text-gray-600 dark:text-gray-300 max-w-sm mb-6">The session is locked until your partner enters the code.</p>
                             <div className="bg-white dark:bg-gray-800 px-4 py-2 rounded-lg border border-blue-200 dark:border-blue-900 shadow-sm flex items-center gap-3">
                                 <span className="font-mono text-xl font-bold tracking-widest text-blue-600 dark:text-blue-400 select-all">{sessionCode}</span>
                                 <button onClick={() => copyCode()} className="p-1.5 text-gray-500 hover:text-blue-500 rounded-md transition-colors"><CopyIcon className="w-4 h-4" /></button>
                             </div>
                             <div className="mt-6 flex gap-3">
                                 <button onClick={() => shareCode()} className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-full font-semibold shadow-lg hover:bg-blue-700 transition-all hover:scale-105"><Share2 className="w-4 h-4" /> Share Code</button>
