                                        <a href={msg.fileData} download={msg.fileName} className="flex items-center gap-3 p-3 bg-black/5 dark:bg-white/10 rounded-lg mb-1 hover:bg-black/10 dark:hover:bg-white/20 transition-colors">
                                            <div className="bg-red-500 text-white p-2 rounded-lg"><FileText className="w-6 h-6" /></div>
                                            <div className="flex-1 min-w-0">
