                                        <div className="min-w-[200px]">
                                            <input autoFocus type="text" value={editMessageText} onChange={(e) => setEditMessageText(e.target.value)} className="w-full p-1 text-sm border rounded dark:bg-gray-700 dark:border-gray-600" onKeyDown={(e) => { if (e.key === 'Enter') handleEditMessage(msg.id, editMessageText); else if (e.key === 'Escape') setEditingMessageId(null); }} />
                                            <div className="text-[10px] text-gray-500 mt-1">Press Enter to save, Esc to cancel</div>
                                        </div>
                                    ) : (
                                        <p className="text-sm text-gray-900 dark:text-gray-100 whitespace-pre-wrap leading-relaxed">{msg.text}</p>
                                    )}

                                    <div className="flex justify-end items-center gap-1 mt-1">
                                        <span className="text-[10px] text-gray-500 dark:text-gray-400">{formatTime(msg.timestamp)}</span>
                                        {isMe && <Check className="w-3 h-3 text-blue-500" />}
                                    </div>

                                    {!isViewOnly && (
                                        <div className={`absolute top-0 ${isMe ? '-left-8' : '-right-8'} opacity-0 group-hover:opacity-100 flex flex-col gap-1 transition-opacity`}>
                                            {msg.type === 'text' && (
                                                <>
                                                    <button onClick={() => handleSaveToNotes(msg.text)} title="Save to Notes" className="p-1 bg-white dark:bg-gray-700 rounded-full shadow hover:text-blue-500"><SaveIcon className="w-3 h-3" /></button>
                                                    {isMe && <button onClick={() => startEditing(msg)} title="Edit" className="p-1 bg-white dark:bg-gray-700 rounded-full shadow hover:text-green-500"><PencilIcon className="w-3 h-3" /></button>}
                                                </>
                                            )}
                                            <button onClick={() => startDeleting(msg)} title="Delete" className="p-1 bg-white dark:bg-gray-700 rounded-full shadow hover:text-red-500"><TrashIcon className="w-3 h-3" /></button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                    {activeTypers.length > 0 && <div className="text-xs text-gray-500 italic ml-12 animate-pulse">{activeTypers.join(', ')} is typing...</div>}
                    <div ref={messagesEndRef} />
                </div>

                {!isViewOnly && (
                    <div className="p-3 bg-white dark:bg-gray-800 border-t dark:border-gray-700">
                        {isUploading && <div className="text-xs text-blue-500 mb-2 flex items-center gap-2"><Loader2 className="w-3 h-3 animate-spin" /> Uploading file...</div>}
                        <div className="flex items-end gap-2">
                            <div className="flex gap-2 pb-2">
                                <button onClick={() => setShowEmojiPicker(!showEmojiPicker)} className="text-gray-500 hover:text-yellow-500 transition-colors p-1"><Smile className="w-6 h-6" /></button>
                                <button onClick={() => fileInputRef.current?.click()} className="text-gray-500 hover:text-blue-500 transition-colors p-1"><Paperclip className="w-6 h-6" /></button>
                                <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
                            </div>
                            <div className="flex-1 relative">
                                <input type="text" value={newMessage} onChange={handleInputChange} onKeyDown={(e) => e.key === 'Enter' && sendMessage()} placeholder="Type a message..." className="w-full pl-4 pr-10 py-3 bg-gray-100 dark:bg-gray-700 border-none rounded-full focus:ring-1 focus:ring-green-500 text-gray-900 dark:text-white" />
                                {showEmojiPicker && (
                                    <div className="absolute bottom-12 left-0 bg-white dark:bg-gray-800 border dark:border-gray-700 shadow-xl rounded-lg p-2 grid grid-cols-6 gap-1 w-64 z-50 emoji-picker-container">
                                        {COMMON_EMOJIS.map(emoji => <button key={emoji} onClick={() => handleEmojiClick(emoji)} className="text-xl hover:bg-gray-100 dark:hover:bg-gray-700 p-1 rounded">{emoji}</button>)}
                                    </div>
                                )}
                            </div>
                            {newMessage.trim() ? (
                                <button onClick={sendMessage} className="p-3 bg-[#005c4b] hover:bg-[#004a3c] text-white rounded-full shadow-md transition-transform active:scale-95"><Send className="w-5 h-5" /></button>
                            ) : (
                                <button onClick={toggleDictation} className={`p-3 rounded-full shadow-md transition-colors ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-[#005c4b] text-white hover:bg-[#004a3c]'}`}><Mic className="w-5 h-5" /></button>
                            )}
                        </div>
                    </div>
                )}
            </>
        ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-center p-8 bg-gray-50 dark:bg-gray-900">
                <div className="bg-white dark:bg-gray-800 p-8 rounded-full shadow-xl mb-6 animate-bounce"><Users className="w-16 h-16 text-blue-500" /></div>
                <h2 className="text-3xl font-bold text-gray-800 dark:text-white mb-3">Study Together</h2>
                <p className="text-gray-500 dark:text-gray-400 max-w-md mb-8">Collaborate in real-time with friends. Share notes, chat, and use AI tools together to master your subjects.</p>
                <div className="flex flex-col sm:flex-row gap-4">
                    <button onClick={() => onActionAttempt(createSession)} className="px-8 py-3 bg-blue-600 text-white rounded-full font-bold shadow-lg hover:bg-blue-700 transition-transform hover:scale-105 flex items-center justify-center gap-2"><MessageCircle className="w-5 h-5" /> Start New Session</button>
                    <button onClick={() => setShowJoinModal(true)} className="px-8 py-3 bg-white dark:bg-gray-800 text-gray-800 dark:text-white border border-gray-200 dark:border-gray-700 rounded-full font-bold shadow-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-transform hover:scale-105 flex items-center justify-center gap-2"><LinkIcon className="w-5 h-5" /> Join with Code</button>
                </div>
            </div>
        )}
      </div>

      {showJoinModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
            <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl w-full max-w-md p-6 transform transition-all scale-100">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-2xl font-bold text-gray-900 dark:text-white">Join Session</h3>
                    <button onClick={() => setShowJoinModal(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"><X className="w-6 h-6" /></button>
                </div>
                <div className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Session Code</label>
                        <input type="text" value={inputCode} onChange={(e) => setInputCode(e.target.value.toUpperCase())} placeholder="Enter 6-character code" className="w-full px-4 py-3 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-xl text-center text-2xl font-mono tracking-widest uppercase focus:ring-2 focus:ring-blue-500 focus:border-blue-500" maxLength={6} />
                    </div>
                    <button onClick={joinSession} disabled={inputCode.length < 6} className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-md">Join Now</button>
                </div>
            </div>
        </div>
      )}

      <ConfirmationModal isOpen={showLeaveConfirm} onClose={() => setShowLeaveConfirm(false)} onConfirm={handleConfirmLeave} title="Leave Session?" message="Are you sure you want to leave this session? You can rejoin later with the same code." confirmText="Leave" confirmColor="red" />

      <ConfirmationModal isOpen={showShareConfirm} onClose={() => setShowShareConfirm(false)} onConfirm={confirmShared} title="Session Ready!" message={`Your session code is: ${createdSessionCode}. Share this with your friends to start studying together.`} confirmText="Got it" confirmColor="blue" />

      {messageToDelete && (
          <ConfirmationModal 
            isOpen={!!messageToDelete} 
            onClose={() => setMessageToDelete(null)} 
            onConfirm={() => handleDeleteMessage(true)} 
            onCancel={() => handleDeleteMessage(false)} 
            title="Delete Message?" 
            message="Delete for everyone or just for you?" 
            confirmText="Delete for Everyone" 
            cancelText="Delete for Me" 
            confirmColor="red" 
            cancelColor="blue" 
          />
      )}

      {sessionToDelete && (
          <ConfirmationModal
            isOpen={!!sessionToDelete}
            onClose={() => setSessionToDelete(null)}
            onConfirm={() => handleDeleteSession(sessionToDelete)}
            title="Delete Chat?"
            message="Are you sure you want to delete this chat history? This cannot be undone."
            confirmText="Delete"
            confirmColor="red"
          />
      )}

        {historyActionSession && (
            <ConfirmationModal
                isOpen={!!historyActionSession}
                onClose={() => setHistoryActionSession(null)}
                onConfirm={() => handleHistoryAction('connect')}
                title="Session Action"
                message={`What would you like to do with the session "${getOtherParticipant(historyActionSession)?.name || 'Group'}"?`}
                confirmText="Connect / Rejoin"
                confirmColor="green"
                tertiaryAction={{
                    text: "View History",
                    onClick: () => handleHistoryAction('view')
                }}
            />
        )}
    </div>
  );
}

import React, { useState } from 'react';
import type { UserDetails } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { signUp, login, findUserByEmail } from '../services/authService';
import { EyeIcon } from './icons/EyeIcon';
import { EyeOffIcon } from './icons/EyeOffIcon';

interface SignUpProps {
    onLogin: (user: UserDetails) => void;
}

const LoadingSpinner: React.FC = () => (
    <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
);

const recoveryQuestions = [
    "recovery.q1",
    "recovery.q2",
    "recovery.q3",
    "recovery.q4",
    "recovery.q5",
];

const SignUp: React.FC<SignUpProps> = ({ onLogin }) => {
  const { t } = useLanguage();
  const [viewMode, setViewMode] = useState<'signIn' | 'signUp' | 'forgotPassword'>('signIn');

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
    recoveryQuestion: recoveryQuestions[0],
    recoveryAnswer: '',
  });

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [errors, setErrors] = useState<Partial<typeof formData> & { general?: string }>({});
  const [message, setMessage] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name as keyof typeof errors]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
    setErrors(prev => ({...prev, general: undefined}));
    setMessage('');
  };

  const validate = () => {
    const newErrors: Partial<typeof formData> = {};
    if (viewMode === 'signUp') {
        if (!formData.name.trim()) newErrors.name = t('validation.nameRequired');
        if (!formData.recoveryQuestion) newErrors.recoveryQuestion = t('validation.recoveryQRequired');
        if (!formData.recoveryAnswer.trim()) newErrors.recoveryAnswer = t('validation.recoveryARequired');
    }
    if (viewMode === 'signUp' || viewMode === 'signIn' || viewMode === 'forgotPassword') {
        if (!formData.email.trim()) newErrors.email = t('validation.emailRequired');
        else if (!/\S+@\S+\.\S+/.test(formData.email)) newErrors.email = t('validation.emailInvalid');
    }

    if (viewMode === 'signUp' || viewMode === 'signIn') {
        if (!formData.password) newErrors.password = t('validation.passwordRequired');
        else if (viewMode === 'signUp' && formData.password.length < 6) newErrors.password = t('validation.passwordMinLength');
    }

    if (viewMode === 'signUp' && formData.password !== formData.confirmPassword) {
        newErrors.confirmPassword = t('validation.passwordMismatch');
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    setIsSubmitting(true);
    setErrors({});
    setMessage('');

    try {
        if (viewMode === 'signUp') {
            const user = await signUp(formData.name, formData.email, formData.password, formData.recoveryQuestion, formData.recoveryAnswer);
            setMessage(t('auth.signupSuccess'));
            setTimeout(() => onLogin(user), 1000);
        } else if (viewMode === 'signIn') {
            const user = await login(formData.email, formData.password);
            setMessage(t('auth.loginSuccess'));
            setTimeout(() => onLogin(user), 500);
        } else if (viewMode === 'forgotPassword') {
            const success = await findUserByEmail(formData.email);
            if (success) {
                setMessage("Password reset link sent to your email.");
                setTimeout(() => setViewMode('signIn'), 3000);
            } else {
                setErrors({ general: t('recovery.error') });
            }
        }
    } catch (error: any) {
        // Robust error extraction
        let errorMsg = '';
        let errorCode = '';

        if (typeof error === 'string') {
            errorMsg = error.toLowerCase();
        } else if (error && typeof error === 'object') {
            errorMsg = (error.message || '').toLowerCase();
            errorCode = (error.code || '').toLowerCase();
        }

        // SignUp specific checks
        if (viewMode === 'signUp' && (errorMsg.includes('email already registered') || errorCode.includes('email-already-in-use'))) {
            setErrors({ email: t('validation.emailExists') });
            setIsSubmitting(false);
            return;
        }

        // Broad Login/Auth Failure Checks for user-friendly message
        const isAuthError = 
            errorMsg.includes('invalid email or password') ||
            errorCode.includes('invalid-credential') ||
            errorCode.includes('user-not-found') ||
            errorCode.includes('wrong-password') ||
            errorCode.includes('invalid-login-credentials') ||
            errorMsg.includes('auth/invalid-credential') ||
            errorMsg.includes('credential is incorrect') ||
            errorMsg.includes('supplied auth credential') ||
            errorMsg.includes('malformed or has expired') ||
            errorCode.includes('auth/too-many-requests');

        if (isAuthError) {
             // Generic friendly message for invalid credentials
             setErrors({ general: t('validation.loginFailed') });
        } else {
            // Clean up the error message for display if it's something else
            let displayMsg = typeof error === 'string' ? error : error.message || 'An unexpected error occurred.';

            // Remove "Firebase: " prefix and code suffix (e.g., "(auth/foo).")
            if (displayMsg.startsWith('Firebase: ')) {
                displayMsg = displayMsg.replace('Firebase: ', '');
            }
            displayMsg = displayMsg.replace(/\s*\(auth\/.*?\)\.?/g, '').trim();

            // Use generic message if cleaning results in empty string or if it's too technical
            if (!displayMsg || displayMsg.toLowerCase().includes('firebase')) {
                 displayMsg = t('validation.loginFailed');
            }

            setErrors({ general: displayMsg });
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  const renderContent = () => {
    const inputClasses = (field: keyof typeof errors) => `w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 bg-white dark:bg-black ${errors[field] ? 'border-red-500 focus:ring-red-500' : 'border-gray-300 dark:border-gray-600 focus:ring-primary'}`;

    if (viewMode === 'forgotPassword') {
        return (
            <div className="space-y-6">
                <div><h2 className="text-center text-3xl font-extrabold">{t('recovery.title')}</h2></div>
                {message ? (
                    <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded relative text-center">
                        {message}
                    </div>
                ) : (
                    <form onSubmit={handleSubmit} className="space-y-4 pt-8">
                        <p className="text-center text-sm text-gray-600 dark:text-gray-400">{t('recovery.step1.prompt')}</p>
                        <div><label className="sr-only">{t('auth.email')}</label><input type="email" name="email" value={formData.email} onChange={handleInputChange} className={inputClasses('email')} placeholder="evans@example.com" required />{errors.email && <p className="text-red-500 text-xs mt-1">{errors.email}</p>}</div>

                        <button type="submit" disabled={isSubmitting} className="w-full flex justify-center py-3 px-4 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-amber-500 hover:bg-amber-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-amber-500 disabled:opacity-50">
                            {isSubmitting ? <LoadingSpinner /> : "Send Reset Link"}
                        </button>
                        {errors.general && <p className="text-red-500 text-sm mt-2 text-center">{errors.general}</p>}
                    </form>
                )}
                <div className="text-sm text-center">
                    <button onClick={() => { setViewMode('signIn'); setMessage(''); setErrors({}); }} className="font-medium text-primary hover:text-primary-dark dark:text-primary-light dark:hover:text-primary">{t('recovery.backToLogin')}</button>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
             <div><h2 className="mt-6 text-center text-3xl font-extrabold">{viewMode === 'signUp' ? t('auth.createAccount') : t('auth.signInToEduBlay')}</h2></div>
             {message && <p className="text-green-500 text-center">{message}</p>}
             <form onSubmit={handleSubmit} className="space-y-4 pt-8">
                {viewMode === 'signUp' && (
                    <>
                        <div><label className="sr-only">{t('auth.fullName')}</label><input type="text" name="name" value={formData.name} onChange={handleInputChange} className={inputClasses('name')} placeholder={t('auth.fullName')} />{errors.name && <p className="text-red-500 text-xs mt-1">{errors.name}</p>}</div>
                    </>
                )}
                <div><label className="sr-only">{t('auth.email')}</label><input type="email" name="email" value={formData.email} onChange={handleInputChange} className={inputClasses('email')} placeholder="evans@example.com" required />{errors.email && <p className="text-red-500 text-xs mt-1">{errors.email}</p>}</div>
