import { QuizType, ActivityType, DayOfWeek } from '../types';
import { timeToMinutes } from '../lib/utils';

// ============================================
// CORE CONFIGURATION
// ============================================

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });

const safetySettings = [
    { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
];

// Fast model for all operations
const MODEL = 'gemini-2.0-flash-exp';

// ============================================
// SIMPLIFIED CACHE
// ============================================

class FastCache {
    private cache = new Map<string, any>();
    private readonly MAX_SIZE = 50;

    get(key: string): any | null {
        return this.cache.get(key) ?? null;
    }

    set(key: string, data: any): void {
        if (this.cache.size >= this.MAX_SIZE) {
            const first = this.cache.keys().next().value;
            this.cache.delete(first);
        }
        this.cache.set(key, data);
    }

    clear(): void {
        this.cache.clear();
    }
}

const cache = new FastCache();

// ============================================
// OPTIMIZED SCHEMAS
// ============================================

const planSlotSchema = {
    type: Type.OBJECT,
    properties: {
        activity: { type: Type.STRING },
        startTime: { type: Type.STRING },
        endTime: { type: Type.STRING },
        type: { type: Type.STRING }, // 'lecture', 'break', 'free', 'agenda', 'study'
        code: { type: Type.STRING },
        location: { type: Type.STRING },
        durationMinutes: { type: Type.NUMBER },
    },
    required: ['activity', 'startTime', 'endTime', 'type']
};

const smartPlanSchema = {
    type: Type.ARRAY,
    items: {
        type: Type.OBJECT,
        properties: {
            day: { type: Type.STRING },
            slots: { type: Type.ARRAY, items: planSlotSchema }
        },
        required: ['day', 'slots']
    }
};

