import { 
    doc, 
    getDoc, 
    setDoc, 
    collection, 
    query, 
    orderBy, 
    limit, 
    onSnapshot,
    writeBatch,
    runTransaction,
    increment,
    serverTimestamp,
    arrayUnion,
    arrayRemove
} from 'firebase/firestore';
import { db, auth } from './firebase';

interface GlobalStats {
    totalRatings: number;
    totalRatingSum: number;
    totalComments: number;
    activeUsers: number;
    studyMaterials: number;
    lastUpdated?: number;
}

interface Comment {
    id: string;
    userId: string;
    userName: string;
    text: string;
    timestamp: any;
    likes: number;
}

interface UserFeedbackData {
    rating: number;
    likedComments: string[];
}

// HELPER: ENSURE AUTH
const ensureAuth = async (): Promise<string> => {
    if (auth.currentUser) return auth.currentUser.uid;
    await new Promise(resolve => setTimeout(resolve, 1000));
    if (auth.currentUser) return auth.currentUser.uid;
    throw new Error("Authentication required.");
};

export const globalFeedbackService = {

    registerUser: async (userId: string, userName: string, email: string): Promise<void> => {
        if (!navigator.onLine) return;
        try {
            const effectiveUserId = auth.currentUser?.uid || userId;
            const userRef = doc(db, "users", effectiveUserId);
            const userDoc = await getDoc(userRef);

            if (!userDoc.exists()) {
                await setDoc(userRef, {
                    id: effectiveUserId,
                    name: userName,
                    email: email,
                    joinedAt: serverTimestamp(),
                    lastActive: serverTimestamp(),
                    uploadedMaterials: 0
                });

                const statsRef = doc(db, "feedback_stats", "summary");
                await setDoc(statsRef, {
                    activeUsers: increment(1)
                }, { merge: true });
            } else {
                await setDoc(userRef, {
                    lastActive: serverTimestamp()
                }, { merge: true });
            }
        } catch (error) {
            console.error('User registration error:', error);
        }
    },

    trackMaterialUpload: async (userId: string): Promise<void> => {
        if (!navigator.onLine) return;
        try {
            const effectiveUserId = auth.currentUser?.uid || userId;
            const batch = writeBatch(db);

            // Increment user's personal count
            const userRef = doc(db, "users", effectiveUserId);
            batch.set(userRef, {
                uploadedMaterials: increment(1),
                lastActive: serverTimestamp()
            }, { merge: true });

            // Increment global stats immediately using atomic increment
            const statsRef = doc(db, "feedback_stats", "summary");
            batch.set(statsRef, {
                studyMaterials: increment(1),
                lastUpdated: Date.now()
            }, { merge: true });

            await batch.commit();
        } catch (error) {
            console.error('Material tracking error:', error);
        }
    },

    subscribeToGlobalStats: (callback: (stats: any) => void): (() => void) => {
        const statsRef = doc(db, "feedback_stats", "summary");
        return onSnapshot(statsRef, (docSnap) => {
            if (docSnap.exists()) {
                const stats = docSnap.data() as GlobalStats;
                const totalRatings = stats.totalRatings || 0;
                const totalRatingSum = stats.totalRatingSum || 0;

                const averageRating = totalRatings > 0 ? totalRatingSum / totalRatings : 0;

                callback({
                    activeUsers: stats.activeUsers || 0,
                    studyMaterials: stats.studyMaterials || 0,
                    totalRatings: totalRatings,
                    averageRating: parseFloat(averageRating.toFixed(1)),
                    satisfaction: averageRating > 0 ? Math.round((averageRating / 5) * 100) : 0,
                    totalComments: stats.totalComments || 0
                });
            } else {
                callback({ activeUsers: 0, studyMaterials: 0, totalRatings: 0, averageRating: 0, satisfaction: 0, totalComments: 0 });
            }
        });
    },

    subscribeToComments: (callback: (comments: Comment[]) => void, limitCount: number = 50): (() => void) => {
        const commentsQuery = query(collection(db, "comments"), orderBy("timestamp", "desc"), limit(limitCount));
        return onSnapshot(commentsQuery, (snapshot) => {
            const comments = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Comment));
            callback(comments);
        });
    },

    postComment: async (userId: string, userName: string, text: string): Promise<void> => {
        if (!navigator.onLine) throw new Error("You are offline");
        try {
            const effectiveUserId = await ensureAuth();
            const batch = writeBatch(db);

            // Create a reference for the new comment
            const commentRef = doc(collection(db, "comments"));

            batch.set(commentRef, {
                userId: effectiveUserId,
                userName,
                text,
                timestamp: serverTimestamp(),
                likes: 0
            });

            const statsRef = doc(db, "feedback_stats", "summary");
            batch.set(statsRef, { totalComments: increment(1) }, { merge: true });

            await batch.commit();
        } catch (error) {
            console.error('Comment post error:', error);
            throw error;
        }
    },

    likeComment: async (userId: string, commentId: string): Promise<void> => {
        if (!navigator.onLine) throw new Error("You are offline");
        try {
            const effectiveUserId = await ensureAuth();
            const userFeedbackRef = doc(db, "users_feedback", effectiveUserId);
            const commentRef = doc(db, "comments", commentId);

            await runTransaction(db, async (transaction) => {
                const [userFeedbackDoc, commentDoc] = await Promise.all([
                    transaction.get(userFeedbackRef),
                    transaction.get(commentRef)
                ]);

                if (!commentDoc.exists()) throw new Error("Comment does not exist");

                const likedComments = userFeedbackDoc.exists() ? userFeedbackDoc.data()?.likedComments || [] : [];
                const hasLiked = likedComments.includes(commentId);
                const currentLikes = commentDoc.data()?.likes || 0;

                if (hasLiked) {
                    transaction.update(commentRef, { likes: Math.max(0, currentLikes - 1) });
                    transaction.set(userFeedbackRef, { likedComments: arrayRemove(commentId) }, { merge: true });
                } else {
                    transaction.update(commentRef, { likes: currentLikes + 1 });
                    transaction.set(userFeedbackRef, { likedComments: arrayUnion(commentId) }, { merge: true });
                }
            });
        } catch (error) {
            console.error('Like error:', error);
            throw error;
        }
    },

    subscribeToUserFeedback: (userId: string, callback: (feedback: UserFeedbackData) => void): (() => void) => {
        const effectiveUserId = auth.currentUser?.uid || userId;
        const userFeedbackRef = doc(db, "users_feedback", effectiveUserId);
        return onSnapshot(userFeedbackRef, (docSnap) => {
            callback(docSnap.exists() ? docSnap.data() as UserFeedbackData : { rating: 0, likedComments: [] });
        });
    },

    submitRating: async (userId: string, rating: number): Promise<void> => {
        if (!navigator.onLine) throw new Error("You are offline");
        try {
            const effectiveUserId = await ensureAuth();
            const statsRef = doc(db, "feedback_stats", "summary");
            const userFeedbackRef = doc(db, "users_feedback", effectiveUserId);

            await runTransaction(db, async (transaction) => {
                const userFeedbackDoc = await transaction.get(userFeedbackRef);
                if (userFeedbackDoc.exists() && (userFeedbackDoc.data()?.rating || 0) > 0) {
                    throw new Error("You have already rated");
                }

                // CRITICAL FIX: Only update rating fields using atomic increments to avoid
                // overwriting 'studyMaterials' or 'activeUsers' counts from concurrent updates.
                transaction.set(statsRef, {
                    totalRatings: increment(1),
                    totalRatingSum: increment(rating),
                    lastUpdated: Date.now()
                }, { merge: true });

                transaction.set(userFeedbackRef, { rating: rating, likedComments: userFeedbackDoc.exists() ? userFeedbackDoc.data()?.likedComments || [] : [] }, { merge: true });
            });
        } catch (error) {
            console.error('Rating error:', error);
            throw error;
        }
    }
};

import { GoogleGenAI, HarmCategory, HarmBlockThreshold, GenerateContentResponse, Type } from "@google/genai";
import type { UserDetails, Lecture, StudyGoal, AgendaItem, SmartPlan, ImagePart, QuizQuestion, PlanSlot } from '../types';
import { QuizType, ActivityType, DayOfWeek } from '../types';
import { timeToMinutes } from '../lib/utils';

// ============================================
// CORE CONFIGURATION
// ============================================

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });

const safetySettings = [
    { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
];

// Fixed 404 error by using a supported model identifier
const MODEL = 'gemini-3-flash-preview';

// ============================================
// SIMPLIFIED CACHE
// ============================================

class FastCache {
    private cache = new Map<string, any>();
    private readonly MAX_SIZE = 50;

    get(key: string): any | null {
        return this.cache.get(key) ?? null;
    }

    set(key: string, data: any): void {
        if (this.cache.size >= this.MAX_SIZE) {
            const first = this.cache.keys().next().value;
            this.cache.delete(first);
        }
        this.cache.set(key, data);
    }

    clear(): void {
        this.cache.clear();
    }
}

const cache = new FastCache();

// ============================================
// OPTIMIZED SCHEMAS
// ============================================

const planSlotSchema = {
    type: Type.OBJECT,
    properties: {
        activity: { type: Type.STRING },
        startTime: { type: Type.STRING },
        endTime: { type: Type.STRING },
        type: { type: Type.STRING }, // 'lecture', 'break', 'free', 'agenda', 'study'
        code: { type: Type.STRING },
        location: { type: Type.STRING },
        durationMinutes: { type: Type.NUMBER },
    },
    required: ['activity', 'startTime', 'endTime', 'type']
};

const smartPlanSchema = {
    type: Type.ARRAY,
    items: {
        type: Type.OBJECT,
        properties: {
            day: { type: Type.STRING },
            slots: { type: Type.ARRAY, items: planSlotSchema }
        },
        required: ['day', 'slots']
    }
};

const quizSchema = {
    type: Type.ARRAY,
    items: {
        type: Type.OBJECT,
        properties: {
            question: { type: Type.STRING },
            options: { type: Type.ARRAY, items: { type: Type.STRING } },
            correctAnswer: { type: Type.STRING },
            explanation: { type: Type.STRING },
            topic: { type: Type.STRING },
            type: { type: Type.STRING },
        },
        required: ['question', 'correctAnswer', 'explanation', 'topic', 'type']
    }
};

const graphSolutionSchema = {
    type: Type.OBJECT,
    properties: {
        explanation: { type: Type.STRING },
        graphFunction: { type: Type.STRING },
        suggestedTitle: { type: Type.STRING },
    },
    required: ['explanation', 'graphFunction']
};

const tableSchema = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING },
        headers: { type: Type.ARRAY, items: { type: Type.STRING } },
        rows: { type: Type.ARRAY, items: { type: Type.ARRAY, items: { type: Type.STRING } } },
        caption: { type: Type.STRING }
    },
    required: ['headers', 'rows']
};

// ============================================
// FAST PARSER
// ============================================

const parseJSON = <T>(response: GenerateContentResponse, fallback?: T): T => {
    try {
        let text = response.text.trim();

        // Strip markdown if present
        if (text.startsWith('```')) {
            const start = text.indexOf('{') !== -1 ? text.indexOf('{') : text.indexOf('[');
            const end = text.lastIndexOf('}') !== -1 ? text.lastIndexOf('}') : text.lastIndexOf(']');
            if (start !== -1 && end !== -1) {
                text = text.substring(start, end + 1);
            }
        }

        return JSON.parse(text) as T;
    } catch (e) {
        console.error("Parse error:", e);
        if (fallback !== undefined) return fallback;
        throw new Error("Failed to parse AI response");
    }
};

// ============================================
// CLEAN & OPTIMIZE PLAN OUTPUT
// ============================================

const cleanPlan = (plan: SmartPlan): SmartPlan => {
    return plan.map(dayPlan => ({
        ...dayPlan,
        slots: dayPlan.slots.map(slot => {
            let { activity, type, code, location } = slot;

            // Use course codes when available
            if (code && type === 'lecture') {
                activity = code.toUpperCase();
            }

            // Remove redundant words
            activity = activity
                .replace(/\s+(study|session|class|lecture)$/i, '')
                .trim();

            // Lectures and Agenda items can have locations
            if (type !== 'lecture' && type !== 'agenda') {
                location = undefined;
            }

            // Lock lectures and agenda items by default
            const isLocked = type === 'lecture' || type === 'agenda';

            return { ...slot, activity, location, isLocked };
        })
    }));
};

// ============================================
// ENFORCE FIXED SLOTS (BUG FIX)
// ============================================

const enforceFixedSlots = (
    plan: SmartPlan, 
    lectures: Lecture[] | null, 
    agendaItems: AgendaItem[]
): SmartPlan => {
    // 1. Create a map of days for easy access
    const dayMap = new Map<string, PlanSlot[]>();

    // Initialize with existing slots, filtering out what we will replace
    plan.forEach(dayPlan => {
        const keptSlots = dayPlan.slots.filter(slot => {
            // Remove agenda items from AI plan as we will force-insert user's version
            if (slot.type === 'agenda') return false; 
            // If lectures are provided manually, remove AI lectures to force-insert user's version
            if (lectures && slot.type === 'lecture') return false; 
            return true;
        });
        dayMap.set(dayPlan.day, keptSlots);
    });

    // Ensure all days exist
    Object.values(DayOfWeek).forEach(day => {
        if (!dayMap.has(day)) {
            dayMap.set(day, []);
        }
    });

    // 2. Insert Lectures (if provided manually)
    if (lectures) {
        lectures.forEach(lec => {
            const slots = dayMap.get(lec.day) || [];
            slots.push({
                activity: lec.subject,
                startTime: lec.startTime,
                endTime: lec.endTime,
                location: lec.location,
                type: ActivityType.LECTURE,
                isLocked: true
            });
            dayMap.set(lec.day, slots);
        });
    }

    // 3. Insert Agenda Items (ALWAYS enforced)
    agendaItems.forEach(item => {
        const slots = dayMap.get(item.day) || [];
        slots.push({
            activity: item.title,
            startTime: item.startTime,
            endTime: item.endTime,
            location: item.location,
            type: ActivityType.AGENDA,
            isLocked: true
        });
        dayMap.set(item.day, slots);
    });

    // 4. Reconstruct Plan & Sort
    const newPlan: SmartPlan = Object.values(DayOfWeek).map(day => {
        const slots = dayMap.get(day) || [];
        // Sort by time
        slots.sort((a, b) => timeToMinutes(a.startTime) - timeToMinutes(b.startTime));
        return { day, slots };
    });

    return newPlan;
};

// ============================================
// SMART PLAN GENERATION (SIMPLIFIED & FAST)
// ============================================

export const generateSmartPlan = async (
    userDetails: UserDetails,
    lectures: Lecture[],
    studyGoals: StudyGoal[], 
    agendaItems: AgendaItem[],
    generalGoals: string,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const cacheKey = `plan_${JSON.stringify({ lectures, studyGoals, agendaItems }).substring(0, 100)}`;

    // Disable cache if we have an existing plan (implies regeneration/edit)
    if (!existingPlan) {
        const cached = cache.get(cacheKey);
        if (cached) return cached;
    }

    const prompt = `You are a scheduling AI. REGENERATE the weekly schedule based on these EXACT inputs.

**CRITICAL: SOURCE OF TRUTH (USER EDITS)**
These inputs have been manually verified/edited by the user. You MUST adhere to them strictly.
1. **Fixed Lectures:** ${JSON.stringify(lectures)}
   - Schedule these EXACTLY at the provided 'startTime' and 'endTime'.
   - Do NOT move, delete, or rename them.

2. **Fixed Agenda:** ${JSON.stringify(agendaItems)}
   - Schedule these EXACTLY as provided. They are immutable.

3. **Study Goals:** ${JSON.stringify(studyGoals)}
   - Fill gaps between fixed events with 'study' sessions for these subjects.

**General Goals:** ${generalGoals}

**Instructions:**
- **Overwrite Conflicts:** If a previous plan existed, DISCARD any slots that conflict with the new 'Fixed Lectures' or 'Fixed Agenda'. The new inputs are the priority.
- **Fill Gaps:** Use 'study' slots to fill open times (8am-8pm), prioritizing the Study Goals.
- **MANDATORY BREAKS:** You MUST insert a 15-30 min 'break' slot after every 2 hours of continuous activity (lectures or study).
- **Types:** 'lecture', 'agenda', 'study', 'break', 'free'.

**Format:**
- 7 days (Monday-Sunday)
- Times in "HH:MM AM/PM" format

Return ONLY the JSON array.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: {
            responseMimeType: 'application/json',
            responseSchema: smartPlanSchema,
            temperature: 0.1, // Very low temperature for strict adherence
            safetySettings,
        },
    });

    const plan = parseJSON<SmartPlan>(response, []);

    // STRICT ENFORCEMENT of manual inputs
    const enforcedPlan = enforceFixedSlots(plan, lectures, agendaItems);

    const cleaned = cleanPlan(enforcedPlan);

    cache.set(cacheKey, cleaned);
    return cleaned;
};

// ============================================
// IMAGE-BASED PLAN (SIMPLIFIED & FAST)
// ============================================

export const generatePlanFromImage = async (
    userDetails: UserDetails,
    studyGoals: StudyGoal[],
    agendaItems: AgendaItem[],
    generalGoals: string,
    image: ImagePart,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const prompt = `Create a COMPREHENSIVE weekly study plan based on this timetable image.

**PHASE 1: EXTRACTION**
1. Identify all course codes/subjects from the image (e.g., "MATH 101", "CS 202").
2. Schedule these exact classes as 'lecture' slots with their times and locations.

**PHASE 2: STUDY GENERATION (CRITICAL)**
1. **FILL FREE TIME:** Identify gaps in the schedule between 8:00 AM and 9:00 PM.
2. **CREATE STUDY SESSIONS:** Fill these gaps with 'study' sessions for the subjects identified in Phase 1.
   - **GOAL:** The user wants a full study schedule, NOT just a copy of the class timetable.
