// ============================================
// FAST PARSER
// ============================================

const parseJSON = <T>(response: GenerateContentResponse, fallback?: T): T => {
    try {
        let text = response.text.trim();

        // Strip markdown if present
        if (text.startsWith('```')) {
            const start = text.indexOf('{') !== -1 ? text.indexOf('{') : text.indexOf('[');
            const end = text.lastIndexOf('}') !== -1 ? text.lastIndexOf('}') : text.lastIndexOf(']');
            if (start !== -1 && end !== -1) {
                text = text.substring(start, end + 1);
            }
        }

        return JSON.parse(text) as T;
    } catch (e) {
        console.error("Parse error:", e);
        if (fallback !== undefined) return fallback;
        throw new Error("Failed to parse AI response");
    }
};

// ============================================
// CLEAN & OPTIMIZE PLAN OUTPUT
// ============================================

const cleanPlan = (plan: SmartPlan): SmartPlan => {
    return plan.map(dayPlan => ({
        ...dayPlan,
        slots: dayPlan.slots.map(slot => {
            let { activity, type, code, location } = slot;

            // Use course codes when available
            if (code && type === 'lecture') {
                activity = code.toUpperCase();
            }

            // Remove redundant words
            activity = activity
                .replace(/\s+(study|session|class|lecture)$/i, '')
                .trim();

            // Lectures and Agenda items can have locations
            if (type !== 'lecture' && type !== 'agenda') {
                location = undefined;
            }

            // Lock lectures and agenda items by default
            const isLocked = type === 'lecture' || type === 'agenda';

            return { ...slot, activity, location, isLocked };
        })
    }));
};

// ============================================
// ENFORCE FIXED SLOTS (BUG FIX)
// ============================================

const enforceFixedSlots = (
    plan: SmartPlan, 
    lectures: Lecture[] | null, 
    agendaItems: AgendaItem[]
): SmartPlan => {
    // 1. Create a map of days for easy access
    const dayMap = new Map<string, PlanSlot[]>();

    // Initialize with existing slots, filtering out what we will replace
    plan.forEach(dayPlan => {
        const keptSlots = dayPlan.slots.filter(slot => {
            // Remove agenda items from AI plan as we will force-insert user's version
            if (slot.type === 'agenda') return false; 
            // If lectures are provided manually, remove AI lectures to force-insert user's version
            if (lectures && slot.type === 'lecture') return false; 
            return true;
        });
        dayMap.set(dayPlan.day, keptSlots);
    });

    // Ensure all days exist
    Object.values(DayOfWeek).forEach(day => {
        if (!dayMap.has(day)) {
            dayMap.set(day, []);
        }
    });

    // 2. Insert Lectures (if provided manually)
    if (lectures) {
        lectures.forEach(lec => {
            const slots = dayMap.get(lec.day) || [];
            slots.push({
                activity: lec.subject,
                startTime: lec.startTime,
                endTime: lec.endTime,
                location: lec.location,
                type: ActivityType.LECTURE,
                isLocked: true
            });
            dayMap.set(lec.day, slots);
        });
    }

    // 3. Insert Agenda Items (ALWAYS enforced)
    agendaItems.forEach(item => {
        const slots = dayMap.get(item.day) || [];
        slots.push({
            activity: item.title,
            startTime: item.startTime,
            endTime: item.endTime,
            location: item.location,
            type: ActivityType.AGENDA,
            isLocked: true
        });
        dayMap.set(item.day, slots);
    });

    // 4. Reconstruct Plan & Sort
    const newPlan: SmartPlan = Object.values(DayOfWeek).map(day => {
        const slots = dayMap.get(day) || [];
        // Sort by time
        slots.sort((a, b) => timeToMinutes(a.startTime) - timeToMinutes(b.startTime));
        return { day, slots };
    });

    return newPlan;
};

// ============================================
// SMART PLAN GENERATION (SIMPLIFIED & FAST)
// ============================================

export const generateSmartPlan = async (
    userDetails: UserDetails,
    lectures: Lecture[],
    studyGoals: StudyGoal[], 
    agendaItems: AgendaItem[],
    generalGoals: string,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const cacheKey = `plan_${JSON.stringify({ lectures, studyGoals, agendaItems }).substring(0, 100)}`;

    // Disable cache if we have an existing plan (implies regeneration/edit)
    if (!existingPlan) {
        const cached = cache.get(cacheKey);
        if (cached) return cached;
    }

    const prompt = `You are a scheduling AI. REGENERATE the weekly schedule based on these EXACT inputs.

**CRITICAL: SOURCE OF TRUTH (USER EDITS)**
These inputs have been manually verified/edited by the user. You MUST adhere to them strictly.
1. **Fixed Lectures:** ${JSON.stringify(lectures)}
   - Schedule these EXACTLY at the provided 'startTime' and 'endTime'.
   - Do NOT move, delete, or rename them.

2. **Fixed Agenda:** ${JSON.stringify(agendaItems)}
   - Schedule these EXACTLY as provided. They are immutable.

3. **Study Goals:** ${JSON.stringify(studyGoals)}
   - Fill gaps between fixed events with 'study' sessions for these subjects.

**General Goals:** ${generalGoals}

**Instructions:**
- **Overwrite Conflicts:** If a previous plan existed, DISCARD any slots that conflict with the new 'Fixed Lectures' or 'Fixed Agenda'. The new inputs are the priority.
- **Fill Gaps:** Use 'study' slots to fill open times (8am-8pm), prioritizing the Study Goals.
- **MANDATORY BREAKS:** You MUST insert a 15-30 min 'break' slot after every 2 hours of continuous activity (lectures or study).
- **Types:** 'lecture', 'agenda', 'study', 'break', 'free'.

**Format:**
- 7 days (Monday-Sunday)
- Times in "HH:MM AM/PM" format

Return ONLY the JSON array.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: {
            responseMimeType: 'application/json',
            responseSchema: smartPlanSchema,
            temperature: 0.1, // Very low temperature for strict adherence
            safetySettings,
        },
    });

    const plan = parseJSON<SmartPlan>(response, []);

    // STRICT ENFORCEMENT of manual inputs
    const enforcedPlan = enforceFixedSlots(plan, lectures, agendaItems);

    const cleaned = cleanPlan(enforcedPlan);

    cache.set(cacheKey, cleaned);
    return cleaned;
};

