interface CollaborativeSessionProps {
  userDetails: UserDetails | null;
  addToast: (message: string, type: Toast['type']) => void;
  onActionAttempt: (action: () => Promise<void>) => void;
  activeCode: string | null;
  setActiveCode: (code: string | null) => void;
  notes: Note[];
  setNotes: (notes: Note[]) => void;
}

export function CollaborativeSession({ userDetails, addToast, onActionAttempt, activeCode, setActiveCode, notes, setNotes }: CollaborativeSessionProps) {
  const [sessionCode, setSessionCode] = useState('');
  const [sessionData, setSessionData] = useState<any>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [isAIThinking, setIsAIThinking] = useState(false);
  const [isViewOnly, setIsViewOnly] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (activeCode) {
      setSessionCode(activeCode);
      setIsSidebarOpen(false);
    }
  }, [activeCode]);

  useEffect(() => {
    if (!sessionCode) return;
    const sessionRef = doc(db, 'sessions', sessionCode);
    const unsub = onSnapshot(sessionRef, (snap) => {
      if (snap.exists()) {
        const data = snap.data();
        setSessionData(data);
        setMessages(data.messages || []);
      }
    });
    return unsub;
  }, [sessionCode]);

  const sendMessage = async () => {
    if (!newMessage.trim() || !sessionCode || !userDetails) return;
    const msg = { id: Date.now().toString(), sender: userDetails.name, text: newMessage, timestamp: Date.now(), type: 'text' };
    setNewMessage('');
    await updateDoc(doc(db, 'sessions', sessionCode), { messages: arrayUnion(msg), lastActivity: Date.now() });
  };

  const askAI = async () => {
    if (messages.length === 0 || isAIThinking) return;
    setIsAIThinking(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });
      const prompt = `Context: ${messages.slice(-10).map(m => m.text).join('\n')}. Provide a helpful study response.`;
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
      const aiMsg = { id: Date.now().toString(), sender: 'EduBlay AI', text: response.text, timestamp: Date.now(), type: 'ai' };
      await updateDoc(doc(db, 'sessions', sessionCode), { messages: arrayUnion(aiMsg), lastActivity: Date.now() });
    } catch (e) {
      addToast("AI failed to respond.", "error");
    } finally {
      setIsAIThinking(false);
    }
  };

  return (
    <div className="flex h-full bg-gray-50 dark:bg-gray-900 rounded-xl overflow-hidden border dark:border-gray-700">
      <div className="flex-1 flex flex-col">
        {sessionCode ? (
          <>
            <div className="p-4 bg-white dark:bg-gray-800 border-b flex justify-between items-center">
              <h2 className="font-bold">Session: {sessionCode}</h2>
              <button onClick={askAI} disabled={isAIThinking} className="flex items-center gap-2 px-3 py-1.5 bg-purple-600 text-white rounded-md text-sm">
                <Sparkles className="w-4 h-4" /> {isAIThinking ? 'Thinking...' : 'Ask AI'}
              </button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-3">
              {messages.map(m => (
                <div key={m.id} className={`flex ${m.sender === userDetails?.name ? 'justify-end' : 'justify-start'}`}>
                  <div className={`p-3 rounded-lg max-w-[80%] ${m.sender === userDetails?.name ? 'bg-blue-600 text-white' : 'bg-white dark:bg-gray-700'}`}>
                    <p className="text-xs opacity-70 mb-1 font-bold">{m.sender}</p>
                    <p>{m.text}</p>
                  </div>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>
            <div className="p-4 bg-white dark:bg-gray-800 border-t flex gap-2">
              <input 
                type="text" 
                value={newMessage} 
                onChange={(e) => setNewMessage(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
                className="flex-1 p-2 border rounded-md dark:bg-gray-700 dark:border-gray-600"
                placeholder="Type a message..."
              />
              <button onClick={sendMessage} className="p-2 bg-blue-600 text-white rounded-md"><Send className="w-5 h-5" /></button>
            </div>
          </>
        ) : (
          <div className="flex-1 flex items-center justify-center text-gray-500">Select or create a session to begin.</div>
        )}
      </div>
    </div>
  );
}

