  }, []);

  const persistAllState = useCallback(() => {
    if (!userDetails?.email) return;

    const userId = userDetails.id || userDetails.email;
    const emailKey = `${USER_KEY_PREFIX}${userDetails.email}`;

    const currentUserData = {
        userDetails,
        smartPlan,
        savedTimetables,
        notes,
        notificationSettings,
        trackedData,
        uploadedMaterials,
        courseCodeMap,
        quizState: {
            quiz: quizState.quiz,
