      case 'feedback':
        return <Feedback 
                    userDetails={userDetails} 
                    addToast={addToast} 
                />;
      case 'help':
        return <Help setView={setView} />;
      case 'about':
        return <About setView={setView} />;
      case 'library':
        return <Library />;
      case 'terms':
        return <Terms />;
      case 'tutorial':
        return <Tutorial
                    addToast={addToast}
                    tutorialVideoUrl={tutorialVideoUrl}
                />;
      default:
        return <div>{t('common.notFound')}</div>;
    }
  };

  if (isInitializing) {
      return (
          <div className="flex flex-col h-screen h-[100dvh] bg-gray-100 dark:bg-gray-900 items-center justify-center">
              <div className="relative">
                  <div className="w-16 h-16 border-4 border-gray-200 dark:border-gray-700 border-t-primary rounded-full animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center">
                      <LogoIcon className="w-8 h-8 text-primary animate-pulse" />
                  </div>
              </div>
              <h1 className="mt-4 text-xl font-bold text-gray-800 dark:text-white tracking-wide">EduBlay</h1>
              <p className="text-sm text-gray-500 dark:text-gray-400 mt-1 animate-pulse">Loading your workspace...</p>
          </div>
      );
  }

  if (!isLoggedIn) {
    if (!welcomeComplete) {
        return <Welcome onProceed={handleWelcomeComplete} />;
    }
    return <SignUp onLogin={handleLogin} />;
  }

  if (isStudyMode) {
     return <FocusedStudyView 
                session={activeSession!} 
                setSession={setActiveSession}
                addToast={addToast}
                trackedData={trackedData}
                setTrackedData={setTrackedData}
                setView={setView}
                learningHubState={learningHubState}
                setLearningHubState={setLearningHubState}
            />;
  }

  return (
    <div className="flex h-screen h-[100dvh] bg-gray-100 dark:bg-gray-900 text-gray-900 dark:text-gray-100 overflow-hidden">
      <NotificationManager plan={smartPlan} settings={notificationSettings} />
      <ToastContainer toasts={toasts} onDismiss={dismissToast} />
      <Sidebar view={view} setView={setView} isOpen={sidebarOpen} setOpen={setSidebarOpen} userDetails={userDetails} />
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        {showNotifPrompt && <NotificationPrompt settings={notificationSettings} setSettings={setNotificationSettings} />}
        <Header 
            toggleSidebar={() => setSidebarOpen(!sidebarOpen)} 
            userDetails={userDetails} 
            setView={setView} 
            addToast={addToast}
            handleLogout={handleLogout}
        />
        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 dark:bg-gray-900 p-4 sm:p-6 lg:p-8">
          {renderView()}
        </main>
      </div>
       {activeSession?.type === 'break' && <BreakView session={activeSession} onEnd={handleBreakCompletion} />}
    </div>
  );
};

export default App;

