const DonutChart: React.FC<{ data: { type: string; value: number; color: string }[] }> = ({ data }) => {
    const { t } = useLanguage();
    const total = data.reduce((sum, item) => sum + item.value, 0);
    if (total === 0) return <div className="flex items-center justify-center h-48 w-48 rounded-full bg-gray-50 dark:bg-gray-800 border-2 border-dashed border-gray-200 dark:border-gray-700 mx-auto"><span className="text-gray-400 text-sm font-medium">{t('progression.noData')}</span></div>;

    const radius = 80;
    const circumference = 2 * Math.PI * radius;
    let accumulatedPercentage = 0;

    return (
        <svg width="200" height="200" viewBox="0 0 200 200" className="transform -rotate-90">
            {data.map((item, index) => {
                if (item.value === 0) return null;
                const percentage = item.value / total;
                const strokeDasharray = `${percentage * circumference} ${circumference}`;
                const strokeDashoffset = -accumulatedPercentage * circumference;
                accumulatedPercentage += percentage;

                return (
                    <circle
                        key={index}
                        r={radius}
                        cx="100"
                        cy="100"
                        fill="transparent"
                        strokeWidth="30"
                        style={{ stroke: item.color }}
                        strokeDasharray={strokeDasharray}
                        strokeDashoffset={strokeDashoffset}
                        className="transition-all duration-1000 ease-out"
                    />
                );
            })}
        </svg>
    );
};

