  const [activeTab, setActiveTab] = useState<'current' | 'history'>('current');

  useEffect(() => {
    const getTailwindColor = (className: string): string => {
        const el = document.createElement('div');
        el.className = className;
        el.style.display = 'none';
        document.body.appendChild(el);
        const color = window.getComputedStyle(el).backgroundColor;
        document.body.removeChild(el);
        return color;
    };

    setChartColors({
      study: getTailwindColor('bg-study'),
      lecture: getTailwindColor('bg-lecture'),
      agenda: getTailwindColor('bg-agenda'),
      break: getTailwindColor('bg-break'),
      free: getTailwindColor('bg-free')
    });
  }, [colorTheme]);

  useEffect(() => {
    const data = storageService.loadItem<WeeklySnapshot[]>('weekly-snapshots-v3');
    if (data) setWeeklySnapshots(data);
  }, []);

  const stats = useMemo(() => {
    if (!plan) return null;

    const totals = { study: 0, lecture: 0, agenda: 0, break: 0, free: 0 };
    const studyBySubject = new Map<string, number>();
    const dailyTotals = new Map<string, number>();

    for (const day of plan) {
      let dayTotalMinutes = 0;
      for (const slot of day.slots) {
        if (!slot.startTime || !slot.endTime) continue;
        const duration = timeToMinutes(slot.endTime) - timeToMinutes(slot.startTime);
        if (duration <= 0) continue;
        const activityType = slot.type || ActivityType.FREE;
        dayTotalMinutes += duration;
        switch (activityType) {
          case ActivityType.STUDY:
            totals.study += duration;
            studyBySubject.set(slot.activity, (studyBySubject.get(slot.activity) || 0) + duration);
            break;
          case ActivityType.LECTURE: totals.lecture += duration; break;
          case ActivityType.AGENDA: totals.agenda += duration; break;
          case ActivityType.BREAK: totals.break += duration; break;
          case ActivityType.FREE: totals.free += duration; break;
        }
      }
      dailyTotals.set(day.day, dayTotalMinutes);
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const dayOfWeek = today.getDay();
    const diffToMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
    const startOfWeek = new Date(today);
    startOfWeek.setDate(today.getDate() - diffToMonday);
    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 6);
    endOfWeek.setHours(23, 59, 59, 999);

    const weeklyTrackedData = trackedData.filter(session => {
        const parts = session.date.split('-').map(Number);
        if (parts.length !== 3) return false;
        const [year, month, day] = parts;
        const sessionDate = new Date(year, month - 1, day);
        return sessionDate >= startOfWeek && sessionDate <= endOfWeek;
    });

    const dailyTrackedMap = new Map<string, number>();
    const dayNames = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    weeklyTrackedData.forEach(session => {
      const parts = session.date.split('-').map(Number);
      const [year, month, day] = parts;
      const sessionDate = new Date(year, month - 1, day);
      const dayName = dayNames[sessionDate.getDay() === 0 ? 6 : sessionDate.getDay() - 1];
      dailyTrackedMap.set(dayName, (dailyTrackedMap.get(dayName) || 0) + session.durationMinutes);
    });

    const currentWeekDailyHours = dayNames.map(day => ({
      day: day.slice(0, 3),
      hours: (dailyTrackedMap.get(day) || 0) / 60
    }));

    const trackedStudyBySubject = new Map<string, number>();
    weeklyTrackedData.forEach(session => {
        trackedStudyBySubject.set(session.subject, (trackedStudyBySubject.get(session.subject) || 0) + session.durationMinutes);
    });

    const allSubjects = Array.from(new Set([...studyBySubject.keys(), ...trackedStudyBySubject.keys()]));
    const trackedVsScheduled = allSubjects.map(subject => ({
        subject,
        scheduledHours: (studyBySubject.get(subject) || 0) / 60,
        trackedHours: (trackedStudyBySubject.get(subject) || 0) / 60,
    }));

    return {
      totalHours: {
        study: (totals.study / 60).toFixed(1),
        lecture: (totals.lecture / 60).toFixed(1),
        agenda: (totals.agenda / 60).toFixed(1),
        break: (totals.break / 60).toFixed(1),
        free: (totals.free / 60).toFixed(1),
      },
      activityDistribution: [
        { type: t('progression.activity.study'), value: totals.study, color: chartColors.study, legendColor: 'bg-study' },
        { type: t('progression.activity.lecture'), value: totals.lecture, color: chartColors.lecture, legendColor: 'bg-lecture' },
        { type: t('progression.activity.agenda'), value: totals.agenda, color: chartColors.agenda, legendColor: 'bg-agenda' },
        { type: t('progression.activity.break'), value: totals.break, color: chartColors.break, legendColor: 'bg-break' },
        { type: t('progression.activity.free'), value: totals.free, color: chartColors.free, legendColor: 'bg-free' },
      ],
      trackedVsScheduled,
      currentWeekDailyHours
    };
  }, [plan, trackedData, chartColors, t]);

  useEffect(() => {
    const checkAndSaveWeeklySnapshot = async () => {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const todayStr = today.toISOString().split('T')[0];
      if (todayStr === lastCheckedDate) return;
      setLastCheckedDate(todayStr);

      const dayOfWeek = today.getDay();
      if (dayOfWeek === 1) { // Monday
        const lastWeekEnd = new Date(today);
        lastWeekEnd.setDate(today.getDate() - 1);
        const lastWeekStart = new Date(lastWeekEnd);
        lastWeekStart.setDate(lastWeekEnd.getDate() - 6);

        const startStr = lastWeekStart.toISOString().split('T')[0];
        if (weeklySnapshots.some(s => s.weekStart === startStr)) return;

        const lastWeekData = trackedData.filter(session => {
          const parts = session.date.split('-').map(Number);
          const sessionDate = new Date(parts[0], parts[1] - 1, parts[2]);
          return sessionDate >= lastWeekStart && sessionDate <= lastWeekEnd;
        });

        if (lastWeekData.length > 0 && plan) {
          const totalTrackedHours = lastWeekData.reduce((sum, s) => sum + s.durationMinutes, 0) / 60;
          let totalScheduledMinutes = 0;
          plan.forEach(d => d.slots.forEach(s => {
            if (s.type === ActivityType.STUDY) totalScheduledMinutes += (timeToMinutes(s.endTime) - timeToMinutes(s.startTime));
          }));
          const totalScheduledHours = totalScheduledMinutes / 60;

          const dailyTrackedMap = new Map<string, number>();
          const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
          lastWeekData.forEach(s => {
              const d = new Date(s.date);
              const name = dayNames[d.getDay()];
              dailyTrackedMap.set(name, (dailyTrackedMap.get(name) || 0) + s.durationMinutes);
          });

          const trackedVsScheduledForAI = Array.from(new Set([...lastWeekData.map(s => s.subject)])).map(subj => ({
              subject: subj,
              trackedHours: (lastWeekData.filter(s => s.subject === subj).reduce((acc, curr) => acc + curr.durationMinutes, 0)) / 60,
              scheduledHours: 0 // Snapshot context simplified
          }));

          const aiAdvice = await generateWeeklyProgressComment(userDetails!, trackedVsScheduledForAI);

          const snapshot: WeeklySnapshot = {
            weekStart: startStr,
            weekEnd: lastWeekEnd.toISOString().split('T')[0],
            dailyTrackedHours: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => ({ day: d, hours: 0 })), // Placeholder
            totalTrackedHours,
            totalScheduledHours,
            comment: `Week of ${startStr} complete!`,
            aiAdvice,
            timestamp: Date.now()
          };

          const updated = [...weeklySnapshots, snapshot];
          setWeeklySnapshots(updated);
          storageService.saveItem('weekly-snapshots-v3', updated);
        }
      }
    };
    if (plan && trackedData.length > 0 && userDetails) checkAndSaveWeeklySnapshot();
  }, [trackedData, plan, userDetails, lastCheckedDate, weeklySnapshots]);

  const latestReport = useMemo(() => {
    if (weeklySnapshots.length === 0) return null;
    const latest = weeklySnapshots[weeklySnapshots.length - 1];
    const oneWeekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
    // Vanish if older than current Monday's tracking period (approx 7 days)
    return latest.timestamp > oneWeekAgo ? latest : null;
  }, [weeklySnapshots]);

  if (!plan || !stats) {
    return (
      <div className="max-w-4xl mx-auto bg-white dark:bg-gray-900 rounded-2xl shadow-lg p-10 text-center animate-fade-in">
        <div className="w-20 h-20 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-6">
            <ChartBarIcon className="w-10 h-10 text-primary" />
        </div>
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-2">{t('progression.title')}</h2>
        <p className="text-gray-500 dark:text-gray-400 max-w-sm mx-auto">{t('progression.noPlan')}</p>
      </div>
    );
  }

  const totalWeekHours = stats.activityDistribution.reduce((acc, curr) => acc + curr.value, 0) / 60;

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-20 animate-fade-in">
       <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
         <div>
            <h2 className="text-4xl font-black text-gray-900 dark:text-white tracking-tight">{t('progression.title')}</h2>
            <p className="text-gray-500 dark:text-gray-400 mt-2 font-medium">{t('progression.subtitle')}</p>
         </div>
         <div className="flex bg-gray-100 dark:bg-gray-800 p-1 rounded-xl border dark:border-gray-700">
            <button 
                onClick={() => setActiveTab('current')}
                className={`px-6 py-2 text-sm font-bold rounded-lg transition-all ${activeTab === 'current' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
            >
                This Week
            </button>
            <button 
                onClick={() => setActiveTab('history')}
                className={`px-6 py-2 text-sm font-bold rounded-lg transition-all ${activeTab === 'history' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
            >
                Full History
            </button>
         </div>
       </div>

       {activeTab === 'current' ? (
           <div className="space-y-8 animate-fade-in-down">
                {/* AI REPORT FOR PREVIOUS WEEK - Only if fresh */}
                {latestReport && (
                    <div className="relative overflow-hidden group">
                        <div className="absolute inset-0 bg-gradient-to-r from-primary/5 to-purple-500/5 dark:from-primary/10 dark:to-purple-500/10 pointer-events-none rounded-[2.5rem]"></div>
                        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] shadow-xl border border-primary/20 dark:border-primary/30 relative">
                            <div className="flex flex-col md:flex-row items-start gap-8">
                                <div className="flex-shrink-0 flex flex-col items-center gap-4">
                                    <div className="w-20 h-20 bg-primary text-white rounded-3xl flex items-center justify-center shadow-lg shadow-primary/30 transform -rotate-3">
                                        <GeminiIcon className="w-10 h-10" />
                                    </div>
                                    <div className="text-center">
                                        <p className="text-[10px] font-black uppercase tracking-widest text-primary/60">Weekly Report</p>
                                        <p className="text-xs font-bold text-gray-400 mt-1">v. Intelligence</p>
                                    </div>
                                </div>
                                <div className="flex-1 space-y-4">
                                    <div>
                                        <h3 className="text-2xl font-black text-gray-900 dark:text-white leading-tight">
                                            Last Week's Academic Analysis
                                        </h3>
                                        <p className="text-sm font-bold text-gray-400 mt-1">
                                            Reporting Period: <span className="text-primary">{latestReport.weekStart}</span> — <span className="text-primary">{latestReport.weekEnd}</span>
                                        </p>
                                    </div>
                                    <div className="p-5 bg-gray-50 dark:bg-gray-900/50 rounded-2xl border dark:border-gray-700/50">
                                        <p className="text-lg text-gray-700 dark:text-gray-200 leading-relaxed font-medium italic">
                                            "{latestReport.aiAdvice}"
                                        </p>
                                    </div>
                                    <div className="flex flex-wrap gap-4 pt-2">
                                        <div className="px-4 py-2 bg-green-50 dark:bg-green-900/20 rounded-full border border-green-100 dark:border-green-800/30">
                                            <span className="text-xs font-bold text-green-600 dark:text-green-400 uppercase tracking-wider">Completion: {((latestReport.totalTrackedHours / Math.max(latestReport.totalScheduledHours, 1)) * 100).toFixed(0)}%</span>
                                        </div>
                                        <div className="px-4 py-2 bg-blue-50 dark:bg-blue-900/20 rounded-full border border-blue-100 dark:border-blue-800/30">
                                            <span className="text-xs font-bold text-blue-600 dark:text-blue-400 uppercase tracking-wider">Total: {latestReport.totalTrackedHours.toFixed(1)}h Studied</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    <StatsCard title="Time Allocation" icon={<ClockIcon className="w-5 h-5"/>} className="lg:col-span-1">
                        <div className="space-y-6">
                            <div className="p-4 bg-primary/5 dark:bg-primary/10 rounded-2xl">
                                <p className="text-xs font-black uppercase tracking-widest text-primary mb-1">{t('progression.totalStudy')}</p>
                                <p className="font-black text-4xl text-gray-900 dark:text-white">{stats.totalHours.study}h</p>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div><p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">{t('progression.totalLecture')}</p><p className="font-bold text-lg text-lecture">{stats.totalHours.lecture}h</p></div>
                                <div><p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">{t('progression.personalAgenda')}</p><p className="font-bold text-lg text-agenda">{stats.totalHours.agenda}h</p></div>
                                <div><p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">{t('progression.totalBreak')}</p><p className="font-bold text-lg text-break">{stats.totalHours.break}h</p></div>
                                <div><p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">{t('progression.totalFree')}</p><p className="font-bold text-lg text-free">{stats.totalHours.free}h</p></div>
                            </div>
                        </div>
                    </StatsCard>

                    <StatsCard title={t('progression.activityBreakdown')} icon={<AwardIcon className="w-5 h-5"/>} className="lg:col-span-2">
                        <div className="flex flex-col sm:flex-row items-center justify-around gap-10">
                            <DonutChart data={stats.activityDistribution} />
                            <div className="space-y-3 text-sm w-full max-w-xs">
                                {stats.activityDistribution.map(item => item.value > 0 && (
                                    <div key={item.type} className="flex items-center justify-between group">
                                        <div className="flex items-center gap-3">
                                            <span className={`w-3 h-3 rounded-full shadow-sm ${item.legendColor} group-hover:scale-125 transition-transform`}></span>
                                            <span className="font-bold text-gray-600 dark:text-gray-300">{item.type}</span>
                                        </div>
                                        <span className="font-black text-gray-900 dark:text-white">{totalWeekHours > 0 ? ((item.value / 60) / totalWeekHours * 100).toFixed(0) : 0}%</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </StatsCard>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    <StatsCard title="Daily Study Progress" icon={<ChartBarIcon className="w-5 h-5"/>}>
                        <WeeklyBarGraph dailyData={stats.currentWeekDailyHours} />
                    </StatsCard>

                    <StatsCard title={t('progression.trackedVsScheduled')} icon={<GeminiIcon className="w-5 h-5"/>}>
                        {stats.trackedVsScheduled.length > 0 ? (
                            <div className="space-y-6">
                                {stats.trackedVsScheduled.map(item => (
                                    <div key={item.subject} className="group">
                                        <div className="flex justify-between mb-2">
                                            <span className="text-sm font-black text-gray-800 dark:text-gray-100 uppercase tracking-tight">{item.subject}</span>
                                            <span className="text-xs font-bold text-gray-400">{item.trackedHours.toFixed(1)}h / {item.scheduledHours.toFixed(1)}h</span>
                                        </div>
                                        <div className="w-full bg-gray-100 dark:bg-gray-700/50 rounded-full h-4 overflow-hidden shadow-inner relative">
                                            <div className="bg-primary/20 h-full rounded-full transition-all duration-1000" style={{ width: `${(item.scheduledHours / Math.max(item.scheduledHours, item.trackedHours, 1)) * 100}%` }}></div>
                                            <div className="bg-primary h-full rounded-full absolute top-0 left-0 transition-all duration-1000 shadow-md" style={{ width: `${(item.trackedHours / Math.max(item.scheduledHours, item.trackedHours, 1)) * 100}%` }}></div>
                                        </div>
                                    </div>
                                ))}
                                <div className="flex items-center justify-end gap-6 pt-4 border-t dark:border-gray-700">
                                    <div className="flex items-center gap-2"><span className="w-2.5 h-2.5 rounded-full bg-primary shadow-sm"></span><span className="text-[10px] font-black uppercase text-gray-400 tracking-widest">{t('progression.legend.tracked')}</span></div>
                                    <div className="flex items-center gap-2"><span className="w-2.5 h-2.5 rounded-full bg-primary/20 shadow-sm"></span><span className="text-[10px] font-black uppercase text-gray-400 tracking-widest">{t('progression.legend.scheduled')}</span></div>
                                </div>
                            </div>
                        ) : (
                            <div className="text-center py-10 opacity-50">
                                <GeminiIcon className="w-12 h-12 mx-auto mb-4 text-gray-400" />
                                <p className="text-sm font-bold uppercase tracking-widest">{t('progression.noGoals')}</p>
                            </div>
                        )}
                    </StatsCard>
                </div>
           </div>
       ) : (
           <div className="space-y-6 animate-fade-in">
              {weeklySnapshots.length > 0 ? (
                  [...weeklySnapshots].reverse().map((snapshot, idx) => (
                    <div key={idx} className="bg-white dark:bg-gray-800 p-8 rounded-3xl border border-gray-100 dark:border-gray-700 shadow-sm hover:shadow-md transition-shadow">
                        <div className="flex flex-col md:flex-row justify-between gap-6">
                            <div className="flex-1 space-y-4">
                                <div className="flex items-center gap-3">
                                    <span className="px-4 py-1.5 bg-gray-100 dark:bg-gray-700 rounded-full text-xs font-black uppercase tracking-widest text-gray-600 dark:text-gray-400">
                                        {snapshot.weekStart} — {snapshot.weekEnd}
                                    </span>
                                </div>
                                <h4 className="text-xl font-black text-gray-800 dark:text-white">{snapshot.comment}</h4>
                                <div className="p-4 bg-gray-50 dark:bg-gray-900 rounded-2xl italic text-gray-600 dark:text-gray-300">
                                    "{snapshot.aiAdvice}"
                                </div>
                            </div>
                            <div className="md:w-64 flex flex-col justify-center gap-3">
                                <div className="p-4 rounded-2xl bg-primary/5 dark:bg-primary/10 border border-primary/10">
                                    <p className="text-[10px] font-black text-primary uppercase tracking-widest mb-1">Weekly Score</p>
                                    <p className="text-3xl font-black text-primary">{((snapshot.totalTrackedHours / Math.max(snapshot.totalScheduledHours, 1)) * 100).toFixed(0)}%</p>
                                </div>
                                <div className="grid grid-cols-2 gap-2">
                                     <div className="p-3 rounded-xl bg-gray-50 dark:bg-gray-900">
                                        <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Studied</p>
                                        <p className="text-sm font-bold">{snapshot.totalTrackedHours.toFixed(1)}h</p>
                                    </div>
                                    <div className="p-3 rounded-xl bg-gray-50 dark:bg-gray-900">
                                        <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Goal</p>
                                        <p className="text-sm font-bold">{snapshot.totalScheduledHours.toFixed(1)}h</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                  ))
              ) : (
                  <div className="text-center py-20 bg-white dark:bg-gray-800 rounded-3xl border-2 border-dashed border-gray-200 dark:border-gray-700">
                      <p className="text-gray-400 font-bold uppercase tracking-widest">No historical reports yet</p>
                  </div>
              )}
           </div>
       )}
    </div>
  );
};

export default Progression;

import React, { useMemo, useState, useEffect } from 'react';
import { SmartPlan, ActivityType, DayOfWeek, TrackedSession, UserDetails } from '../types';
import { DAYS_OF_WEEK } from '../constants';
import { useLanguage } from '../contexts/LanguageContext';
import { useColorTheme } from '../contexts/ColorThemeContext';
import { timeToMinutes } from '../lib/utils';
import { generateWeeklyProgressComment } from '../services/geminiService';
import { GeminiIcon } from './icons/GeminiIcon';
import { storageService } from '../services/authService';
import { ChartBarIcon } from './icons/ChartBarIcon';
import { ClockIcon } from './icons/ClockIcon';
import { AwardIcon } from './icons/AwardIcon';

interface ProgressionProps {
  plan: SmartPlan | null;
  trackedData: TrackedSession[];
  userDetails: UserDetails | null;
}

interface WeeklySnapshot {
  weekStart: string;
  weekEnd: string;
  dailyTrackedHours: Array<{
    day: string;
    hours: number;
  }>;
  totalTrackedHours: number;
  totalScheduledHours: number;
  comment: string;
  aiAdvice: string;
  timestamp: number;
}

const StatsCard: React.FC<{ title: string; children: React.ReactNode; className?: string; icon?: React.ReactNode }> = ({ title, children, className = '', icon }) => (
    <div className={`bg-white dark:bg-gray-800/50 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 ${className}`}>
        <div className="flex items-center gap-2 mb-6">
            {icon && <div className="text-primary">{icon}</div>}
            <h3 className="text-lg font-bold text-gray-800 dark:text-gray-200">{title}</h3>
        </div>
        <div>
            {children}
        </div>
    </div>
);

const DonutChart: React.FC<{ data: { type: string; value: number; color: string }[] }> = ({ data }) => {
    const { t } = useLanguage();
    const total = data.reduce((sum, item) => sum + item.value, 0);
    if (total === 0) return <div className="flex items-center justify-center h-48 w-48 rounded-full bg-gray-50 dark:bg-gray-800 border-2 border-dashed border-gray-200 dark:border-gray-700 mx-auto"><span className="text-gray-400 text-sm font-medium">{t('progression.noData')}</span></div>;

    const radius = 80;
    const circumference = 2 * Math.PI * radius;
    let accumulatedPercentage = 0;

    return (
        <svg width="200" height="200" viewBox="0 0 200 200" className="transform -rotate-90">
            {data.map((item, index) => {
                if (item.value === 0) return null;
                const percentage = item.value / total;
                const strokeDasharray = `${percentage * circumference} ${circumference}`;
                const strokeDashoffset = -accumulatedPercentage * circumference;
                accumulatedPercentage += percentage;

                return (
                    <circle
                        key={index}
                        r={radius}
                        cx="100"
                        cy="100"
                        fill="transparent"
                        strokeWidth="30"
                        style={{ stroke: item.color }}
                        strokeDasharray={strokeDasharray}
                        strokeDashoffset={strokeDashoffset}
                        className="transition-all duration-1000 ease-out"
                    />
                );
            })}
        </svg>
    );
};

const WeeklyBarGraph: React.FC<{
  dailyData: Array<{ day: string; hours: number }>;
}> = ({ dailyData }) => {
  const { t } = useLanguage();

  if (dailyData.length === 0) {
    return <div className="text-gray-500 dark:text-gray-400 text-center py-8">{t('progression.noData')}</div>;
  }

  const maxHours = Math.max(...dailyData.map(d => d.hours), 1);

  return (
    <div className="w-full">
      <div className="flex justify-between items-end h-48 space-x-2 md:space-x-4">
