}> = ({ quiz, currentQuestionIndex, feedback, onAnswerSubmit, onNextQuestion }) => {
    const { t } = useLanguage();
    const [selectedAnswer, setSelectedAnswer] = useState('');
    const currentQuestion = quiz[currentQuestionIndex];

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (selectedAnswer.trim()) {
            onAnswerSubmit(selectedAnswer);
        }
    };

    useEffect(() => {
        setSelectedAnswer(''); // Reset when question changes
    }, [currentQuestionIndex]);

    const isMCQ = !!currentQuestion.options && currentQuestion.options.length > 0;
    const inputClasses = "block w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm placeholder-gray-400 text-gray-900 dark:text-gray-200 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm";

    return (
        <div className="max-w-4xl mx-auto space-y-8 animate-fade-in">
            <div className="p-8 bg-white dark:bg-gray-800 rounded-xl shadow-lg border border-gray-100 dark:border-gray-700">
                <p className="text-sm font-semibold text-gray-500 dark:text-gray-400 mb-2 uppercase tracking-widest">{t('examprep.quiz.questionOf', { current: currentQuestionIndex + 1, total: quiz.length })}</p>
                <div className="prose-lg dark:prose-invert max-w-none mb-6">
                    <FormattedContent content={currentQuestion.question} />
                </div>

                <form onSubmit={handleSubmit}>
                    {isMCQ ? (
                        <div className="space-y-3">
                            {currentQuestion.options?.map((option, index) => (
                                <label key={index} className={`flex items-center p-4 border-2 rounded-xl cursor-pointer transition-all ${
                                    selectedAnswer === option ? 'border-primary bg-primary/5 ring-1 ring-primary/20' : 'border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700/50'
                                }`}>
                                    <input 
                                        type="radio"
                                        name="quiz-option"
                                        value={option}
                                        checked={selectedAnswer === option}
                                        onChange={(e) => setSelectedAnswer(e.target.value)}
                                        disabled={!!feedback}
                                        className="h-5 w-5 text-primary focus:ring-primary border-gray-300"
                                    />
                                    <span className="ml-3 prose-lg dark:prose-invert max-w-none font-medium"><FormattedContent content={option} /></span>
                                </label>
                            ))}
                        </div>
                    ) : (
                        <textarea 
                            value={selectedAnswer}
                            onChange={(e) => setSelectedAnswer(e.target.value)}
                            disabled={!!feedback}
                            placeholder={t('examprep.quiz.answerPlaceholder')}
                            rows={4}
                            className={inputClasses}
                        />
                    )}

                    {!feedback && (
                        <button type="submit" disabled={!selectedAnswer.trim()} className="mt-8 w-full py-4 bg-primary text-primary-text font-bold text-lg rounded-2xl shadow-xl shadow-primary/20 hover:bg-primary-dark disabled:bg-primary/50 transition-all transform hover:-translate-y-0.5">
                            <CheckIcon className="inline w-5 h-5 mr-2" /> Submit Answer
                        </button>
                    )}
                </form>

                {feedback && (
                    <div className={`mt-8 p-6 rounded-2xl border-l-8 ${feedback.isCorrect ? 'bg-green-50 dark:bg-green-900/10 border-green-500' : 'bg-red-50 dark:bg-red-900/10 border-red-500'}`}>
                        <div className="flex items-center gap-3 mb-2">
                             <div className={`w-8 h-8 rounded-full flex items-center justify-center ${feedback.isCorrect ? 'bg-green-500' : 'bg-red-500'} text-white shadow-lg`}>
                                {feedback.isCorrect ? <CheckIcon className="w-5 h-5" /> : <CloseIcon className="w-5 h-5" />}
                             </div>
                             <h4 className={`font-black text-xl ${feedback.isCorrect ? 'text-green-700 dark:text-green-300' : 'text-red-700 dark:text-red-300'}`}>
                                {feedback.isCorrect ? t('examprep.quiz.correct') : t('examprep.quiz.incorrect')}
                            </h4>
                        </div>
                        {!feedback.isCorrect && <div className="text-sm prose-lg dark:prose-invert max-w-none mt-2 font-bold opacity-80">Correct answer: <FormattedContent content={currentQuestion.correctAnswer} /></div>}
                        <div className="mt-4 text-gray-700 dark:text-gray-300 prose-lg dark:prose-invert max-w-none"><FormattedContent content={feedback.explanation} /></div>
                        <button onClick={onNextQuestion} className="mt-6 flex items-center justify-center gap-2 w-full sm:w-auto px-8 py-3 bg-gray-900 text-white font-bold rounded-xl hover:bg-black shadow-lg transition-all">
                            {currentQuestionIndex < quiz.length - 1 ? t('examprep.quiz.nextQuestion') : t('examprep.quiz.viewResults')} <ArrowRightIcon className="w-5 h-5" />
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

const QuizSummaryView: React.FC<{
    summary: QuizSummary;
    quiz: QuizQuestion[];
    userAnswers: string[];
    onStartNew: () => void;
    onRestart: () => void;
}> = ({ summary, quiz, userAnswers, onStartNew, onRestart }) => {
    const { t } = useLanguage();
    const [reviewMode, setReviewMode] = useState(false);

    if (reviewMode) {
        return (
            <div className="max-w-4xl mx-auto space-y-6 animate-fade-in">
                <button onClick={() => setReviewMode(false)} className="flex items-center gap-2 text-sm font-bold text-primary hover:underline uppercase tracking-widest">
                    <ArrowLeftIcon className="w-4 h-4"/> Back to Summary
                </button>
                {quiz.map((q, index) => {
                    const userAnswer = userAnswers[index];
                    const isCorrect = userAnswer === q.correctAnswer;
                    return (
                        <div key={index} className={`p-6 rounded-2xl border-l-8 shadow-sm ${isCorrect ? 'bg-green-50/50 dark:bg-green-900/10 border-green-500' : 'bg-red-50/50 dark:bg-red-900/10 border-red-500'}`}>
                            <p className="text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Question {index + 1}</p>
                            <div className="prose-lg dark:prose-invert max-w-none my-2"><FormattedContent content={q.question} /></div>
                            <div className="mt-4 space-y-1">
                                <p className="text-sm prose-lg dark:prose-invert max-w-none">Your answer: <span className="font-bold">{userAnswer || 'Not answered'}</span></p>
                                {!isCorrect && <p className="text-sm prose-lg dark:prose-invert max-w-none">Correct answer: <span className="font-bold text-green-600"><FormattedContent content={q.correctAnswer} /></span></p>}
                            </div>
                        </div>
                    );
                })}
                 <button onClick={() => setReviewMode(false)} className="flex items-center gap-2 text-sm font-bold text-primary hover:underline mt-8 uppercase tracking-widest">
                    <ArrowLeftIcon className="w-4 h-4"/> Back to Summary
                </button>
            </div>
        )
    }

    return (
        <div className="max-w-4xl mx-auto space-y-8 text-center animate-fade-in">
            <div className="p-10 bg-white dark:bg-gray-800 rounded-3xl shadow-2xl border border-gray-100 dark:border-gray-700">
                <h2 className="text-4xl font-black mb-2 text-gray-900 dark:text-white tracking-tight">{t('examprep.summary.title')}</h2>
                <div className="relative inline-block my-8">
                     <svg className="w-48 h-48 transform -rotate-90">
                        <circle cx="96" cy="96" r="88" stroke="currentColor" strokeWidth="12" fill="transparent" className="text-gray-100 dark:text-gray-700" />
                        <circle cx="96" cy="96" r="88" stroke="currentColor" strokeWidth="12" fill="transparent" className="text-primary" strokeDasharray={552.92} strokeDashoffset={552.92 * (1 - summary.score / 100)} strokeLinecap="round" />
                    </svg>
                    <div className="absolute inset-0 flex items-center justify-center">
                        <p className="text-5xl font-black text-gray-900 dark:text-white">{summary.score.toFixed(0)}%</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 text-left my-8">
                    <div className="p-6 bg-green-50 dark:bg-green-900/10 rounded-2xl border border-green-100 dark:border-green-800/30">
                        <h3 className="font-black text-lg text-green-700 dark:text-green-300 uppercase tracking-tight mb-3">{t('examprep.summary.strengths')}</h3>
                        {summary.strengths.length > 0 ? (
                            <ul className="space-y-2">
                                {summary.strengths.map((s, i) => <li key={i} className="flex items-center gap-2 text-sm font-medium text-green-800 dark:text-green-200"><CheckIcon className="w-4 h-4" /> {s}</li>)}
                            </ul>
                        ) : <p className="text-sm text-gray-500 mt-2 italic">{t('examprep.summary.strengths.placeholder')}</p>}
                    </div>
                    <div className="p-6 bg-red-50 dark:bg-red-900/10 rounded-2xl border border-red-100 dark:border-red-800/30">
                        <h3 className="font-black text-lg text-red-700 dark:text-red-300 uppercase tracking-tight mb-3">{t('examprep.summary.weaknesses')}</h3>
                        {summary.weaknesses.length > 0 ? (
                            <ul className="space-y-2">
                                {summary.weaknesses.map((w, i) => <li key={i} className="flex items-center gap-2 text-sm font-medium text-red-800 dark:text-red-200"><CloseIcon className="w-4 h-4" /> {w}</li>)}
                            </ul>
                        ) : 
                        <p className="text-sm text-gray-500 mt-2 italic">{t('examprep.summary.weaknesses.placeholder')}</p>}
                    </div>
                </div>

                <div className="p-6 bg-blue-50 dark:bg-blue-900/10 rounded-2xl border border-blue-100 dark:border-blue-800/30 text-left">
                    <h3 className="font-black text-lg text-blue-700 dark:text-blue-300 uppercase tracking-tight mb-2">{t('examprep.summary.recommendations')}</h3>
                    {summary.recommendations.length > 0 ? (
                        <p className="text-blue-800 dark:text-blue-200 leading-relaxed">{t('examprep.summary.recommendations.body', { topics: summary.recommendations.join(', ') })}</p>
                    ) : <p className="text-blue-800 dark:text-blue-200">Consistency is key! Keep practicing to maintain this level of performance.</p>}
                </div>

                <div className="flex flex-col sm:flex-row gap-4 mt-10">
                    <button onClick={() => setReviewMode(true)} className="flex-1 py-4 px-6 rounded-2xl text-md font-bold transition-all bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 text-gray-800 dark:text-white uppercase tracking-wider">Review Answers</button>
                    <button onClick={onRestart} className="flex-1 py-4 px-6 rounded-2xl text-md font-bold transition-all bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 text-gray-800 dark:text-white uppercase tracking-wider">Restart Quiz</button>
                    <button onClick={onStartNew} className="flex-1 py-4 px-6 rounded-2xl text-md font-bold transition-all bg-primary text-primary-text hover:bg-primary-dark shadow-lg shadow-primary/30 uppercase tracking-wider">
                        {t('examprep.summary.newQuiz')}
                    </button>
                </div>
            </div>
        </div>
    );
};

const getLangCodeForSpeech = (lang: Language) => {
    const map: Record<Language, string> = {
        en: 'en-US',
        es: 'es-ES',
        fr: 'fr-FR',
        de: 'de-DE',
        ja: 'ja-JP',
        zh: 'zh-CN',
    };
    return map[lang] || 'en-US';
}


export const ExamPrep: React.FC<ExamPrepProps> = ({
    addToast,
    setView,
    generationState,
    setGenerationState,
    quizState,
    setQuizState,
    notes,
    setNotes,
    examPrepState,
    setExamPrepState,
    onGenerateQuizAttempt,
    onSolveProblemAttempt,
}) => {
    const { t, language } = useLanguage();
    const { mode, numQuestions, quizType, uploadedFiles, focusArea, questionImage, questionText, solution, outputFormat, programmingLanguage, graphInterval, graphYInterval, graphConfig } = examPrepState;
    const recognitionRef = useRef<any>(null);
    const [isListening, setIsListening] = useState(false);
    const [isCameraModalOpen, setIsCameraModalOpen] = useState(false);
    const graphCanvasRef = useRef<HTMLCanvasElement | null>(null);

    const updateState = <K extends keyof ExamPrepState>(key: K, value: ExamPrepState[K]) => {
        setExamPrepState(prev => ({...prev, [key]: value}));
    }

    useEffect(() => {
        if (mode === 'solve') {
            const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
            if (SpeechRecognition) {
                recognitionRef.current = new SpeechRecognition();
                const recognition = recognitionRef.current;
                recognition.continuous = true;
                recognition.interimResults = true;
                recognition.lang = getLangCodeForSpeech(language);

                recognition.onresult = (event: any) => {
                    let finalTranscript = '';
                    for (let i = event.resultIndex; i < event.results.length; ++i) {
                        if (event.results[i].isFinal) {
                            finalTranscript += event.results[i][0].transcript;
                        }
                    }
                    if (finalTranscript) {
                        setExamPrepState(prev => ({...prev, questionText: prev.questionText + finalTranscript.trim() + ' '}));
                    }
                };

                recognition.onend = () => {
                    setIsListening(false);
                };

                recognition.onerror = (event: any) => {
                    addToast(t('toasts.examprep.speechError', { error: event.error }), 'error');
                    setIsListening(false);
                };
            } else {
                recognitionRef.current = null;
            }

            return () => {
                if (recognitionRef.current) {
                    recognitionRef.current.stop();
                }
            };
        }
    }, [mode, addToast, t, language, setExamPrepState]);

    const handleMicClick = () => {
        if (!recognitionRef.current) {
            addToast(t('toasts.examprep.speechUnsupported'), 'error');
            return;
        }

        if (isListening) {
            recognitionRef.current.stop();
            setIsListening(false);
        } else {
            if (questionText.trim() && !questionText.endsWith(' ')) {
                setExamPrepState(prev => ({...prev, questionText: prev.questionText + ' '}));
            }
            recognitionRef.current.start();
            setIsListening(true);
        }
    };

    const onDrop = useCallback(async (acceptedFiles: File[]) => {
        if (mode === 'quiz') {
            const validFiles = acceptedFiles.filter(file => {
                if (file.size > 25 * 1024 * 1024) { 
                    addToast(t('toasts.fileSizeTooLarge', {fileName: file.name, size: 25}), 'error');
                    return false;
                }
                return true;
            });
            if (validFiles.length > 0) {
                updateState('uploadedFiles', [...uploadedFiles, ...validFiles]);
                addToast(t('toasts.filesAdded', {count: validFiles.length}), 'success');
            }
        } else { 
            const file = acceptedFiles[0];
            if (file && file.type.startsWith('image/')) {
                if (file.size > 25 * 1024 * 1024) { 
                    addToast(t('toasts.fileSizeTooLarge', {fileName: file.name, size: 25}), 'error');
                    return;
                }
                try {
                    const { dataUrl } = await processAndResizeImage(file);
                    updateState('questionImage', dataUrl);
                } catch(e: any) {
                    addToast(e.message || 'Failed to process image.', 'error');
                }
            } else if (file) {
                addToast(t('toasts.invalidImageFile'), 'error');
            }
        }
    }, [mode, uploadedFiles, addToast, t, updateState]);

    const { getRootProps, getInputProps, isDragActive } = useDropzone({ onDrop, multiple: true });

    const removeFile = (index: number) => {
        const newFiles = [...uploadedFiles];
        newFiles.splice(index, 1);
        updateState('uploadedFiles', newFiles);
    };

    const handleGenerateQuiz = () => {
        onGenerateQuizAttempt(async () => {
            if (uploadedFiles.length === 0) {
                addToast(t('toasts.examprep.noFiles'), 'warning');
                return;
            }

            setGenerationState({ isLoading: true, message: t('examprep.verifying'), error: null, source: 'quiz' });

            try {
                let combinedContent = '';
                for (const file of uploadedFiles) {
                    const base64String = await new Promise<string>((resolve, reject) => {
                        const reader = new FileReader();
                        reader.onload = () => resolve((reader.result as string).split(',')[1]);
                        reader.onerror = error => reject(error);
                        reader.readAsDataURL(file);
                    });
                    const filePart: ImagePart = { inlineData: { data: base64String, mimeType: file.type } };

                    const isMaterial = await isStudyMaterial(filePart, { fast: true });
                    if (isMaterial) {
                        const text = await extractTextFromDocument(filePart, { fast: true });
                        combinedContent += text + '\n\n';
                    } else {
                        addToast(t('examprep.error.notStudyMaterial', { fileName: file.name }), 'warning');
                    }
                }

                const MAX_CONTEXT = 30000;
                if(combinedContent.length > MAX_CONTEXT) {
                    combinedContent = combinedContent.substring(0, MAX_CONTEXT);
                    addToast(t('toasts.quizContentTruncated'), 'warning');
                }

                if (!combinedContent.trim()) {
                    throw new Error(t('toasts.examprep.textExtractFailed'));
                }

                setGenerationState(prev => ({ ...prev, message: t('examprep.creatingQuiz') }));
                const questions = await generateQuiz(combinedContent, numQuestions, quizType, focusArea);

                if (questions && questions.length > 0) {
                     setQuizState({ quiz: questions, currentQuestionIndex: 0, userAnswers: [], feedback: null, summary: null });
                     setGenerationState({ isLoading: false, message: '', error: null, source: null });
                } else {
                     throw new Error(t('examprep.error.noQuestions'));
                }
            } catch (error: any) {
                addToast(error.message || t('examprep.error.generic'), 'error');
                setGenerationState({ isLoading: false, message: '', error: null, source: null });
            }
        });
    };

    const handleAnswerSubmit = (answer: string) => {
        const currentQuestion = quizState.quiz[quizState.currentQuestionIndex];
        const isCorrect = currentQuestion.options 
            ? answer === currentQuestion.correctAnswer
            : currentQuestion.correctAnswer.toLowerCase().trim() === answer.toLowerCase().trim();

        setQuizState(prev => ({
            ...prev,
            userAnswers: [...prev.userAnswers, answer],
            feedback: { isCorrect, explanation: currentQuestion.explanation }
        }));
    };

    const handleNextQuestion = () => {
        if (quizState.currentQuestionIndex < quizState.quiz.length - 1) {
            setQuizState(prev => ({ ...prev, currentQuestionIndex: prev.currentQuestionIndex + 1, feedback: null }));
        } else {
            const correctAnswers = quizState.userAnswers.filter((answer, index) => {
                const q = quizState.quiz[index];
                return q.options 
                    ? answer === q.correctAnswer 
                    : answer.toLowerCase().trim() === q.correctAnswer.toLowerCase().trim();
            }).length;

            const score = (correctAnswers / quizState.quiz.length) * 100;

            const topics = quizState.quiz.map(q => q.topic);
            const topicPerformance = topics.reduce((acc, topic, i) => {
                if(!acc[topic]) acc[topic] = { correct: 0, total: 0 };
                acc[topic].total++;
                const q = quizState.quiz[i];
                const isCorrect = q.options 
                    ? quizState.userAnswers[i] === q.correctAnswer
                    : quizState.userAnswers[i].toLowerCase().trim() === q.correctAnswer.toLowerCase().trim();
                if (isCorrect) {
                    acc[topic].correct++;
                }
                return acc;
            }, {} as Record<string, {correct: number, total: number}>);

            const strengths = Object.keys(topicPerformance).filter(t => topicPerformance[t].correct / topicPerformance[t].total > 0.7);
            const weaknesses = Object.keys(topicPerformance).filter(t => topicPerformance[t].correct / topicPerformance[t].total <= 0.7);

            const summary: QuizSummary = { score, strengths, weaknesses, recommendations: weaknesses };
            setQuizState(prev => ({ ...prev, summary, feedback: null }));
        }
    };

    const resetQuiz = () => {
        setQuizState({ quiz: [], currentQuestionIndex: 0, userAnswers: [], feedback: null, summary: null });
    };

    const handleSolveProblem = () => {
        onSolveProblemAttempt(async () => {
            if (!questionText.trim() && !questionImage) {
                addToast(t('toasts.examprep.noQuestion'), 'warning');
                return;
            }

            setGenerationState({ isLoading: true, message: t('examprep.solver.generatingSolution'), error: null, source: 'solve' });

            try {
                let imagePart: ImagePart | null = null;
                if (questionImage) {
                    const base64String = questionImage.split(',')[1];
                    const mimeType = questionImage.match(/data:(image\/\w+);base64,/)?.[1] || 'image/jpeg';
                    imagePart = { inlineData: { data: base64String, mimeType } };

                    if (!examPrepState.isVerifying) {
                        const isProblem = await isImageAProblem(imagePart);
                        if (!isProblem) {
                            addToast(t('toasts.examprep.invalidImage'), 'warning');
                            setGenerationState({ isLoading: false, message: '', error: null, source: null });
                            return;
                        }
                    }
                }

                const result = await solveProblem(
                    questionText,
                    imagePart,
                    outputFormat,
                    programmingLanguage,
                    graphInterval,
                    graphYInterval
                );

                if (outputFormat === 'graph') {
                    try {
                        const graphData = typeof result === 'string' && result.includes('{') ? JSON.parse(result) : result;
                        updateState('solution', graphData.explanation);

                        const plotter = new AdvancedGraphPlotter();

                        let functions: string[] = [];
                        if (typeof graphData.graphFunction === 'string') {
                            const rawFunc = graphData.graphFunction.trim();
                            if (rawFunc.startsWith('[') && rawFunc.endsWith(']')) {
                                try {
                                    const parsed = JSON.parse(rawFunc);
                                    if (Array.isArray(parsed)) {
                                        functions = parsed.filter(item => typeof item === 'string');
                                    } else {
                                         functions = [String(parsed)];
                                    }
                                } catch (e) {
                                    functions = rawFunc.replace(/[\[\]"']/g, '').split(',').map(f => f.trim()).filter(f => f);
                                }
                            } else {
                                functions = rawFunc.split(',').map(f => f.trim()).filter(f => f);
                            }
                        } else if (Array.isArray(graphData.graphFunction)) {
                            functions = graphData.graphFunction.filter(item => typeof item === 'string');
                        }

                        if (functions.length === 0) {
                            throw new Error("Could not parse function expression from AI response.");
                        }

                        const intervalConfig = plotter.parseInterval(graphInterval);
                        const smartInterval = plotter.determineSmartInterval(functions[0]);

                        const xMin = intervalConfig?.xMin ?? smartInterval.xMin;
                        const xMax = intervalConfig?.xMax ?? smartInterval.xMax;
                        const samples = intervalConfig?.samples ?? 200;

                        const datasets = functions.map((func: string, index: number) => {
                            const points = plotter.generatePoints({
                                expr: func,
                                xMin,
                                xMax,
                                samples,
                                angleMode: intervalConfig?.angleMode || 'radians'
                            });

                            const colors = ['#3b82f6', '#ef4444', '#10b981', '#f97316', '#ec4899'];

                            return {
                                label: func.replace(/Math\./g, ''),
                                data: points,
                                borderColor: colors[index % colors.length],
                                backgroundColor: colors[index % colors.length],
                                fill: false,
                                pointRadius: 0,
                                tension: 0.3
                            };
                        });

                        updateState('graphConfig', {
                            type: 'line',
                            data: { datasets },
                            options: {
                                plugins: {
                                    title: {
                                        display: !!graphData.suggestedTitle,
                                        text: graphData.suggestedTitle
                                    }
                                }
                            }
                        });

                    } catch (e) {
                        console.error("Failed to parse or plot graph data", e);
                        addToast('Failed to render graph from AI response.', 'error');
                        updateState('solution', typeof result === 'string' ? result : JSON.stringify(result, null, 2));
                        updateState('graphConfig', null);
                    }
                } else {
                    updateState('solution', result);
                    updateState('graphConfig', null);
                }
                setGenerationState({ isLoading: false, message: '', error: null, source: null });
            } catch (error: any) {
                addToast(error.message || t('toasts.error.solveProblem'), 'error');
                setGenerationState({ isLoading: false, message: '', error: null, source: null });
            }
        });
    };

    if (quizState.summary) {
        return <QuizSummaryView summary={quizState.summary} quiz={quizState.quiz} userAnswers={quizState.userAnswers} onStartNew={resetQuiz} onRestart={() => setQuizState(prev => ({ ...prev, summary: null, currentQuestionIndex: 0, userAnswers: [], feedback: null }))} />;
    }

    if (quizState.quiz.length > 0) {
        return <QuizRunner quiz={quizState.quiz} currentQuestionIndex={quizState.currentQuestionIndex} feedback={quizState.feedback} onAnswerSubmit={handleAnswerSubmit} onNextQuestion={handleNextQuestion} />;
    }

    return (
        <div className="max-w-4xl mx-auto space-y-8 animate-fade-in">
            <div>
                <h2 className="text-4xl font-black text-gray-900 dark:text-white tracking-tight">{t('examprep.main.title')}</h2>
            </div>

            <div className="flex bg-gray-200 dark:bg-gray-700/50 backdrop-blur-sm rounded-2xl p-1.5 shadow-inner border border-gray-100 dark:border-gray-700">
                <button
                    onClick={() => updateState('mode', 'quiz')}
                    className={`flex-1 py-3 rounded-xl font-black text-sm uppercase tracking-widest transition-all ${
                        mode === 'quiz' 
                        ? 'bg-white dark:bg-gray-800 shadow-xl text-primary' 
                        : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
                    }`}
                >
                    {t('examprep.tab.quiz')}
                </button>
                <button
                    onClick={() => updateState('mode', 'solve')}
                    className={`flex-1 py-3 rounded-xl font-black text-sm uppercase tracking-widest transition-all ${
                        mode === 'solve' 
                        ? 'bg-white dark:bg-gray-800 shadow-xl text-primary' 
                        : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
                    }`}
                >
                    {t('examprep.tab.solver')}
                </button>
            </div>

            {mode === 'quiz' && (
                <div className="relative bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-2xl p-8 md:p-12 space-y-10 border border-gray-100 dark:border-gray-700">
                    <LoadingOverlay isLoading={generationState.isLoading && generationState.source === 'quiz'} message={generationState.message} />
                    <div className="text-center space-y-2">
                        <h3 className="text-3xl font-black text-gray-900 dark:text-white">{t('examprep.quiz.title')}</h3>
                        <p className="text-gray-500 max-w-md mx-auto">{t('examprep.quiz.intro')}</p>
                    </div>

                    <div className="space-y-4">
                        <h4 className="font-black text-xs uppercase tracking-[0.2em] text-primary">{t('examprep.quiz.step1')}</h4>
