import { 
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  signOut,
  sendPasswordResetEmail,
  updateProfile,
  onAuthStateChanged as firebaseOnAuthStateChanged
} from 'firebase/auth';
import { 
  doc, 
  getDoc, 
  setDoc, 
  collection, 
  query, 
  where, 
  getDocs, 
  limit
} from 'firebase/firestore';
import { auth, db } from './firebase';
import type { UserDetails } from '../types';
import { EducationalLevel } from '../types';
import { initializeUsage } from '../lib/usageManager';

const SESSION_TOKEN_KEY = 'sessionToken';
const USER_KEY_PREFIX = 'eb_u_data_';

/**
 * Aggressively sanitizes data for Firestore.
 * Removes undefined, File, and Blob objects which cause "invalid nested entity" errors.
 */
const sanitizeForFirestore = (obj: any): any => {
    try {
        return JSON.parse(JSON.stringify(obj, (key, value) => {
            if (value === undefined) return null;
            // Strip non-serializable browser objects
            if (typeof window !== 'undefined') {
                if (value instanceof File || value instanceof Blob || value instanceof FileList) {
                    return null;
                }
            }
            return value;
        }));
    } catch (e) {
        console.error("Sanitization failed", e);
        return {};
    }
};

/**
 * Utility to prune heavy binary data from state if local storage quota is hit
 */
const pruneState = (data: any): any => {
    const pruned = JSON.parse(JSON.stringify(data));

    // Remove heavy image previews/base64 from dashboard inputs
    if (pruned.dashboardInputs) {
        pruned.dashboardInputs.imagePreview = null;
        pruned.dashboardInputs.imageFile = null;
    }

    // Remove heavy base64 from learning hub files
    if (pruned.learningHubState?.file) {
        pruned.learningHubState.file.base64 = "";
    }

    return pruned;
};

export const storageService = {
    saveItem: (key: string, value: any) => {
        try {
            localStorage.setItem(key, JSON.stringify(value));
        } catch (error: any) {
            if (error.name === 'QuotaExceededError' || error.name === 'NS_ERROR_DOM_QUOTA_REACHED') {
                console.warn(`Quota exceeded for "${key}". Attempting to prune heavy data...`);
                try {
                    const pruned = pruneState(value);
                    localStorage.setItem(key, JSON.stringify(pruned));
                    console.log(`Successfully saved pruned version of "${key}"`);
                } catch (innerError) {
                    console.error(`Failed to save even pruned data for "${key}"`, innerError);
                }
            } else {
                console.error(`Failed to save item "${key}"`, error);
            }
        }
    },
    loadItem: <T,>(key: string): T | null => {
        try {
            const item = localStorage.getItem(key);
            return item ? JSON.parse(item) : null;
        } catch (error) {
            return null;
        }
    },
    removeItem: (key: string) => localStorage.removeItem(key),

    saveUserData: async (userId: string, data: any): Promise<void> => {
        if (!userId) return;
        try {
            const safeData = sanitizeForFirestore(data);
            const userRef = doc(db, 'users', userId);
            await setDoc(userRef, safeData, { merge: true });
        } catch (error: any) {
            console.error('Firestore save failed:', error.message);
        }
    },
    syncUserToCloud: async (userId: string, data: any): Promise<void> => {
        return storageService.saveUserData(userId, data);
    },
    loadUserData: async (userId: string): Promise<any | null> => {
        if (!userId) return null;
        try {
            const userRef = doc(db, 'users', userId);
            const docSnap = await getDoc(userRef);
            return docSnap.exists() ? docSnap.data() : null;
        } catch (error: any) {
            return null;
        }
    },
    exportAllData: () => {
        const data: { [key: string]: any } = {};
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key) {
                const item = localStorage.getItem(key);
                try { data[key] = JSON.parse(item!); } catch { data[key] = item; }
            }
        }
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `edublay_backup_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    },
    importAllData: (file: File): Promise<void> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = (event) => {
                try {
                    const data = JSON.parse(event.target?.result as string);
                    Object.keys(data).forEach(key => storageService.saveItem(key, data[key]));
                    resolve();
                } catch { reject(new Error("Failed to parse import file.")); }
            };
            reader.readAsText(file);
        });
    },
    clearAllData: () => localStorage.clear()
};

const createToken = (user: UserDetails): string => btoa(encodeURIComponent(JSON.stringify(user)));
const decodeToken = (token: string): UserDetails | null => {
    try { return JSON.parse(decodeURIComponent(atob(token))); } catch { return null; }
};

export const signUp = async (name: string, email: string, password_param: string, recoveryQuestion: string, recoveryAnswer: string): Promise<UserDetails> => {
    const userCredential = await createUserWithEmailAndPassword(auth, email, password_param);
    const user = userCredential.user;
    await updateProfile(user, { displayName: name });
    const newUser: UserDetails = {
        id: user.uid,
        name,
        email,
        educationalLevel: EducationalLevel.UNDERGRADUATE,
        usage: initializeUsage(),
        recoveryQuestion,
        recoveryAnswer
    };
    await storageService.saveUserData(user.uid, { userDetails: newUser });
    storageService.saveItem(SESSION_TOKEN_KEY, createToken(newUser));
    return newUser;
};

export const login = async (email: string, password_param: string): Promise<UserDetails> => {
    const userCredential = await signInWithEmailAndPassword(auth, email, password_param);
    const user = userCredential.user;
    const cloudData = await storageService.loadUserData(user.uid);
    let userDetails = cloudData?.userDetails || {
        id: user.uid,
        name: user.displayName || email.split('@')[0],
        email: email,
        educationalLevel: EducationalLevel.UNDERGRADUATE,
        usage: initializeUsage()
    };

    if (cloudData) {
        storageService.saveItem(`${USER_KEY_PREFIX}${email}`, cloudData);
    }

    storageService.saveItem(SESSION_TOKEN_KEY, createToken(userDetails));
    return userDetails;
};

export const findUserByEmail = async (email: string): Promise<boolean> => {
    const usersRef = collection(db, 'users');
    const q = query(usersRef, where('userDetails.email', '==', email), limit(1));
    const querySnapshot = await getDocs(q);
    return !querySnapshot.empty;
};

export const getRecoveryQuestionByEmail = async (email: string): Promise<string | null> => {
    const usersRef = collection(db, 'users');
    const q = query(usersRef, where('userDetails.email', '==', email), limit(1));
    const querySnapshot = await getDocs(q);
    if (querySnapshot.empty) return null;
    const userData = querySnapshot.docs[0].data();
    return userData.userDetails?.recoveryQuestion || null;
};

export const verifyRecoveryAnswer = async (email: string, answer: string): Promise<boolean> => {
    const usersRef = collection(db, 'users');
    const q = query(usersRef, where('userDetails.email', '==', email), limit(1));
    const querySnapshot = await getDocs(q);
    if (querySnapshot.empty) return false;
    const userData = querySnapshot.docs[0].data();
    const storedAnswer = userData.userDetails?.recoveryAnswer;
    return storedAnswer?.toLowerCase().trim() === answer.toLowerCase().trim();
};

export const sendResetEmail = async (email: string): Promise<void> => {
    await sendPasswordResetEmail(auth, email);
};

export const logout = async () => {
    await signOut(auth);
    storageService.removeItem(SESSION_TOKEN_KEY);
};

export const getCurrentUser = (): UserDetails | null => {
    const token = storageService.loadItem<string>(SESSION_TOKEN_KEY);
    return token ? decodeToken(token) : null;
};

import React, { useState } from 'react';
import type { UserDetails } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { signUp, login, getRecoveryQuestionByEmail, verifyRecoveryAnswer, sendResetEmail } from '../services/authService';
import { EyeIcon } from './icons/EyeIcon';
import { EyeOffIcon } from './icons/EyeOffIcon';
import { MailIcon } from './icons/MailIcon';
import { CheckCircleIcon } from './icons/CheckCircleIcon';

interface SignUpProps {
    onLogin: (user: UserDetails) => void;
}

const LoadingSpinner: React.FC = () => (
    <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
);

const recoveryQuestions = [
    "recovery.q1",
    "recovery.q2",
    "recovery.q3",
    "recovery.q4",
    "recovery.q5",
];

const SignUp: React.FC<SignUpProps> = ({ onLogin }) => {
  const { t } = useLanguage();
  const [viewMode, setViewMode] = useState<'signIn' | 'signUp' | 'forgotPassword'>('signIn');
  const [recoveryStep, setRecoveryStep] = useState<'email' | 'question' | 'verified' | 'sent'>('email');

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
    recoveryQuestion: recoveryQuestions[0],
    recoveryAnswer: '',
  });

  const [recoveryData, setRecoveryData] = useState({
    question: '',
    answer: '',
  });

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [errors, setErrors] = useState<any>({});
  const [message, setMessage] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors((prev: any) => ({ ...prev, [name]: undefined }));
    }
    setErrors((prev: any) => ({...prev, general: undefined}));
    setMessage('');
  };

  const handleRecoveryInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const { name, value } = e.target;
      setRecoveryData(prev => ({ ...prev, [name]: value }));
      setErrors((prev: any) => ({ ...prev, recovery: undefined }));
  };

  const validate = () => {
    const newErrors: any = {};
    if (viewMode === 'signUp') {
        if (!formData.name.trim()) newErrors.name = t('validation.nameRequired');
        if (!formData.recoveryQuestion) newErrors.recoveryQuestion = t('validation.recoveryQRequired');
        if (!formData.recoveryAnswer.trim()) newErrors.recoveryAnswer = t('validation.recoveryARequired');
    }
    if (viewMode === 'signUp' || viewMode === 'signIn' || (viewMode === 'forgotPassword' && recoveryStep === 'email')) {
        if (!formData.email.trim()) newErrors.email = t('validation.emailRequired');
        else if (!/\S+@\S+\.\S+/.test(formData.email)) newErrors.email = t('validation.emailInvalid');
    }

    if (viewMode === 'signUp' || viewMode === 'signIn') {
        if (!formData.password) newErrors.password = t('validation.passwordRequired');
        else if (viewMode === 'signUp' && formData.password.length < 6) newErrors.password = t('validation.passwordMinLength');
    }

    if (viewMode === 'signUp' && formData.password !== formData.confirmPassword) {
        newErrors.confirmPassword = t('validation.passwordMismatch');
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleFetchQuestion = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.email.trim()) {
        setErrors({ email: t('validation.emailRequired') });
        return;
    }
    setIsSubmitting(true);
    try {
        const question = await getRecoveryQuestionByEmail(formData.email);
        if (question) {
            setRecoveryData(prev => ({ ...prev, question }));
            setRecoveryStep('question');
        } else {
            setErrors({ general: t('validation.userNotFound') });
        }
    } catch (e) {
        setErrors({ general: t('recovery.error') });
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleVerifyAnswer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!recoveryData.answer.trim()) return;
    setIsSubmitting(true);
    try {
        const isValid = await verifyRecoveryAnswer(formData.email, recoveryData.answer);
        if (isValid) {
            setRecoveryStep('verified');
        } else {
            setErrors({ recovery: t('validation.recoveryAIncorrect') });
        }
    } catch (e) {
        setErrors({ recovery: t('recovery.error') });
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleSendLink = async () => {
    setIsSubmitting(true);
    try {
        await sendResetEmail(formData.email);
        setRecoveryStep('sent');
        setMessage("Password reset link has been sent to your email. Please check your inbox and spam folder.");
    } catch (e) {
        setErrors({ general: t('recovery.error') });
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    setIsSubmitting(true);
    setErrors({});
    setMessage('');

    try {
        if (viewMode === 'signUp') {
            const user = await signUp(formData.name, formData.email, formData.password, formData.recoveryQuestion, formData.recoveryAnswer);
            setMessage(t('auth.signupSuccess'));
            setTimeout(() => onLogin(user), 1000);
        } else if (viewMode === 'signIn') {
            const user = await login(formData.email, formData.password);
            setMessage(t('auth.loginSuccess'));
            setTimeout(() => onLogin(user), 500);
        }
    } catch (error: any) {
        let displayMsg = error.message || 'An unexpected error occurred.';
        if (displayMsg.toLowerCase().includes('firebase')) {
            displayMsg = t('validation.loginFailed');
        }
        setErrors({ general: displayMsg });
    } finally {
        setIsSubmitting(false);
    }
  };

  const renderForgotPasswordContent = () => {
      const inputClasses = "w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary bg-white dark:bg-black transition-all";

      if (recoveryStep === 'email') {
          return (
            <div className="space-y-6 animate-fade-in">
                <div className="text-center">
                    <h2 className="text-3xl font-black text-gray-900 dark:text-white">{t('recovery.title')}</h2>
                    <p className="mt-2 text-gray-500 dark:text-gray-400">{t('recovery.step1.prompt')}</p>
                </div>
                <form onSubmit={handleFetchQuestion} className="space-y-4">
                    <div>
                        <input type="email" name="email" value={formData.email} onChange={handleInputChange} className={inputClasses} placeholder="your-email@example.com" required />
                        {errors.email && <p className="text-red-500 text-xs mt-1 ml-1">{errors.email}</p>}
                    </div>
                    <button type="submit" disabled={isSubmitting} className="w-full py-4 bg-primary text-primary-text font-bold rounded-xl shadow-lg hover:bg-primary-dark transition-all flex justify-center items-center">
                        {isSubmitting ? <LoadingSpinner /> : "Find Account"}
                    </button>
                    {errors.general && <p className="text-red-500 text-sm mt-2 text-center font-bold">{errors.general}</p>}
                </form>
            </div>
          );
      }

      if (recoveryStep === 'question') {
          return (
              <div className="space-y-6 animate-fade-in">
                <div className="text-center">
                    <h2 className="text-3xl font-black text-gray-900 dark:text-white">Verify Identity</h2>
                    <p className="mt-2 text-gray-500 dark:text-gray-400">Please answer your security question to reset your password.</p>
                </div>
                <div className="p-5 bg-primary/5 border border-primary/20 rounded-2xl">
                    <p className="text-xs font-black uppercase tracking-widest text-primary mb-1">Your Security Question</p>
                    <p className="text-lg font-bold text-gray-800 dark:text-gray-200">{t(recoveryData.question as any)}</p>
                </div>
                <form onSubmit={handleVerifyAnswer} className="space-y-4">
                    <div>
                        <input type="text" name="answer" value={recoveryData.answer} onChange={handleRecoveryInputChange} className={inputClasses} placeholder="Type your answer..." required autoFocus />
                        {errors.recovery && <p className="text-red-500 text-xs mt-1 ml-1 font-bold">{errors.recovery}</p>}
                    </div>
                    <button type="submit" disabled={isSubmitting} className="w-full py-4 bg-primary text-primary-text font-bold rounded-xl shadow-lg hover:bg-primary-dark transition-all flex justify-center items-center">
                        {isSubmitting ? <LoadingSpinner /> : "Verify Answer"}
                    </button>
                    <div className="pt-4 border-t dark:border-gray-700 text-center">
                        <p className="text-sm text-gray-500 mb-3">Can't remember the answer?</p>
                        <button type="button" onClick={handleSendLink} disabled={isSubmitting} className="flex items-center justify-center gap-2 w-full py-3 bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-200 rounded-xl hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors">
                            <MailIcon className="w-5 h-5" /> Send reset link anyway
                        </button>
                    </div>
                </form>
              </div>
          );
      }

      if (recoveryStep === 'verified') {
          return (
              <div className="space-y-6 animate-fade-in text-center">
                  <div className="w-20 h-20 bg-green-500 text-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-xl">
                      <CheckCircleIcon className="w-12 h-12" />
                  </div>
                  <h2 className="text-3xl font-black text-gray-900 dark:text-white">Identity Verified</h2>
                  <p className="text-gray-500 dark:text-gray-400">Your answer is correct. Click below to receive a secure password reset link at <strong>{formData.email}</strong>.</p>
                  <button onClick={handleSendLink} disabled={isSubmitting} className="w-full py-4 bg-primary text-primary-text font-black text-xl rounded-xl shadow-xl shadow-primary/30 hover:bg-primary-dark hover:-translate-y-1 transition-all flex justify-center items-center gap-3 mt-8">
                      {isSubmitting ? <LoadingSpinner /> : <><MailIcon className="w-6 h-6" /> Send Reset Password Link</>}
                  </button>
              </div>
          );
      }

      if (recoveryStep === 'sent') {
          return (
              <div className="space-y-6 animate-fade-in text-center">
                   <div className="w-20 h-20 bg-blue-500 text-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-xl">
                      <MailIcon className="w-12 h-12" />
                  </div>
                  <h2 className="text-3xl font-black text-gray-900 dark:text-white">Email Sent!</h2>
                  <div className="p-6 bg-white dark:bg-gray-800 rounded-2xl shadow-inner border border-gray-100 dark:border-gray-700">
                    <p className="text-gray-600 dark:text-gray-300 leading-relaxed font-medium">{message}</p>
                  </div>
                  <p className="text-sm text-gray-400 mt-4">Still nothing? Check your spam folder or wait a few minutes.</p>
                  <button onClick={() => { setViewMode('signIn'); setRecoveryStep('email'); }} className="mt-8 text-primary font-black uppercase tracking-widest hover:underline">
                      Back to Sign In
                  </button>
              </div>
          );
      }
  };

  const renderContent = () => {
    const inputClasses = (field: string) => `w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary bg-white dark:bg-black transition-all ${errors[field] ? 'border-red-500 ring-1 ring-red-500' : ''}`;

    if (viewMode === 'forgotPassword') {
        return renderForgotPasswordContent();
    }

    return (
        <div className="space-y-8">
             <div className="text-center">
                 <h2 className="text-4xl font-black text-gray-900 dark:text-white tracking-tight">{viewMode === 'signUp' ? t('auth.createAccount') : t('auth.signInToEduBlay')}</h2>
                 <p className="mt-2 text-gray-500 dark:text-gray-400 font-medium">{viewMode === 'signUp' ? 'Start your academic journey today' : 'Continue where you left off'}</p>
             </div>
             {message && <div className="p-4 bg-green-50 text-green-700 rounded-xl border border-green-200 text-center font-bold animate-fade-in">{message}</div>}
             <form onSubmit={handleSubmit} className="space-y-4">
                {viewMode === 'signUp' && (
                    <div><input type="text" name="name" value={formData.name} onChange={handleInputChange} className={inputClasses('name')} placeholder={t('auth.fullName')} required />{errors.name && <p className="text-red-500 text-xs mt-1 ml-1">{errors.name}</p>}</div>
                )}
                <div><input type="email" name="email" value={formData.email} onChange={handleInputChange} className={inputClasses('email')} placeholder={t('auth.email')} required />{errors.email && <p className="text-red-500 text-xs mt-1 ml-1">{errors.email}</p>}</div>
                <div className="relative"><input type={showPassword ? 'text' : 'password'} name="password" value={formData.password} onChange={handleInputChange} className={inputClasses('password')} placeholder={t('auth.password')} required /><button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-400 hover:text-primary transition-colors">{showPassword ? <EyeOffIcon className="h-5 w-5"/> : <EyeIcon className="h-5 w-5"/>}</button></div>{errors.password && <p className="text-red-500 text-xs mt-1 ml-1">{errors.password}</p>}
                 {viewMode === 'signUp' && (
                    <>
                    <div className="relative">
                        <input 
                            type={showConfirmPassword ? 'text' : 'password'} 
                            name="confirmPassword" 
                            value={formData.confirmPassword} 
                            onChange={handleInputChange} 
                            className={inputClasses('confirmPassword')} 
                            placeholder={t('auth.confirmPassword')} 
                            required
                        />
                        <button 
                            type="button" 
                            onClick={() => setShowConfirmPassword(!showConfirmPassword)} 
                            className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-400 hover:text-primary transition-colors"
                        >
                            {showConfirmPassword ? <EyeOffIcon className="h-5 w-5"/> : <EyeIcon className="h-5 w-5"/>}
                        </button>
                    </div>
                    {errors.confirmPassword && <p className="text-red-500 text-xs mt-1 ml-1">{errors.confirmPassword}</p>}
                    <div className="pt-4 border-t dark:border-gray-700">
                        <label htmlFor="recoveryQuestion" className="block text-xs font-black uppercase tracking-widest text-gray-400 mb-2">{t('recovery.question')}</label>
                        <select name="recoveryQuestion" value={formData.recoveryQuestion} onChange={handleInputChange} className={inputClasses('recoveryQuestion')}>{recoveryQuestions.map(q => <option key={q} value={q}>{t(q as any)}</option>)}</select>
                        <p className="text-[10px] text-gray-400 mt-2">This question will help you recover your password if you forget it.</p>
                    </div>
                    <div><input type="text" name="recoveryAnswer" value={formData.recoveryAnswer} onChange={handleInputChange} className={inputClasses('recoveryAnswer')} placeholder={t('recovery.answer')} required />{errors.recoveryAnswer && <p className="text-red-500 text-xs mt-1 ml-1">{errors.recoveryAnswer}</p>}</div>
                    </>
                )}
                {viewMode === 'signIn' && (
                    <div className="text-right"><button type="button" onClick={() => { setViewMode('forgotPassword'); setRecoveryStep('email'); setErrors({}); }} className="text-sm font-bold text-primary hover:underline">{t('recovery.forgot')}</button></div>
                )}
                <button type="submit" disabled={isSubmitting} className="w-full py-4 bg-primary text-primary-text font-black text-xl rounded-xl shadow-xl shadow-primary/30 hover:bg-primary-dark hover:-translate-y-1 active:translate-y-0 disabled:opacity-50 disabled:translate-y-0 transition-all flex justify-center items-center">
                     {isSubmitting ? <LoadingSpinner /> : (viewMode === 'signUp' ? t('auth.signUp') : t('auth.signIn'))}
                </button>
                {errors.general && <p className="text-red-500 text-sm mt-2 text-center font-bold animate-shake">{errors.general}</p>}
            </form>

            <div className="text-center pt-4">
                <p className="text-sm text-gray-500 font-medium">
                    {viewMode === 'signUp' ? t('auth.alreadyAccount') : t('auth.needAnAccount')}{' '}
                    <button onClick={() => { setViewMode(viewMode === 'signUp' ? 'signIn' : 'signUp'); setErrors({}); setMessage(''); }} className="font-bold text-primary hover:underline">
                      {viewMode === 'signUp' ? t('auth.signIn') : t('auth.signUpWithEmail')}
                    </button>
                </p>
            </div>
        </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-2xl p-8 md:p-12 border border-gray-100 dark:border-gray-700 animate-fade-in-down">
        {renderContent()}
      </div>
      <style>{`
          @keyframes shake {
              0%, 100% { transform: translateX(0); }
              25% { transform: translateX(-5px); }
              75% { transform: translateX(5px); }
          }
          .animate-shake { animation: shake 0.2s ease-in-out 0s 2; }
      `}</style>
    </div>
  );
};

export default SignUp;

import { 
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  signOut,
  sendPasswordResetEmail,
  updateProfile
} from 'firebase/auth';
import { 
  doc, 
  getDoc, 
  setDoc, 
  collection, 
  query, 
  where, 
  getDocs, 
  limit
} from 'firebase/firestore';
import { auth, db } from './firebase';
import type { UserDetails } from '../types';
import { EducationalLevel } from '../types';
import { initializeUsage } from '../lib/usageManager';

const SESSION_TOKEN_KEY = 'sessionToken';

const sanitizeForFirestore = (obj: any): any => {
    try {
        return JSON.parse(JSON.stringify(obj, (key, value) => {
            if (value === undefined) return null;
            return value;
        }));
    } catch (e) {
        console.error("Sanitization failed", e);
        return {};
    }
};

export const storageService = {
    saveItem: (key: string, value: any) => {
        try {
            localStorage.setItem(key, JSON.stringify(value));
        } catch (error) {
            console.error(`Failed to save item "${key}"`, error);
        }
    },
    loadItem: <T,>(key: string): T | null => {
        try {
            const item = localStorage.getItem(key);
            return item ? JSON.parse(item) : null;
        } catch (error) {
            return null;
        }
    },
    removeItem: (key: string) => localStorage.removeItem(key),

    saveUserData: async (userId: string, data: any): Promise<void> => {
        if (!userId) return;
        try {
            const safeData = sanitizeForFirestore(data);
            const userRef = doc(db, 'users', userId);
            await setDoc(userRef, safeData, { merge: true });
        } catch (error: any) {
            console.error('Firestore save failed:', error.message);
        }
    },
    syncUserToCloud: async (userId: string, data: any): Promise<void> => {
        return storageService.saveUserData(userId, data);
    },
    loadUserData: async (userId: string): Promise<any | null> => {
        if (!userId) return null;
        try {
            const userRef = doc(db, 'users', userId);
            const docSnap = await getDoc(userRef);
            return docSnap.exists() ? docSnap.data() : null;
        } catch (error: any) {
            return null;
        }
    },
    clearAllData: () => localStorage.clear()
};

const createToken = (user: UserDetails): string => btoa(encodeURIComponent(JSON.stringify(user)));
const decodeToken = (token: string): UserDetails | null => {
    try { return JSON.parse(decodeURIComponent(atob(token))); } catch { return null; }
};

export const signUp = async (name: string, email: string, password_param: string, recoveryQuestion: string, recoveryAnswer: string): Promise<UserDetails> => {
    const userCredential = await createUserWithEmailAndPassword(auth, email, password_param);
    const user = userCredential.user;
    await updateProfile(user, { displayName: name });
    const newUser: UserDetails = {
        id: user.uid,
        name,
        email,
        educationalLevel: EducationalLevel.UNDERGRADUATE,
        usage: initializeUsage(),
        recoveryQuestion,
        recoveryAnswer
    };
    await storageService.saveUserData(user.uid, { userDetails: newUser });
    storageService.saveItem(SESSION_TOKEN_KEY, createToken(newUser));
    return newUser;
};

export const login = async (email: string, password_param: string): Promise<UserDetails> => {
    const userCredential = await signInWithEmailAndPassword(auth, email, password_param);
    const user = userCredential.user;
    const cloudData = await storageService.loadUserData(user.uid);
    let userDetails = cloudData?.userDetails || {
        id: user.uid,
        name: user.displayName || email.split('@')[0],
        email: email,
        educationalLevel: EducationalLevel.UNDERGRADUATE,
        usage: initializeUsage()
    };
    storageService.saveItem(SESSION_TOKEN_KEY, createToken(userDetails));
    return userDetails;
};

export const findUserByEmail = async (email: string): Promise<boolean> => {
    const usersRef = collection(db, 'users');
    const q = query(usersRef, where('userDetails.email', '==', email), limit(1));
    const querySnapshot = await getDocs(q);
    return !querySnapshot.empty;
};

export const getRecoveryQuestionByEmail = async (email: string): Promise<string | null> => {
    const usersRef = collection(db, 'users');
    const q = query(usersRef, where('userDetails.email', '==', email), limit(1));
    const querySnapshot = await getDocs(q);
    if (querySnapshot.empty) return null;
    const userData = querySnapshot.docs[0].data();
    return userData.userDetails?.recoveryQuestion || null;
};

export const verifyRecoveryAnswer = async (email: string, answer: string): Promise<boolean> => {
    const usersRef = collection(db, 'users');
    const q = query(usersRef, where('userDetails.email', '==', email), limit(1));
    const querySnapshot = await getDocs(q);
    if (querySnapshot.empty) return false;
    const userData = querySnapshot.docs[0].data();
    const storedAnswer = userData.userDetails?.recoveryAnswer;
    return storedAnswer?.toLowerCase().trim() === answer.toLowerCase().trim();
};

export const sendResetEmail = async (email: string): Promise<void> => {
    await sendPasswordResetEmail(auth, email);
};

export const logout = async () => {
    await signOut(auth);
    storageService.removeItem(SESSION_TOKEN_KEY);
};

export const getCurrentUser = (): UserDetails | null => {
    const token = storageService.loadItem<string>(SESSION_TOKEN_KEY);
    return token ? decodeToken(token) : null;
}

import React, { useState } from 'react';
import type { UserDetails } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { signUp, login, getRecoveryQuestionByEmail, verifyRecoveryAnswer, sendResetEmail } from '../services/authService';
import { EyeIcon } from './icons/EyeIcon';
import { EyeOffIcon } from './icons/EyeOffIcon';
import { MailIcon } from './icons/MailIcon';
import { CheckCircleIcon } from './icons/CheckCircleIcon';

interface SignUpProps {
    onLogin: (user: UserDetails) => void;
}

const LoadingSpinner: React.FC = () => (
    <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
);

const recoveryQuestions = [
    "recovery.q1",
    "recovery.q2",
    "recovery.q3",
    "recovery.q4",
    "recovery.q5",
];

const SignUp: React.FC<SignUpProps> = ({ onLogin }) => {
  const { t } = useLanguage();
  const [viewMode, setViewMode] = useState<'signIn' | 'signUp' | 'forgotPassword'>('signIn');
  const [recoveryStep, setRecoveryStep] = useState<'email' | 'question' | 'verified' | 'sent'>('email');

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
    recoveryQuestion: recoveryQuestions[0],
    recoveryAnswer: '',
  });

  const [recoveryData, setRecoveryData] = useState({
    question: '',
    answer: '',
  });

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [errors, setErrors] = useState<any>({});
  const [message, setMessage] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors((prev: any) => ({ ...prev, [name]: undefined }));
    }
    setErrors((prev: any) => ({...prev, general: undefined}));
    setMessage('');
  };

  const handleRecoveryInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const { name, value } = e.target;
      setRecoveryData(prev => ({ ...prev, [name]: value }));
      setErrors((prev: any) => ({ ...prev, recovery: undefined }));
  };

  const validate = () => {
    const newErrors: any = {};
    if (viewMode === 'signUp') {
        if (!formData.name.trim()) newErrors.name = t('validation.nameRequired');
        if (!formData.recoveryQuestion) newErrors.recoveryQuestion = t('validation.recoveryQRequired');
        if (!formData.recoveryAnswer.trim()) newErrors.recoveryAnswer = t('validation.recoveryARequired');
    }
    if (viewMode === 'signUp' || viewMode === 'signIn' || (viewMode === 'forgotPassword' && recoveryStep === 'email')) {
        if (!formData.email.trim()) newErrors.email = t('validation.emailRequired');
        else if (!/\S+@\S+\.\S+/.test(formData.email)) newErrors.email = t('validation.emailInvalid');
    }

    if (viewMode === 'signUp' || viewMode === 'signIn') {
        if (!formData.password) newErrors.password = t('validation.passwordRequired');
        else if (viewMode === 'signUp' && formData.password.length < 6) newErrors.password = t('validation.passwordMinLength');
    }

    if (viewMode === 'signUp' && formData.password !== formData.confirmPassword) {
        newErrors.confirmPassword = t('validation.passwordMismatch');
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleFetchQuestion = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.email.trim()) {
        setErrors({ email: t('validation.emailRequired') });
        return;
    }
    setIsSubmitting(true);
    try {
        const question = await getRecoveryQuestionByEmail(formData.email);
        if (question) {
            setRecoveryData(prev => ({ ...prev, question }));
            setRecoveryStep('question');
        } else {
            setErrors({ general: t('validation.userNotFound') });
        }
    } catch (e) {
        setErrors({ general: t('recovery.error') });
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleVerifyAnswer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!recoveryData.answer.trim()) return;
    setIsSubmitting(true);
    try {
        const isValid = await verifyRecoveryAnswer(formData.email, recoveryData.answer);
        if (isValid) {
            setRecoveryStep('verified');
        } else {
            setErrors({ recovery: t('validation.recoveryAIncorrect') });
        }
    } catch (e) {
        setErrors({ recovery: t('recovery.error') });
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleSendLink = async () => {
    setIsSubmitting(true);
    try {
        await sendResetEmail(formData.email);
        setRecoveryStep('sent');
        setMessage("Password reset link has been sent to your email. Please check your inbox and spam folder.");
    } catch (e) {
        setErrors({ general: t('recovery.error') });
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    setIsSubmitting(true);
    setErrors({});
    setMessage('');

    try {
        if (viewMode === 'signUp') {
            const user = await signUp(formData.name, formData.email, formData.password, formData.recoveryQuestion, formData.recoveryAnswer);
            setMessage(t('auth.signupSuccess'));
            setTimeout(() => onLogin(user), 1000);
        } else if (viewMode === 'signIn') {
            const user = await login(formData.email, formData.password);
            setMessage(t('auth.loginSuccess'));
            setTimeout(() => onLogin(user), 500);
        }
    } catch (error: any) {
        let displayMsg = error.message || 'An unexpected error occurred.';
        if (displayMsg.toLowerCase().includes('firebase')) {
            displayMsg = t('validation.loginFailed');
        }
        setErrors({ general: displayMsg });
    } finally {
        setIsSubmitting(false);
    }
  };

  const renderForgotPasswordContent = () => {
      const inputClasses = "w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary bg-white dark:bg-black transition-all";

      if (recoveryStep === 'email') {
          return (
            <div className="space-y-6 animate-fade-in">
                <div className="text-center">
                    <h2 className="text-3xl font-black text-gray-900 dark:text-white">{t('recovery.title')}</h2>
                    <p className="mt-2 text-gray-500 dark:text-gray-400">{t('recovery.step1.prompt')}</p>
                </div>
                <form onSubmit={handleFetchQuestion} className="space-y-4">
                    <div>
                        <input type="email" name="email" value={formData.email} onChange={handleInputChange} className={inputClasses} placeholder="your-email@example.com" required />
                        {errors.email && <p className="text-red-500 text-xs mt-1 ml-1">{errors.email}</p>}
                    </div>
                    <button type="submit" disabled={isSubmitting} className="w-full py-4 bg-primary text-primary-text font-bold rounded-xl shadow-lg hover:bg-primary-dark transition-all flex justify-center items-center">
                        {isSubmitting ? <LoadingSpinner /> : "Find Account"}
                    </button>
                    {errors.general && <p className="text-red-500 text-sm mt-2 text-center font-bold">{errors.general}</p>}
                </form>
            </div>
          );
      }

      if (recoveryStep === 'question') {
          return (
              <div className="space-y-6 animate-fade-in">
                <div className="text-center">
                    <h2 className="text-3xl font-black text-gray-900 dark:text-white">Verify Identity</h2>
                    <p className="mt-2 text-gray-500 dark:text-gray-400">Please answer your security question to reset your password.</p>
                </div>
                <div className="p-5 bg-primary/5 border border-primary/20 rounded-2xl">
                    <p className="text-xs font-black uppercase tracking-widest text-primary mb-1">Your Security Question</p>
                    <p className="text-lg font-bold text-gray-800 dark:text-gray-200">{t(recoveryData.question as any)}</p>
                </div>
                <form onSubmit={handleVerifyAnswer} className="space-y-4">
                    <div>
                        <input type="text" name="answer" value={recoveryData.answer} onChange={handleRecoveryInputChange} className={inputClasses} placeholder="Type your answer..." required autoFocus />
                        {errors.recovery && <p className="text-red-500 text-xs mt-1 ml-1 font-bold">{errors.recovery}</p>}
                    </div>
                    <button type="submit" disabled={isSubmitting} className="w-full py-4 bg-primary text-primary-text font-bold rounded-xl shadow-lg hover:bg-primary-dark transition-all flex justify-center items-center">
                        {isSubmitting ? <LoadingSpinner /> : "Verify Answer"}
                    </button>
                    <div className="pt-4 border-t dark:border-gray-700 text-center">
                        <p className="text-sm text-gray-500 mb-3">Can't remember the answer?</p>
                        <button type="button" onClick={handleSendLink} disabled={isSubmitting} className="flex items-center justify-center gap-2 w-full py-3 bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-200 rounded-xl hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors">
                            <MailIcon className="w-5 h-5" /> Send reset link anyway
                        </button>
                    </div>
                </form>
              </div>
          );
      }

      if (recoveryStep === 'verified') {
          return (
              <div className="space-y-6 animate-fade-in text-center">
                  <div className="w-20 h-20 bg-green-500 text-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-xl">
                      <CheckCircleIcon className="w-12 h-12" />
                  </div>
                  <h2 className="text-3xl font-black text-gray-900 dark:text-white">Identity Verified</h2>
                  <p className="text-gray-500 dark:text-gray-400">Your answer is correct. Click below to receive a secure password reset link at <strong>{formData.email}</strong>.</p>
                  <button onClick={handleSendLink} disabled={isSubmitting} className="w-full py-4 bg-primary text-primary-text font-black text-xl rounded-xl shadow-xl shadow-primary/30 hover:bg-primary-dark hover:-translate-y-1 transition-all flex justify-center items-center gap-3 mt-8">
                      {isSubmitting ? <LoadingSpinner /> : <><MailIcon className="w-6 h-6" /> Send Reset Password Link</>}
                  </button>
              </div>
          );
      }

      if (recoveryStep === 'sent') {
          return (
              <div className="space-y-6 animate-fade-in text-center">
                   <div className="w-20 h-20 bg-blue-500 text-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-xl">
                      <MailIcon className="w-12 h-12" />
                  </div>
                  <h2 className="text-3xl font-black text-gray-900 dark:text-white">Email Sent!</h2>
                  <div className="p-6 bg-white dark:bg-gray-800 rounded-2xl shadow-inner border border-gray-100 dark:border-gray-700">
                    <p className="text-gray-600 dark:text-gray-300 leading-relaxed font-medium">{message}</p>
                  </div>
                  <p className="text-sm text-gray-400 mt-4">Still nothing? Check your spam folder or wait a few minutes.</p>
                  <button onClick={() => { setViewMode('signIn'); setRecoveryStep('email'); }} className="mt-8 text-primary font-black uppercase tracking-widest hover:underline">
                      Back to Sign In
                  </button>
              </div>
          );
      }
  };

  const renderContent = () => {
    const inputClasses = (field: string) => `w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary bg-white dark:bg-black transition-all ${errors[field] ? 'border-red-500 ring-1 ring-red-500' : ''}`;

    if (viewMode === 'forgotPassword') {
        return (
          <div className="animate-fade-in">
            {renderForgotPasswordContent()}
            {recoveryStep !== 'sent' && (
              <div className="text-center mt-8">
                <button onClick={() => { setViewMode('signIn'); setRecoveryStep('email'); setErrors({}); }} className="text-sm font-bold text-primary hover:underline">
                  Back to Sign In
                </button>
              </div>
            )}
          </div>
        );
    }

    return (
        <div className="space-y-8">
             <div className="text-center">
                 <h2 className="text-4xl font-black text-gray-900 dark:text-white tracking-tight">{viewMode === 'signUp' ? t('auth.createAccount') : t('auth.signInToEduBlay')}</h2>
                 <p className="mt-2 text-gray-500 dark:text-gray-400 font-medium">{viewMode === 'signUp' ? 'Start your academic journey today' : 'Continue where you left off'}</p>
             </div>
             {message && <div className="p-4 bg-green-50 text-green-700 rounded-xl border border-green-200 text-center font-bold animate-fade-in">{message}</div>}
             <form onSubmit={handleSubmit} className="space-y-4">
                {viewMode === 'signUp' && (
                    <div><input type="text" name="name" value={formData.name} onChange={handleInputChange} className={inputClasses('name')} placeholder={t('auth.fullName')} required />{errors.name && <p className="text-red-500 text-xs mt-1 ml-1">{errors.name}</p>}</div>
                )}
                <div><input type="email" name="email" value={formData.email} onChange={handleInputChange} className={inputClasses('email')} placeholder={t('auth.email')} required />{errors.email && <p className="text-red-500 text-xs mt-1 ml-1">{errors.email}</p>}</div>
                <div className="relative"><input type={showPassword ? 'text' : 'password'} name="password" value={formData.password} onChange={handleInputChange} className={inputClasses('password')} placeholder={t('auth.password')} required /><button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-400 hover:text-primary transition-colors">{showPassword ? <EyeOffIcon className="h-5 w-5"/> : <EyeIcon className="h-5 w-5"/>}</button></div>{errors.password && <p className="text-red-500 text-xs mt-1 ml-1">{errors.password}</p>}
                 {viewMode === 'signUp' && (
                    <>
                    <div className="relative">
                        <input 
                            type={showConfirmPassword ? 'text' : 'password'} 
                            name="confirmPassword" 
                            value={formData.confirmPassword} 
                            onChange={handleInputChange} 
                            className={inputClasses('confirmPassword')} 
                            placeholder={t('auth.confirmPassword')} 
                            required
                        />
                        <button 
                            type="button" 
                            onClick={() => setShowConfirmPassword(!showConfirmPassword)} 
                            className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-400 hover:text-primary transition-colors"
                        >
                            {showConfirmPassword ? <EyeOffIcon className="h-5 w-5"/> : <EyeIcon className="h-5 w-5"/>}
                        </button>
                    </div>
                    {errors.confirmPassword && <p className="text-red-500 text-xs mt-1 ml-1">{errors.confirmPassword}</p>}
                    <div className="pt-4 border-t dark:border-gray-700">
                        <label htmlFor="recoveryQuestion" className="block text-xs font-black uppercase tracking-widest text-gray-400 mb-2">{t('recovery.question')}</label>
                        <select name="recoveryQuestion" value={formData.recoveryQuestion} onChange={handleInputChange} className={inputClasses('recoveryQuestion')}>{recoveryQuestions.map(q => <option key={q} value={q}>{t(q as any)}</option>)}</select>
                        <p className="text-[10px] text-gray-400 mt-2">This question will help you recover your password if you forget it.</p>
                    </div>
                    <div><input type="text" name="recoveryAnswer" value={formData.recoveryAnswer} onChange={handleInputChange} className={inputClasses('recoveryAnswer')} placeholder={t('recovery.answer')} required />{errors.recoveryAnswer && <p className="text-red-500 text-xs mt-1 ml-1">{errors.recoveryAnswer}</p>}</div>
                    </>
                )}
                {viewMode === 'signIn' && (
                    <div className="text-right"><button type="button" onClick={() => { setViewMode('forgotPassword'); setRecoveryStep('email'); setErrors({}); }} className="text-sm font-bold text-primary hover:underline">{t('recovery.forgot')}</button></div>
                )}
                <button type="submit" disabled={isSubmitting} className="w-full py-4 bg-primary text-primary-text font-black text-xl rounded-xl shadow-xl shadow-primary/30 hover:bg-primary-dark hover:-translate-y-1 active:translate-y-0 disabled:opacity-50 disabled:translate-y-0 transition-all flex justify-center items-center">
                     {isSubmitting ? <LoadingSpinner /> : (viewMode === 'signUp' ? t('auth.signUp') : t('auth.signIn'))}
                </button>
                {errors.general && <p className="text-red-500 text-sm mt-2 text-center font-bold animate-shake">{errors.general}</p>}
            </form>

            <div className="text-center pt-4">
                <p className="text-sm text-gray-500 font-medium">
                    {viewMode === 'signUp' ? t('auth.alreadyAccount') : t('auth.needAnAccount')}{' '}
                    <button onClick={() => { setViewMode(viewMode === 'signUp' ? 'signIn' : 'signUp'); setErrors({}); setMessage(''); }} className="font-bold text-primary hover:underline">
                      {viewMode === 'signUp' ? t('auth.signIn') : t('auth.signUpWithEmail')}
                    </button>
                </p>
            </div>
        </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-2xl p-8 md:p-12 border border-gray-100 dark:border-gray-700 animate-fade-in-down">
        {renderContent()}
      </div>
      <style>{`
          @keyframes shake {
              0%, 100% { transform: translateX(0); }
              25% { transform: translateX(-5px); }
              75% { transform: translateX(5px); }
          }
          .animate-shake { animation: shake 0.2s ease-in-out 0s 2; }
      `}</style>
    </div>
  );
};

