import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import type { UploadedFile } from '../types';
import { PdfIcon } from './icons/PdfIcon';
import { PowerPointIcon } from './icons/PowerPointIcon';
import { useLanguage } from '../contexts/LanguageContext';
import { ZoomInIcon } from './icons/ZoomInIcon';
import { ZoomOutIcon } from './icons/ZoomOutIcon';
import { LayoutHorizontalIcon } from './icons/LayoutHorizontalIcon';
import { LayoutVerticalIcon } from './icons/LayoutVerticalIcon';
import { FitToPageIcon } from './icons/FitToPageIcon';
import { FitToWidthIcon } from './icons/FitToWidthIcon';


declare const pdfjsLib: any;

interface FileViewerProps {
    file: UploadedFile | null;
    zoom?: number;
    onZoomChange?: (newZoom: number) => void;
    showControls?: boolean;
}

const FileViewer: React.FC<FileViewerProps> = ({ file, zoom: controlledZoom, onZoomChange, showControls = true }) => {
    const { t } = useLanguage();
    const pdfDocRef = useRef<any>(null);
    const [numPages, setNumPages] = useState(0);
    const [isPdfLoading, setIsPdfLoading] = useState(false);
    const [internalZoom, setInternalZoom] = useState(1.0);
    const [visiblePages, setVisiblePages] = useState(new Set([1]));
    const [pageDimensions, setPageDimensions] = useState<{width: number, height: number}[]>([]);
    const observerRef = useRef<IntersectionObserver | null>(null);
    const pageRefs = useRef<Map<number, HTMLDivElement>>(new Map());
    const activeRenderTasks = useRef(new Map());
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const imgRef = useRef<HTMLImageElement>(null);

    const [layoutMode, setLayoutMode] = useState<'vertical' | 'horizontal'>('vertical');
    const [zoomMode, setZoomMode] = useState<'manual' | 'fit-page' | 'fit-width'>('manual');

    const isControlled = controlledZoom !== undefined && onZoomChange !== undefined;
    const zoom = isControlled ? controlledZoom : internalZoom;
    const setZoom = isControlled ? onZoomChange! : setInternalZoom;

    const isPdf = file?.type === 'application/pdf';
    const isImage = file?.type.startsWith('image/');
    const isPptx = file?.type === 'application/vnd.openxmlformats-officedocument.presentationml.presentation';

    // Safely generate a URL for the file to be used in <img> tags or downloads
    const fileUrl = useMemo(() => {
        if (!file?.base64) return null;
        try {
            const binaryString = window.atob(file.base64);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }
            const blob = new Blob([bytes], { type: file.type });
            return URL.createObjectURL(blob);
        } catch (e) {
            console.error("Failed to create file URL", e);
            return null;
        }
    }, [file?.base64, file?.type]);

    // Clean up the object URL when component unmounts or file changes
    useEffect(() => {
        return () => {
            if (fileUrl) URL.revokeObjectURL(fileUrl);
        };
    }, [fileUrl]);

    const handleZoomIn = () => {
        setZoomMode('manual');
        setZoom(Math.min(zoom + 0.25, 3.0));
    };
    const handleZoomOut = () => {
        setZoomMode('manual');
        setZoom(Math.max(zoom - 0.25, 0.25));
    };
    const handleZoomReset = () => {
        setZoomMode('manual');
        setZoom(1.0);
    };
    const handleRangeZoom = (newZoom: number) => {
        setZoomMode('manual');
        setZoom(newZoom);
    };

    const handleFitToPage = useCallback(() => setZoomMode('fit-page'), []);
    const handleFitToWidth = useCallback(() => setZoomMode('fit-width'), []);

    const recalculateZoom = useCallback(() => {
        if (zoomMode === 'manual' || !scrollContainerRef.current) {
            return;
        }

        const container = scrollContainerRef.current;
        const paddingX = 32;
        const paddingY = 32;
        const containerWidth = container.clientWidth - paddingX;
        const containerHeight = container.clientHeight - paddingY;

        let contentWidth = 0;
        let contentHeight = 0;

        if (isPdf && pageDimensions.length > 0) {
            contentWidth = pageDimensions[0].width;
            contentHeight = pageDimensions[0].height;
        } else if (isImage && imgRef.current) {
            contentWidth = imgRef.current.naturalWidth;
            contentHeight = imgRef.current.naturalHeight;
        }

        if (contentWidth === 0 || contentHeight === 0) return;

        let newZoom = 1;
        if (zoomMode === 'fit-page') {
            newZoom = Math.min(containerWidth / contentWidth, containerHeight / contentHeight);
        } else if (zoomMode === 'fit-width') {
            newZoom = containerWidth / contentWidth;
        }

        setZoom(Math.max(0.1, newZoom));

    }, [zoomMode, pageDimensions, isPdf, isImage, setZoom]);

    useEffect(() => {
        recalculateZoom();

        const container = scrollContainerRef.current;
        if (!container) return;

        const resizeObserver = new ResizeObserver(() => {
            recalculateZoom();
        });
        resizeObserver.observe(container);

        return () => resizeObserver.disconnect();
    }, [recalculateZoom]);

    useEffect(() => {
        recalculateZoom();
    }, [pageDimensions, recalculateZoom]);


    useEffect(() => {
        if (!file?.base64 || !isPdf) return;

        setIsPdfLoading(true);

        // FIX: Convert binary string to Uint8Array
        const binaryString = window.atob(file.base64);
        const bytes = new Uint8Array(binaryString.length);
        for (let i = 0; i < binaryString.length; i++) {
            bytes[i] = binaryString.charCodeAt(i);
        }

        const loadingTask = pdfjsLib.getDocument({ data: bytes });
        loadingTask.promise.then(async (pdf: any) => {
            pdfDocRef.current = pdf;
            setNumPages(pdf.numPages);

            const dims = [];
            for (let i = 1; i <= pdf.numPages; i++) {
                const page = await pdf.getPage(i);
                const viewport = page.getViewport({ scale: 1.0 });
                dims.push({ width: viewport.width, height: viewport.height });
            }
            setPageDimensions(dims);
            setVisiblePages(new Set([1]));
            setIsPdfLoading(false);

        }).catch((err: any) => {
            console.error('Error loading PDF document', err);
            setIsPdfLoading(false);
        });

        return () => {
            if (pdfDocRef.current) {
                pdfDocRef.current.destroy();
            }
            pdfDocRef.current = null;
            setNumPages(0);
            setPageDimensions([]);
            pageRefs.current.clear();
        };
    }, [file, isPdf]);

    useEffect(() => {
        if (!isPdf || !pdfDocRef.current || pageDimensions.length === 0) return;

        const basePdfScale = 1.0;

        visiblePages.forEach(pageNum => {
            const pageDiv = pageRefs.current.get(pageNum);
            const canvas = pageDiv?.querySelector('canvas');
            if (!canvas) return;

            if (canvas.dataset.renderedZoom === String(zoom) && canvas.dataset.renderedLayout === layoutMode) {
                return;
            }

            if (activeRenderTasks.current.has(pageNum)) {
                activeRenderTasks.current.get(pageNum).cancel();
            }

            pdfDocRef.current.getPage(pageNum).then((page: any) => {
                const context = canvas.getContext('2d');
                if (!context) return;

                const viewport = page.getViewport({ scale: basePdfScale * zoom });

                canvas.height = viewport.height;
                canvas.width = viewport.width;

                const renderTask = page.render({
                    canvasContext: context,
                    viewport: viewport,
                });

                activeRenderTasks.current.set(pageNum, renderTask);

                renderTask.promise
                    .then(() => {
                        canvas.dataset.renderedZoom = String(zoom);
                        canvas.dataset.renderedLayout = layoutMode;
                    })
                    .catch((err: any) => {
                        if (err.name !== 'RenderingCancelledException') {
                            console.error(`Failed to render page ${pageNum}`, err);
                        }
                    })
                    .finally(() => {
                        if (activeRenderTasks.current.get(pageNum) === renderTask) {
                            activeRenderTasks.current.delete(pageNum);
                        }
                    });
            });
        });

        return () => {
            activeRenderTasks.current.forEach((task: any) => task.cancel());
            activeRenderTasks.current.clear();
        };
    }, [isPdf, visiblePages, zoom, pageDimensions, layoutMode]);

    useEffect(() => {
        if (observerRef.current) observerRef.current.disconnect();

        observerRef.current = new IntersectionObserver((entries) => {
            setVisiblePages(prevVisiblePages => {
                const newVisiblePages = new Set(prevVisiblePages);
                let updated = false;
                entries.forEach(entry => {
                    const pageNum = parseInt(entry.target.getAttribute('data-page-number') || '0', 10);
                    if (pageNum && entry.isIntersecting) {
                        if (!newVisiblePages.has(pageNum)) {
                            newVisiblePages.add(pageNum);
                            updated = true;
                        }
                    }
                });
                return updated ? newVisiblePages : prevVisiblePages;
            });
        }, { rootMargin: '200px' });

        pageRefs.current.forEach(pageElement => {
            if (pageElement) {
                observerRef.current?.observe(pageElement);
            }
        });

        return () => observerRef.current?.disconnect();
    }, [numPages, pageDimensions, layoutMode]);

    if (!file) {
        return (
            <div className="h-full flex items-center justify-center text-center text-gray-500 bg-gray-100 dark:bg-gray-800 rounded-lg">
                <p>{t('fileviewer.noMaterial')}</p>
            </div>
        );
    }

    return (
        <div className="w-full h-full bg-gray-200 dark:bg-gray-900 rounded-lg overflow-hidden relative flex flex-col">
            {showControls && (isPdf || isImage) && (
                <div className="absolute top-4 left-1/2 -translate-x-1/2 z-20 bg-gray-100/90 dark:bg-gray-800/90 backdrop-blur-md rounded-full shadow-lg flex items-center gap-2 p-2 border border-gray-300 dark:border-gray-700">
                    {isPdf && (
                        <>
                             <button onClick={() => setLayoutMode(layoutMode === 'vertical' ? 'horizontal' : 'vertical')} className="p-2 rounded-full text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700" title={layoutMode === 'vertical' ? t('fileviewer.layout.horizontal') : t('fileviewer.layout.vertical')}>
                                {layoutMode === 'vertical' ? <LayoutHorizontalIcon className="w-5 h-5" /> : <LayoutVerticalIcon className="w-5 h-5" />}
                            </button>
                            <div className="w-px h-5 bg-gray-300 dark:bg-gray-600"></div>
                        </>
                    )}
                    <button onClick={handleZoomOut} className="p-1 rounded-full text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700" title="Zoom Out"><ZoomOutIcon className="w-5 h-5" /></button>

                    <input 
                        type="range" 
                        min="0.25" 
                        max="3" 
                        step="0.05" 
                        value={zoom} 
                        onChange={(e) => handleRangeZoom(parseFloat(e.target.value))} 
                        className="w-24 h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer dark:bg-gray-700 accent-primary" 
                        aria-label="Zoom slider"
                    />

                    <button onClick={handleZoomIn} className="p-1 rounded-full text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700" title="Zoom In"><ZoomInIcon className="w-5 h-5" /></button>

                    <div className="w-px h-5 bg-gray-300 dark:bg-gray-600"></div>

                    <button onClick={handleFitToPage} className={`p-2 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 ${zoomMode === 'fit-page' ? 'text-primary' : 'text-gray-700 dark:text-gray-300'}`} title={t('fileviewer.zoom.fitPage')}><FitToPageIcon className="w-5 h-5" /></button>
                    <button onClick={handleFitToWidth} className={`p-2 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 ${zoomMode === 'fit-width' ? 'text-primary' : 'text-gray-700 dark:text-gray-300'}`} title={t('fileviewer.zoom.fitWidth')}><FitToWidthIcon className="w-5 h-5" /></button>

                    <div className="w-px h-5 bg-gray-300 dark:bg-gray-600"></div>

                    <button onClick={handleZoomReset} className="text-sm font-semibold px-2 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-md" title="Reset Zoom">
                        {Math.round(zoom * 100)}%
                    </button>
                </div>
            )}
            {isPdf ? (
                <>
                    {isPdfLoading && (
                        <div className="absolute inset-0 bg-black/20 flex items-center justify-center z-10">
                            <div className="animate-spin w-8 h-8 border-4 border-white/30 border-t-white rounded-full"></div>
                        </div>
                    )}
                    <div ref={scrollContainerRef} className={`flex-1 overflow-auto p-4 ${layoutMode === 'horizontal' ? 'flex flex-row items-center gap-4' : 'flex flex-col'}`}>
                        {Array.from(new Array(numPages), (_, index) => {
                            const pageNum = index + 1;
                            const dims = pageDimensions[index];
                            return (
                                <div
                                    key={index}
                                    ref={el => { if (el) pageRefs.current.set(pageNum, el); else pageRefs.current.delete(pageNum); }}
                                    data-page-number={pageNum}
                                    className={layoutMode === 'horizontal' ? 'h-full flex-shrink-0 flex items-center justify-center' : 'flex justify-center mb-4'}
                                    style={{ 
                                        minHeight: dims ? `${(dims.height * zoom)}px` : '1000px',
                                        ...(layoutMode === 'horizontal' && { minWidth: dims ? `${(dims.width * zoom)}px` : '700px' })
                                    }}
                                >
                                    {visiblePages.has(pageNum) && (
                                        <canvas
                                            className="shadow-lg"
                                        />
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </>
            ) : isImage ? (
                 <div ref={scrollContainerRef} className="w-full h-full overflow-auto flex justify-center items-center p-4">
                    {fileUrl && (
                        <img 
                            ref={imgRef} 
                            src={fileUrl} 
                            alt={file.name} 
                            className="max-w-none max-h-none object-contain transition-transform" 
                            style={{ width: 'auto', height: 'auto', transform: `scale(${zoom})`, transformOrigin: 'center' }} 
                            onLoad={recalculateZoom} 
                        />
                    )}
                </div>
            ) : (
                <div className="h-full flex flex-col items-center justify-center text-center text-gray-700 dark:text-gray-300 p-8">
                    {isPptx ? <PowerPointIcon className="w-24 h-24 text-orange-500 mb-4" /> : <PdfIcon className="w-24 h-24 text-red-500 mb-4" />}
                    <h3 className="text-xl font-bold mb-2">{t('fileviewer.previewNotAvailable')}</h3>
                    <p className="text-gray-500 dark:text-gray-400 mb-4">
                        {t('fileviewer.unsupportedType', { type: file.type })}
                    </p>
                    {fileUrl && (
                        <a 
                            href={fileUrl} 
                            download={file.name}
                            className="px-4 py-2 bg-primary text-primary-text rounded-md hover:bg-primary-dark"
                        >
                            {t('fileviewer.downloadFile', { name: file.name })}
                        </a>
                    )}
                </div>
            )}
        </div>
    );
};

export default FileViewer;

import { 
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  signOut,
  updateProfile,
  onAuthStateChanged as firebaseOnAuthStateChanged
} from 'firebase/auth';
import { 
  doc, 
  getDoc, 
  setDoc, 
  collection, 
  query, 
  where, 
  getDocs, 
  limit,
  serverTimestamp
} from 'firebase/firestore';
import { auth, db } from './firebase';
import type { UserDetails } from '../types';
import { EducationalLevel } from '../types';
import { initializeUsage } from '../lib/usageManager';

const SESSION_TOKEN_KEY = 'sessionToken';
const USER_KEY_PREFIX = 'eb_u_data_';

const sanitizeForFirestore = (obj: any): any => {
    try {
        return JSON.parse(JSON.stringify(obj, (key, value) => {
            if (value === undefined) return null;
            return value;
        }));
    } catch (e) {
        console.error("Sanitization failed", e);
        return {};
    }
};

export const storageService = {
    saveItem: (key: string, value: any) => {
        try {
            localStorage.setItem(key, JSON.stringify(value));
        } catch (error: any) {
            console.error(`Failed to save item "${key}"`, error);
        }
    },
    loadItem: <T,>(key: string): T | null => {
        try {
            const item = localStorage.getItem(key);
            return item ? JSON.parse(item) : null;
        } catch (error) {
            return null;
        }
    },
    removeItem: (key: string) => localStorage.removeItem(key),

    saveUserData: async (userId: string, data: any): Promise<void> => {
        if (!userId) return;
        try {
            const safeData = sanitizeForFirestore(data);
            const userRef = doc(db, 'users', userId);
            await setDoc(userRef, safeData, { merge: true });
        } catch (error: any) {
            console.error('Firestore save failed:', error.message);
        }
    },
    syncUserToCloud: async (userId: string, data: any): Promise<void> => {
        return storageService.saveUserData(userId, data);
    },
    loadUserData: async (userId: string): Promise<any | null> => {
        if (!userId) return null;
        try {
            const userRef = doc(db, 'users', userId);
            const docSnap = await getDoc(userRef);
            return docSnap.exists() ? docSnap.data() : null;
        } catch (error: any) {
            return null;
        }
    },
    exportAllData: () => {
        const data: { [key: string]: any } = {};
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key) {
                const item = localStorage.getItem(key);
                try { data[key] = JSON.parse(item!); } catch { data[key] = item; }
            }
        }
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `edublay_backup_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    },
    importAllData: (file: File): Promise<void> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = (event) => {
                try {
                    const data = JSON.parse(event.target?.result as string);
                    Object.keys(data).forEach(key => storageService.saveItem(key, data[key]));
                    resolve();
                } catch { reject(new Error("Failed to parse import file.")); }
            };
            reader.readAsText(file);
        });
    },
    clearAllData: () => localStorage.clear()
};

const createToken = (user: UserDetails): string => btoa(encodeURIComponent(JSON.stringify(user)));
const decodeToken = (token: string): UserDetails | null => {
    try { return JSON.parse(decodeURIComponent(atob(token))); } catch { return null; }
};

export const signUp = async (name: string, email: string, password_param: string, recoveryQuestion: string, recoveryAnswer: string): Promise<UserDetails> => {
    const userCredential = await createUserWithEmailAndPassword(auth, email, password_param);
    const user = userCredential.user;
    await updateProfile(user, { displayName: name });
    const newUser: UserDetails = {
        id: user.uid,
        name,
        email,
        educationalLevel: EducationalLevel.UNDERGRADUATE,
        usage: initializeUsage(),
        recoveryQuestion,
        recoveryAnswer
    };
    await storageService.saveUserData(user.uid, { userDetails: newUser });
    storageService.saveItem(SESSION_TOKEN_KEY, createToken(newUser));
    return newUser;
};

export const login = async (email: string, password_param: string): Promise<UserDetails> => {
    const userCredential = await signInWithEmailAndPassword(auth, email, password_param);
    const user = userCredential.user;
    const cloudData = await storageService.loadUserData(user.uid);

    // Recovery Logic: Prevent overwriting local materials with cloud sync if cloud version is stripped
    const localKey = `${USER_KEY_PREFIX}${email}`;
    const localData = storageService.loadItem<any>(localKey);

    let finalData = cloudData;
    if (localData && cloudData) {
        if (localData.learningHubState?.file?.base64 && !cloudData.learningHubState?.file?.base64) {
             finalData = {
                 ...cloudData,
                 learningHubState: {
                     ...cloudData.learningHubState,
                     file: {
                         ...cloudData.learningHubState?.file,
                         base64: localData.learningHubState.file.base64
                     }
                 }
             };
        }
    }

    const userDetails = finalData?.userDetails || {
        id: user.uid,
        name: user.displayName || email.split('@')[0],
        email: email,
        educationalLevel: EducationalLevel.UNDERGRADUATE,
        usage: initializeUsage()
    };

    if (finalData) storageService.saveItem(localKey, finalData);
    storageService.saveItem(SESSION_TOKEN_KEY, createToken(userDetails));
    return userDetails;
};

export const findUserByEmail = async (email: string): Promise<boolean> => {
    const usersRef = collection(db, 'users');
    const q = query(usersRef, where('userDetails.email', '==', email), limit(1));
    const querySnapshot = await getDocs(q);
    return !querySnapshot.empty;
};

export const logout = async () => {
    await signOut(auth);
    storageService.removeItem(SESSION_TOKEN_KEY);
};

export const getCurrentUser = (): UserDetails | null => {
    const token = storageService.loadItem<string>(SESSION_TOKEN_KEY);
    return token ? decodeToken(token) : null;
};

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import type { UploadedFile } from '../types';
import { PdfIcon } from './icons/PdfIcon';
import { PowerPointIcon } from './icons/PowerPointIcon';
import { useLanguage } from '../contexts/LanguageContext';
import { ZoomInIcon } from './icons/ZoomInIcon';
import { ZoomOutIcon } from './icons/ZoomOutIcon';
import { LayoutHorizontalIcon } from './icons/LayoutHorizontalIcon';
import { LayoutVerticalIcon } from './icons/LayoutVerticalIcon';
import { FitToPageIcon } from './icons/FitToPageIcon';
import { FitToWidthIcon } from './icons/FitToWidthIcon';

declare const pdfjsLib: any;

interface FileViewerProps {
    file: UploadedFile | null;
    zoom?: number;
    onZoomChange?: (newZoom: number) => void;
    showControls?: boolean;
}

const FileViewer: React.FC<FileViewerProps> = ({ file, zoom: controlledZoom, onZoomChange, showControls = true }) => {
    const { t } = useLanguage();
    const pdfDocRef = useRef<any>(null);
    const [numPages, setNumPages] = useState(0);
    const [isPdfLoading, setIsPdfLoading] = useState(false);
    const [internalZoom, setInternalZoom] = useState(1.0);
    const [pageDimensions, setPageDimensions] = useState<{width: number, height: number}[]>([]);
    const pageRefs = useRef<Map<number, HTMLDivElement>>(new Map());
    const activeRenderTasks = useRef(new Map());
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const imgRef = useRef<HTMLImageElement>(null);
    const [fileUrl, setFileUrl] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);

    const [layoutMode, setLayoutMode] = useState<'vertical' | 'horizontal'>('vertical');
    const [zoomMode, setZoomMode] = useState<'manual' | 'fit-page' | 'fit-width'>('manual');

    const isControlled = controlledZoom !== undefined && onZoomChange !== undefined;
    const zoom = isControlled ? controlledZoom : internalZoom;
    const setZoom = isControlled ? onZoomChange! : setInternalZoom;

    const isPdf = file?.type === 'application/pdf';
    const isImage = file?.type.startsWith('image/');
    const isPptx = file?.type === 'application/vnd.openxmlformats-officedocument.presentationml.presentation';

    const pdfData = useMemo(() => {
        if (!file?.base64) return null;
        try {
            const binaryString = atob(file.base64);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }
            return bytes;
        } catch (e) {
            console.error("Binary decode failed", e);
            return null;
        }
    }, [file?.base64]);

    useEffect(() => {
        if (!file || !pdfData) return;
        const blob = new Blob([pdfData], { type: file.type });
        const url = URL.createObjectURL(blob);
        setFileUrl(url);
        return () => { if (url) URL.revokeObjectURL(url); };
    }, [file, pdfData]);

    const handleZoomIn = () => { setZoomMode('manual'); setZoom(Math.min(zoom + 0.25, 3.0)); };
    const handleZoomOut = () => { setZoomMode('manual'); setZoom(Math.max(zoom - 0.25, 0.25)); };
    const handleZoomReset = () => { setZoomMode('manual'); setZoom(1.0); };
    const handleRangeZoom = (newVal: number) => { setZoomMode('manual'); setZoom(newVal); };
    const handleFitToPage = useCallback(() => setZoomMode('fit-page'), []);
    const handleFitToWidth = useCallback(() => setZoomMode('fit-width'), []);

    const recalculateZoom = useCallback(() => {
        if (zoomMode === 'manual' || !scrollContainerRef.current) return;
        const container = scrollContainerRef.current;
        const padding = 32;
        const containerWidth = container.clientWidth - padding;
        const containerHeight = container.clientHeight - padding;

        let contentWidth = 0;
        let contentHeight = 0;

        if (isPdf && pageDimensions.length > 0) {
            contentWidth = Math.max(...pageDimensions.map(d => d.width));
            contentHeight = Math.max(...pageDimensions.map(d => d.height));
        } else if (isImage && imgRef.current) {
            contentWidth = imgRef.current.naturalWidth;
            contentHeight = imgRef.current.naturalHeight;
        }

        if (contentWidth === 0 || contentHeight === 0) return;

        let newZoom = 1;
        if (zoomMode === 'fit-page') {
            newZoom = Math.min(containerWidth / contentWidth, containerHeight / contentHeight);
        } else if (zoomMode === 'fit-width') {
            newZoom = containerWidth / contentWidth;
        }
        setZoom(Math.max(0.1, newZoom));
    }, [zoomMode, pageDimensions, isPdf, isImage, setZoom]);

    useEffect(() => {
        recalculateZoom();
        window.addEventListener('resize', recalculateZoom);
        return () => window.removeEventListener('resize', recalculateZoom);
    }, [recalculateZoom]);

    useEffect(() => {
        if (!isPdf || !pdfData) return;
        setIsPdfLoading(true);
        setError(null);

        pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js`;

        const loadingTask = pdfjsLib.getDocument({ data: pdfData });
        loadingTask.promise.then(async (pdf: any) => {
            pdfDocRef.current = pdf;
            setNumPages(pdf.numPages);
            const dims = [];
            for (let i = 1; i <= pdf.numPages; i++) {
                const page = await pdf.getPage(i);
                const viewport = page.getViewport({ scale: 1.0 });
                dims.push({ width: viewport.width, height: viewport.height });
            }
            setPageDimensions(dims);
            setIsPdfLoading(false);
        }).catch((err: any) => {
            console.error('PDF Load Error:', err);
            setError(`Failed to load PDF: ${err.message}`);
            setIsPdfLoading(false);
        });

        return () => {
            if (pdfDocRef.current) pdfDocRef.current.destroy();
            pageRefs.current.clear();
            activeRenderTasks.current.forEach(t => t?.cancel());
            activeRenderTasks.current.clear();
        };
    }, [isPdf, pdfData]);

    const renderPage = useCallback(async (pageNum: number) => {
        const pageDiv = pageRefs.current.get(pageNum);
        const canvas = pageDiv?.querySelector('canvas');
        const textLayerDiv = pageDiv?.querySelector('.textLayer') as HTMLDivElement;

        if (!pdfDocRef.current || !canvas || !textLayerDiv) return;
        if (activeRenderTasks.current.has(pageNum)) activeRenderTasks.current.get(pageNum).cancel();

        const page = await pdfDocRef.current.getPage(pageNum);
        const pixelRatio = window.devicePixelRatio || 1;
        const viewport = page.getViewport({ scale: zoom * pixelRatio });

        canvas.height = viewport.height;
        canvas.width = viewport.width;
        canvas.style.height = `${viewport.height / pixelRatio}px`;
        canvas.style.width = `${viewport.width / pixelRatio}px`;

        const context = canvas.getContext('2d', { alpha: false });
        const renderTask = page.render({ canvasContext: context, viewport });
        activeRenderTasks.current.set(pageNum, renderTask);

        try {
            await renderTask.promise;
            textLayerDiv.innerHTML = '';
            textLayerDiv.style.width = canvas.style.width;
            textLayerDiv.style.height = canvas.style.height;
            textLayerDiv.style.setProperty('--scale-factor', String(zoom * pixelRatio));

            const textContent = await page.getTextContent();
            pdfjsLib.renderTextLayer({
                textContent,
                container: textLayerDiv,
                viewport: page.getViewport({ scale: zoom * pixelRatio }),
                textDivs: []
            });
        } catch (err) {
            if (err.name !== 'RenderingCancelledException') console.error("Render failed", err);
        }
    }, [zoom]);

    useEffect(() => {
        if (!isPdf || !pdfDocRef.current || numPages === 0) return;
        for (let i = 1; i <= numPages; i++) renderPage(i);
    }, [isPdf, numPages, zoom, renderPage]);

    if (error) return <div className="p-8 text-center text-red-500 bg-red-50 dark:bg-red-950/20 rounded-xl">{error}</div>;
    if (!file) return <div className="p-8 text-center text-gray-500">{t('fileviewer.noMaterial')}</div>;

    const btnClass = "p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400 transition-colors";
    const activeBtnClass = "p-2 rounded-lg bg-primary/10 text-primary";

    return (
        <div className="flex flex-col h-full bg-gray-100 dark:bg-gray-950 rounded-xl overflow-hidden border dark:border-gray-800">
            {showControls && (isPdf || isImage) && (
                <div className="flex items-center justify-between px-4 py-2 bg-white dark:bg-gray-900 border-b dark:border-gray-800 z-10">
                    <div className="flex items-center gap-2">
                        <button onClick={handleZoomOut} className={btnClass}><ZoomOutIcon className="w-5 h-5"/></button>
                        <input type="range" min="0.25" max="3" step="0.05" value={zoom} onChange={(e) => handleRangeZoom(parseFloat(e.target.value))} className="w-24 accent-primary" />
                        <button onClick={handleZoomIn} className={btnClass}><ZoomInIcon className="w-5 h-5"/></button>
                        <span className="text-xs font-bold text-gray-500">{Math.round(zoom * 100)}%</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <button onClick={handleFitToPage} className={zoomMode === 'fit-page' ? activeBtnClass : btnClass} title={t('fileviewer.zoom.fitPage')}><FitToPageIcon className="w-5 h-5"/></button>
                        <button onClick={handleFitToWidth} className={zoomMode === 'fit-width' ? activeBtnClass : btnClass} title={t('fileviewer.zoom.fitWidth')}><FitToWidthIcon className="w-5 h-5"/></button>
                        {isPdf && (
                            <>
                                <button onClick={() => setLayoutMode('vertical')} className={layoutMode === 'vertical' ? activeBtnClass : btnClass}><LayoutVerticalIcon className="w-5 h-5"/></button>
                                <button onClick={() => setLayoutMode('horizontal')} className={layoutMode === 'horizontal' ? activeBtnClass : btnClass}><LayoutHorizontalIcon className="w-5 h-5"/></button>
                            </>
                        )}
                    </div>
                </div>
            )}
            <div ref={scrollContainerRef} className="flex-1 overflow-auto p-4 bg-gray-200 dark:bg-gray-900/50 custom-scrollbar">
                <div className={`flex ${layoutMode === 'vertical' ? 'flex-col items-center gap-8' : 'flex-row items-start gap-4'} min-h-full`}>
                    {isPdf ? Array.from({ length: numPages }, (_, i) => i + 1).map(pageNum => (
                        <div key={pageNum} ref={el => { if (el) pageRefs.current.set(pageNum, el); }} className="relative bg-white shadow-xl dark:shadow-black/50 overflow-hidden" style={{ width: pageDimensions[pageNum - 1] ? `${pageDimensions[pageNum - 1].width * zoom}px` : '100%', height: pageDimensions[pageNum - 1] ? `${pageDimensions[pageNum - 1].height * zoom}px` : 'auto' }}>
                            <canvas className="block w-full h-full" />
                            <div className="textLayer absolute inset-0 pointer-events-auto" />
                        </div>
                    )) : isImage ? (
                        <div className="max-w-full inline-block bg-white shadow-2xl rounded-lg overflow-hidden">
                            <img ref={imgRef} src={fileUrl || ''} alt={file.name} className="block transition-all" style={{ transform: `scale(${zoom})`, transformOrigin: 'top left' }} />
                        </div>
                    ) : (
                        <div className="bg-white dark:bg-gray-800 p-12 rounded-2xl shadow-xl text-center max-w-lg mx-auto mt-10">
                            {isPptx ? <PowerPointIcon className="w-20 h-20 mx-auto text-orange-500 mb-6" /> : <PdfIcon className="w-20 h-20 mx-auto text-red-500 mb-6" />}
                            <h3 className="text-xl font-bold">{file.name}</h3>
                            <p className="text-gray-500 my-4">{t('fileviewer.unsupportedType', { type: file.type })}</p>
                            {fileUrl && <a href={fileUrl} download={file.name} className="px-8 py-3 bg-primary text-white font-bold rounded-xl shadow-lg inline-block">{t('fileviewer.downloadFile', { name: file.name })}</a>}
                        </div>
                    )}
                </div>
            </div>
            <style>{`
                .textLayer { position: absolute; left: 0; top: 0; right: 0; bottom: 0; overflow: hidden; opacity: 0.2; line-height: 1.0; white-space: pre; }
                .textLayer:hover { opacity: 1; }
                .textLayer span { color: transparent; position: absolute; white-space: pre; cursor: text; transform-origin: 0% 0%; }
                .custom-scrollbar::-webkit-scrollbar { width: 8px; height: 8px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.2); border-radius: 4px; }
                .dark .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); }
            `}</style>
        </div>
    );
};
export default FileViewer;

