const SendIcon = (props: any) => <svg {...props} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13"></line><polygon points="22 2 15 22 11 13 2 9 22 2"></polygon></svg>;

const UploadSlides: React.FC<UploadSlidesProps> = ({
  smartPlan, setSmartPlan, activeSession, setActiveSession, setView, addToast,
  learningHubState, setLearningHubState, notes, setNotes,
  showTitle = true, isStudyModeView = false,
  intendedStudyContext, setIntendedStudyContext,
  onAttemptUpload,
}) => {
  const { t } = useLanguage();
  const [chatInput, setChatInput] = useState('');
  const [zoom, setZoom] = useState(1.0);
  const { file, analysisMode, analysisResults, chatHistory, isProcessing, processingMessage } = learningHubState;

  const setAnalysisMode = (mode: AnalysisMode) => setLearningHubState(prev => ({ ...prev, analysisMode: mode }));

  const handleChatSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || !file) return;
    const userMsg = chatInput;
    const history = [...chatHistory];
    setChatInput('');
    setLearningHubState(p => ({ ...p, isProcessing: true, chatHistory: [...p.chatHistory, { user: userMsg, blay: '...' }] }));

    try {
        const filePart: ImagePart = { inlineData: { data: file.base64, mimeType: file.type } };
        const stream = await chatWithDocumentStream(filePart, userMsg, history, file.context);
        let full = '';
        for await (const chunk of stream) {
            full += chunk.text;
            setLearningHubState(p => {
                const h = [...p.chatHistory];
                h[h.length-1].blay = full;
                return { ...p, chatHistory: h };
            });
        }
    } catch {
        addToast(t('toasts.chatError'), 'error');
    } finally { setLearningHubState(p => ({ ...p, isProcessing: false })); }
  };

  const handleAnalysis = async (mode: 'summarize' | 'explain') => {
      if (analysisResults[mode]) return setAnalysisMode(mode);
      setLearningHubState(p => ({ ...p, isProcessing: true, processingMessage: t(`uploadslides.loading.${mode}` as any) }));
      try {
          const part: ImagePart = { inlineData: { data: file!.base64, mimeType: file!.type } };
          const result = mode === 'summarize' ? await summarizeDocument(part, file!.context) : await explainDocument(part, file!.context);
          setLearningHubState(p => ({ ...p, analysisMode: mode, analysisResults: { ...p.analysisResults, [mode]: result } }));
      } catch { addToast("Analysis failed", "error"); }
      finally { setLearningHubState(p => ({ ...p, isProcessing: false })); }
  };

  if (!file) {
      const { getRootProps, getInputProps } = useDropzone({ onDrop: files => onAttemptUpload(files[0]) });
      return (
          <div {...getRootProps()} className="flex-1 flex flex-col items-center justify-center p-12 border-4 border-dashed rounded-3xl border-gray-300 dark:border-gray-700 hover:border-primary transition-all cursor-pointer bg-white dark:bg-gray-800">
              <input {...getInputProps()} />
              <UploadIcon className="w-16 h-16 text-gray-400 mb-4"/>
              <p className="text-xl font-bold text-gray-700 dark:text-gray-300">{t('uploadslides.dropzone')}</p>
          </div>
      );
  }

  return (
      <div className="flex flex-col h-full gap-4">
          <div className="flex-1 grid lg:grid-cols-2 gap-4 min-h-0">
              <FileViewer file={file} zoom={zoom} onZoomChange={setZoom} showControls={!isStudyModeView} />
              <div className="flex flex-col h-full bg-white dark:bg-gray-800 rounded-2xl shadow-xl overflow-hidden border dark:border-gray-700">
                  <div className="p-4 border-b dark:border-gray-700 flex gap-2 overflow-x-auto">
                      <button onClick={() => setAnalysisMode('chat')} className={`px-4 py-2 rounded-xl font-bold text-sm whitespace-nowrap ${analysisMode === 'chat' ? 'bg-primary text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'}`}>Chat</button>
                      <button onClick={() => handleAnalysis('summarize')} className={`px-4 py-2 rounded-xl font-bold text-sm whitespace-nowrap ${analysisMode === 'summarize' ? 'bg-primary text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'}`}>Summary</button>
                      <button onClick={() => handleAnalysis('explain')} className={`px-4 py-2 rounded-xl font-bold text-sm whitespace-nowrap ${analysisMode === 'explain' ? 'bg-primary text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'}`}>Explain</button>
                  </div>
                  <div className="flex-1 overflow-hidden">
                      {analysisMode === 'chat' ? (
                          <ChatView chatHistory={chatHistory} chatInput={chatInput} setChatInput={setChatInput} handleChatSubmit={handleChatSubmit} isProcessing={isProcessing} handleEditMessage={() => {}} />
                      ) : (
                          <div className="p-6 h-full overflow-y-auto">
                              <RichTextViewer content={analysisResults[analysisMode as 'summarize' | 'explain'] || 'Loading...'} />
                          </div>
                      )}
                  </div>
              </div>
          </div>
      </div>
  );
};
export default UploadSlides;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import type { UploadedFile } from '../types';
import { PdfIcon } from './icons/PdfIcon';
import { PowerPointIcon } from './icons/PowerPointIcon';
import { useLanguage } from '../contexts/LanguageContext';
import { ZoomInIcon } from './icons/ZoomInIcon';
import { ZoomOutIcon } from './icons/ZoomOutIcon';
import { LayoutHorizontalIcon } from './icons/LayoutHorizontalIcon';
import { LayoutVerticalIcon } from './icons/LayoutVerticalIcon';
import { FitToPageIcon } from './icons/FitToPageIcon';
import { FitToWidthIcon } from './icons/FitToWidthIcon';

declare const pdfjsLib: any;

interface FileViewerProps {
    file: UploadedFile | null;
    zoom?: number;
    onZoomChange?: (newZoom: number) => void;
    showControls?: boolean;
}

const FileViewer: React.FC<FileViewerProps> = ({ file, zoom: controlledZoom, onZoomChange, showControls = true }) => {
    const { t } = useLanguage();
    const pdfDocRef = useRef<any>(null);
    const [numPages, setNumPages] = useState(0);
    const [isPdfLoading, setIsPdfLoading] = useState(false);
    const [internalZoom, setInternalZoom] = useState(1.0);
    const [pageDimensions, setPageDimensions] = useState<{width: number, height: number}[]>([]);
    const pageRefs = useRef<Map<number, HTMLDivElement>>(new Map());
    const activeRenderTasks = useRef(new Map());
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const imgRef = useRef<HTMLImageElement>(null);
    const [fileUrl, setFileUrl] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);

    const [layoutMode, setLayoutMode] = useState<'vertical' | 'horizontal'>('vertical');
    const [zoomMode, setZoomMode] = useState<'manual' | 'fit-page' | 'fit-width'>('manual');

    const isControlled = controlledZoom !== undefined && onZoomChange !== undefined;
    const zoom = isControlled ? controlledZoom : internalZoom;
    const setZoom = isControlled ? onZoomChange! : setInternalZoom;

    const isPdf = file?.type === 'application/pdf';
    const isImage = file?.type.startsWith('image/');
    const isPptx = file?.type === 'application/vnd.openxmlformats-officedocument.presentationml.presentation';

    const pdfData = useMemo(() => {
        if (!file?.base64) return null;
        try {
            const binaryString = atob(file.base64);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }
            return bytes;
        } catch (e) {
            console.error("Binary decode failed", e);
            return null;
        }
    }, [file?.base64]);

    useEffect(() => {
        if (!file || !pdfData) return;
        const blob = new Blob([pdfData], { type: file.type });
        const url = URL.createObjectURL(blob);
        setFileUrl(url);
        return () => { if (url) URL.revokeObjectURL(url); };
    }, [file, pdfData]);

    const handleZoomIn = () => { setZoomMode('manual'); setZoom(Math.min(zoom + 0.25, 3.0)); };
    const handleZoomOut = () => { setZoomMode('manual'); setZoom(Math.max(zoom - 0.25, 0.25)); };
    const handleZoomReset = () => { setZoomMode('manual'); setZoom(1.0); };
    const handleRangeZoom = (newVal: number) => { setZoomMode('manual'); setZoom(newVal); };
    const handleFitToPage = useCallback(() => setZoomMode('fit-page'), []);
    const handleFitToWidth = useCallback(() => setZoomMode('fit-width'), []);

    const recalculateZoom = useCallback(() => {
        if (zoomMode === 'manual' || !scrollContainerRef.current) return;
        const container = scrollContainerRef.current;
        const padding = 32;
        const containerWidth = container.clientWidth - padding;
        const containerHeight = container.clientHeight - padding;

        let contentWidth = 0;
        let contentHeight = 0;

        if (isPdf && pageDimensions.length > 0) {
            contentWidth = Math.max(...pageDimensions.map(d => d.width));
            contentHeight = Math.max(...pageDimensions.map(d => d.height));
        } else if (isImage && imgRef.current) {
            contentWidth = imgRef.current.naturalWidth;
            contentHeight = imgRef.current.naturalHeight;
        }

        if (contentWidth === 0 || contentHeight === 0) return;

        let newZoom = 1;
        if (zoomMode === 'fit-page') {
            newZoom = Math.min(containerWidth / contentWidth, containerHeight / contentHeight);
        } else if (zoomMode === 'fit-width') {
            newZoom = containerWidth / contentWidth;
        }
        setZoom(Math.max(0.1, newZoom));
    }, [zoomMode, pageDimensions, isPdf, isImage, setZoom]);

    useEffect(() => {
        recalculateZoom();
        window.addEventListener('resize', recalculateZoom);
        return () => window.removeEventListener('resize', recalculateZoom);
    }, [recalculateZoom]);

    useEffect(() => {
        if (!isPdf || !pdfData) return;
        setIsPdfLoading(true);
        setError(null);

        pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js`;

        const loadingTask = pdfjsLib.getDocument({ data: pdfData });
        loadingTask.promise.then(async (pdf: any) => {
            pdfDocRef.current = pdf;
            setNumPages(pdf.numPages);
            const dims = [];
            for (let i = 1; i <= pdf.numPages; i++) {
                const page = await pdf.getPage(i);
                const viewport = page.getViewport({ scale: 1.0 });
                dims.push({ width: viewport.width, height: viewport.height });
            }
            setPageDimensions(dims);
            setIsPdfLoading(false);
        }).catch((err: any) => {
            console.error('PDF Load Error:', err);
            setError(`Failed to load PDF: ${err.message}`);
            setIsPdfLoading(false);
        });

        return () => {
            if (pdfDocRef.current) pdfDocRef.current.destroy();
            pageRefs.current.clear();
            activeRenderTasks.current.forEach(t => t?.cancel());
            activeRenderTasks.current.clear();
        };
    }, [isPdf, pdfData]);

    const renderPage = useCallback(async (pageNum: number) => {
        const pageDiv = pageRefs.current.get(pageNum);
        const canvas = pageDiv?.querySelector('canvas');
        const textLayerDiv = pageDiv?.querySelector('.textLayer') as HTMLDivElement;

        if (!pdfDocRef.current || !canvas || !textLayerDiv) return;
        if (activeRenderTasks.current.has(pageNum)) activeRenderTasks.current.get(pageNum).cancel();

        const page = await pdfDocRef.current.getPage(pageNum);
        const pixelRatio = window.devicePixelRatio || 1;
        const viewport = page.getViewport({ scale: zoom * pixelRatio });

        canvas.height = viewport.height;
        canvas.width = viewport.width;
        canvas.style.height = `${viewport.height / pixelRatio}px`;
        canvas.style.width = `${viewport.width / pixelRatio}px`;

        const context = canvas.getContext('2d', { alpha: false });
        const renderTask = page.render({ canvasContext: context, viewport });
        activeRenderTasks.current.set(pageNum, renderTask);

        try {
            await renderTask.promise;
            textLayerDiv.innerHTML = '';
            textLayerDiv.style.width = canvas.style.width;
            textLayerDiv.style.height = canvas.style.height;
            textLayerDiv.style.setProperty('--scale-factor', String(zoom * pixelRatio));

            const textContent = await page.getTextContent();
            pdfjsLib.renderTextLayer({
                textContent,
                container: textLayerDiv,
                viewport: page.getViewport({ scale: zoom * pixelRatio }),
                textDivs: []
            });
        } catch (err) {
            if (err.name !== 'RenderingCancelledException') console.error("Render failed", err);
        }
    }, [zoom]);

    useEffect(() => {
        if (!isPdf || !pdfDocRef.current || numPages === 0) return;
        for (let i = 1; i <= numPages; i++) renderPage(i);
    }, [isPdf, numPages, zoom, renderPage]);

    if (error) return (
        <div className="flex flex-col items-center justify-center h-full p-8 text-center bg-red-50 dark:bg-red-950/20 rounded-xl">
            <p className="text-red-500 font-bold mb-4">{error}</p>
            {fileUrl && <a href={fileUrl} download={file?.name} className="px-4 py-2 bg-primary text-white rounded-lg shadow hover:bg-primary-dark">Download File</a>}
        </div>
    );

    if (!file) return (
        <div className="flex flex-col items-center justify-center h-full min-h-[400px] text-gray-400 p-8 bg-gray-50 dark:bg-gray-900 rounded-xl">
            <PdfIcon className="w-16 h-16 opacity-10 mb-4" />
            <p className="text-lg font-medium">{t('fileviewer.noMaterial')}</p>
        </div>
    );

    const btnClass = "p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400 transition-colors";
    const activeBtnClass = "p-2 rounded-lg bg-primary/10 text-primary";

    return (
        <div className="flex flex-col h-full bg-gray-100 dark:bg-gray-950 rounded-xl overflow-hidden border dark:border-gray-800">
            {showControls && (isPdf || isImage) && (
                <div className="flex items-center justify-between px-4 py-2 bg-white dark:bg-gray-900 border-b dark:border-gray-800 z-10 flex-shrink-0 shadow-sm">
                    <div className="flex items-center gap-2">
                        <button onClick={handleZoomOut} className={btnClass} title="Zoom Out"><ZoomOutIcon className="w-5 h-5"/></button>
                        <input type="range" min="0.25" max="3" step="0.05" value={zoom} onChange={(e) => handleRangeZoom(parseFloat(e.target.value))} className="w-24 accent-primary" />
                        <button onClick={handleZoomIn} className={btnClass} title="Zoom In"><ZoomInIcon className="w-5 h-5"/></button>
                        <span className="text-xs font-bold text-gray-500 w-12 text-center">{Math.round(zoom * 100)}%</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <button onClick={handleFitToPage} className={zoomMode === 'fit-page' ? activeBtnClass : btnClass} title={t('fileviewer.zoom.fitPage')}><FitToPageIcon className="w-5 h-5"/></button>
                        <button onClick={handleFitToWidth} className={zoomMode === 'fit-width' ? activeBtnClass : btnClass} title={t('fileviewer.zoom.fitWidth')}><FitToWidthIcon className="w-5 h-5"/></button>
                        <div className="w-px h-6 bg-gray-200 dark:bg-gray-700 mx-2"></div>
                        {isPdf && (
                            <>
                                <button onClick={() => setLayoutMode('vertical')} className={layoutMode === 'vertical' ? activeBtnClass : btnClass} title={t('fileviewer.layout.vertical')}><LayoutVerticalIcon className="w-5 h-5"/></button>
                                <button onClick={() => setLayoutMode('horizontal')} className={layoutMode === 'horizontal' ? activeBtnClass : btnClass} title={t('fileviewer.layout.horizontal')}><LayoutHorizontalIcon className="w-5 h-5"/></button>
                            </>
                        )}
                    </div>
                </div>
            )}
            <div ref={scrollContainerRef} className="flex-1 overflow-auto p-4 bg-gray-200 dark:bg-gray-900/50 custom-scrollbar">
                {isPdfLoading && (
                    <div className="flex items-center justify-center h-full">
                        <div className="animate-spin w-8 h-8 border-4 border-primary/30 border-t-primary rounded-full"></div>
                    </div>
                )}
                <div className={`flex ${layoutMode === 'vertical' ? 'flex-col items-center gap-8' : 'flex-row items-start gap-4'} min-h-full`}>
                    {isPdf ? Array.from({ length: numPages }, (_, i) => i + 1).map(pageNum => (
                        <div key={pageNum} ref={el => { if (el) pageRefs.current.set(pageNum, el); }} className="relative bg-white shadow-xl dark:shadow-black/50 overflow-hidden flex-shrink-0" style={{ width: pageDimensions[pageNum - 1] ? `${pageDimensions[pageNum - 1].width * zoom}px` : '100%', height: pageDimensions[pageNum - 1] ? `${pageDimensions[pageNum - 1].height * zoom}px` : 'auto' }}>
                            <canvas className="block w-full h-full" />
                            <div className="textLayer absolute inset-0 pointer-events-auto" />
                        </div>
                    )) : isImage ? (
                        <div className="max-w-full inline-block bg-white shadow-2xl rounded-lg overflow-hidden">
                            <img ref={imgRef} src={fileUrl || ''} alt={file.name} className="block transition-all" style={{ transform: `scale(${zoom})`, transformOrigin: 'top left' }} />
                        </div>
                    ) : (
                        <div className="bg-white dark:bg-gray-800 p-12 rounded-2xl shadow-xl text-center max-w-lg mx-auto mt-10 border dark:border-gray-700">
                            {isPptx ? <PowerPointIcon className="w-20 h-20 mx-auto text-orange-500 mb-6" /> : <PdfIcon className="w-20 h-20 mx-auto text-red-500 mb-6" />}
                            <h3 className="text-xl font-bold">{file.name}</h3>
                            <p className="text-gray-500 my-4">{t('fileviewer.unsupportedType', { type: file.type })}</p>
                            {fileUrl && <a href={fileUrl} download={file.name} className="px-8 py-3 bg-primary text-white font-bold rounded-xl shadow-lg inline-block transition-transform hover:scale-105">{t('fileviewer.downloadFile', { name: file.name })}</a>}
                        </div>
                    )}
                </div>
            </div>
            <style>{`
                .textLayer { position: absolute; left: 0; top: 0; right: 0; bottom: 0; overflow: hidden; opacity: 0.2; line-height: 1.0; white-space: pre; }
                .textLayer:hover { opacity: 1; }
                .textLayer span { color: transparent; position: absolute; white-space: pre; cursor: text; transform-origin: 0% 0%; }
                .textLayer ::selection { background: rgba(0, 0, 255, 0.2); }
                .custom-scrollbar::-webkit-scrollbar { width: 8px; height: 8px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.15); border-radius: 4px; }
                .dark .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); }
            `}</style>
        </div>
    );
};
export default FileViewer;

import { GoogleGenAI, HarmCategory, HarmBlockThreshold, GenerateContentResponse, Type } from "@google/genai";
import type { UserDetails, Lecture, StudyGoal, AgendaItem, SmartPlan, ImagePart, QuizQuestion, QuizType, ChatTurn } from '../types';

// ============================================
// CORE CONFIGURATION
// ============================================

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });

const safetySettings = [
    { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
];

const MODEL = 'gemini-3-flash-preview';

// ============================================
// OPTIMIZED SCHEMAS
// ============================================

const planSlotSchema = {
    type: Type.OBJECT,
    properties: {
        activity: { type: Type.STRING },
        startTime: { type: Type.STRING },
        endTime: { type: Type.STRING },
        type: { type: Type.STRING }, // 'lecture', 'study', 'break', 'free'
        code: { type: Type.STRING },
        location: { type: Type.STRING },
        durationMinutes: { type: Type.NUMBER },
    },
    required: ['activity', 'startTime', 'endTime', 'type']
};

const smartPlanSchema = {
    type: Type.ARRAY,
    items: {
        type: Type.OBJECT,
        properties: {
            day: { type: Type.STRING },
            slots: { type: Type.ARRAY, items: planSlotSchema }
        },
        required: ['day', 'slots']
    }
};

const quizSchema = {
    type: Type.ARRAY,
    items: {
        type: Type.OBJECT,
        properties: {
            question: { type: Type.STRING },
            options: { type: Type.ARRAY, items: { type: Type.STRING } },
            correctAnswer: { type: Type.STRING },
            explanation: { type: Type.STRING },
            topic: { type: Type.STRING },
            type: { type: Type.STRING },
        },
        required: ['question', 'correctAnswer', 'explanation', 'topic', 'type']
    }
};

// ============================================
// FAST PARSER
// ============================================

const parseJSON = <T>(response: GenerateContentResponse, fallback?: T): T => {
    try {
        let text = response.text.trim();
        if (text.startsWith('```')) {
            const start = text.indexOf('{') !== -1 ? text.indexOf('{') : text.indexOf('[');
            const end = text.lastIndexOf('}') !== -1 ? text.lastIndexOf('}') : text.lastIndexOf(']');
            if (start !== -1 && end !== -1) text = text.substring(start, end + 1);
        }
        return JSON.parse(text) as T;
    } catch (e) {
        if (fallback !== undefined) return fallback;
        throw new Error("Failed to parse AI response");
    }
};

// ============================================
// SMART PLAN GENERATION
// ============================================

export const generateSmartPlan = async (
    userDetails: UserDetails,
    lectures: Lecture[],
    studyGoals: StudyGoal[],
    agendaItems: AgendaItem[],
    generalGoals: string,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const prompt = `Act as an expert academic planner. Create a high-performance weekly study plan for ${userDetails.name}.
Lectures: ${JSON.stringify(lectures)}
Goals: ${JSON.stringify(studyGoals)}
Personal: ${JSON.stringify(agendaItems)}
Notes: "${generalGoals}"
Return ONLY JSON array of 7 days (Monday-Sunday). Use "HH:MM AM/PM" format.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: { 
            responseMimeType: 'application/json', 
            responseSchema: smartPlanSchema, 
            temperature: 0.1, 
            safetySettings 
        },
    });
    return parseJSON<SmartPlan>(response, []);
};

export const generatePlanFromImage = async (
    userDetails: UserDetails,
    studyGoals: StudyGoal[],
    agendaItems: AgendaItem[],
    generalGoals: string,
    image: ImagePart,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const prompt = `Extract the class schedule from this image and build an optimized academic plan. 
Include: ${JSON.stringify(studyGoals)}
Agenda: ${JSON.stringify(agendaItems)}
Return ONLY JSON array of 7 days.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: prompt }, image] },
        config: { 
            responseMimeType: 'application/json', 
            responseSchema: smartPlanSchema, 
            temperature: 0.1, 
            safetySettings 
        },
    });
    return parseJSON<SmartPlan>(response, []);
};

// ============================================
// CLASSIFICATION & ANALYSIS
// ============================================

export const isImageTimetable = async (image: ImagePart): Promise<boolean> => {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: "Is this a class schedule? Answer ONLY true/false" }, image] },
        config: { safetySettings, maxOutputTokens: 5 },
    });
    return response.text.trim().toLowerCase().includes('true');
};

export const isStudyMaterial = async (file: ImagePart, options?: { fast: boolean }): Promise<boolean> => {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: "Is this educational material? Answer ONLY true/false" }, file] },
        config: { safetySettings, maxOutputTokens: 5 },
    });
    return response.text.trim().toLowerCase().includes('true');
};

export const isImageAProblem = async (image: ImagePart): Promise<boolean> => {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: "Is this an academic problem? Answer ONLY true/false" }, image] },
        config: { safetySettings, maxOutputTokens: 5 },
    });
    return response.text.trim().toLowerCase().includes('true');
};

export const getDocumentContext = async (file: ImagePart, options?: { fast: boolean }): Promise<string> => {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: "Subject of this material? (1-3 words max)" }, file] },
        config: { safetySettings, maxOutputTokens: 15 },
    });
