const UploadSlides: React.FC<UploadSlidesProps> = ({
  smartPlan, setSmartPlan, activeSession, setActiveSession, setView, addToast,
  learningHubState, setLearningHubState, notes, setNotes,
  showTitle = true, isStudyModeView = false,
  intendedStudyContext, setIntendedStudyContext,
  onAttemptUpload,
}) => {
  const { t } = useLanguage();
  const [chatInput, setChatInput] = useState('');
  const [zoom, setZoom] = useState(1.0);
  const { file, analysisMode, analysisResults, chatHistory, isProcessing, processingMessage } = learningHubState;

  const setAnalysisMode = (mode: AnalysisMode) => setLearningHubState(prev => ({ ...prev, analysisMode: mode }));

  const handleChatSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || !file) return;
    const userMsg = chatInput;
    const history = [...chatHistory];
    setChatInput('');
    setLearningHubState(p => ({ ...p, isProcessing: true, chatHistory: [...p.chatHistory, { user: userMsg, blay: '...' }] }));

    try {
        const filePart: ImagePart = { inlineData: { data: file.base64, mimeType: file.type } };
        const stream = await chatWithDocumentStream(filePart, userMsg, history, file.context);
        let full = '';
        for await (const chunk of stream) {
            full += chunk.text;
            setLearningHubState(p => {
                const h = [...p.chatHistory];
                h[h.length-1].blay = full;
                return { ...p, chatHistory: h };
            });
        }
    } catch {
        addToast(t('toasts.chatError'), 'error');
    } finally { setLearningHubState(p => ({ ...p, isProcessing: false })); }
  };

  const handleAnalysis = async (mode: 'summarize' | 'explain' | 'read') => {
      if (analysisResults[mode]) return setAnalysisMode(mode === 'read' ? 'read-focus' : mode);
      setLearningHubState(p => ({ ...p, isProcessing: true, processingMessage: t(`uploadslides.loading.${mode}` as any) }));
      try {
          const part: ImagePart = { inlineData: { data: file!.base64, mimeType: file!.type } };
          const result = mode === 'summarize' ? await summarizeDocument(part, file!.context) : mode === 'explain' ? await explainDocument(part, file!.context) : await extractTextFromDocument(part);
          setLearningHubState(p => ({ ...p, analysisMode: mode === 'read' ? 'read-focus' : mode, analysisResults: { ...p.analysisResults, [mode]: result } }));
      } catch { addToast("Analysis failed", "error"); }
      finally { setLearningHubState(p => ({ ...p, isProcessing: false })); }
  };

  if (!file) {
      const { getRootProps, getInputProps } = useDropzone({ onDrop: files => onAttemptUpload(files[0]) });
      return (
          <div className="flex flex-col h-full items-center justify-center p-12 bg-white dark:bg-gray-800 rounded-3xl border-4 border-dashed border-gray-300 dark:border-gray-700 hover:border-primary transition-all cursor-pointer" {...getRootProps()}>
              <input {...getInputProps()} />
              <UploadIcon className="w-16 h-16 text-gray-400 mb-6"/>
              <p className="text-xl font-bold text-gray-700 dark:text-gray-300">{t('uploadslides.dropzone')}</p>
          </div>
      );
  }

  return (
      <div className="flex flex-col h-full gap-4">
          <div className="flex-1 grid lg:grid-cols-2 gap-4 min-h-0">
              <FileViewer file={file} zoom={zoom} onZoomChange={setZoom} showControls={!isStudyModeView} />
              <div className="flex flex-col h-full bg-white dark:bg-gray-800 rounded-2xl shadow-xl overflow-hidden border dark:border-gray-700">
                  <div className="p-4 border-b dark:border-gray-700 flex gap-2 overflow-x-auto">
                      <button onClick={() => setAnalysisMode('chat')} className={`px-4 py-2 rounded-xl font-bold text-sm whitespace-nowrap ${analysisMode === 'chat' ? 'bg-primary text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'}`}>Chat</button>
                      <button onClick={() => handleAnalysis('summarize')} className={`px-4 py-2 rounded-xl font-bold text-sm whitespace-nowrap ${analysisMode === 'summarize' ? 'bg-primary text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'}`}>Summary</button>
                      <button onClick={() => handleAnalysis('explain')} className={`px-4 py-2 rounded-xl font-bold text-sm whitespace-nowrap ${analysisMode === 'explain' ? 'bg-primary text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'}`}>Explain</button>
                      <button onClick={() => handleAnalysis('read')} className={`px-4 py-2 rounded-xl font-bold text-sm whitespace-nowrap ${analysisMode === 'read-focus' ? 'bg-primary text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'}`}>Read Aloud</button>
                  </div>
                  <div className="flex-1 overflow-hidden">
                      {analysisMode === 'chat' || analysisMode === 'actions' || analysisMode === 'none' ? (
                          <ChatView chatHistory={chatHistory} chatInput={chatInput} setChatInput={setChatInput} handleChatSubmit={handleChatSubmit} isProcessing={isProcessing} />
                      ) : (
                          <div className="p-6 h-full overflow-y-auto bg-gray-50 dark:bg-gray-950">
                              <RichTextViewer content={analysisResults[analysisMode === 'read-focus' ? 'read' : analysisMode as any] || 'Loading...'} />
                          </div>
                      )}
                  </div>
              </div>
          </div>
      </div>
  );
};
export default UploadSlides;

