const KatexRenderer: React.FC<{ content: string; displayMode: boolean }> = React.memo(({ content, displayMode }) => {
    try {
        const html = katex.renderToString(content, { throwOnError: false, displayMode });
        return <span dangerouslySetInnerHTML={{ __html: html }} />;
    } catch { return <code>{content}</code>; }
});

const RichTextViewer: React.FC<{ content: string; highlightCharIndex?: number }> = React.memo(({ content, highlightCharIndex }) => {
    const renderInlineElements = (line: string) => {
        const inlineRegex = /(\$\$[\s\S]*?\$\$)|(\$.*?\$)|(\*\*.*?\*\*)|(`.*?`)/g;
        const parts = line.split(inlineRegex).filter(Boolean);
        return parts.map((part, index) => {
            if (part.startsWith('$$')) return <KatexRenderer key={index} content={part.slice(2, -2)} displayMode={true} />;
            if (part.startsWith('$')) return <KatexRenderer key={index} content={part.slice(1, -1)} displayMode={false} />;
            if (part.startsWith('**')) return <strong key={index} className="text-gray-900 dark:text-white font-black">{part.slice(2, -2)}</strong>;
            if (part.startsWith('`')) return <code key={index} className="bg-gray-100 dark:bg-gray-700 px-1.5 py-0.5 rounded text-sm font-mono text-primary-dark dark:text-primary-light">{part.slice(1, -1)}</code>;
            return part;
        });
    };

    const blocks = content.split(/(```[\s\S]*?```)/g).filter(Boolean);
    return (
        <div className="prose prose-base dark:prose-invert max-w-none text-left leading-relaxed">
            {blocks.map((block, index) => {
                if (block.startsWith('```')) {
                    const code = block.slice(3, -3).replace(/^[a-zA-Z]+\n/, '');
                    return <pre key={index} className="p-4 bg-gray-900 rounded-xl overflow-x-auto text-xs font-mono text-gray-100 my-4 shadow-inner border border-white/5"><code>{code}</code></pre>;
                }
                const lines = block.split('\n');
                return lines.map((line, i) => line.trim() ? <p key={i} className="my-2">{renderInlineElements(line)}</p> : <br key={i}/>);
            })}
        </div>
    );
});

