const SendIcon = (props: any) => <svg {...props} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13"></line><polygon points="22 2 15 22 11 13 2 9 22 2"></polygon></svg>;

const UploadSlides: React.FC<UploadSlidesProps> = ({
  smartPlan, setSmartPlan, activeSession, setActiveSession, setView, addToast,
  learningHubState, setLearningHubState, notes, setNotes,
  showTitle = true, isStudyModeView = false,
  intendedStudyContext, setIntendedStudyContext,
  onAttemptUpload,
}) => {
  const { t } = useLanguage();
  const [chatInput, setChatInput] = useState('');
  const [zoom, setZoom] = useState(1.0);
  const { file, analysisMode, analysisResults, chatHistory, isProcessing, processingMessage } = learningHubState;

  const setAnalysisMode = (mode: AnalysisMode) => setLearningHubState(prev => ({ ...prev, analysisMode: mode }));

  const handleChatSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || !file) return;
    const userMsg = chatInput;
    const history = [...chatHistory];
    setChatInput('');
    setLearningHubState(p => ({ ...p, isProcessing: true, chatHistory: [...p.chatHistory, { user: userMsg, blay: '...' }] }));

    try {
        const filePart: ImagePart = { inlineData: { data: file.base64, mimeType: file.type } };
        const stream = await chatWithDocumentStream(filePart, userMsg, history, file.context);
        let full = '';
        for await (const chunk of stream) {
            full += chunk.text;
            setLearningHubState(p => {
                const h = [...p.chatHistory];
                h[h.length-1].blay = full;
                return { ...p, chatHistory: h };
            });
        }
    } catch {
        addToast(t('toasts.chatError'), 'error');
    } finally { setLearningHubState(p => ({ ...p, isProcessing: false })); }
  };

  const handleAnalysis = async (mode: 'summarize' | 'explain' | 'read') => {
      if (analysisResults[mode]) return setAnalysisMode(mode === 'read' ? 'read-focus' : mode);
      setLearningHubState(p => ({ ...p, isProcessing: true, processingMessage: t(`uploadslides.loading.${mode}` as any) }));
      try {
          const part: ImagePart = { inlineData: { data: file!.base64, mimeType: file!.type } };
          const result = mode === 'summarize' ? await summarizeDocument(part, file!.context) : mode === 'explain' ? await explainDocument(part, file!.context) : await extractTextFromDocument(part);
          setLearningHubState(p => ({ ...p, analysisMode: mode === 'read' ? 'read-focus' : mode, analysisResults: { ...p.analysisResults, [mode]: result } }));
      } catch { addToast("Analysis failed", "error"); }
      finally { setLearningHubState(p => ({ ...p, isProcessing: false })); }
  };

  if (!file) {
      const { getRootProps, getInputProps } = useDropzone({ onDrop: files => onAttemptUpload(files[0]) });
      return (
          <div className="flex flex-col h-full items-center justify-center p-12 bg-white dark:bg-gray-800 rounded-[2.5rem] border-4 border-dashed border-gray-200 dark:border-gray-700 hover:border-primary transition-all cursor-pointer shadow-inner group" {...getRootProps()}>
              <input {...getInputProps()} />
              <div className="w-24 h-24 bg-gray-50 dark:bg-gray-900 rounded-3xl flex items-center justify-center mb-8 group-hover:scale-110 transition-transform shadow-xl">
                <UploadIcon className="w-12 h-12 text-gray-400 group-hover:text-primary transition-colors"/>
              </div>
              <p className="text-2xl font-black text-gray-700 dark:text-gray-300 uppercase tracking-widest">{t('uploadslides.dropzone')}</p>
              <p className="text-gray-500 mt-2 font-medium">PDF, PPTX, Images (Max 25MB)</p>
          </div>
      );
  }

  return (
      <div className="flex flex-col h-full gap-6">
          <div className="flex-1 grid lg:grid-cols-2 gap-6 min-h-0">
              <FileViewer file={file} zoom={zoom} onZoomChange={setZoom} showControls={!isStudyModeView} />
              <div className="flex flex-col h-full bg-white dark:bg-gray-900 rounded-[2.5rem] shadow-2xl overflow-hidden border-2 border-gray-100 dark:border-gray-800">
                  <div className="p-4 bg-gray-50 dark:bg-gray-800/50 border-b-2 dark:border-gray-800 flex gap-2 overflow-x-auto no-scrollbar">
                      <button onClick={() => setAnalysisMode('chat')} className={`px-6 py-2.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${analysisMode === 'chat' || analysisMode === 'actions' || analysisMode === 'none' ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'bg-white dark:bg-gray-900 text-gray-500 hover:text-primary'}`}>Chat</button>
                      <button onClick={() => handleAnalysis('summarize')} className={`px-6 py-2.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${analysisMode === 'summarize' ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'bg-white dark:bg-gray-900 text-gray-500 hover:text-primary'}`}>Summary</button>
                      <button onClick={() => handleAnalysis('explain')} className={`px-6 py-2.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${analysisMode === 'explain' ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'bg-white dark:bg-gray-900 text-gray-500 hover:text-primary'}`}>Explain</button>
                      <button onClick={() => handleAnalysis('read')} className={`px-6 py-2.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${analysisMode === 'read-focus' ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'bg-white dark:bg-gray-900 text-gray-500 hover:text-primary'}`}>Read Aloud</button>
                  </div>
                  <div className="flex-1 overflow-hidden">
                      {analysisMode === 'chat' || analysisMode === 'actions' || analysisMode === 'none' ? (
                          <ChatView chatHistory={chatHistory} chatInput={chatInput} setChatInput={setChatInput} handleChatSubmit={handleChatSubmit} isProcessing={isProcessing} />
                      ) : (
                          <div className="p-8 h-full overflow-y-auto bg-gray-50 dark:bg-gray-950 custom-scrollbar">
                              <RichTextViewer content={analysisResults[analysisMode === 'read-focus' ? 'read' : analysisMode as any] || 'Analyzing...'} />
                          </div>
                      )}
                  </div>
              </div>
          </div>
      </div>
  );
};
