const Progression: React.FC<ProgressionProps> = ({ plan, trackedData, userDetails }) => {
  const { t } = useLanguage();
  const { colorTheme } = useColorTheme();
  const [weeklySnapshots, setWeeklySnapshots] = useState<WeeklySnapshot[]>([]);
  const [lastCheckedDate, setLastCheckedDate] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'current' | 'history'>('current');

  useEffect(() => {
    const loadSnapshots = async () => {
        const data = await storageService.loadItem<WeeklySnapshot[]>('weekly-snapshots-v3');
        if (data) setWeeklySnapshots(data);
    };
    loadSnapshots();
  }, []);

  const stats = useMemo(() => {
    if (!plan) return null;
    const totals = { study: 0, lecture: 0, agenda: 0, break: 0, free: 0 };
    const studyBySubject = new Map<string, number>();
    for (const day of plan) {
      for (const slot of day.slots) {
        if (!slot.startTime || !slot.endTime) continue;
        const duration = timeToMinutes(slot.endTime) - timeToMinutes(slot.startTime);
        if (duration <= 0) continue;
        const type = slot.type || ActivityType.FREE;
        if (type === ActivityType.STUDY) {
            totals.study += duration;
            studyBySubject.set(slot.activity, (studyBySubject.get(slot.activity) || 0) + duration);
        } else if (type === ActivityType.LECTURE) totals.lecture += duration;
        else if (type === ActivityType.AGENDA) totals.agenda += duration;
        else if (type === ActivityType.BREAK) totals.break += duration;
        else totals.free += duration;
      }
    }
    const dayNames = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    const currentWeekDailyHours = dayNames.map(day => ({ day: day.slice(0, 3), hours: 0 }));
    return {
      totalHours: { study: (totals.study / 60).toFixed(1), lecture: (totals.lecture / 60).toFixed(1), agenda: (totals.agenda / 60).toFixed(1), break: (totals.break / 60).toFixed(1), free: (totals.free / 60).toFixed(1) },
      trackedVsScheduled: Array.from(studyBySubject.keys()).map(s => ({ subject: s, scheduledHours: studyBySubject.get(s)! / 60, trackedHours: 0 })),
      currentWeekDailyHours
    };
  }, [plan, trackedData, t]);

  useEffect(() => {
    const checkAndSaveWeeklySnapshot = async () => {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const todayStr = today.toISOString().split('T')[0];
      if (todayStr === lastCheckedDate) return;
      setLastCheckedDate(todayStr);
      if (today.getDay() === 1 && plan && userDetails) {
          const snapshot: WeeklySnapshot = { weekStart: todayStr, weekEnd: todayStr, dailyTrackedHours: [], totalTrackedHours: 0, totalScheduledHours: 1, comment: '', aiAdvice: 'Good start!', timestamp: Date.now() };
          const updated = [...weeklySnapshots, snapshot];
          setWeeklySnapshots(updated);
          await storageService.saveItem('weekly-snapshots-v3', updated);
      }
    };
    if (plan && userDetails) checkAndSaveWeeklySnapshot();
  }, [plan, userDetails, lastCheckedDate, weeklySnapshots]);

  if (!plan || !stats) {
    return (
      <div className="max-w-4xl mx-auto bg-white dark:bg-gray-900 rounded-2xl shadow-lg p-10 text-center animate-fade-in">
        <div className="w-20 h-20 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-6"><ChartBarIcon className="w-10 h-10 text-primary" /></div>
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-2">{t('progression.title')}</h2>
        <p className="text-gray-500 dark:text-gray-400 max-w-sm mx-auto">{t('progression.noPlan')}</p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-20 animate-fade-in">
       <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
         <div>
            <h2 className="text-4xl font-black text-gray-900 dark:text-white tracking-tight">{t('progression.title')}</h2>
            <p className="text-gray-500 dark:text-gray-400 mt-2 font-medium">{t('progression.subtitle')}</p>
         </div>
       </div>
       <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <StatsCard title="Current Allocation" icon={<ClockIcon className="w-5 h-5"/>} className="lg:col-span-1">
                <div className="space-y-6">
                    <div className="p-4 bg-primary/5 dark:bg-primary/10 rounded-2xl">
                        <p className="text-xs font-black uppercase tracking-widest text-primary mb-1">{t('progression.totalStudy')}</p>
                        <p className="font-black text-4xl text-gray-900 dark:text-white">{stats.totalHours.study}h</p>
                    </div>
                </div>
            </StatsCard>
            <StatsCard title="Daily Progress" icon={<ChartBarIcon className="w-5 h-5"/>} className="lg:col-span-2">
                <WeeklyBarGraph dailyData={stats.currentWeekDailyHours} />
            </StatsCard>
       </div>
    </div>
  );
};
export default Progression;

import React, { useState, useEffect, useRef } from 'react';
import { useLanguage } from '../contexts/LanguageContext.tsx';
