const PieChart: React.FC<{ data: Record<string, number> }> = ({ data }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const chartInstance = useRef<any>(null);

    useEffect(() => {
        if (!canvasRef.current || !window.Chart) return;

        const ctx = canvasRef.current.getContext('2d');
        if (!ctx) return;

        if (chartInstance.current) {
            chartInstance.current.destroy();
        }

        const labels = Object.keys(data);
        const values = Object.values(data);

        if (labels.length === 0) return;

        const colors = {
            study: '#2563eb',
            lecture: '#7c3aed',
            agenda: '#ea580c',
            break: '#16a34a',
            free: '#4b5563',
        };

        const bgColors = labels.map(label => {
            const key = label.toLowerCase() as keyof typeof colors;
            return colors[key] || '#94a3b8';
        });

        chartInstance.current = new window.Chart(ctx, {
            type: 'doughnut',
            data: {
                labels: labels.map(l => l.charAt(0).toUpperCase() + l.slice(1)),
                datasets: [{
                    data: values,
                    backgroundColor: bgColors,
                    borderWidth: 0,
                    hoverOffset: 15
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                cutout: '70%',
                plugins: {
                    legend: {
                        position: 'bottom',
                        labels: {
                            usePointStyle: true,
                            padding: 20,
                            font: { weight: 'bold', size: 12 },
                            color: document.documentElement.classList.contains('dark') ? '#94a3b8' : '#475569'
                        }
                    },
                    tooltip: {
                        backgroundColor: '#1e293b',
                        padding: 12,
                        titleFont: { size: 14, weight: 'bold' },
                        callbacks: {
                            label: (context: any) => ` ${context.label}: ${(context.raw / 60).toFixed(1)}h`
                        }
                    }
                }
            }
        });

        return () => {
            if (chartInstance.current) chartInstance.current.destroy();
        };
    }, [data]);

    return (
        <div className="relative h-64 w-full">
            <canvas ref={canvasRef}></canvas>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none mb-10">
                <span className="text-xs font-black text-gray-400 uppercase tracking-widest">Time</span>
                <span className="text-2xl font-black text-gray-800 dark:text-white">Breakdown</span>
            </div>
        </div>
    );
};

