            </div>

            <div className="flex bg-gray-200 dark:bg-gray-800 p-1.5 rounded-2xl shadow-inner w-full md:w-auto">
                <button 
                    onClick={() => setActiveTab('current')}
                    className={`flex-1 md:flex-none px-8 py-3 rounded-xl font-black text-sm uppercase tracking-widest transition-all ${activeTab === 'current' ? 'bg-white dark:bg-gray-700 shadow-xl text-primary' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
                >
                    Current Week
                </button>
                <button 
                    onClick={() => setActiveTab('history')}
