export const chatWithDocumentStream = async (
    file: ImagePart | null, 
    userMessage: string, 
    history: ChatTurn[], 
    context: string,
    smartPlan?: SmartPlan | null
) => {
    const chatHistory = history.map(turn => ([{ role: 'user', parts: [{ text: turn.user }] }, { role: 'model', parts: [{ text: turn.blay }] }])).flat();
    const systemInstruction = `You are Blay, an expert AI tutor. Context: ${context}. ${smartPlan ? `User's Schedule: ${JSON.stringify(smartPlan)}` : ''}. Use markdown and LaTeX for math.`;
    const userParts: any[] = [{ text: userMessage }];
    if (file) userParts.push(file);
    const contents: any = [...chatHistory, { role: 'user', parts: userParts }];
    return await ai.models.generateContentStream({ model: FLASH_MODEL, contents, config: { systemInstruction, safetySettings } });
};

