    if (chartRef.current) {
        chartRef.current.destroy();
    }

    const ctx = canvasRef.current.getContext('2d');
    const colors: Record<string, string> = {
        study: '#2563eb',
        lecture: '#7c3aed',
        agenda: '#ea580c',
