import { 
    doc, 
    getDoc, 
    setDoc, 
    collection, 
    query, 
    orderBy, 
    limit, 
    onSnapshot,
    writeBatch,
    runTransaction,
    increment,
    serverTimestamp,
    arrayUnion,
    arrayRemove
} from 'firebase/firestore';
import { db, auth } from './firebase';

interface GlobalStats {
    totalRatings: number;
    totalRatingSum: number;
    totalComments: number;
    activeUsers: number;
    studyMaterials: number;
}

export const globalFeedbackService = {
    /**
     * Registers a new user and increments the global active user count.
     * Uses atomic increment to ensure accuracy across multiple signups.
     */
    registerUser: async (userId: string, userName: string, email: string): Promise<void> => {
        if (!navigator.onLine) return;
        const userRef = doc(db, "users", userId);
        const statsRef = doc(db, "feedback_stats", "summary");

        try {
            const userDoc = await getDoc(userRef);
            if (!userDoc.exists()) {
                // Create user profile
                await setDoc(userRef, { 
                    id: userId, 
                    name: userName, 
                    email, 
                    joinedAt: serverTimestamp(), 
                    uploadedMaterials: 0 
                });

                // Atomically increment active users
                await setDoc(statsRef, { 
                    activeUsers: increment(1) 
                }, { merge: true });

                console.log("✅ Global: Active user count increased.");
            }
        } catch (e) {
            console.error("❌ GlobalFeedback Error (registerUser):", e);
        }
    },

    /**
     * Increments the global study material count whenever a user creates or uploads material.
     */
    trackMaterialUpload: async (userId: string): Promise<void> => {
        if (!navigator.onLine) return;
        const userRef = doc(db, "users", userId);
        const statsRef = doc(db, "feedback_stats", "summary");

        try {
            const batch = writeBatch(db);
            // Track per-user upload count
            batch.set(userRef, { uploadedMaterials: increment(1) }, { merge: true });
            // Track global app material count
            batch.set(statsRef, { studyMaterials: increment(1) }, { merge: true });

            await batch.commit();
            console.log("✅ Global: Study material count increased.");
        } catch (e) {
            console.error("❌ GlobalFeedback Error (trackMaterialUpload):", e);
        }
    },

    /**
     * Subscribes to global app stats including user counts, material counts, and ratings.
     */
    subscribeToGlobalStats: (callback: (stats: any) => void) => {
        const statsRef = doc(db, "feedback_stats", "summary");
        return onSnapshot(statsRef, (docSnap) => {
            if (docSnap.exists()) {
                const s = docSnap.data() as GlobalStats;
                const totalRatings = s.totalRatings || 0;
                const totalRatingSum = s.totalRatingSum || 0;
                const avg = totalRatings > 0 ? totalRatingSum / totalRatings : 0;

                callback({ 
                    ...s, 
                    activeUsers: s.activeUsers || 0,
                    studyMaterials: s.studyMaterials || 0,
                    totalRatings: totalRatings,
                    averageRating: parseFloat(avg.toFixed(1)), 
                    satisfaction: Math.round((avg / 5) * 100) 
                });
            } else {
                // Default if doc doesn't exist yet
                callback({
                    activeUsers: 0,
                    studyMaterials: 0,
                    totalRatings: 0,
                    totalComments: 0,
                    averageRating: 0,
                    satisfaction: 0
                });
            }
        });
    },

    subscribeToComments: (callback: (comments: any[]) => void) => {
        const q = query(collection(db, "comments"), orderBy("timestamp", "desc"), limit(50));
        return onSnapshot(q, (snap) => callback(snap.docs.map(d => ({ id: d.id, ...d.data() }))));
    },

    postComment: async (userId: string, userName: string, text: string) => {
        if (!navigator.onLine) throw new Error("Offline");
        const commentRef = doc(collection(db, "comments"));
        const statsRef = doc(db, "feedback_stats", "summary");
        const batch = writeBatch(db);

        batch.set(commentRef, { 
            userId, 
            userName, 
            text, 
            timestamp: serverTimestamp(), 
            likes: 0 
        });
        batch.set(statsRef, { totalComments: increment(1) }, { merge: true });

        await batch.commit();
    },

    submitRating: async (userId: string, rating: number) => {
        if (!navigator.onLine) throw new Error("Offline");
        await runTransaction(db, async (transaction) => {
            const userRatingRef = doc(db, "users_feedback", userId);
            const statsRef = doc(db, "feedback_stats", "summary");

            const userSnap = await transaction.get(userRatingRef);
            if (userSnap.exists() && userSnap.data()?.rating > 0) {
                throw new Error("You have already rated the app.");
            }

            // Atomically update global totals
            transaction.set(statsRef, { 
                totalRatings: increment(1), 
                totalRatingSum: increment(rating) 
            }, { merge: true });

            // Save user's specific rating to prevent double-voting
            transaction.set(userRatingRef, { rating }, { merge: true });
        });
    },

    subscribeToUserFeedback: (userId: string, callback: (data: any) => void) => {
        return onSnapshot(doc(db, "users_feedback", userId), (d) => callback(d.data()));
    },

    likeComment: async (userId: string, commentId: string) => {
        if (!navigator.onLine) return;
        const feedbackRef = doc(db, "users_feedback", userId);
        const commentRef = doc(db, "comments", commentId);

        await runTransaction(db, async (tx) => {
            const f = await tx.get(feedbackRef);
            const likes = f.data()?.likedComments || [];
            const liked = likes.includes(commentId);

            tx.set(feedbackRef, { 
                likedComments: liked ? arrayRemove(commentId) : arrayUnion(commentId) 
            }, { merge: true });

            tx.update(commentRef, { 
                likes: increment(liked ? -1 : 1) 
            });
        });
    }
};

