  const [examPrepState, setExamPrepState] = useState<ExamPrepState>({ mode: 'quiz', topic: '', numQuestions: 5, quizType: QuizType.MCQ, uploadedFiles: [], focusArea: '', isVerifying: false, questionImage: null, questionText: '', solution: null, outputFormat: 'steps', programmingLanguage: 'python', graphInterval: '', graphYInterval: '', graphConfig: null });
  const [profileEditState, setProfileEditState] = useState<ProfileEditState>({ isEditing: false, details: null });
  const [notesViewState, setNotesViewState] = useState<NotesViewState>({ currentNoteId: null, searchTerm: '' });
  const [reportDraft, setReportDraft] = useState<ReportDraft>({ category: 'bug', description: '', attachment: null, contactEmail: '', contactWhatsApp: '' });

  const [showNotifPrompt, setShowNotifPrompt] = useState(false);

  const addToast = useCallback((message: string, type: Toast['type']) => {
    const newToast = { id: Date.now(), message, type };
    setToasts(prev => [...prev, newToast]);
  }, []);

  const persistAllState = useCallback(async () => {
    if (!userDetails?.email) return;
    const userId = userDetails.id || userDetails.email;
    const emailKey = `${USER_KEY_PREFIX}${userDetails.email}`;

    const localUserData = {
        userDetails, smartPlan, savedTimetables, notes,
        notificationSettings, trackedData, uploadedMaterials,
        courseCodeMap,
        quizState: { quiz: quizState.quiz, currentQuestionIndex: quizState.currentQuestionIndex, userAnswers: quizState.userAnswers },
        learningHubState: { ...learningHubState, isProcessing: false },
        dashboardInputs: { ...dashboardInputs, imageFile: null }
    };

    await storageService.saveItem(emailKey, localUserData);

    const cloudUserData = JSON.parse(JSON.stringify(localUserData));
    if (cloudUserData.learningHubState?.file) cloudUserData.learningHubState.file.base64 = ""; 
    if (cloudUserData.dashboardInputs) {
        cloudUserData.dashboardInputs.imagePreview = null;
        cloudUserData.dashboardInputs.imageFile = null;
    }
    await storageService.syncUserToCloud(userId, cloudUserData);
  }, [userDetails, smartPlan, savedTimetables, notes, notificationSettings, trackedData, quizState, uploadedMaterials, courseCodeMap, learningHubState, dashboardInputs]);

    const loadUserData = useCallback(async (user: UserDetails) => {
        const emailKey = `${USER_KEY_PREFIX}${user.email}`;
        const userData = await storageService.loadItem<any>(emailKey);

        const applyState = (data: any) => {
            const finalUserDetails = { ...user, ...(data.userDetails || {}), usage: (data.userDetails?.usage || user.usage || initializeUsage()) };
            setUserDetails(finalUserDetails);
            setSmartPlan(data.smartPlan || null);
            setSavedTimetables(data.savedTimetables || []);
            setNotes(data.notes || []);
            setTrackedData(data.trackedData || []);
            setUploadedMaterials(data.uploadedMaterials || []);
            setNotificationSettings(data.notificationSettings || defaultNotificationSettings);
            setCourseCodeMap(data.courseCodeMap || {});
            if (data.quizState && data.quizState.quiz?.length > 0) setQuizState({ ...defaultQuizState, ...data.quizState, feedback: null, summary: null });
            if (data.learningHubState) setLearningHubState(prev => ({ ...prev, ...data.learningHubState, isProcessing: false }));
            if (data.dashboardInputs) setDashboardInputs(prev => ({ ...prev, ...data.dashboardInputs, imageFile: null }));
        };
        applyState(userData || {});
    }, []);

    const checkAndRun = async (
        feature: FeatureName,
        action: (...args: any[]) => Promise<void> | void,
        ...args: any[]
    ) => {
        if (!userDetails) return;
        try {
            await action(...args);
            setUserDetails(prev => prev ? { ...prev, usage: incrementUsage(prev.usage, feature) } : null);
            return true;
        } catch (e) {
            console.error(`Feature ${feature} error:`, e);
            return false; 
        }
    };

    const handleNewMaterialUpload = useCallback(async (fileToProcess: File) => {
        if (!userDetails) return;
        setLearningHubState(prev => ({...prev, isProcessing: true, processingMessage: t('uploadslides.verifying')}));

        try {
            const context = intendedStudyContext ? intendedStudyContext.fromSlot.activity : undefined;

            let base64String: string;
            let mimeType = fileToProcess.type;
            let finalSize = fileToProcess.size;

            if (fileToProcess.type.startsWith('image/')) {
                const resized = await processAndResizeImage(fileToProcess);
                base64String = resized.base64;
                mimeType = resized.mimeType;
                finalSize = atob(base64String).length;
            } else {
                base64String = await new Promise<string>((resolve, reject) => {
                    const reader = new FileReader();
                    reader.readAsDataURL(fileToProcess);
                    reader.onload = () => resolve((reader.result as string).split(',')[1]);
                    reader.onerror = error => reject(error);
                });
            }
            const filePart: ImagePart = { inlineData: { data: base64String, mimeType: mimeType } };

            const isMaterial = await isStudyMaterial(filePart, { fast: true });
            if (!isMaterial) {
                throw new Error(t('examprep.error.notStudyMaterial', { fileName: fileToProcess.name }));
            }

            let fileContext = context;
            if (!fileContext) {
                setLearningHubState(prev => ({ ...prev, processingMessage: t('uploadslides.extractingContext') }));
                fileContext = await getDocumentContext(filePart, { fast: true });
            }

            const processedFile: UploadedFile = {
                name: fileToProcess.name,
                type: mimeType,
                size: finalSize,
                base64: base64String,
                context: fileContext,
            };

            setLearningHubState(prev => ({ ...prev, file: processedFile, analysisMode: 'actions', analysisResults: { summarize: null, explain: null, read: null }, chatHistory: [] }));

            const newMaterial: UploadedMaterialInfo = {
                name: processedFile.name,
                type: processedFile.type,
                size: processedFile.size,
                context: processedFile.context,
                uploadedAt: new Date().toISOString()
            };

            // CRITICAL: Global material tracking must be called outside the setState functional updater
            if (userDetails.id) {
                globalFeedbackService.trackMaterialUpload(userDetails.id).catch(console.error);
            }

            setUploadedMaterials(prevMaterials => {
                const isNew = !prevMaterials.some(m => m.name === newMaterial.name && m.size === newMaterial.size);
                if (isNew) {
                    return [...prevMaterials, newMaterial];
                }
                return prevMaterials;
            });

        } catch (error: any) {
            addToast(error.message, 'error');
            throw error;
        } finally {
            setLearningHubState(prev => ({...prev, isProcessing: false, processingMessage: ''}));
        }
    }, [addToast, t, userDetails, intendedStudyContext]);

    const handleSavePlanAttempt = (planName: string) => {
        checkAndRun('timetables', () => {
            if (!smartPlan) return;
            const newPlan: StoredPlan = {
                id: Date.now().toString(),
                name: planName,
                createdAt: new Date().toISOString(),
                plan: smartPlan,
                isFavourite: false,
            };
            setSavedTimetables(prev => [...prev, newPlan]);
            addToast(t('toasts.planSaved'), 'success');
        });
    };

    const handleNewMaterialUploadAttempt = (file: File) => {
        checkAndRun('uploads', () => handleNewMaterialUpload(file));
    };

    const handleGenerateQuizAttempt = (apiAction: () => Promise<void>) => {
        checkAndRun('quizzes', apiAction);
    };

    const handleSolveProblemAttempt = (apiAction: () => Promise<void>) => {
        checkAndRun('solves', apiAction);
    };

    const handleBreakCompletion = (skipped: boolean) => {
        const breakSession = activeSession;
        if (!breakSession || breakSession.type !== 'break') {
            setActiveSession(null);
            setView('dashboard');
            return;
        }

        if (breakSession.postBreakView) {
            setActiveSession(null);
            setView(breakSession.postBreakView);
            return;
        }

        if (!smartPlan || !breakSession.day) {
            setActiveSession(null);
            setView('dashboard');
            return;
        }

        const dayPlan = smartPlan.find(d => d.day === breakSession.day);
        if (!dayPlan) {
            setActiveSession(null);
            setView('dashboard');
            return;
        }

        const sortedSlots = [...dayPlan.slots].sort((a,b) => timeToMinutes(a.startTime) - timeToMinutes(b.startTime));
        const breakIndex = sortedSlots.findIndex(s => s.startTime === breakSession.fromSlot.startTime && s.activity === breakSession.fromSlot.activity);

        if (breakIndex !== -1 && breakIndex + 1 < sortedSlots.length) {
            const nextSlot = sortedSlots[breakIndex + 1];

            if (nextSlot.type === ActivityType.STUDY) {
                const now = Date.now();
                const duration = timeToMinutes(nextSlot.endTime) - timeToMinutes(nextSlot.startTime);
                const nextNextSlot = breakIndex + 2 < sortedSlots.length ? sortedSlots[breakIndex + 2] : null;

                const newSession: ActiveSession = {
                    startTime: now,
                    endTime: now + duration * 60 * 1000,
                    subject: nextSlot.activity,
                    type: ActivityType.STUDY,
                    fromSlot: nextSlot,
                    nextSlot: nextNextSlot,
                    durationMinutes: duration,
                    day: breakSession.day,
                };
                setActiveSession(newSession);
                return;
            }
        }

        setActiveSession(null);
        setView('dashboard');
    };

    const tutorialVideoUrl = 'https://youtu.be/f14AwLpLb9E';

    useEffect(() => {
        const init = async () => {
            try {
                const user = await getCurrentUser();
                const welcome = await storageService.loadItem<boolean>('welcomeComplete');
                const lastView = await storageService.loadItem<number>('lastFeedbackViewedTime');

                setWelcomeComplete(welcome || false);
                if (lastView) setLastFeedbackViewedTime(lastView);

                if (user) {
                    await loadUserData(user);
                    setIsLoggedIn(true);
                }
            } catch (error) {
                console.error("Initialization error:", error);
            } finally {
                setTimeout(() => setIsInitializing(false), 100);
            }
        };
        init();
    }, [loadUserData]);

  useEffect(() => {
    const handler = setTimeout(() => { if (isLoggedIn) persistAllState(); }, 2000); 
    return () => clearTimeout(handler);
  }, [isLoggedIn, persistAllState]);

  useEffect(() => {
    if (view === 'feedback') {
        const now = Date.now();
        setUnreadFeedbackCount(0);
        setLastFeedbackViewedTime(now);
        storageService.saveItem('lastFeedbackViewedTime', now);
    }
  }, [view]);

  const handleLogin = async (user: UserDetails) => {
    await loadUserData(user);
    setIsLoggedIn(true);
  };

  const handleLogout = async () => {
    await persistAllState(); 
    await logout();
    setUserDetails(null);
    setIsLoggedIn(false);
    setSmartPlan(null);
    setSavedTimetables([]);
    setNotes([]);
    setActiveSession(null);
    setLearningHubState({ file: null, analysisMode: 'none', analysisResults: { summarize: null, explain: null, read: null }, chatHistory: [], isProcessing: false });
    addToast(t('auth.logoutSuccess'), 'info');
  };

  const handleWelcomeComplete = async () => {
      setWelcomeComplete(true);
      await storageService.saveItem('welcomeComplete', true);
  };

  if (isInitializing) {
      return (
          <div className="flex flex-col h-screen h-[100dvh] bg-gray-100 dark:bg-gray-900 items-center justify-center">
              <div className="relative">
                  <div className="w-16 h-16 border-4 border-gray-200 dark:border-gray-700 border-t-primary rounded-full animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center"><LogoIcon className="w-8 h-8 text-primary animate-pulse" /></div>
              </div>
              <h1 className="mt-4 text-xl font-bold text-gray-800 dark:text-white tracking-wide">EduBlay</h1>
          </div>
      );
  }

  if (!isLoggedIn) {
    if (!welcomeComplete) return <Welcome onProceed={handleWelcomeComplete} />;
    return <SignUp onLogin={handleLogin} />;
  }

  if (activeSession?.type === 'study') {
     return <FocusedStudyView session={activeSession!} setSession={setActiveSession} addToast={addToast} trackedData={trackedData} setTrackedData={setTrackedData} setView={setView} learningHubState={learningHubState} setLearningHubState={setLearningHubState} />;
  }

  return (
    <div className="flex h-screen h-[100dvh] bg-gray-100 dark:bg-gray-900 text-gray-900 dark:text-gray-100 overflow-hidden">
      <NotificationManager plan={smartPlan} settings={notificationSettings} />
      <ToastContainer toasts={toasts} onDismiss={(id) => setToasts(prev => prev.filter(t => t.id !== id))} />
      <Sidebar view={view} setView={setView} isOpen={sidebarOpen} setOpen={setSidebarOpen} userDetails={userDetails} unreadFeedbackCount={unreadFeedbackCount} />
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        {showNotifPrompt && <NotificationPrompt settings={notificationSettings} setSettings={setNotificationSettings} />}
        <Header toggleSidebar={() => setSidebarOpen(!sidebarOpen)} userDetails={userDetails} setView={setView} addToast={addToast} handleLogout={handleLogout} />
        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 dark:bg-gray-900 p-4 sm:p-6 lg:p-8">
          {(() => {
              if (view === 'collaborative') return <CollaborativeSession userDetails={userDetails} addToast={addToast} onActionAttempt={(a) => a()} activeCode={activeCode} setActiveCode={setActiveCode} notes={notes} setNotes={setNotes} />;
              switch (view) {
                case 'dashboard': return <Dashboard setSmartPlan={setSmartPlan} smartPlan={smartPlan} userDetails={userDetails} setUserDetails={setUserDetails} savedTimetables={savedTimetables} setSavedTimetables={setSavedTimetables} addToast={addToast} setActiveSession={setActiveSession} trackedData={trackedData} setTrackedData={setTrackedData} generationState={generationState} setGenerationState={setGenerationState} dashboardInputs={dashboardInputs} setDashboardInputs={setDashboardInputs} setView={setView} setIntendedStudyContext={setIntendedStudyContext} setLearningHubState={setLearningHubState} courseCodeMap={courseCodeMap} setCourseCodeMap={setCourseCodeMap} onSavePlanAttempt={handleSavePlanAttempt} />;
                case 'profile': return <Profile userDetails={userDetails} setUserDetails={setUserDetails} addToast={addToast} profileEditState={profileEditState} setProfileEditState={setProfileEditState} />;
                case 'mytimetables': return <MyTimetables savedTimetables={savedTimetables} setSavedTimetables={setSavedTimetables} onLoadPlan={(plan) => { setSmartPlan(plan); setView('dashboard'); }} addToast={addToast} userDetails={userDetails} />;
                case 'progression': return <Progression plan={smartPlan} trackedData={trackedData} userDetails={userDetails} />;
                case 'notes': return <Notes notes={notes} setNotes={setNotes} notesViewState={notesViewState} setNotesViewState={setNotesViewState} userDetails={userDetails} onMaterialTracked={() => { if(userDetails?.id) globalFeedbackService.trackMaterialUpload(userDetails.id).catch(console.error); }} />;
                case 'uploadslides': return <UploadSlides smartPlan={smartPlan} setSmartPlan={setSmartPlan} activeSession={activeSession} setActiveSession={setActiveSession} setView={setView} addToast={addToast} learningHubState={learningHubState} setLearningHubState={setLearningHubState} notes={notes} setNotes={setNotes} intendedStudyContext={intendedStudyContext} setIntendedStudyContext={setIntendedStudyContext} onAttemptUpload={(f) => handleNewMaterialUploadAttempt(f)} />;
                case 'examprep': return <ExamPrep addToast={addToast} setView={setView} generationState={generationState} setGenerationState={setGenerationState} quizState={quizState} setQuizState={setQuizState} notes={notes} setNotes={setNotes} examPrepState={examPrepState} setExamPrepState={setExamPrepState} onGenerateQuizAttempt={handleGenerateQuizAttempt} onSolveProblemAttempt={handleSolveProblemAttempt} />;
                case 'language': return <LanguageSettings />;
                case 'theme': return <ThemeSettings />;
                case 'notification': return <NotificationSettingsComponent settings={notificationSettings} setSettings={setNotificationSettings} />;
                case 'settings': return <Settings addToast={addToast} handleLogout={handleLogout} userDetails={userDetails} setShowUpgradeModal={() => {}} />;
                case 'report': return <Reports userDetails={userDetails} reportDraft={reportDraft} setReportDraft={setReportDraft} addToast={addToast} />;
                case 'feedback': return <Feedback userDetails={userDetails} addToast={addToast} />;
                case 'help': return <Help setView={setView} />;
                case 'about': return <About setView={setView} />;
                case 'library': return <Library />;
                case 'terms': return <Terms />;
                case 'tutorial': return <Tutorial addToast={addToast} tutorialVideoUrl={tutorialVideoUrl} />;
                default: return <div>{t('common.notFound')}</div>;
              }
          })()}
        </main>
      </div>
       {activeSession?.type === 'break' && <BreakView session={activeSession} onEnd={handleBreakCompletion} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import type { Note, NotesViewState, UserDetails } from '../types';
import { StarIcon } from './icons/StarIcon';
import { TrashIcon } from './icons/TrashIcon';
import { PlusIcon } from './icons/PlusIcon';
import { useLanguage } from '../contexts/LanguageContext';
import ConfirmationModal from './ConfirmationModal';

interface NotesProps {
    notes: Note[];
    setNotes: (notes: Note[]) => void;
    notesViewState: NotesViewState;
    setNotesViewState: React.Dispatch<React.SetStateAction<NotesViewState>>;
    userDetails?: UserDetails | null;
    onMaterialTracked?: () => void;
}

const Notes: React.FC<NotesProps> = ({ notes, setNotes, notesViewState, setNotesViewState, onMaterialTracked }) => {
    const [noteToDelete, setNoteToDelete] = useState<Note | null>(null);
    const { t } = useLanguage();

    const { currentNoteId, searchTerm } = notesViewState;

    const setCurrentNoteId = (id: string | null) => {
        setNotesViewState(prev => ({ ...prev, currentNoteId: id }));
    };

    const setSearchTerm = (term: string) => {
        setNotesViewState(prev => ({ ...prev, searchTerm: term }));
    };

    const currentNote = notes.find(n => n.id === currentNoteId) || null;

    useEffect(() => {
        const sortedNotes = [...notes].sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
        if (sortedNotes.length > 0 && !currentNoteId) {
            setCurrentNoteId(sortedNotes[0].id);
        }
        if (currentNoteId && !notes.find(n => n.id === currentNoteId)) {
            setCurrentNoteId(sortedNotes[0]?.id || null);
        }
    }, [notes, currentNoteId, setCurrentNoteId]);

    const createNewNote = () => {
        const newNote: Note = {
            id: Date.now().toString(),
            title: t('notes.newNote'),
            content: '',
            subject: 'General',
            createdAt: new Date().toISOString(),
            isFavourite: false,
        };
        setNotes([newNote, ...notes]);
        setCurrentNoteId(newNote.id);

        // Track global study material creation
        if (onMaterialTracked) {
            onMaterialTracked();
        }
    };

    const updateNote = (field: keyof Note, value: any) => {
        if (currentNote) {
            const updatedNote = { ...currentNote, [field]: value };
            const updatedNotes = notes.map(n => n.id === currentNote.id ? updatedNote : n);
            setNotes(updatedNotes);
        }
    };

    const handleDeleteRequest = (note: Note) => setNoteToDelete(note);

    const confirmDeleteNote = () => {
        if (!noteToDelete) return;
        const updatedNotes = notes.filter(n => n.id !== noteToDelete.id);
        setNotes(updatedNotes);
        if (currentNoteId === noteToDelete.id) {
            setCurrentNoteId(updatedNotes[0]?.id || null);
        }
        setNoteToDelete(null);
    };

    const toggleFavourite = (id: string) => {
        const updatedNotes = notes.map(n => n.id === id ? { ...n, isFavourite: !n.isFavourite } : n);
        setNotes(updatedNotes);
    }

    const filteredNotes = notes.filter(note => 
        note.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        note.subject.toLowerCase().includes(searchTerm.toLowerCase()) ||
        note.content.toLowerCase().includes(searchTerm.toLowerCase())
    ).sort((a,b) => (b.isFavourite ? 1 : 0) - (a.isFavourite ? 1 : 0));

    return (
        <>
            <div className="flex h-[calc(100vh-10rem)] max-w-7xl mx-auto bg-white dark:bg-gray-900 rounded-2xl shadow-lg overflow-hidden border dark:border-gray-700">
                <div className="w-1/3 border-r dark:border-gray-700 flex flex-col">
                    <div className="p-4 border-b dark:border-gray-700">
                        <input
                            type="search"
                            placeholder={t('notes.search')}
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-md text-sm"
                        />
                    </div>
                    <div className="flex-1 overflow-y-auto">
                        {filteredNotes.map(note => (
                            <div
                                key={note.id}
                                onClick={() => setCurrentNoteId(note.id)}
                                className={`p-4 cursor-pointer border-l-4 ${currentNote?.id === note.id ? 'bg-blue-50 dark:bg-blue-900/30 border-blue-500' : 'border-transparent hover:bg-gray-100 dark:hover:bg-gray-800'}`}
                            >
                                <h4 className="font-bold truncate text-gray-800 dark:text-gray-200">{note.title}</h4>
                                <p className="text-sm text-gray-500 dark:text-gray-400">{note.subject}</p>
                            </div>
                        ))}
                    </div>
                    <div className="p-2 border-t dark:border-gray-700">
                        <button onClick={createNewNote} className="w-full flex items-center justify-center gap-2 px-4 py-2 text-sm font-medium text-white bg-blue-700 rounded-md hover:bg-blue-800">
                            <PlusIcon className="w-4 h-4"/> {t('notes.newNote')}
                        </button>
                    </div>
                </div>

                <div className="w-2/3 flex flex-col">
                    {currentNote ? (
                        <>
                            <div className="p-4 border-b dark:border-gray-700 flex justify-between items-center">
                                <input
                                    type="text"
                                    value={currentNote.title}
                                    onChange={(e) => updateNote('title', e.target.value)}
                                    className="text-xl font-bold bg-transparent focus:outline-none w-full text-gray-800 dark:text-gray-200"
                                />
                                <div className="flex items-center gap-2">
                                    <button onClick={() => toggleFavourite(currentNote.id)} className={`p-2 rounded-full ${currentNote.isFavourite ? 'text-yellow-500' : 'text-gray-400 hover:text-yellow-400'}`}>
                                        <StarIcon className={`w-5 h-5 ${currentNote.isFavourite ? 'fill-current' : ''}`} />
                                    </button>
                                    <button onClick={() => handleDeleteRequest(currentNote)} className="p-2 text-gray-400 hover:text-red-500 rounded-full">
                                        <TrashIcon className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                            <div className="p-4 border-b dark:border-gray-700">
                                <input
                                    type="text"
                                    placeholder={t('notes.subject')}
                                    value={currentNote.subject}
                                    onChange={(e) => updateNote('subject', e.target.value)}
                                    className="w-full bg-gray-100 dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-md text-sm px-3 py-1"
                                />
                            </div>
                            <div className="flex-1 p-4">
                                <textarea
                                    value={currentNote.content}
                                    onChange={(e) => updateNote('content', e.target.value)}
                                    className="w-full h-full resize-none bg-transparent focus:outline-none text-gray-700 dark:text-gray-300"
                                    placeholder={t('notes.writePlaceholder')}
                                />
                            </div>
                        </>
                    ) : (
                        <div className="flex items-center justify-center h-full text-center text-gray-500 dark:text-gray-400">
                            <div>
                                <p>{t('notes.selectOrCreate')}</p>
                                <button onClick={createNewNote} className="text-blue-700 dark:text-blue-500 hover:underline">{t('notes.createNew')}</button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
             {noteToDelete && (
                <ConfirmationModal
                    isOpen={!!noteToDelete}
                    onClose={() => setNoteToDelete(null)}
                    onConfirm={confirmDeleteNote}
                    title={t('confirmation.deleteNote.title')}
                    message={t('confirmation.deleteNote.message', { title: noteToDelete.title })}
                    confirmText={t('common.delete')}
                    confirmColor="red"
                />
            )}
        </>
    );
};

export default Notes;

import React, { useMemo, useState, useEffect, useRef } from 'react';
import { SmartPlan, TrackedSession, UserDetails, ActivityType, PlanSlot } from '../types';
import { DAYS_OF_WEEK } from '../constants';
import { useLanguage } from '../contexts/LanguageContext';
import { timeToMinutes } from '../lib/utils';
import { generateWeeklyProgressComment } from '../services/geminiService';
import { storageService } from '../services/authService';
import { ChartBarIcon } from './icons/ChartBarIcon';
import { ClockIcon } from './icons/ClockIcon';
import { GeminiIcon } from './icons/GeminiIcon';
import { PieChartIcon } from './icons/PieChartIcon';
import { HistoryIcon } from './icons/HistoryIcon';
import { TrendingUpIcon } from './icons/TrendingUpIcon';

declare global {
    interface Window {
        Chart: any;
    }
}

interface ProgressionProps {
  plan: SmartPlan | null;
  trackedData: TrackedSession[];
  userDetails: UserDetails | null;
}

interface WeeklySnapshot {
  weekId: string;
  startDate: string;
  totalTracked: number;
  totalScheduled: number;
  subjectBreakdown: Record<string, number>;
  aiComment: string;
}

const ProgressBar: React.FC<{ progress: number; colorClass: string; label?: string; subLabel?: string }> = ({ progress, colorClass, label, subLabel }) => (
    <div className="w-full">
        <div className="flex justify-between items-end mb-2">
            <span className="text-[10px] font-black uppercase tracking-[0.15em] text-gray-400">{label}</span>
            <span className="text-[10px] font-bold text-gray-500">{subLabel}</span>
        </div>
        <div className="w-full bg-gray-200 dark:bg-gray-700/40 rounded-full h-3.5 overflow-hidden shadow-inner border border-transparent dark:border-gray-600/20">
            <div 
                className={`h-full ${colorClass} transition-all duration-1000 ease-out shadow-[0_0_10px_rgba(16,185,129,0.2)]`}
                style={{ width: `${Math.min(100, progress)}%` }}
            />
        </div>
    </div>
);

const Progression: React.FC<ProgressionProps> = ({ plan, trackedData, userDetails }) => {
  const { t } = useLanguage();
  const [history, setHistory] = useState<WeeklySnapshot[]>([]);
  const [activeTab, setActiveTab] = useState<'current' | 'history'>('current');
  const [aiComment, setAiComment] = useState<string>('');
  const [isGeneratingComment, setIsGeneratingComment] = useState(false);
  const chartRef = useRef<any>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Stats calculation
  const stats = useMemo(() => {
    if (!plan) return null;

    const now = new Date();
    const startOfWeek = new Date(now);
    startOfWeek.setDate(now.getDate() - now.getDay() + (now.getDay() === 0 ? -6 : 1));
    startOfWeek.setHours(0, 0, 0, 0);

    const totals: Record<string, number> = { study: 0, lecture: 0, agenda: 0, break: 0, free: 0 };
    const subjectScheduled: Record<string, number> = {};
    const subjectTracked: Record<string, number> = {};
    const dailyTracked: Record<string, number> = { Mon: 0, Tue: 0, Wed: 0, Thu: 0, Fri: 0, Sat: 0, Sun: 0 };
    const daysMap = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    // Calculate Scheduled Stats from Plan
    plan.forEach(day => {
      day.slots.forEach(slot => {
        const duration = timeToMinutes(slot.endTime) - timeToMinutes(slot.startTime);
        const type = slot.type.toLowerCase();
        if (totals[type] !== undefined) totals[type] += duration;

        if (type === 'study' || type === 'lecture') {
            subjectScheduled[slot.activity] = (subjectScheduled[slot.activity] || 0) + duration;
        }
      });
    });

    // Calculate Tracked Stats from Session Data
    const thisWeekTracked = trackedData.filter(s => new Date(s.date) >= startOfWeek);
    let totalTrackedMinutes = 0;
    thisWeekTracked.forEach(s => {
        totalTrackedMinutes += s.durationMinutes;
        subjectTracked[s.subject] = (subjectTracked[s.subject] || 0) + s.durationMinutes;
        const dayKey = daysMap[new Date(s.date).getDay()];
        if (dailyTracked[dayKey] !== undefined) dailyTracked[dayKey] += s.durationMinutes;
    });

    // FIX: Explicitly type reduce parameters to avoid unknown type error
    const totalMinutes = Object.values(totals).reduce((a: number, b: number) => a + b, 0);
    const activityBreakdown = Object.entries(totals).map(([type, mins]) => ({
        type,
        minutes: mins,
        percentage: totalMinutes > 0 ? Math.round((mins / totalMinutes) * 100) : 0
    }));

    return {
      totals,
      totalTrackedHours: (totalTrackedMinutes / 60).toFixed(1),
      activityBreakdown,
      dailyData: Object.entries(dailyTracked).map(([day, mins]) => ({ day, hours: mins / 60 })),
      subjectComparison: Object.keys(subjectScheduled).map(subject => ({
          subject,
          scheduled: (subjectScheduled[subject] / 60).toFixed(1),
          tracked: ((subjectTracked[subject] || 0) / 60).toFixed(1),
          percentage: Math.min(100, Math.round(((subjectTracked[subject] || 0) / subjectScheduled[subject]) * 100))
      }))
    };
  }, [plan, trackedData]);

  // Chart initialization
  useEffect(() => {
    if (!canvasRef.current || !stats || activeTab !== 'current' || !window.Chart) return;

    if (chartRef.current) {
        chartRef.current.destroy();
    }

    const ctx = canvasRef.current.getContext('2d');
    const colors: Record<string, string> = {
        study: '#2563eb',
        lecture: '#7c3aed',
        agenda: '#ea580c',
        break: '#16a34a',
        free: '#4b5563',
    };

    chartRef.current = new window.Chart(ctx, {
        type: 'doughnut',
        data: {
            labels: stats.activityBreakdown.map(a => a.type),
            datasets: [{
                data: stats.activityBreakdown.map(a => a.minutes),
                backgroundColor: stats.activityBreakdown.map(a => colors[a.type] || '#cbd5e1'),
                borderWidth: 0,
                hoverOffset: 10
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: '75%',
            plugins: {
                legend: { display: false },
                tooltip: {
                    callbacks: {
                        label: (context: any) => {
                            const val = context.raw;
                            const hours = (val / 60).toFixed(1);
                            return ` ${hours} hours`;
                        }
                    }
                }
            }
        }
    });

    return () => {
        if (chartRef.current) chartRef.current.destroy();
    };
  }, [stats, activeTab]);

  useEffect(() => {
    const loadData = async () => {
        const savedHistory = await storageService.loadItem<WeeklySnapshot[]>('progression_history');
        if (savedHistory) setHistory(savedHistory);
    };
    loadData();
  }, []);

  useEffect(() => {
    if (!plan || !userDetails || !trackedData.length) return;
    const generateComment = async () => {
      setIsGeneratingComment(true);
      try {
          const weeklyData = stats?.subjectComparison.map(s => ({
              subject: s.subject,
              scheduledHours: parseFloat(s.scheduled),
              trackedHours: parseFloat(s.tracked)
          })) || [];
          const comment = await generateWeeklyProgressComment(userDetails, weeklyData);
          setAiComment(comment);
      } catch (e) {
          console.error(e);
      } finally {
          setIsGeneratingComment(false);
      }
    };
    generateComment();
  }, [plan, userDetails, trackedData, stats]);

  if (!plan) {
    return (
      <div className="max-w-4xl mx-auto bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-2xl p-16 text-center animate-fade-in border-2 border-gray-100 dark:border-gray-700">
        <div className="w-24 h-24 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-8">
            <ChartBarIcon className="w-12 h-12 text-primary" />
        </div>
        <h2 className="text-4xl font-black text-gray-900 dark:text-white mb-4 tracking-tight">{t('progression.title')}</h2>
        <p className="text-gray-500 dark:text-gray-400 max-w-md mx-auto text-lg font-medium">{t('progression.noPlan')}</p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-8 pb-20 animate-fade-in">
        {/* Top Header & Tabs */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
            <div className="space-y-1">
                <h1 className="text-4xl font-black text-gray-900 dark:text-white tracking-tight">{t('progression.title')}</h1>
                <p className="text-gray-500 dark:text-gray-400 font-medium">Track your study habits and progress over time.</p>
            </div>

            <div className="flex bg-gray-200 dark:bg-gray-800 p-1.5 rounded-2xl shadow-inner w-full md:w-auto">
                <button 
                    onClick={() => setActiveTab('current')}
                    className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest transition-all ${activeTab === 'current' ? 'bg-white dark:bg-gray-700 shadow-lg text-primary' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
                >
                    Live Tracking
                </button>
                <button 
                    onClick={() => setActiveTab('history')}
                    className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-white dark:bg-gray-700 shadow-lg text-primary' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
                >
                    AI Weekly Reports
                </button>
            </div>
        </div>

        {activeTab === 'current' ? (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">

                {/* Left Card: Time Allocation Overview */}
                <div className="lg:col-span-4 bg-white dark:bg-gray-800 rounded-[2rem] p-8 shadow-xl border border-gray-100 dark:border-gray-700 h-full flex flex-col justify-between">
                    <div className="flex items-center gap-3 mb-8 text-primary">
                        <ClockIcon className="w-5 h-5" />
                        <h3 className="text-lg font-black uppercase tracking-tight">{t('progression.weeklyOverview')}</h3>
                    </div>

                    <div className="bg-gray-900 rounded-2xl p-6 mb-8 text-white relative overflow-hidden group">
                        <div className="absolute inset-0 bg-primary/10 opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>
                        <p className="text-[10px] font-black uppercase tracking-[0.2em] text-primary-light mb-1">{t('progression.totalStudy').toUpperCase()}</p>
                        <p className="text-5xl font-black tracking-tighter">{(stats!.totals.study / 60).toFixed(1)}h</p>
                    </div>

                    <div className="grid grid-cols-2 gap-y-6">
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-1">{t('progression.totalLecture')}</p>
                            <p className="text-xl font-black text-purple-600">{(stats!.totals.lecture / 60).toFixed(1)}h</p>
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-1">{t('progression.personalAgenda')}</p>
                            <p className="text-xl font-black text-orange-600">{(stats!.totals.agenda / 60).toFixed(1)}h</p>
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-1">{t('progression.totalBreak')}</p>
                            <p className="text-xl font-black text-green-600">{(stats!.totals.break / 60).toFixed(1)}h</p>
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-1">{t('progression.totalFree')}</p>
                            <p className="text-xl font-black text-gray-500">{(stats!.totals.free / 60).toFixed(1)}h</p>
                        </div>
                    </div>
                </div>

                {/* Right Card: Activity Breakdown (Doughnut) */}
                <div className="lg:col-span-8 bg-white dark:bg-gray-800 rounded-[2rem] p-8 shadow-xl border border-gray-100 dark:border-gray-700 h-full">
                    <div className="flex items-center gap-3 mb-8 text-primary">
                        <PieChartIcon className="w-5 h-5" />
                        <h3 className="text-lg font-black uppercase tracking-tight">{t('progression.activityBreakdown')}</h3>
                    </div>

                    <div className="flex flex-col md:flex-row items-center gap-12">
                        <div className="relative w-64 h-64 flex-shrink-0">
                            <canvas ref={canvasRef}></canvas>
                            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                                <div className="text-center">
                                    <p className="text-xs font-black text-gray-400 uppercase">{t('common.finish')}</p>
                                    {/* FIX: Explicitly type reduce parameters to avoid arithmetic operation errors on unknown types */}
                                    <p className="text-3xl font-black text-gray-900 dark:text-white">{(Number(Object.values(stats!.totals).reduce((a: number, b: number) => a + b, 0)) / 60 / 24).toFixed(0)}d</p>
                                </div>
                            </div>
                        </div>

                        <div className="flex-1 space-y-4 w-full">
                            {stats!.activityBreakdown.map((activity, idx) => (
                                <div key={idx} className="flex items-center justify-between group">
                                    <div className="flex items-center gap-3">
                                        <div className={`w-3 h-3 rounded-full ${
                                            activity.type === 'study' ? 'bg-blue-600' :
                                            activity.type === 'lecture' ? 'bg-purple-600' :
                                            activity.type === 'agenda' ? 'bg-orange-600' :
                                            activity.type === 'break' ? 'bg-green-600' : 'bg-gray-600'
                                        }`} />
                                        <span className="font-bold text-gray-700 dark:text-gray-300 capitalize">{t(`progression.activity.${activity.type}` as any)}</span>
                                    </div>
                                    <span className="font-black text-gray-900 dark:text-white group-hover:scale-110 transition-transform">{activity.percentage}%</span>
