                                        >
                                            <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 hidden group-hover:block bg-gray-900 text-white text-[10px] px-2 py-1 rounded shadow-xl whitespace-nowrap z-20 font-bold border border-gray-700">
                                                {d.hours.toFixed(1)}h
                                            </div>
                                        </div>
                                    </div>
                                    <span className="text-[10px] font-black text-gray-400 uppercase">{d.day}</span>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Bottom Card 2: Tracked vs. Scheduled Study (Comparison) */}
                <div className="lg:col-span-7 bg-white dark:bg-gray-800 rounded-[2rem] p-8 shadow-xl border border-gray-100 dark:border-gray-700">
                    <div className="flex items-center gap-3 mb-10 text-primary">
                        <TrendingUpIcon className="w-5 h-5" />
