                         </div>
                         <div className="relative z-10">
                            <div className="flex items-center gap-3 mb-6">
                                <GeminiIcon className="w-6 h-6 text-primary animate-pulse" />
                                <h3 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight">AI Academic Coach</h3>
                            </div>
                            {isGeneratingComment ? (
                                <div className="flex items-center gap-3 text-gray-400 font-bold animate-pulse">
                                    <div className="flex gap-1.5">
                                        <div className="w-2.5 h-2.5 bg-gray-400 rounded-full animate-bounce"></div>
                                        <div className="w-2.5 h-2.5 bg-gray-400 rounded-full animate-bounce [animation-delay:-.3s]"></div>
                                        <div className="w-2.5 h-2.5 bg-gray-400 rounded-full animate-bounce [animation-delay:-.5s]"></div>
                                    </div>
