                                </div>
                            ) : (
                                <p className="text-base md:text-lg text-gray-700 dark:text-gray-200 font-medium leading-relaxed max-w-5xl">
                                    "{aiComment || "Track your first session of the week to get personalized feedback from your AI coach."}"
                                </p>
                            )}
                         </div>
                    </div>
                </div>
            </div>
        ) : (
            /* History View */
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {history.length > 0 ? (
                    history.map((snapshot) => (
