export const generateSmartPlan = async (
    userDetails: UserDetails, 
    lectures: Lecture[], 
    studyGoals: StudyGoal[], 
    agendaItems: AgendaItem[], 
    generalGoals: string,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const prompt = `Act as a world-class academic scheduler. Create a high-performance weekly study plan for ${userDetails.name}.

**DATA INPUTS:**
- Lectures/Classes: ${JSON.stringify(lectures)}
- COMPULSORY Weekly Study Goals (Hours to allocate): ${JSON.stringify(studyGoals)}
- Personal Agenda/Events: ${JSON.stringify(agendaItems)}
- User Preferences & Special Instructions: "${generalGoals}"
${existingPlan ? `- Current Plan to Modify: ${JSON.stringify(existingPlan)}` : ''}

**SCHEDULING RULES:**
1. **COMPULSORY STUDY SESSIONS:** You MUST distribute the hours specified in 'Study Goals' throughout the week. If a user wants 5 hours of 'Biology', create multiple 'study' blocks for Biology totaling 5 hours.
2. **PRIORITY:** Agenda Items (Events) and Lectures are fixed. Study sessions must be scheduled around them.
3. **BALANCED LOAD:** Do not exceed 8 hours of total focused activity per day unless requested.
4. **BREAKS:** Add a 15-30 min 'break' after every lecture or study session longer than 90 mins.
5. **CATEGORIZATION (CRITICAL):**
   - Type 'lecture': For items in the Lectures list.
   - Type 'study': For sessions dedicated to subjects in the Study Goals list.
   - Type 'agenda': For personal events/errands in the Agenda Items list.
   - Type 'break': For rest periods.
   - Type 'free': For completely unscheduled time.
6. **FORMAT:** Return a JSON array of 7 days (Monday to Sunday). Every minute of the day from 6 AM to 11 PM should be accounted for. Use course codes for activity names if available.

Return ONLY the JSON.`;

    const response = await ai.models.generateContent({
        model: FLASH_MODEL,
        contents: prompt,
        config: { 
            responseMimeType: 'application/json', 
