                    </div>
                </div>

                {/* AI Academic Coach Section */}
                <div className="lg:col-span-12 bg-gradient-to-br from-primary to-primary-dark rounded-[2.5rem] p-1 shadow-2xl overflow-hidden">
                    <div className="bg-white dark:bg-gray-900 rounded-[2.3rem] p-8 md:p-12 relative overflow-hidden group">
                         <div className="absolute top-0 right-0 p-10 opacity-5 group-hover:scale-110 transition-transform duration-700 pointer-events-none">
                             <AwardIcon className="w-64 h-64 text-white" />
                         </div>
                         <div className="relative z-10">
