                                    <div className="w-12 h-12 bg-primary/20 rounded-2xl flex items-center justify-center text-primary">
                                        <GeminiIcon className="w-7 h-7 animate-pulse" />
                                    </div>
                                    <div>
                                        <h3 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Academic Performance Analyst</h3>
                                        <p className="text-sm text-gray-500 font-bold">Powered by EduBlay Intelligence</p>
