  return (
    <div className="max-w-5xl mx-auto space-y-24 pb-20 px-4 animate-fade-in">
        {/* Hero Section */}
        <section className="relative pt-12 overflow-hidden">
            <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full h-full bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-primary/5 to-transparent -z-10 blur-3xl"></div>
            <div className="text-center space-y-6">
                <div className="inline-block p-4 bg-white dark:bg-gray-800 rounded-3xl shadow-2xl mb-4 border border-gray-50 dark:border-gray-700 animate-bounce-slow">
                    <LogoIcon className="w-20 h-20 text-primary" />
                </div>
                <h2 className="text-5xl md:text-6xl font-black text-gray-900 dark:text-white tracking-tight">
                    {t('about.title')}
                </h2>
                <p className="text-xl md:text-2xl text-gray-600 dark:text-gray-400 max-w-2xl mx-auto font-medium">
                    {t('about.welcome')}
                </p>
