const NotificationPrompt: React.FC<{
    settings: NotificationSettings;
    setSettings: (settings: NotificationSettings) => void;
}> = ({ setSettings }) => {
    const { t } = useLanguage();
    const handleFirstTimeEnable = () => {
        if (typeof Notification === 'undefined') {
            alert('This browser does not support desktop notification');
            setSettings({ status: 'configured', enabled: false, reminders: true, reminderTime: 10, sessionStart: true, breakStartEnd: true });
            return;
        }
        if (Notification.permission === 'denied') {
            alert(t('notifications.firstTime.denied'));
            setSettings({ status: 'configured', enabled: true, reminders: true, reminderTime: 10, sessionStart: true, breakStartEnd: true });
            return;
        }
        Notification.requestPermission().then(permission => {
            if (permission === 'granted') {
                setSettings({ status: 'configured', enabled: true, reminders: true, reminderTime: 10, sessionStart: true, breakStartEnd: true });
                new Notification(t('notifications.firstTime.enabled'), { body: t('notifications.firstTime.enabledBody') });
            } else {
                setSettings({ status: 'configured', enabled: false, reminders: true, reminderTime: 10, sessionStart: true, breakStartEnd: true });
            }
        });
    };
    const handleDismiss = () => setSettings({ status: 'configured', enabled: false, reminders: true, reminderTime: 10, sessionStart: true, breakStartEnd: true });
    return (
        <div className="bg-primary-dark text-white p-3 text-center z-50 shadow-md no-print animate-fade-in-down">
            <div className="max-w-4xl mx-auto flex items-center justify-between gap-4">
                <p className="text-sm text-left">{t('notifications.firstTime.body')}</p>
                <div className="flex items-center gap-2 flex-shrink-0">
                    <button onClick={handleFirstTimeEnable} className="px-3 py-1.5 text-sm font-semibold bg-white text-primary rounded-md hover:bg-gray-100 whitespace-nowrap">{t('notifications.firstTime.turnOn')}</button>
                    <button onClick={handleDismiss} className="text-sm font-medium hover:underline whitespace-nowrap">{t('notifications.firstTime.maybeLater')}</button>
                    <button onClick={handleDismiss} className="p-1 rounded-full hover:bg-white/20" aria-label={t('common.close')}><CloseIcon className="w-4 h-4" /></button>
                </div>
            </div>
        </div>
    );
};

const defaultNotificationSettings: NotificationSettings = { status: 'unconfigured', enabled: false, reminders: true, reminderTime: 10, sessionStart: true, breakStartEnd: true };
const defaultQuizState: QuizState = { quiz: [], currentQuestionIndex: 0, userAnswers: [], feedback: null, summary: null };

const App: React.FC = () => {
  const { t } = useLanguage();
  const [isInitializing, setIsInitializing] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [view, setView] = useState<View>('dashboard');
  const [userDetails, setUserDetails] = useState<UserDetails | null>(null);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [smartPlan, setSmartPlan] = useState<SmartPlan | null>(null);
  const [savedTimetables, setSavedTimetables] = useState<StoredPlan[]>([]);
  const [notes, setNotes] = useState<Note[]>([]);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [activeSession, setActiveSession] = useState<ActiveSession | null>(null);
  const [learningHubState, setLearningHubState] = useState<LearningHubState>({ file: null, analysisMode: 'none', analysisResults: { summarize: null, explain: null, read: null }, chatHistory: [], isProcessing: false, processingMessage: '' });
  const [notificationSettings, setNotificationSettings] = useState<NotificationSettings>(defaultNotificationSettings);
  const [trackedData, setTrackedData] = useState<TrackedSession[]>([]);
  const [uploadedMaterials, setUploadedMaterials] = useState<UploadedMaterialInfo[]>([]);
  const [generationState, setGenerationState] = useState<GenerationState>({ isLoading: false, message: '', error: null, source: 'dashboard' });
  const [quizState, setQuizState] = useState<QuizState>(defaultQuizState);
  const [intendedStudyContext, setIntendedStudyContext] = useState<{ subject: string; fromSlot: PlanSlot } | null>(null);
  const [welcomeComplete, setWelcomeComplete] = useState(false);
  const [courseCodeMap, setCourseCodeMap] = useState<CourseCodeMap>({});
  const [activeCode, setActiveCode] = useState<string | null>(null);

  const [unreadFeedbackCount, setUnreadFeedbackCount] = useState(0);
  const [lastFeedbackViewedTime, setLastFeedbackViewedTime] = useState<number>(0);

  const [showTutorialInvitation, setShowTutorialInvitation] = useState(false);

  const [dashboardInputs, setDashboardInputs] = useState<DashboardInputState>({ lectures: [], studyGoals: [], agendaItems: [], generalGoals: '', imageFile: null, imagePreview: null, step: 1, isManualPlan: false, isEditing: false });
  const [examPrepState, setExamPrepState] = useState<ExamPrepState>({ mode: 'quiz', topic: '', numQuestions: 5, quizType: QuizType.MCQ, uploadedFiles: [], focusArea: '', isVerifying: false, questionImage: null, questionText: '', solution: null, outputFormat: 'steps', programmingLanguage: 'python', graphInterval: '', graphYInterval: '', graphConfig: null });
  const [profileEditState, setProfileEditState] = useState<ProfileEditState>({ isEditing: false, details: null });
  const [notesViewState, setNotesViewState] = useState<NotesViewState>({ currentNoteId: null, searchTerm: '' });
  const [reportDraft, setReportDraft] = useState<ReportDraft>({ category: 'bug', description: '', attachment: null, contactEmail: '', contactWhatsApp: '' });

  const addToast = useCallback((message: string, type: Toast['type']) => {
    const newToast = { id: Date.now(), message, type };
    setToasts(prev => [...prev, newToast]);
  }, []);

  const persistAllState = useCallback(async () => {
    if (!userDetails?.email) return;
    const userId = userDetails.id || userDetails.email;
    const emailKey = `${USER_KEY_PREFIX}${userDetails.email}`;

    const localUserData = {
        userDetails, smartPlan, savedTimetables, notes,
        notificationSettings, trackedData, uploadedMaterials,
        courseCodeMap,
        quizState: { quiz: quizState.quiz, currentQuestionIndex: quizState.currentQuestionIndex, userAnswers: quizState.userAnswers },
        learningHubState: { ...learningHubState, isProcessing: false },
        dashboardInputs: { ...dashboardInputs, imageFile: null }
    };

    await storageService.saveItem(emailKey, localUserData);

    const cloudUserData = JSON.parse(JSON.stringify(localUserData));
    if (cloudUserData.learningHubState?.file) cloudUserData.learningHubState.file.base64 = ""; 
    if (cloudUserData.dashboardInputs) {
        cloudUserData.dashboardInputs.imagePreview = null;
        cloudUserData.dashboardInputs.imageFile = null;
    }
    await storageService.syncUserToCloud(userId, cloudUserData);
  }, [userDetails, smartPlan, savedTimetables, notes, notificationSettings, trackedData, quizState, uploadedMaterials, courseCodeMap, learningHubState, dashboardInputs]);

    const loadUserData = useCallback(async (user: UserDetails) => {
        const emailKey = `${USER_KEY_PREFIX}${user.email}`;
        const userData = await storageService.loadItem<any>(emailKey);

        const applyState = (data: any) => {
            const finalUserDetails = { ...user, ...(data.userDetails || {}), usage: (data.userDetails?.usage || user.usage || initializeUsage()) };
            setUserDetails(finalUserDetails);
            setSmartPlan(data.smartPlan || null);
            setSavedTimetables(data.savedTimetables || []);
            setNotes(data.notes || []);
            setTrackedData(data.trackedData || []);
            setUploadedMaterials(data.uploadedMaterials || []);
            setNotificationSettings(data.notificationSettings || defaultNotificationSettings);
            setCourseCodeMap(data.courseCodeMap || {});
            if (data.quizState && data.quizState.quiz?.length > 0) setQuizState({ ...defaultQuizState, ...data.quizState, feedback: null, summary: null });
            if (data.learningHubState) setLearningHubState(prev => ({ ...prev, ...data.learningHubState, isProcessing: false }));
            if (data.dashboardInputs) setDashboardInputs(prev => ({ ...prev, ...data.dashboardInputs, imageFile: null }));
        };
        applyState(userData || {});
    }, []);

    const checkAndRun = async (
        feature: FeatureName,
        action: (...args: any[]) => Promise<void> | void,
        ...args: any[]
    ) => {
        if (!userDetails) return;
        try {
            await action(...args);
            setUserDetails(prev => prev ? { ...prev, usage: incrementUsage(prev.usage, feature) } : null);
            return true;
        } catch (e) {
            console.error(`Feature ${feature} error:`, e);
            return false; 
        }
    };

    const handleNewMaterialUpload = useCallback(async (fileToProcess: File) => {
        if (!userDetails) return;
        setLearningHubState(prev => ({...prev, isProcessing: true, processingMessage: t('uploadslides.verifying')}));

        try {
            const context = intendedStudyContext ? intendedStudyContext.fromSlot.activity : undefined;

            let base64String: string;
            let mimeType = fileToProcess.type;
            let finalSize = fileToProcess.size;

            if (fileToProcess.type.startsWith('image/')) {
                const resized = await processAndResizeImage(fileToProcess);
                base64String = resized.base64;
                mimeType = resized.mimeType;
                finalSize = atob(base64String).length;
            } else {
                base64String = await new Promise<string>((resolve, reject) => {
                    const reader = new FileReader();
                    reader.readAsDataURL(fileToProcess);
                    reader.onload = () => resolve((reader.result as string).split(',')[1]);
                    reader.onerror = error => reject(error);
                });
            }
            const filePart: ImagePart = { inlineData: { data: base64String, mimeType: mimeType } };

            const isMaterial = await isStudyMaterial(filePart, { fast: true });
            if (!isMaterial) {
                throw new Error(t('examprep.error.notStudyMaterial', { fileName: fileToProcess.name }));
            }

            let fileContext = context;
            if (!fileContext) {
                setLearningHubState(prev => ({ ...prev, processingMessage: t('uploadslides.extractingContext') }));
                fileContext = await getDocumentContext(filePart, { fast: true });
            }

            const processedFile: UploadedFile = {
                name: fileToProcess.name,
                type: mimeType,
                size: finalSize,
                base64: base64String,
                context: fileContext,
            };

            setLearningHubState(prev => ({ ...prev, file: processedFile, analysisMode: 'actions', analysisResults: { summarize: null, explain: null, read: null }, chatHistory: [] }));

            const newMaterial: UploadedMaterialInfo = {
                name: processedFile.name,
                type: processedFile.type,
                size: processedFile.size,
                context: processedFile.context,
                uploadedAt: new Date().toISOString()
            };

            if (userDetails.id) {
                globalFeedbackService.trackMaterialUpload(userDetails.id).catch(console.error);
            }

            setUploadedMaterials(prevMaterials => {
                const isNew = !prevMaterials.some(m => m.name === newMaterial.name && m.size === newMaterial.size);
                if (isNew) {
                    return [...prevMaterials, newMaterial];
                }
                return prevMaterials;
            });

        } catch (error: any) {
            addToast(error.message, 'error');
            throw error;
        } finally {
            setLearningHubState(prev => ({...prev, isProcessing: false, processingMessage: ''}));
        }
    }, [addToast, t, userDetails, intendedStudyContext]);

    const handleSavePlanAttempt = (planName: string) => {
        checkAndRun('timetables', () => {
            if (!smartPlan) return;
            const newPlan: StoredPlan = {
                id: Date.now().toString(),
                name: planName,
                createdAt: new Date().toISOString(),
                plan: smartPlan,
                isFavourite: false,
            };
            setSavedTimetables(prev => [...prev, newPlan]);
            addToast(t('toasts.planSaved'), 'success');
        });
    };

    const handleNewMaterialUploadAttempt = (file: File) => {
        checkAndRun('uploads', () => handleNewMaterialUpload(file));
    };

    const handleGenerateQuizAttempt = (apiAction: () => Promise<void>) => {
        checkAndRun('quizzes', apiAction);
    };

    const handleSolveProblemAttempt = (apiAction: () => Promise<void>) => {
        checkAndRun('solves', apiAction);
    };

    const handleBreakCompletion = (skipped: boolean) => {
        const breakSession = activeSession;
        if (!breakSession || breakSession.type !== 'break') {
            setActiveSession(null);
            setView('dashboard');
            return;
        }

        if (breakSession.postBreakView) {
            setActiveSession(null);
            setView(breakSession.postBreakView);
            return;
        }

        if (!smartPlan || !breakSession.day) {
            setActiveSession(null);
            setView('dashboard');
            return;
        }

        const dayPlan = smartPlan.find(d => d.day === breakSession.day);
        if (!dayPlan) {
            setActiveSession(null);
            setView('dashboard');
            return;
        }

        const sortedSlots = [...dayPlan.slots].sort((a,b) => timeToMinutes(a.startTime) - timeToMinutes(b.startTime));
        const breakIndex = sortedSlots.findIndex(s => s.startTime === breakSession.fromSlot.startTime && s.activity === breakSession.fromSlot.activity);

        if (breakIndex !== -1 && breakIndex + 1 < sortedSlots.length) {
            const nextSlot = sortedSlots[breakIndex + 1];

            if (nextSlot.type === ActivityType.STUDY) {
                const now = Date.now();
                const duration = timeToMinutes(nextSlot.endTime) - timeToMinutes(nextSlot.startTime);
                const nextNextSlot = breakIndex + 2 < sortedSlots.length ? sortedSlots[breakIndex + 2] : null;

                const newSession: ActiveSession = {
                    startTime: now,
                    endTime: now + duration * 60 * 1000,
                    subject: nextSlot.activity,
                    type: ActivityType.STUDY,
                    fromSlot: nextSlot,
                    nextSlot: nextNextSlot,
                    durationMinutes: duration,
                    day: breakSession.day,
                };
                setActiveSession(newSession);
                return;
            }
        }

        setActiveSession(null);
        setView('dashboard');
    };

    useEffect(() => {
        const init = async () => {
            try {
                const user = await getCurrentUser();
                const welcome = await storageService.loadItem<boolean>('welcomeComplete');
                const lastView = await storageService.loadItem<number>('lastFeedbackViewedTime');

                setWelcomeComplete(welcome || false);
                setLastFeedbackViewedTime(lastView || 0);

                if (user) {
                    await loadUserData(user);
                    setIsLoggedIn(true);
                }
            } catch (error) {
                console.error("Initialization error:", error);
            } finally {
                setTimeout(() => setIsInitializing(false), 100);
            }
        };
        init();
    }, [loadUserData]);

  useEffect(() => {
    const handler = setTimeout(() => { if (isLoggedIn) persistAllState(); }, 2000); 
    return () => clearTimeout(handler);
  }, [isLoggedIn, persistAllState]);

  useEffect(() => {
    if (!isLoggedIn || view === 'feedback') {
        if (view === 'feedback') setUnreadFeedbackCount(0);
        return;
    }

    const unsubscribe = globalFeedbackService.subscribeToComments((comments) => {
        if (view === 'feedback') {
            setUnreadFeedbackCount(0);
            return;
        }

        const unread = comments.filter(c => {
            if (!c.timestamp) return false;
            const msgTime = c.timestamp.toDate ? c.timestamp.toDate().getTime() : new Date(c.timestamp).getTime();
            return msgTime > lastFeedbackViewedTime;
        });
        setUnreadFeedbackCount(unread.length);
    });

    return () => unsubscribe();
  }, [isLoggedIn, lastFeedbackViewedTime, view]);

  useEffect(() => {
    if (view === 'feedback') {
        const now = Date.now();
        setUnreadFeedbackCount(0);
        setLastFeedbackViewedTime(now);
        storageService.saveItem('lastFeedbackViewedTime', now);
    }
  }, [view]);

  const handleLogin = async (user: UserDetails) => {
    await loadUserData(user);
    setIsLoggedIn(true);
  };

  const handleLogout = async () => {
    await persistAllState(); 
    await logout();
    setUserDetails(null);
    setIsLoggedIn(false);
    setSmartPlan(null);
    setSavedTimetables([]);
    setNotes([]);
    setActiveSession(null);
    setLearningHubState({ file: null, analysisMode: 'none', analysisResults: { summarize: null, explain: null, read: null }, chatHistory: [], isProcessing: false });
    addToast(t('auth.logoutSuccess'), 'info');
  };

  const handleWelcomeComplete = async () => {
      setWelcomeComplete(true);
      await storageService.saveItem('welcomeComplete', true);
  };

  const handleDetailsConfirmed = async () => {
      if (!userDetails?.email) return;
      const key = `has_seen_tutorial_popup_${userDetails.email}`;
      const hasSeen = await storageService.loadItem<boolean>(key);
      if (!hasSeen) {
          setShowTutorialInvitation(true);
      }
  };

  const confirmTutorialRedirect = async () => {
      if (userDetails?.email) {
          await storageService.saveItem(`has_seen_tutorial_popup_${userDetails.email}`, true);
      }
      setShowTutorialInvitation(false);
      setView('tutorial');
  };

  const cancelTutorialRedirect = async () => {
      if (userDetails?.email) {
          await storageService.saveItem(`has_seen_tutorial_popup_${userDetails.email}`, true);
      }
      setShowTutorialInvitation(false);
  };

  if (isInitializing) {
      return (
          <div className="flex flex-col h-screen h-[100dvh] bg-gray-100 dark:bg-gray-900 items-center justify-center">
              <div className="relative">
                  <div className="w-16 h-16 border-4 border-gray-200 dark:border-gray-700 border-t-primary rounded-full animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center"><LogoIcon className="w-8 h-8 text-primary animate-pulse" /></div>
              </div>
              <h1 className="mt-4 text-xl font-bold text-gray-800 dark:text-white tracking-wide">EduBlay</h1>
          </div>
      );
  }

  if (!isLoggedIn) {
    if (!welcomeComplete) return <Welcome onProceed={handleWelcomeComplete} />;
    return <SignUp onLogin={handleLogin} />;
  }

  if (activeSession?.type === 'study') {
     return <FocusedStudyView session={activeSession!} setSession={setActiveSession} addToast={addToast} trackedData={trackedData} setTrackedData={setTrackedData} setView={setView} learningHubState={learningHubState} setLearningHubState={setLearningHubState} />;
  }

  const showNotifPrompt = notificationSettings.status === 'unconfigured' && typeof Notification !== 'undefined' && Notification.permission === 'default';

  return (
    <div className="flex h-screen h-[100dvh] bg-gray-100 dark:bg-gray-900 text-gray-900 dark:text-gray-100 overflow-hidden">
      <NotificationManager plan={smartPlan} settings={notificationSettings} />
      <ToastContainer toasts={toasts} onDismiss={(id) => setToasts(prev => prev.filter(t => t.id !== id))} />
      <Sidebar view={view} setView={setView} isOpen={sidebarOpen} setOpen={setSidebarOpen} userDetails={userDetails} unreadFeedbackCount={unreadFeedbackCount} />
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        {showNotifPrompt && <NotificationPrompt settings={notificationSettings} setSettings={setNotificationSettings} />}
        <Header toggleSidebar={() => setSidebarOpen(!sidebarOpen)} userDetails={userDetails} setView={setView} addToast={addToast} handleLogout={handleLogout} />
        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 dark:bg-gray-900 p-4 sm:p-6 lg:p-8">
          {(() => {
              if (view === 'collaborative') return <CollaborativeSession userDetails={userDetails} addToast={addToast} onActionAttempt={(a) => a()} activeCode={activeCode} setActiveCode={setActiveCode} notes={notes} setNotes={setNotes} />;
              switch (view) {
                case 'dashboard': return <Dashboard setSmartPlan={setSmartPlan} smartPlan={smartPlan} userDetails={userDetails} setUserDetails={setUserDetails} savedTimetables={savedTimetables} setSavedTimetables={setSavedTimetables} addToast={addToast} setActiveSession={setActiveSession} trackedData={trackedData} setTrackedData={setTrackedData} generationState={generationState} setGenerationState={setGenerationState} dashboardInputs={dashboardInputs} setDashboardInputs={setDashboardInputs} setView={setView} setIntendedStudyContext={setIntendedStudyContext} setLearningHubState={setLearningHubState} courseCodeMap={courseCodeMap} setCourseCodeMap={setCourseCodeMap} onSavePlanAttempt={handleSavePlanAttempt} onDetailsConfirmed={handleDetailsConfirmed} />;
                case 'profile': return <Profile userDetails={userDetails} setUserDetails={setUserDetails} addToast={addToast} profileEditState={profileEditState} setProfileEditState={setProfileEditState} />;
                case 'mytimetables': return <MyTimetables savedTimetables={savedTimetables} setSavedTimetables={setSavedTimetables} onLoadPlan={(plan) => { setSmartPlan(plan); setView('dashboard'); }} addToast={addToast} userDetails={userDetails} />;
                case 'progression': return <Progression plan={smartPlan} trackedData={trackedData} userDetails={userDetails} />;
                case 'notes': return <Notes notes={notes} setNotes={setNotes} notesViewState={notesViewState} setNotesViewState={setNotesViewState} userDetails={userDetails} onMaterialTracked={() => { if(userDetails?.id) globalFeedbackService.trackMaterialUpload(userDetails.id).catch(console.error); }} />;
                case 'uploadslides': return <UploadSlides smartPlan={smartPlan} setSmartPlan={setSmartPlan} activeSession={activeSession} setActiveSession={setActiveSession} setView={setView} addToast={addToast} learningHubState={learningHubState} setLearningHubState={setLearningHubState} notes={notes} setNotes={setNotes} intendedStudyContext={intendedStudyContext} setIntendedStudyContext={setIntendedStudyContext} onAttemptUpload={(f) => handleNewMaterialUploadAttempt(f)} />;
                case 'examprep': return <ExamPrep addToast={addToast} setView={setView} generationState={generationState} setGenerationState={setGenerationState} quizState={quizState} setQuizState={setQuizState} notes={notes} setNotes={setNotes} examPrepState={examPrepState} setExamPrepState={setExamPrepState} onGenerateQuizAttempt={handleGenerateQuizAttempt} onSolveProblemAttempt={handleSolveProblemAttempt} />;
                case 'language': return <LanguageSettings />;
                case 'theme': return <ThemeSettings />;
                case 'notification': return <NotificationSettingsComponent settings={notificationSettings} setSettings={setNotificationSettings} />;
                case 'settings': return <Settings addToast={addToast} handleLogout={handleLogout} userDetails={userDetails} setShowUpgradeModal={() => {}} />;
                case 'report': return <Reports userDetails={userDetails} reportDraft={reportDraft} setReportDraft={setReportDraft} addToast={addToast} />;
                case 'feedback': return <Feedback userDetails={userDetails} addToast={addToast} />;
                case 'help': return <Help setView={setView} />;
                case 'about': return <About setView={setView} />;
                case 'library': return <Library />;
                case 'terms': return <Terms />;
                case 'tutorial': return <Tutorial addToast={addToast} tutorialVideoUrl='https://youtu.be/f14AwLpLb9E' />;
                default: return <div>{t('common.notFound')}</div>;
              }
          })()}
        </main>
      </div>
       {activeSession?.type === 'break' && <BreakView session={activeSession} onEnd={handleBreakCompletion} />}

       <ConfirmationModal
           isOpen={showTutorialInvitation}
           onClose={cancelTutorialRedirect}
           onConfirm={confirmTutorialRedirect}
           title="Welcome to EduBlay!"
           message="We're excited to have you! Would you like to visit our Tutorial section or watch a quick video on how the app works?"
           confirmText="Proceed"
           cancelText="Cancel"
           confirmColor="blue"
       />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useDropzone } from 'react-dropzone';
import UserDetailsForm from './UserDetailsForm';
import TimetableInput from './TimetableInput';
import SmartPlanView from './SmartPlanView';
import CourseCodeModal from './CourseCodeModal';
import { generateSmartPlan, generatePlanFromImage, isImageTimetable } from '../services/geminiService';
import type { UserDetails, Lecture, StudyGoal, AgendaItem, SmartPlan, StoredPlan, ImagePart, CourseCodeMap, Toast, ActiveSession, PlanSlot, TrackedSession, GenerationState, DashboardInputState, LearningHubState } from '../types';
import { EducationalLevel, ActivityType, DayOfWeek } from '../types';
import { UploadIcon } from './icons/UploadIcon';
import { useLanguage } from '../contexts/LanguageContext';
import { LogoIcon } from './icons/LogoIcon';
import { DAYS_OF_WEEK } from '../constants';
import EditTimetableModal from './EditTimetableModal';
import { RefreshIcon } from './icons/RefreshIcon';
import { LogIcon } from './icons/LogIcon';
import { ClockIcon } from './icons/ClockIcon';
import { PlayIcon } from './icons/PlayIcon';
import LogStudyModal from './LogStudyModal';
import { timeToMinutes, processAndResizeImage } from '../lib/utils';
import { initializeUsage } from '../lib/usageManager';

const emptyUserDetails: UserDetails = { name: '', educationalLevel: EducationalLevel.UNDERGRADUATE, institution: '', country: '', email: '', programmeOfStudy: '', institutionAbbreviation: '', usage: initializeUsage() };

const getDayOfWeek = (date: Date): DayOfWeek => {
    const dayIndex = date.getDay(); 
    const days: DayOfWeek[] = [DayOfWeek.Sunday, DayOfWeek.Monday, DayOfWeek.Tuesday, DayOfWeek.Wednesday, DayOfWeek.Thursday, DayOfWeek.Friday, DayOfWeek.Saturday];
    return days[dayIndex];
};

const LoadingOverlay: React.FC<{ isLoading: boolean; message: string }> = ({ isLoading, message }) => {
    if (!isLoading) return null;
    return (
        <div className="absolute inset-0 bg-white/80 dark:bg-gray-800/80 flex flex-col items-center justify-center z-30 rounded-xl backdrop-blur-sm">
            <div className="animate-spin w-12 h-12 border-4 border-primary/30 border-t-primary rounded-full"></div>
            <p className="mt-4 font-semibold text-gray-700 dark:text-gray-300">{message}</p>
        </div>
    );
};

interface DashboardProps {
  setSmartPlan: (plan: SmartPlan | null) => void;
  smartPlan: SmartPlan | null;
  userDetails: UserDetails | null;
  setUserDetails: (details: UserDetails) => void;
  savedTimetables: StoredPlan[];
  setSavedTimetables: (plans: StoredPlan[]) => void;
  addToast: (message: string, type: Toast['type']) => void;
  setActiveSession: (session: ActiveSession | null) => void;
  trackedData: TrackedSession[];
  setTrackedData: (data: TrackedSession[]) => void;
  generationState: GenerationState;
  setGenerationState: React.Dispatch<React.SetStateAction<GenerationState>>;
  dashboardInputs: DashboardInputState;
  setDashboardInputs: React.Dispatch<React.SetStateAction<DashboardInputState>>;
  setView: (view: any) => void;
  setIntendedStudyContext: (context: { subject: string; fromSlot: PlanSlot } | null) => void;
  setLearningHubState: React.Dispatch<React.SetStateAction<LearningHubState>>;
  courseCodeMap: CourseCodeMap;
  setCourseCodeMap: (map: CourseCodeMap) => void;
  onSavePlanAttempt: (planName: string) => void;
  onDetailsConfirmed?: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ 
    setSmartPlan, 
    smartPlan, 
    userDetails, 
    setUserDetails, 
    savedTimetables, 
    setSavedTimetables, 
    addToast, 
    setActiveSession, 
    trackedData, 
    setTrackedData,
    generationState,
    setGenerationState,
    dashboardInputs,
    setDashboardInputs,
    setView,
    setIntendedStudyContext,
    setLearningHubState,
    courseCodeMap,
    setCourseCodeMap,
    onSavePlanAttempt,
    onDetailsConfirmed
}) => {
  const [saveModalOpen, setSaveModalOpen] = useState(false);
  const [planName, setPlanName] = useState('');
  const [tempSmartPlan, setTempSmartPlan] = useState<SmartPlan | null>(null);
  const [courseCodes, setCourseCodes] = useState<string[]>([]);
  const [isCodeModalOpen, setIsCodeModalOpen] = useState(false);
  const { t } = useLanguage();
  const [currentActivity, setCurrentActivity] = useState<{ slot: PlanSlot, day: DayOfWeek, nextSlot: PlanSlot | null } | null>(null);
  const dayRefs = useRef<Record<DayOfWeek, HTMLDivElement | null>>({} as any);
  const [isInputMode, setIsInputMode] = useState(false);

  const [logStudyModalState, setLogStudyModalState] = useState<{ isOpen: boolean; slot: PlanSlot | null; day: DayOfWeek | null; nextSlot: PlanSlot | null }>({ isOpen: false, slot: null, day: null, nextSlot: null });

  const { lectures, studyGoals, agendaItems, generalGoals, imageFile, imagePreview, step, isEditing } = dashboardInputs;

  const checkForAgendaConflicts = useCallback((
    plan: SmartPlan, 
    originalLectures: Lecture[], 
    originalAgendaItems: AgendaItem[]
  ) => {
    originalAgendaItems.forEach(item => {
        if (!item.title.trim()) return;

        const isScheduled = plan.some(dayPlan => 
            dayPlan.day === item.day &&
            dayPlan.slots.some(slot => 
                slot.type === ActivityType.AGENDA &&
                slot.activity === item.title &&
                timeToMinutes(slot.startTime) === timeToMinutes(item.startTime)
            )
        );

        if (!isScheduled) {
            const itemStart = timeToMinutes(item.startTime);
            const itemEnd = timeToMinutes(item.endTime);

            const conflictingLecture = originalLectures.find(lec => 
                lec.day === item.day &&
                itemStart < timeToMinutes(lec.endTime) &&
                itemEnd > timeToMinutes(lec.startTime)
            );

            if (conflictingLecture) {
                addToast(t('toasts.agendaConflict', { title: item.title, lecture: conflictingLecture.subject }), 'warning');
            }
        }
    });
  }, [addToast, t]);

  const handleScrollToCurrentActivity = () => {
    if (currentActivity?.day && dayRefs.current[currentActivity.day]) {
      dayRefs.current[currentActivity.day]?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  };

  useEffect(() => {
    const updateCurrentActivity = () => {
        if (!smartPlan) {
            setCurrentActivity(null);
            return;
        }

        const now = new Date();
        const currentDay = getDayOfWeek(now);
        const dayPlan = smartPlan.find(d => d.day === currentDay);

        if (!dayPlan || dayPlan.slots.length === 0) {
            setCurrentActivity(null);
            return;
        }

        const nowMinutes = now.getHours() * 60 + now.getMinutes();

        const sortedSlots = [...dayPlan.slots].sort((a,b) => timeToMinutes(a.startTime) - timeToMinutes(b.startTime));

        let relevantSlot: PlanSlot | null = null;
        let nextSlotForRelevant: PlanSlot | null = null;

        const currentSlotIndex = sortedSlots.findIndex(slot => {
            const startMinutes = timeToMinutes(slot.startTime);
            const endMinutes = timeToMinutes(slot.endTime);
            if (endMinutes < startMinutes) { 
                return nowMinutes >= startMinutes || nowMinutes < endMinutes;
            }
            return startMinutes <= nowMinutes && nowMinutes < endMinutes;
        });

        if (currentSlotIndex !== -1) {
            relevantSlot = sortedSlots[currentSlotIndex];
            if (currentSlotIndex + 1 < sortedSlots.length) {
                nextSlotForRelevant = sortedSlots[currentSlotIndex + 1];
            }
        } else {
            const nextSlotIndex = sortedSlots.findIndex(slot => timeToMinutes(slot.startTime) > nowMinutes);
            if (nextSlotIndex !== -1) {
                relevantSlot = sortedSlots[nextSlotIndex];
                if (nextSlotIndex + 1 < sortedSlots.length) {
                    nextSlotForRelevant = sortedSlots[currentSlotIndex + 1];
                }
            }
        }

        if (relevantSlot) {
            setCurrentActivity({ slot: relevantSlot, day: currentDay, nextSlot: nextSlotForRelevant });
        } else {
            setCurrentActivity(null); 
        }
    };

    updateCurrentActivity();
    const interval = setInterval(updateCurrentActivity, 60000);
    return () => clearInterval(interval);
  }, [smartPlan]);

  const setLectures = useCallback((updater: React.SetStateAction<Lecture[]>) => {
      setDashboardInputs(prev => ({ ...prev, lectures: typeof updater === 'function' ? updater(prev.lectures) : updater }));
  }, [setDashboardInputs]);

  const setStudyGoals = useCallback((updater: React.SetStateAction<StudyGoal[]>) => {
      setDashboardInputs(prev => ({ ...prev, studyGoals: typeof updater === 'function' ? updater(prev.studyGoals) : updater }));
  }, [setDashboardInputs]);

  const setAgendaItems = useCallback((updater: React.SetStateAction<AgendaItem[]>) => {
      setDashboardInputs(prev => ({ ...prev, agendaItems: typeof updater === 'function' ? updater(prev.agendaItems) : updater }));
  }, [setDashboardInputs]);

  const setGeneralGoals = useCallback((goals: string) => {
      setDashboardInputs(prev => ({ ...prev, generalGoals: goals }));
  }, [setDashboardInputs]);

  const isInputSufficient = !!imageFile || !!imagePreview ||
    lectures.some(l => l.subject.trim() !== '') ||
    studyGoals.some(g => g.subject.trim() !== '') ||
    agendaItems.some(a => a.title.trim() !== '');

  const extractCourseCodes = (plan: SmartPlan): string[] => {
    const codeRegex = /\b([A-Z]{2,5}\s?\d{2,4})\b/g;
    const codes = new Set<string>();
    plan.forEach(day => {
        day.slots.forEach(slot => {
            if (slot.code) {
                codes.add(slot.code);
            }
            if (slot.type === ActivityType.LECTURE || slot.type === ActivityType.STUDY) {
                const matches = slot.activity.match(codeRegex);
                if (matches) {
                    matches.forEach(code => codes.add(code));
                }
            }
        });
    });
    return Array.from(codes);
  };

    const applyCourseCodeMap = (plan: SmartPlan, map: CourseCodeMap): SmartPlan => {
        if (Object.keys(map).length === 0) return plan;

        return plan.map(day => ({
            ...day,
            slots: day.slots.map(slot => {
                const codeRegex = /\b([A-Z]{2,5}\s?\d{2,4})\b/g;
                const codeToMatch = slot.code || slot.activity.match(codeRegex)?.[0];

                if (codeToMatch && codeToMatch in map) {
                    const newName = map[codeToMatch];
                    if (newName && newName.trim() !== '') {
                        return { ...slot, activity: newName.trim(), code: codeToMatch };
                    }
                }
                if (codeToMatch && !slot.code) {
                    return { ...slot, code: codeToMatch };
                }
                return slot;
            })
        }));
    };

    const processPlanForCodes = (plan: SmartPlan, isInitialGeneration: boolean) => {
        let extractedCodes = extractCourseCodes(plan);
        const isManualInput = !imageFile && !imagePreview;

        if (isManualInput) {
            const validInputs = [
                ...lectures.map(l => l.subject.toUpperCase()),
                ...studyGoals.map(s => s.subject.toUpperCase())
            ].join(' ');

            extractedCodes = extractedCodes.filter(code => {
                 return validInputs.includes(code.toUpperCase());
             });
        }

        const newCodes = extractedCodes.filter(c => !courseCodeMap[c]);

        if (isInitialGeneration && newCodes.length > 0) {
            setTempSmartPlan(plan);
            setCourseCodes(extractedCodes); 
            setIsCodeModalOpen(true);
        } else {
            const finalPlan = applyCourseCodeMap(plan, courseCodeMap);
            setSmartPlan(finalPlan);
        }
    };

  const handleNextStep = () => {
    if (!userDetails || !userDetails.name || !userDetails.educationalLevel) {
        addToast(t('dashboard.error.fillDetails'), 'error');
        return;
    }
    const isUniversityLevel = ![EducationalLevel.HIGH_SCHOOL, EducationalLevel.OTHER].includes(userDetails.educationalLevel);
    if (isUniversityLevel && !userDetails.country) {
        addToast(t('common.countryRequired'), 'error');
        return;
    }

    // Notify app that details have been confirmed before switching to step 2
    if (onDetailsConfirmed) {
        onDetailsConfirmed();
    }

    setDashboardInputs(prev => ({...prev, step: 2}));
  };

  const handleGeneratePlan = async () => {
    if (!isInputSufficient || !userDetails) {
        addToast(t('dashboard.error.noInput'), 'error');
        return;
    }

    const isRegeneration = !!smartPlan;
    const loadingMessage = isRegeneration ? "Applying your changes..." : t('dashboard.generating');

    setGenerationState({ isLoading: true, message: loadingMessage, error: null, source: 'dashboard' });

    if (imageFile || imagePreview) {
        setGenerationState(prev => ({ ...prev, message: isRegeneration ? "Updating plan from new inputs..." : t('dashboard.verifyingImage') }));
        try {
            let imagePart: ImagePart;

            if (imageFile) {
                const { base64, mimeType } = await processAndResizeImage(imageFile);
                imagePart = { inlineData: { data: base64, mimeType } };
            } else if (imagePreview) {
                const [meta, data] = imagePreview.split(',');
                const mimeType = meta.split(':')[1].split(';')[0];
                imagePart = { inlineData: { data: data, mimeType } };
            } else {
                 throw new Error("No image data found");
            }

            if (!isRegeneration) {
                const isTimetable = await isImageTimetable(imagePart);
                if (!isTimetable) {
                    addToast(t('dashboard.error.notATimetable'), 'error');
                    setGenerationState({ isLoading: false, message: '', error: null, source: null });
                    return;
                }
            }

            setGenerationState(prev => ({ ...prev, message: isRegeneration ? "Rebuilding schedule..." : t('dashboard.generating') }));
            const generatedPlan = await generatePlanFromImage(userDetails, studyGoals, agendaItems, generalGoals, imagePart, isRegeneration ? smartPlan : undefined);

            const extractedLectures: Lecture[] = [];
            generatedPlan.forEach(dayPlan => {
                dayPlan.slots.forEach(slot => {
                    if (slot.type === ActivityType.LECTURE) {
                        extractedLectures.push({
                            id: `${dayPlan.day}-${slot.startTime}`,
                            subject: slot.activity,
                            day: dayPlan.day,
                            startTime: slot.startTime,
                            endTime: slot.endTime,
                            location: slot.location
                        });
                    }
                });
            });

            checkForAgendaConflicts(generatedPlan, extractedLectures, agendaItems);
            processPlanForCodes(generatedPlan, !isRegeneration);
            setGenerationState({ isLoading: false, message: '', error: null, source: null });
            setIsInputMode(false);

        } catch (e) {
             const message = e instanceof Error ? e.message : String(e);
             addToast(message || t('toasts.error.unexpected'), 'error');
             setGenerationState({ isLoading: false, message: '', error: null, source: null });
        }
    } else {
        setGenerationState(prev => ({ ...prev, message: loadingMessage }));
        try {
            const plan = await generateSmartPlan(userDetails, lectures, studyGoals, agendaItems, generalGoals, isRegeneration ? smartPlan : undefined);
            checkForAgendaConflicts(plan, lectures, agendaItems);
            processPlanForCodes(plan, !isRegeneration);
            setGenerationState({ isLoading: false, message: '', error: null, source: null });
            setIsInputMode(false);
        } catch (e: any) {
            const message = e instanceof Error ? e.message : String(e);
            addToast(message || t('toasts.error.unexpected'), 'error');
            setGenerationState({ isLoading: false, message: '', error: null, source: null });
        }
    }
  };

  const handleCourseCodeConfirmation = (confirmedMap: CourseCodeMap) => {
    if (!tempSmartPlan) return;

    const updatedMap = { ...courseCodeMap, ...confirmedMap };
    setCourseCodeMap(updatedMap);

    const finalPlan = applyCourseCodeMap(tempSmartPlan, updatedMap);

    setSmartPlan(finalPlan);
    setIsCodeModalOpen(false);
    setTempSmartPlan(null);
    setCourseCodes([]);
  };

  const onDrop = useCallback(async (acceptedFiles: File[]) => {
    const file = acceptedFiles[0];
    if (file) {
        if (file.size > 25 * 1024 * 1024) { 
            addToast(t('toasts.fileSizeTooLarge', { fileName: file.name, size: 25 }), 'error');
            return;
        }

        try {
            const { dataUrl } = await processAndResizeImage(file);

            setDashboardInputs(prev => ({
                ...prev,
                imageFile: file,
                imagePreview: dataUrl,
                lectures: [],
                studyGoals: [],
            }));
        } catch (error) {
            addToast("Failed to process image.", 'error');
        }
    }
  }, [setDashboardInputs, addToast, t]);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'image/jpeg': ['.jpeg', '.jpg'],
      'image/png': ['.png'],
    },
    multiple: false,
    disabled: generationState.isLoading || lectures.length > 0 || studyGoals.length > 0,
  });

  const clearImage = () => {
      setDashboardInputs(prev => ({ ...prev, imageFile: null, imagePreview: null }));
  }

  const handleSavePlan = () => {
    if (smartPlan && planName.trim()) {
      onSavePlanAttempt(planName.trim());
      setSaveModalOpen(false);
      setPlanName('');
    } else if (!planName.trim()) {
        addToast(t('toasts.planNameRequired'), 'warning');
    }
  };

  const handleStartStudySession = (slot: PlanSlot, day: DayOfWeek) => {
    setLogStudyModalState({ isOpen: false, slot: null, day: null, nextSlot: null });

    let nextSlot: PlanSlot | null = null;
    if (smartPlan) {
        const dayPlan = smartPlan.find(d => d.day === day);
        if (dayPlan) {
            const sortedSlots = [...dayPlan.slots].sort((a,b) => timeToMinutes(a.startTime) - timeToMinutes(b.startTime));
            const currentIndex = sortedSlots.findIndex(s => s.startTime === slot.startTime && s.activity === slot.activity);
            if (currentIndex !== -1 && currentIndex + 1 < sortedSlots.length) {
                nextSlot = sortedSlots[currentIndex + 1];
            }
        }
    }

    const now = Date.now();
    const duration = timeToMinutes(slot.endTime) - timeToMinutes(slot.startTime);
    const newSession: ActiveSession = {
        startTime: now,
        endTime: now + duration * 60 * 1000,
        subject: slot.activity,
        type: ActivityType.STUDY,
        fromSlot: slot,
        nextSlot: nextSlot,
        durationMinutes: duration,
        day: day,
    };
    setActiveSession(newSession);
    addToast(t('toasts.sessionStarted'), 'success');
  };

  const handleStudySlotClick = (slot: PlanSlot, day: DayOfWeek) => {
    let nextSlot: PlanSlot | null = null;
    if (smartPlan) {
        const dayPlan = smartPlan.find(d => d.day === day);
        if (dayPlan) {
            const sortedSlots = [...dayPlan.slots].sort((a,b) => timeToMinutes(a.startTime) - timeToMinutes(b.startTime));
            const currentIndex = sortedSlots.findIndex(s => s.startTime === slot.startTime && s.activity === slot.activity);
            if (currentIndex !== -1 && currentIndex + 1 < sortedSlots.length) {
                nextSlot = sortedSlots[currentIndex + 1];
            }
        }
    }
    setLogStudyModalState({ isOpen: true, slot, day, nextSlot });
  };

  const handleUploadSlidesForSession = (slot: PlanSlot) => {
    setIntendedStudyContext({ subject: slot.activity, fromSlot: slot });
    setView('uploadslides');
    setLogStudyModalState({ isOpen: false, slot: null, day: null, nextSlot: null });
  };

  const handleEditInputs = () => {
    setIsInputMode(true); 
    setDashboardInputs(prev => ({...prev, step: 2}));
  };

  const handleStartOver = () => {
    setSmartPlan(null);
    setIsInputMode(false);
    setDashboardInputs({
        lectures: [],
        studyGoals: [],
        agendaItems: [],
        generalGoals: '',
        imageFile: null,
        imagePreview: null,
        step: 1,
        isManualPlan: false,
        isEditing: false,
    });
    setCourseCodeMap({});
  };

  const isNow = (startTime: string, endTime: string): boolean => {
    const now = new Date();
    const nowMinutes = now.getHours() * 60 + now.getMinutes();
    const startMinutes = timeToMinutes(startTime);
    const endMinutes = timeToMinutes(endTime);

    if (endMinutes < startMinutes) { 
        return nowMinutes >= startMinutes || nowMinutes < endMinutes;
    } else { 
        return nowMinutes >= startMinutes && nowMinutes < endMinutes;
    }
  }

  const renderPlanCreationSteps = () => {
    if (!userDetails) return null; 
    if (step === 1) {
        return (
            <div>
              <h2 className="text-3xl font-bold text-gray-800 dark:text-white mb-2">{t('dashboard.createPlanTitle')}</h2>
              <p className="text-gray-500 dark:text-gray-400 mb-6">{t('dashboard.createPlanSubtitle')}
              </p>
              <UserDetailsForm userDetails={userDetails} setUserDetails={setUserDetails} />
              <button onClick={handleNextStep} className="mt-6 w-full py-3 bg-primary text-primary-text font-semibold rounded-lg shadow-md hover:bg-primary-dark transition-colors">{t('common.confirm')}</button>
            </div>
        );
    }

    if (step === 2) {
        const showDropzone = !!imagePreview || (lectures.length === 0 && studyGoals.length === 0);
        const disableManual = !!imagePreview; 

        return (
            <div>
                <h3 className="text-2xl font-bold text-gray-800 dark:text-white mb-2 text-center">{t('dashboard.step2.title')}</h3>
                <p className="text-gray-500 dark:text-gray-400 mb-6 text-center">{t('dashboard.step2.subtitle')}</p>

               <div {...getRootProps()} className={`group relative p-8 border-2 border-dashed rounded-lg cursor-pointer transition-colors ${!!imagePreview ? 'border-green-500' : (lectures.length > 0 || studyGoals.length > 0 ? 'opacity-50 cursor-not-allowed' : 'hover:border-green-500 dark:hover:border-green-400 hover:bg-green-50 dark:hover:bg-green-900/20')} border-gray-300 dark:border-gray-600 text-center ${isDragActive ? 'border-green-600 bg-green-100 dark:bg-green-900/30' : ''}`}>
                 <input {...getInputProps()} />
                 {imagePreview ? (
                     <>
                       <img src={imagePreview} alt={t('dashboard.alt.timetablePreview')} className="max-h-52 mx-auto rounded-lg shadow-md" />
                       <button onClick={(e) => { e.stopPropagation(); clearImage(); }} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1.5 shadow-lg leading-none">&times;</button>
                     </>
                 ) : (
                    <>
                        <UploadIcon className="w-12 h-12 mx-auto mb-2 text-gray-400" />
                        <p className="font-semibold text-gray-700 dark:text-gray-300">{lectures.length > 0 || studyGoals.length > 0 ? t('dashboard.uploadDisabled') : t('dashboard.uploadTimetable')}</p>
                        <p className="text-sm text-gray-500">{t('dashboard.uploadTimetable.hint')}</p>
                    </>
                 )}
               </div>

               <div className="flex items-center my-6">
                 <div className="flex-grow border-t border-gray-300 dark:border-gray-600"></div>
                 <span className="flex-shrink mx-4 text-gray-500 font-semibold">{t('common.or')}</span>
                 <div className="flex-grow border-t border-gray-300 dark:border-gray-600"></div>
               </div>
                <div className="text-center mb-4">
                    <p className="text-gray-600 dark:text-gray-400">{t('dashboard.manualEntry')}</p>
                </div>
               <TimetableInput 
                   lectures={lectures} setLectures={setLectures} 
                   studyGoals={studyGoals} setStudyGoals={setStudyGoals}
                   agendaItems={agendaItems} setAgendaItems={setAgendaItems}
                   generalGoals={generalGoals} setGeneralGoals={setGeneralGoals}
                   manualSectionsDisabled={disableManual}
               />
               <button onClick={handleGeneratePlan} className="mt-8 w-full py-4 bg-primary text-primary-text font-bold text-lg rounded-xl shadow-lg hover:bg-primary-dark disabled:bg-primary/50 disabled:cursor-not-allowed transition-all" disabled={!isInputSufficient || generationState.isLoading}>
                 {generationState.isLoading ? t('dashboard.generating') : (smartPlan ? t('dashboard.regeneratePlan') : t('dashboard.generatePlan'))}
               </button>
             </div>
        );
    }
  };

  if (!userDetails) {
      return null;
  }

  return (
    <div className="max-w-7xl mx-auto space-y-8">
      {smartPlan && !isInputMode ? (
        <div>
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
            <h2 className="text-3xl font-bold text-gray-800 dark:text-white">{t('dashboard.yourSmartPlan')}</h2>
            <div className="flex flex-wrap gap-2 w-full justify-start sm:w-auto sm:justify-end">
              <button onClick={handleEditInputs} className="px-4 py-2 text-sm font-medium bg-gray-200 dark:bg-gray-700 rounded-md hover:bg-gray-300 dark:hover:bg-gray-600">{t('dashboard.editInputs')}</button>
              <button onClick={() => setDashboardInputs(prev => ({...prev, isEditing: true}))} className="px-4 py-2 text-sm font-medium bg-gray-200 dark:bg-gray-700 rounded-md hover:bg-gray-300 dark:hover:bg-gray-600">{t('dashboard.editTimetable')}</button>
              <button onClick={handleStartOver} className="px-4 py-2 text-sm font-medium bg-gray-200 dark:bg-gray-700 rounded-md hover:bg-gray-300 dark:hover:bg-gray-600">{t('dashboard.startOver')}</button>
              <button onClick={() => setSaveModalOpen(true)} className="px-4 py-2 text-sm font-medium text-primary-text bg-primary rounded-md hover:bg-primary-dark">{t('common.save')}</button>
            </div>
          </div>

          {smartPlan && (
            currentActivity ? (
                <div
                    onClick={handleScrollToCurrentActivity}
                    onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); handleScrollToCurrentActivity(); } }}
                    role="button"
                    tabIndex={0}
                    className="bg-gradient-to-br from-primary to-sky-400 dark:from-primary-dark dark:to-sky-700 rounded-2xl shadow-xl p-6 md:p-8 mb-8 text-white transition-transform duration-300 hover:scale-[1.02] focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-100 dark:focus:ring-offset-gray-900 focus:ring-primary cursor-pointer"
                >
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="font-semibold text-primary-text/80">{ isNow(currentActivity.slot.startTime, currentActivity.slot.endTime) ? t('dashboard.happeningNow') : t('dashboard.upNext')} &bull; {currentActivity.day}</p>
                            <h3 className="text-3xl font-bold mt-1">{currentActivity.slot.activity}</h3>
                            <div className="flex items-center gap-2 mt-2 text-primary-text/90">
                                <ClockIcon className="w-5 h-5" />
                                <span>{currentActivity.slot.startTime} - {currentActivity.slot.endTime}</span>
                            </div>
                        </div>
                        {currentActivity.slot.type === 'study' && getDayOfWeek(new Date()) === currentActivity.day && (
                            <button 
                                onClick={(e) => { e.stopPropagation(); handleStudySlotClick(currentActivity.slot, currentActivity.day); }}
                                className="flex items-center gap-2 px-6 py-3 bg-white/20 hover:bg-white/30 rounded-xl font-semibold transition-all backdrop-blur-sm"
                            >
                                <PlayIcon className="w-5 h-5"/> {t('dashboard.startSession')}
                            </button>
                        )}
                    </div>
                </div>
            ) : (
                <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-6 text-center mb-8">
                    <h3 className="text-xl font-semibold text-gray-700 dark:text-gray-300">{t('dashboard.doneForToday')}</h3>
                    <p className="text-gray-500 mt-1">{t('dashboard.enjoyFreeTime')}</p>
                </div>
            )
          )}

          <SmartPlanView plan={smartPlan} onStudySlotClick={handleStudySlotClick} dayRefs={dayRefs} addToast={addToast} userDetails={userDetails} />
        </div>
      ) : (
        <div className="relative bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-6 md:p-10">
            <LoadingOverlay isLoading={generationState.isLoading && generationState.source === 'dashboard'} message={generationState.message} />
             {renderPlanCreationSteps()}
        </div>
      )}

      {isEditing && smartPlan && (
        <EditTimetableModal
            isOpen={isEditing}
            onClose={() => setDashboardInputs(prev => ({...prev, isEditing: false}))}
            plan={smartPlan}
            setPlan={setSmartPlan}
            addToast={addToast}
        />
      )}

      {saveModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-gray-800 rounded-lg p-6 w-full max-w-sm">
            <h3 className="text-lg font-bold mb-4">{t('dashboard.saveModal.title')}</h3>
            <input 
                type="text" 
                value={planName} 
                onChange={e => setPlanName(e.target.value)} 
                placeholder={t('dashboard.planNamePlaceholder')} 
                className="w-full p-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-200 placeholder-gray-500 dark:placeholder-gray-400 focus:outline-none focus:ring-primary focus:border-primary"
            />
            <div className="flex justify-end gap-2 mt-4">
              <button onClick={() => setSaveModalOpen(false)} className="px-4 py-2 bg-gray-200 dark:bg-gray-600 rounded-md">{t('common.cancel')}</button>
              <button onClick={handleSavePlan} className="px-4 py-2 bg-primary text-primary-text rounded-md">{t('common.save')}</button>
            </div>
          </div>
        </div>
      )}

      {isCodeModalOpen && (
        <CourseCodeModal
            isOpen={isCodeModalOpen}
            onClose={() => setIsCodeModalOpen(false)}
            onConfirm={handleCourseCodeConfirmation}
            codes={courseCodes}
            existingMap={courseCodeMap}
        />
      )}

      <LogStudyModal
        isOpen={logStudyModalState.isOpen}
        onClose={() => setLogStudyModalState({ isOpen: false, slot: null, day: null, nextSlot: null })}
        onStartSession={(slot) => handleStartStudySession(slot, logStudyModalState.day!)}
        onUploadSlides={handleUploadSlidesForSession}
        slot={logStudyModalState.slot}
        day={logStudyModalState.day}
        nextSlot={logStudyModalState.nextSlot}
      />

    </div>
  );
};

