import { 
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  signOut,
  updateProfile,
  sendPasswordResetEmail
} from 'firebase/auth';
import { 
  doc, 
  getDoc, 
  setDoc, 
  collection, 
  query, 
  where, 
  getDocs, 
  limit
} from 'firebase/firestore';
import { auth, db } from './firebase';
import type { UserDetails } from '../types';
import { EducationalLevel } from '../types';
import { initializeUsage } from '../lib/usageManager';
import { globalFeedbackService } from './globalFeedbackService';

const SESSION_TOKEN_KEY = 'sessionToken';
const USER_KEY_PREFIX = 'eb_u_data_';
const DB_NAME = 'EduBlayDB';
const STORE_NAME = 'kv_store';

// --- Native IndexedDB Wrapper ---
const idb = {
    getStore: async (mode: IDBTransactionMode) => {
        return new Promise<IDBObjectStore>((resolve, reject) => {
            const request = indexedDB.open(DB_NAME, 1);
            request.onupgradeneeded = () => request.result.createObjectStore(STORE_NAME);
            request.onsuccess = () => {
                const db = request.result;
                const tx = db.transaction(STORE_NAME, mode);
                resolve(tx.objectStore(STORE_NAME));
            };
            request.onerror = () => reject(request.error);
        });
    },
    set: async (key: string, value: any) => {
        const store = await idb.getStore('readwrite');
        return new Promise((resolve, reject) => {
            const req = store.put(value, key);
            req.onsuccess = () => resolve(true);
            req.onerror = () => reject(req.error);
        });
    },
    get: async <T>(key: string): Promise<T | null> => {
        const store = await idb.getStore('readonly');
        return new Promise((resolve, reject) => {
            const req = store.get(key);
            req.onsuccess = () => resolve(req.result || null);
            req.onerror = () => reject(req.error);
        });
    },
    remove: async (key: string) => {
        const store = await idb.getStore('readwrite');
        return new Promise((resolve) => {
            const req = store.delete(key);
            req.onsuccess = () => resolve(true);
        });
    },
    clear: async () => {
        const store = await idb.getStore('readwrite');
        return new Promise((resolve) => {
            const req = store.clear();
            req.onsuccess = () => resolve(true);
        });
    }
};

const sanitizeForFirestore = (obj: any): any => {
    try {
        return JSON.parse(JSON.stringify(obj, (key, value) => {
            if (value === undefined) return null;
            return value;
        }));
    } catch (e) {
        return {};
    }
};

export const storageService = {
    saveItem: async (key: string, value: any) => {
        try {
            if (key.startsWith(USER_KEY_PREFIX) || typeof value === 'object') {
                await idb.set(key, value);
            } else {
                localStorage.setItem(key, JSON.stringify(value));
            }
        } catch (error: any) {
            console.error(`Storage failed for "${key}":`, error);
            await idb.set(key, value);
        }
    },
    loadItem: async <T,>(key: string): Promise<T | null> => {
        try {
            const idbValue = await idb.get<T>(key);
            if (idbValue !== null) return idbValue;

            const localValue = localStorage.getItem(key);
            return localValue ? JSON.parse(localValue) : null;
        } catch (error) {
            return null;
        }
    },
    removeItem: async (key: string) => {
        localStorage.removeItem(key);
        await idb.remove(key);
    },

    saveUserData: async (userId: string, data: any): Promise<void> => {
        if (!userId) return;
        try {
            const safeData = sanitizeForFirestore(data);
            const userRef = doc(db, 'users', userId);
            await setDoc(userRef, safeData, { merge: true });
        } catch (error: any) {
            console.error('Cloud sync failed:', error.message);
        }
    },
    syncUserToCloud: async (userId: string, data: any): Promise<void> => {
        return storageService.saveUserData(userId, data);
    },
    loadUserData: async (userId: string): Promise<any | null> => {
        if (!userId) return null;
        try {
            const userRef = doc(db, 'users', userId);
            const docSnap = await getDoc(userRef);
            return docSnap.exists() ? docSnap.data() : null;
        } catch (error: any) {
            return null;
        }
    },
    exportAllData: async () => {
        const data: { [key: string]: any } = {};
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key) {
                const item = localStorage.getItem(key);
                try { data[key] = JSON.parse(item!); } catch { data[key] = item; }
            }
        }
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `edublay_backup_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    },
    importAllData: async (file: File): Promise<void> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = async (event) => {
                try {
                    const data = JSON.parse(event.target?.result as string);
                    for (const key of Object.keys(data)) {
                        await storageService.saveItem(key, data[key]);
                    }
                    resolve();
                } catch { reject(new Error("Failed to parse import file.")); }
            };
            reader.readAsText(file);
        });
    },
    clearAllData: async () => {
        localStorage.clear();
        await idb.clear();
    }
};

const createToken = (user: UserDetails): string => btoa(encodeURIComponent(JSON.stringify(user)));
const decodeToken = (token: string): UserDetails | null => {
    try { return JSON.parse(decodeURIComponent(atob(token))); } catch { return null; }
};

export const signUp = async (name: string, email: string, password_param: string, recoveryQuestion: string, recoveryAnswer: string): Promise<UserDetails> => {
    const userCredential = await createUserWithEmailAndPassword(auth, email, password_param);
    const user = userCredential.user;
    await updateProfile(user, { displayName: name });
    const newUser: UserDetails = {
        id: user.uid,
        name,
        email,
        educationalLevel: EducationalLevel.OTHER, 
        hasConfirmedDetails: false, // Strictly force confirmation
        usage: initializeUsage(),
        recoveryQuestion,
        recoveryAnswer
    };

    // Register user for feedback global counts
    await globalFeedbackService.registerUser(user.uid, name, email);

    await storageService.saveUserData(user.uid, { userDetails: newUser });
    await storageService.saveItem(SESSION_TOKEN_KEY, createToken(newUser));
    return newUser;
};

export const login = async (email: string, password_param: string): Promise<UserDetails> => {
    const userCredential = await signInWithEmailAndPassword(auth, email, password_param);
    const user = userCredential.user;
    const cloudData = await storageService.loadUserData(user.uid);

    const localKey = `${USER_KEY_PREFIX}${email}`;
    const localData = await storageService.loadItem<any>(localKey);

    let finalData = cloudData;
    if (localData && cloudData) {
        if (localData.learningHubState?.file?.base64 && !cloudData.learningHubState?.file?.base64) {
             finalData = {
                 ...cloudData,
                 learningHubState: {
                     ...cloudData.learningHubState,
                     file: {
                         ...cloudData.learningHubState?.file,
                         base64: localData.learningHubState.file.base64
                     }
                 }
             };
        }
    }

    const userDetails = finalData?.userDetails || {
        id: user.uid,
        name: user.displayName || email.split('@')[0],
        email: email,
        educationalLevel: EducationalLevel.OTHER,
        hasConfirmedDetails: false, // Default to false if not found
        usage: initializeUsage()
    };

    if (finalData) await storageService.saveItem(localKey, finalData);
    await storageService.saveItem(SESSION_TOKEN_KEY, createToken(userDetails));
    return userDetails;
};

export const findUserByEmail = async (email: string): Promise<boolean | 'unknown'> => {
    try {
        const usersRef = collection(db, 'users');
        const q = query(usersRef, where('email', '==', email), limit(1));
        const querySnapshot = await getDocs(q);
        return !querySnapshot.empty;
    } catch (error: any) {
        if (error.code === 'permission-denied' || error.message?.includes('permission')) {
            console.warn("⚠️ Account lookup restricted. Proceeding with standard reset flow.");
            return 'unknown';
        }
        console.error("❌ Error finding user:", error);
        return 'unknown';
    }
};

export const logout = async () => {
    await signOut(auth);
    await storageService.removeItem(SESSION_TOKEN_KEY);
};

export const getCurrentUser = async (): Promise<UserDetails | null> => {
    const token = await storageService.loadItem<string>(SESSION_TOKEN_KEY);
    return token ? decodeToken(token) : null;
};

export const resetPassword = async (email: string): Promise<boolean> => {
    try {
        await sendPasswordResetEmail(auth, email);
        console.log('✅ Password reset email sent to:', email);
        return true; 
    } catch (error) {
        console.error('❌ Reset password error:', error);
        return false;
    }
};

import React, { useMemo } from 'react';
import { useLanguage } from '../contexts/LanguageContext';
import { UserDetails, EducationalLevel } from '../types';
import { countries } from '../data/countries';
import { universities } from '../data/universities';
import SearchableDropdown from './SearchableDropdown';

interface UserDetailsFormProps {
    userDetails: UserDetails;
    setUserDetails: (details: UserDetails) => void;
    showExtendedFields?: boolean;
}

const UserDetailsForm: React.FC<UserDetailsFormProps> = ({ userDetails, setUserDetails, showExtendedFields = false }) => {
    const { t } = useLanguage();

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        setUserDetails({ ...userDetails, [e.target.name]: e.target.value });
    };

    const handleDropdownChange = (name: keyof UserDetails, value: string) => {
        setUserDetails({ ...userDetails, [name]: value });
    };

    const universityOptions = useMemo(() => {
        const filtered = userDetails.country
            ? universities.filter(u => u.country === userDetails.country)
            : universities;
        return filtered.map(u => ({ name: u.name }));
    }, [userDetails.country]);

    const countryOptions = useMemo(() => countries.map(c => ({ name: c })), []);

    const inputClasses = "block w-full px-3 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm placeholder-gray-500 dark:placeholder-gray-400 text-gray-900 dark:text-gray-200 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm";

    const programmeLabel =
        userDetails.educationalLevel === EducationalLevel.HIGH_SCHOOL || userDetails.educationalLevel === EducationalLevel.OTHER
            ? t('userDetails.courseOfStudy')
            : t('userDetails.programmeOfStudies');

    const isUniversityLevel = ![EducationalLevel.HIGH_SCHOOL, EducationalLevel.OTHER].includes(userDetails.educationalLevel);

    const eduLevelOptions = [
        { value: EducationalLevel.HIGH_SCHOOL, labelKey: 'eduLevel.highSchool' },
        { value: EducationalLevel.UNDERGRADUATE, labelKey: 'eduLevel.undergraduate' },
        { value: EducationalLevel.POSTGRADUATE, labelKey: 'eduLevel.postgraduate' },
        { value: EducationalLevel.DOCTORATE, labelKey: 'eduLevel.doctorate' },
        { value: EducationalLevel.OTHER, labelKey: 'eduLevel.other' },
    ];

    return (
        <div className="space-y-4">
            <div>
                <label htmlFor="name" className="block text-sm font-medium text-gray-700 dark:text-gray-300">{t('userDetails.name')}</label>
                <input type="text" name="name" id="name" value={userDetails.name} onChange={handleInputChange} className={inputClasses} required />
            </div>
            {showExtendedFields && (
                <>
                     <div>
                        <label htmlFor="biography" className="block text-sm font-medium text-gray-700 dark:text-gray-300">{t('profile.biography')} ({t('common.optional')})</label>
                        <textarea 
                            name="biography" 
                            id="biography" 
                            rows={4}
                            value={userDetails.biography || ''} 
                            onChange={handleInputChange} 
                            className={`${inputClasses} resize-y`} 
                            placeholder={t('profile.biographyPlaceholder')}
                            maxLength={500}
                        />
                        <p className="text-xs text-right text-gray-500 dark:text-gray-400 mt-1">{(userDetails.biography || '').length} / 500</p>
                    </div>
                </>
            )}

            <div>
                <label htmlFor="educationalLevel" className="block text-sm font-medium text-gray-700 dark:text-gray-300">{t('userDetails.level')}</label>
                <select name="educationalLevel" id="educationalLevel" value={userDetails.educationalLevel} onChange={handleInputChange} className={inputClasses}>
                    <option value={EducationalLevel.OTHER} disabled={userDetails.educationalLevel !== EducationalLevel.OTHER}>-- {t('preferences.subtitle' as any).split('.')[0]} --</option>
                    {eduLevelOptions.map(({ value, labelKey }) => (
                        <option key={value} value={value}>{t(labelKey)}</option>
                    ))}
                </select>
            </div>

            <div>
                <label htmlFor="programmeOfStudy" className="block text-sm font-medium text-gray-700 dark:text-gray-300">{programmeLabel}</label>
                <input
                    type="text"
                    name="programmeOfStudy"
                    id="programmeOfStudy"
                    value={userDetails.programmeOfStudy || ''}
                    onChange={handleInputChange}
                    className={inputClasses}
                    placeholder={t('userDetails.programmePlaceholder')}
                />
            </div>

            {isUniversityLevel ? (
                <>
                    <div>
                        <label htmlFor="country" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                            {t('userDetails.country')}
                            <span className="text-red-500 ml-1">*</span>
                        </label>
                         <SearchableDropdown
                            id="country"
                            name="country"
                            options={countryOptions}
                            value={userDetails.country || ''}
                            onChange={(value) => handleDropdownChange('country', value)}
                            placeholder={t('userDetails.countryPlaceholder')}
                         />
                    </div>
                     <div>
                        <label htmlFor="institution" className="block text-sm font-medium text-gray-700 dark:text-gray-300">{t('userDetails.institution')}</label>
                         <SearchableDropdown
                            id="institution"
                            name="institution"
                            options={universityOptions}
                            value={userDetails.institution || ''}
                            onChange={(value) => handleDropdownChange('institution', value)}
                            placeholder={t('userDetails.institutionPlaceholder')}
                            disabled={!userDetails.country}
                         />
                    </div>
                    {showExtendedFields && (
                        <div>
                            <label htmlFor="institutionAbbreviation" className="block text-sm font-medium text-gray-700 dark:text-gray-300">{t('profile.institutionAbbr')} ({t('common.optional')})</label>
                            <input
                                type="text"
                                name="institutionAbbreviation"
                                id="institutionAbbreviation"
